-- Generated from canonical AzerothCore WotLK English; do not hand-edit.
-- Italian-only table: a missing key leaves the English client text untouched.
GS_lang = "IT"
GS_Gossip = {}
GS_Gossip[1001403763] = "Finalmente, tutto è a posto. Sei pronto per il tuo debutto sul grande palcoscenico?"
GS_Gossip[1002501069] = "Benvenuto tra noi, YOUR_CLASS."
GS_Gossip[1002748779] = "Fallo in fretta, YOUR_RACE. Sono stanco e non ho tempo per cortesie.."
GS_Gossip[1003668280] = "Preferiresti di affidare i tuoi beni a un goblin?"
GS_Gossip[1004962920] = "Non mi fraintendere, preferirei non stare in un tunnel pieno di silithid giorno dopo giorno, ma se nascondermi qui e osservare i movimenti di questi creature può aiutarci a vincere la guerra, lo farò per quanto tempo sarà necessario."
GS_Gossip[1007767842] = "Nessuna libertà maggiore che volare tra i cieli, YOUR_CLASS. Cosa posso fare per te oggi?"
GS_Gossip[1012087545] = "Dove si trova Elder Hammershout?"
GS_Gossip[1012439419] = "10,000 anni di conoscenza registrata tendono a richiamare l'elemento sbagliato nell'Athenaeum. I libri vengono rubati, recuperati e rubati nuovamente in modo quotidiano."
GS_Gossip[1014333837] = "Ho sempre amato ordinare e organizzare le cose. Immagino che abbia preso da mia madre."
GS_Gossip[1014361887] = "Benvenuto nel villaggio di Starfall, viaggiatore. Sei venuto ad aiutarci?"
GS_Gossip[1015715407] = "Siamo stati mandati qui da Darnassus per aiutare i Stormpike nel momento del bisogno."
GS_Gossip[1017136579] = "Dovrai essere paziente con me, YOUR_NAME. Ho il mio Spybot all'interno che sta lavorando su una questione molto delicata. Sarò da te tra un momento.NEW_LINENEW_LINEOh, e fai un favore a me, cerca di non far vedere a Lescovar... stiamo per ambasciarlo."
GS_Gossip[1017682025] = "Ah, uno dei nostri. È bello vedere che i nostri numeri stanno crescendo così rapidamente che ormai non riesco più a tenere traccia dei volti dei nostri membri.NEW_LINENEW_LINEQuel idiota Thrall pensa che stia lavorando duramente per purificare l'immagine dei magi neri e dimostrare che siamo i suoi servitori. Idiota! La Legione Infuocata ridurrà completamente in cenere questo intero mondo dopo averlo svuotato del tutto."
GS_Gossip[1018975514] = "Borak, mi serve un altro mazzo di sanguespina."
GS_Gossip[1019357869] = "Sto tenendo d'occhio quegli stupidi forsaken là sotto. Non si può mai essere troppo cauti con loro!"
GS_Gossip[1020387598] = "Perché si sono fermati?"
GS_Gossip[1024294066] = "Quali beni ho guadagnato il diritto di acquistare per l'uso in Forra dei Cantaguerra?"
GS_Gossip[1030913015] = "Se stai cercando di registrare una corporazione, ti suggerirei di chiedere all'interno delle mura stesse di Lunargenta."
GS_Gossip[1033445614] = "Gymer, di cosa devo essere a conoscenza? Non ho mai cavalcato su un gigante."
GS_Gossip[1034540609] = "Portami alla Torre di Northpass."
GS_Gossip[1038301663] = "Tu?NEW_LINENEW_LINE<Lorax ride.>NEW_LINENEW_LINEÈ dubbio.NEW_LINENEW_LINESto qui in queste rovine e sogno. Sogno il giorno in cui catturerò quel miserabile ladro, Goraluk Anvilcrack.NEW_LINENEW_LINEAvevamo un accordo, lui e io. Un accordo che lui ha rotto. Tradito."
GS_Gossip[103831249] = "Se me lo chiedi, non c'è una professione migliore di quella di un minatore. E se me lo chiedi, non c'è un minatore migliore di un nano!"
GS_Gossip[1040684115] = "Puoi trovare Radnaal che pratica la sua arte fuori da casa sua lungo la strada per Darnassus. Dovresti fermarti a vedere cosa può insegnarti."
GS_Gossip[1042473472] = "Looma della Mana"
GS_Gossip[105100528] = "La macchina si regola per affrontarti.NEW_LINENEW_LINEDietro alla macchina c'è uno slot vuoto, stranamente deformato, con un'incisione che recita: \"Propirtee o' Cap'n Gelkak Gyromast\""
GS_Gossip[105339242] = "L'incantatoria è una tradizione di famiglia che si tramanda da generazioni. Ho imparato fin da piccolo, proprio come sta facendo ora mio figlio."
GS_Gossip[1053835427] = "L'erborista intorno qui è Martha Alliestar. È là in anello interno dell'Apothecarium."
GS_Gossip[1054669185] = "Chi sei?"
GS_Gossip[1056688924] = "Sì? Certo che sono un fabbro. Credi forse che i Nani siano gli unici degni del loro peso in martelli? Va bene, allora. Vai a prendere un nano per aiutarti!"
GS_Gossip[1056787768] = "Teletrasporta a La tana di Sindragosa."
GS_Gossip[1057328860] = "<La nonna Geyah annuisce, accettando la tua risposta.>NEW_LINENEW_LINENon posso più combattere gli spiriti, YOUR_NAME. Il mio tempo è ormai passato da tempo. Ancora una volta, devo ringraziarti per tutto ciò che hai fatto. Mentre Garrosh potrebbe essere immobile, molti dei miei persone sono stati sollevati dai tuoi successi. Ora sono disposti a lottare per i nostri diritti come clan uniti."
GS_Gossip[1057590949] = "Sappiamo che i seguaci del culto del wyrm si stanno radunando dall'altra parte del tunnel. Prenderemo posizione qui."
GS_Gossip[1062110490] = "Ogni oggetto che ho in vendita l'ho acquisito personalmente. Hai la mia garanzia personale di autenticità."
GS_Gossip[1063652449] = "Questo albergo fu costruito prima che i selvaggi del nord si svegliassero. Grazie alla Luce, almeno questo è vero!NEW_LINENEW_LINEResterai a lungo?"
GS_Gossip[1073352652] = "Ehi, tesoro. Lo zeppelin che si ferma qui ti porterà dritto a Picco del Tuono, gratis. Chi ha bisogno di wyverne quando si hanno noi goblin qui, non ti pare?"
GS_Gossip[1075870230] = "Un'altra interruzione. Come diavolo dovrei fare qualcosa di lavoro in questo modo? Non rispondere; sembro io mi preoccupi per quello che hai da dire? Se un giorno vogliamo ripulire questo posto e espandere l'impero, avrò bisogno di assoluto silenzio!"
GS_Gossip[1076796778] = "Albergo Aldor"
GS_Gossip[1076959297] = "Che, se posso permettermi, stai facendo qui? Indossa l'abbigliamento degli studenti e studia!"
GS_Gossip[1081725034] = "Mi dispiace, le nostre birre sono esclusive per i membri del \"Club Birra del Mese\"."
GS_Gossip[108482147] = "Ce l'abbiamo fatta! Riuscite a credere a quello che stiamo sentendo? È incredibile!"
GS_Gossip[1087862824] = "Il mio maestro, Plugger Spazzring, è un buon capo.  E lui guadagna molto denaro.  I suoi sacchetti sono straripanti!"
GS_Gossip[1090115223] = "Saluti.  Sono l'Anacoreta Avuun dei draenei.  Sono qui per studiare gli Scomparsi del Santuario Incolto nella speranza di poter trovare una cura per la loro condizione."
GS_Gossip[1097544371] = "Questo è l'unico modo in cui Harry parlerà mai con me! Devo tenere questo stupido maschera sempre..."
GS_Gossip[1099142342] = "Giorno dopo giorno, tutto ciò che facciamo è faticare in questa miniera. L'uomo elfo rosso non è stato creato per un lavoro manuale simile."
GS_Gossip[1100275642] = "Dove si trova Elder Skygleam?"
GS_Gossip[1100986733] = "Sono Moordo, cacciatore anziano di Stillpine."
GS_Gossip[1101182670] = "Le questioni di natura ufficiale vengono gestite solo a Darnassus. Devi recarti lì per iniziare il processo di creazione della tua guild."
GS_Gossip[1101218007] = "Cio’ che spiegherebbe perché sei seduto in una cella di prigione in fondo a una montagna, giusto, nano?"
GS_Gossip[1103878729] = "Mmm... cibo."
GS_Gossip[1104825645] = "Non ho più lavoro per te, YOUR_NAME. Vorrei che sapessi che il branzino rosso che abbiamo condiviso era qualcosa di speciale che non dimenticherò mai..."
GS_Gossip[1109972175] = "Cosa vuoi da Raze??"
GS_Gossip[1111307754] = "Dici, percepisco un certo grado di incredulità nella tua voce - ma sì, è così che è successo."
GS_Gossip[1113888388] = "Per favore continua, Zamael."
GS_Gossip[1114746457] = "Sembro un YOUR_CLASS a te? Ora vai via prima che io senta la necessità di ungere la mia lama... con il tuo sangue."
GS_Gossip[1115391924] = "Se sei venuto in cerca del dono della mobilità rapida e sicura, allora sei arrivato alla destinazione giusta! Quest'anno il nuovo modello di Mechano-striders è appena arrivato, e sono pronto a mostrarti tutto ciò che ha da offrire!"
GS_Gossip[1118352053] = "Ehi, se le persone vogliono correre intorno a scavare nella terra in cerca di uova colorate, chi sono io per giudicare? Comunque ottengo comunque una percentuale dei profitti sulla vernice, e ho investito in galline quest'anno."
GS_Gossip[1120463231] = "Vieni dentro, mon... dimentica per un momento le tue preoccupazioni!NEW_LINENEW_LINERiposo del corpo, riposo dell'anima."
GS_Gossip[1121815084] = "Un'ispezione superficiale dei resti scheletrici indica che la carne è stata arrostita. Una vista piuttosto orribile."
GS_Gossip[1122827727] = "Non ho molto tempo in questo mondo, ma se la Luce lo vorrà, sarà abbastanza tempo per compiere il mio destino. Quando ti recherai di fronte al Barone Rivendare, sarò al tuo fianco."
GS_Gossip[1123461226] = "<Sobbing> Odio i cimiteri. Tanti morti. E la mia cara Luhanaa...."
GS_Gossip[1123667293] = "Non ti sfiderò, ma vorrei vedere le tue merci."
GS_Gossip[1129014166] = "Mostrami l'armatura dei signori del Flagello, Ormus."
GS_Gossip[1133106802] = "Fermati - no. Sii più lento - forse.NEW_LINENEW_LINELa Scholomance è la loro principale fonte di addestramento e istruzione. È da lì che i membri del Cult si diffondono e alla fine, riescono ad entrare nelle nostre società.NEW_LINENEW_LINEPer questo dobbiamo colpire alla fonte. Il cuore stesso del Culto dei Dannati!"
GS_Gossip[1136022244] = "Saluti, YOUR_CLASS.NEW_LINENEW_LINEL'Orda controlla attualmente il Forte di Wintergrasp. Quando la battaglia è sul punto di iniziare, parla con me per entrare in battaglia.NEW_LINENEW_LINELa battaglia successiva inizia tra $4354k."
GS_Gossip[1136257302] = "Il mio padre mi ha regalato la sua armatura da battaglia e l'ascia. Presto la metterò a buon uso."
GS_Gossip[1136669548] = "Oh, non preoccuparti per Buddy. Non ti farà del male, gli piace solo grattarsi di tanto in tanto.NEW_LINENEW_LINEÈ solo un grande gatto adorabile.NEW_LINENEW_LINENon sei tu, Buddy? Sì, sei tu, tu piccola cosa carina. Sei il piccolo bambino di mamma, ecco cos'eri!"
GS_Gossip[1137166897] = "Siate vigili, amici. Il Traditore medita nel cortile appena oltre."
GS_Gossip[1138005837] = "Elder Goldwell trascorre il suo tempo nel villaggio di Kharanos a Dun Morogh."
GS_Gossip[113949842] = "Siamo molto fortunati ad essere vivi, tu e io!"
GS_Gossip[1140320540] = "Cerchi Kardris Sognatore. Lei e gli altri sciamani si trovano nella stanza d'ingresso al Forte di Thrall nella Valle della Saggezza."
GS_Gossip[1143144807] = "Perché non distruggerli con il potere combinato degli Aspetti?"
GS_Gossip[1143245561] = "Tutte le ricompense per i servizi resi devono essere distribuite da Warcaller Sardon Truslice.NEW_LINENEW_LINEPosta senza bollette."
GS_Gossip[1148433030] = "Banca nel quartiere commerciale, torre centrale. Non potrai perderla."
GS_Gossip[1149692333] = "I spiriti degli elementi ci circondano. Dobbiamo sempre ascoltare. Ho visto di persona le conseguenze quando li ignoriamo..."
GS_Gossip[115672943] = "Desideriamo che lei, Sua Altezza, si ritiri."
GS_Gossip[1157887844] = "Quando sarai pronto ti posizionerò sulla mia testa e marceremo nel cuore del Flagello a Zul'Drak. Devi guidarmi per distruggere e annientare i nostri nemici!"
GS_Gossip[1158032771] = "<L'Arcano Guardiano fa un gesto verso la città inferiore, dove si può trovare una grande forgia.>"
GS_Gossip[1159071022] = "Sta scappando!"
GS_Gossip[1159621037] = "Certo! Vai con la benedizione di Elune."
GS_Gossip[1159649053] = "Stiamo festeggiando chi che si è liberato da che? Bah, chi se ne frega?! Più caramelle!"
GS_Gossip[116175169] = "Se stai andando in città, allora ho qualcosa di importante da farti fare!"
GS_Gossip[1164441094] = "Il cono felino prende il nome dalla corruzione magica felina. Cerca il fungo del cono felino nel campo dei satiri nazziviani - a ovest."
GS_Gossip[1164955316] = "Tuskarr Kite"
GS_Gossip[1165408260] = "C'è un alchimista che vive in cima alle colline tra Northshire e Roccavento che potrebbe essere di qualche aiuto. Perché non vai a visitarlo?"
GS_Gossip[1165626452] = "Con i calderoni compromessi, ora possiamo introdurre l'agente opposto nell'ambiente. Questo dovrebbe dare alla piaga un assaggio della loro stessa medicina, così si potrebbe dire!NEW_LINENEW_LINEControlla con l'Erborista Dithers per ottenere informazioni sui reagenti necessari per utilizzare nei calderoni.  Io mi occuperò di tutti i rapporti sull'andamento complessivo nel trasformare la peste contro il Flagello!"
GS_Gossip[1166613092] = "I Creatori sono consapevoli dell'entità delle informazioni custodite in questo repository. Successivamente, una copia portatile dei dati archiviati qui sarà resa disponibile una volta che sarai in sintonia con i Dischi di Norgannon.NEW_LINENEW_LINEPrendi in considerazione i tuoi requisiti superficiali per l'assimilazione di questa conoscenza come completi. A tuo piacimento, accedi ai Dischi di Norgannon per iniziare la sintesi dei tuoi dischi."
GS_Gossip[1167403062] = "Saluti, YOUR_NAME. Procedi con cautela..."
GS_Gossip[1168032060] = "Troverai i nostri istruttori di estrazione verso la parte posteriore del Trader's Tier."
GS_Gossip[1170402745] = "Ora siamo un popolo senza una casa a cui chiamare la nostra."
GS_Gossip[1170897830] = "Se me lo chiedi, penso che i goblin siano un gioco da ragazzi. Abbiamo gli strumenti e abbiamo il talento!"
GS_Gossip[1170951992] = "È tutto intorno a noi. È nella mia testa!"
GS_Gossip[1171468198] = "Il nostro è un percorso per coloro che hanno una volontà di ferro e una determinazione inamovibile. Sembrerebbe che tu non possieda nessuna di queste qualità, YOUR_CLASS."
GS_Gossip[1171589811] = "Normalmente puoi trovare lo stand dei fiori di Miss Primrose nel sud-est di Dalaran."
GS_Gossip[1172547883] = "Non ho tempo per parlare in questo momento."
GS_Gossip[1172648303] = "Cosa deve essere fatta?"
GS_Gossip[1177567654] = "Elder Ohanzee si trova a Gundrak."
GS_Gossip[1179309661] = "Che storia interessante."
GS_Gossip[117983756] = "Posso esserti d'aiuto?"
GS_Gossip[118091648] = "L'uovo sembra resistente come un uovo della Black Dragonflight dovrebbe essere. Forse se mettessi molti frammenti apexis accanto a esso, le loro vibrazioni lo farebbero rompere?NEW_LINENEW_LINEPeccato che non sembri avere i trentacinque frammenti di apexis necessari per compiere l'incarico."
GS_Gossip[1183309863] = "Non hai ciò che serve per combattere nel Circuito dei Combattimenti di Steamwheedle, YOUR_CLASS. Smettila di sprecare il mio tempo."
GS_Gossip[1185043025] = "Un tempo fa, durante i miei viaggi, ho incontrato un uomo che mi disse, \"Mastri utilizzandolo e potrete averlo questo.\"NEW_LINENEW_LINECosa pensi che possa significare? Non lo sapevo allora, e sinceramente non lo so nemmeno adesso..."
GS_Gossip[1186916849] = "Bene... mostrami l'offerta!"
GS_Gossip[1188416209] = "Molto impegnato... molto impegnato! Cosa?"
GS_Gossip[1188447856] = "Dulvi è la donna che cerchi. L'addestra nuovi candidati al centro della Sorveglianza."
GS_Gossip[1188521360] = "È incredibile ciò che si può imparare da un gnomo se si schiaccia abbastanza forte: piccoli trucchi intelligenti per uscire dai guai, per preparare deliziosi biscotti e persino come costruire una macchina volante."
GS_Gossip[1191758214] = "Da quando le ombre hanno preso Duskwood non sono riuscito a dormire. Resto sveglio per i suoni spettrali di urla che arrivano con la brezza. Suona quasi come se fossero agnelli a urlare, e non smettono mai."
GS_Gossip[1194061094] = "Stai cercando Mishiki. Ha una capanna a sud nel villaggio di Sen'jin."
GS_Gossip[1194792166] = "Qui ho accumulato ciò che potrebbe essere il più grande deposito di conoscenze in tutta Outland. Anche le grandi biblioteche di Lunargenta fanno pallida figura in confronto.NEW_LINENEW_LINEPer favore... guarda, leggi, esplora quanto vuoi. Troverai tutto organizzato e chiaramente etichettato."
GS_Gossip[1195192359] = "Mantieni il tuo volume basso, YOUR_CLASS. Sono in maschera e spio per conto di Venompuntura."
GS_Gossip[1196170070] = "Benvenuto a Tranquillien, YOUR_CLASS. Mi scuso per lo stato in cui lo trovi. Come puoi vedere, abbiamo avuto alcuni problemi, ma i Forsaken e la loro Signora Sylvanas Windrunner ci hanno prestato un grande aiuto nel momento del bisogno.NEW_LINENEW_LINESe puoi dare una mano, non esitare a farlo. Possiamo usare tutto l'aiuto che possiamo ottenere nella nostra lotta contro le miriadi di forze schierate contro di noi."
GS_Gossip[1196230736] = "Mi chiedo quanto tempo resteranno a Lunargenta. Spero che si divertano qui!"
GS_Gossip[1202478521] = "Elder Darkcore può essere trovato nel Sepulcra."
GS_Gossip[1203776724] = "Salve, YOUR_CLASS.  C'è un grande bisogno e un'onore e fama ancora maggiori da guadagnare nella Valle d'Alterac in questo momento. Vuoi unirti alla nostra battaglia contro la Guardia Stormpike?"
GS_Gossip[120469972] = "L'oste Norman, situato nell'anello superiore del Distretto Commerciale, è la persona con cui parlare."
GS_Gossip[1204823930] = "Che? Vuoi donare del panno a Lunargenta?NEW_LINENEW_LINEStai cercando semplicemente un Hawkstrider, non è vero? Va bene, va bene... sii di aiuto a questa città e ti assicuro che la tua reputazione qui salirà."
GS_Gossip[1204967345] = "Il capitano è fantastico! Abbiamo tempo per rilassarci quando ormeggiamo. Sono quelle le ore a cui aspetto di più."
GS_Gossip[1206183017] = "Byancie ha spesso prestato i suoi servizi ai sentinelli che pattugliano le terre selvagge locali. Dovresti parlare con lei se desideri imparare l'Assistenza Medica."
GS_Gossip[1212817786] = "È bello rivederti, YOUR_NAME.NEW_LINENEW_LINEVieni a rinfrescare le tattiche del Flagello?"
GS_Gossip[1217702356] = "Il sacrificio di Anveena ci ha dato a tutti una nuova speranza per il futuro."
GS_Gossip[1218893280] = "Sei qui anche tu per dimostrare il tuo valore al Re dei Lich?NEW_LINENEW_LINEÈ un po' arcaico, non ti pare? Dovere combattere e sopravvivere?"
GS_Gossip[1220595063] = "Nell'epoca della guerra, Razelikh l'Inquinatore servì come il più temibile dei luogotenenti del Signore Kazzak. Quando la Legione fu sconfitta e Kazzak fu costretto a ritirarsi nella Cicala Contaminata, Razelikh fu incaricato dal suo padrone di occupare le Terre Maledette.NEW_LINENEW_LINEMentre l'Alleanza combatteva battaglie meschine con l'Orda per il territorio al di fuori delle Terre Sfracellate, Razelikh stava unendo le diverse sette del Consiglio delle Ombre e i brutali orchi Dreadmaul della regione."
GS_Gossip[122337177] = "La nave \"Assurance\" è inspiegabilmente piena di problemi e non possiamo salpare per Northrend."
GS_Gossip[1223643754] = "Puoi vedermi? Sai quanto vengo ignorato qui sopra solo perché nessuno può vedermi? Che sollievo finalmente avere qualcuno con cui parlare!NEW_LINENEW_LINEEh, quindi devi avermi mandato qualcuno tra i membri vivi della mia ex compagnia mercenaria, non è vero? Certo che lo sono!NEW_LINENEW_LINEMa basta con questi inutili chiacchericcio, c'è molto lavoro per te e per me se intendi mettere le cose a posto e restituire lo spirito di Lord Valthalak a lui!"
GS_Gossip[1226798862] = "Quali piante si trovano a Felwood che potrebbero essere corrotte?"
GS_Gossip[1227961023] = "Il titolo di questo libro è scritto con un tocco manuale: Diario di Maureen Dalson."
GS_Gossip[1229327166] = "Riconduccimi alla vita."
GS_Gossip[1230684185] = "Ciao, YOUR_CLASS. Se non l'hai già fatto, dovresti davvero parlare con Solanna, guerriera del lungo cammino."
GS_Gossip[1230829027] = "Va bene, ammetto che hai dimostrato di essere all'altezza e perfino di più, YOUR_NAME.NEW_LINENEW_LINESe prima ero duro con te era perché ho visto la scintilla di un vero Guardiano del Cielo in te. Oserei dire che sei l'aspirante più bravo che abbiamo!NEW_LINENEW_LINEQualsiasi momento in cui vorrai aiutare, sarò più che orgoglioso di darti un altro set di bombe."
GS_Gossip[1234334016] = "Come facciamo a farlo?"
GS_Gossip[1238364673] = "L'Albergo di Lunargenta."
GS_Gossip[1242532173] = "Permesso di visualizzare la tua selezione di fuochi d'artificio."
GS_Gossip[1247051192] = "Qualche provvista per il viaggio? Forse un rinfresco da gustare mentre guardi gli scontri?"
GS_Gossip[1247303318] = "Nel corso dei millenni, Ilyenia Moonfire ha padroneggiato numerose armi e ora offre ad altri l'opportunità di impararne l'uso. Puoi trovarla alla Terrazza dei Guerrieri se desideri ricevere addestramento."
GS_Gossip[1248341969] = "Per imparare a diventare uno con la Natura agli occhi della Madre Terra, questa è una questione d'onore. Se la tua volontà è di imparare le vie del Cacciatore, devi cercare Yaw Sharpmane all'estremità settentrionale del villaggio di Bloodhoof."
GS_Gossip[1248768246] = "Mostrami la tua varietà di, err... cose."
GS_Gossip[1249502319] = "È tutto armi e fiamme finché qualcuno non perde e muore."
GS_Gossip[1253740048] = "<Angela annuisce.>NEW_LINENEW_LINEDopo le morti, i Sei decisero che la migliore azione da intraprendere era quella di sigillare il bastone dietro barriere impenetrabili di magia e nominare un guardiano: un custode del bastone... Sarei stato io quel guardiano."
GS_Gossip[1254884250] = "Nessuna parte degli animali che cacciamo viene sprecata. "
GS_Gossip[1254935033] = "Duca dei Venti! Ho il tuo sigillo! Ascolta il mio richiamo!"
GS_Gossip[1257561410] = "Vattene! Ho un colloquio con i Dreadlords, e le questioni di cui discutiamo non ti riguardano!"
GS_Gossip[1258213032] = "Serviamo Thorim, sorella."
GS_Gossip[1259411999] = "Un Tavolo Abbondante è disposto con cinque cibi del Ringraziamento del Pellegrino, uno davanti a ogni sedia.NEW_LINENEW_LINEMentre seduto su una sedia, puoi mangiare quanto vuoi di quel cibo, nonché passare porzioni di quel cibo alle altre sedie. Festa e condivisione con gli amici!NEW_LINENEW_LINESe mangi abbastanza di un solo cibo, otterrai benefici unici per quel cibo.NEW_LINENEW_LINEInoltre, se mangi abbastanza di ogni cibo, guadagnerai lo Spirito del Condividere!"
GS_Gossip[1259727695] = "Mi dispiace di averti disturbato, amico. Prosegui!"
GS_Gossip[1260018588] = "Ah, YOUR_RACE... Possiedo una grande conoscenza del mondo e del modo di creare incantamenti di grande potere."
GS_Gossip[1260896124] = "Da dove proviene questa tecnologia?"
GS_Gossip[1262050938] = "Di che tipo di addestratore stai cercando?"
GS_Gossip[1263658061] = "Siamo con te Brann! Aprilo!"
GS_Gossip[1267764501] = "Duca di Cynders! Ho il tuo sigillo! Ascolta il mio richiamo!"
GS_Gossip[1271748867] = "Praticando! Presto sarò abbastanza bravo da unirmi agli altri evocatori e prendere il mio turno all'interno del Labirinto delle Ombre ad Auchindoun.NEW_LINENEW_LINESpero di avere l'occasione di evocare qualcosa di grande! Forse qualcosa tanto grande quanto Murmur, anche se non perderò il controllo su di lui!"
GS_Gossip[1272454791] = "Seikwa può prendersi cura dei tuoi amici animali quando ne hai bisogno. Cerca di trovarla davanti all'osteria."
GS_Gossip[12725493] = "<Il clero ti guarda da un angolo dell'occhio.>"
GS_Gossip[1272832561] = "Sì, mi piacerebbe molto andare a Blackwind Landing."
GS_Gossip[127338250] = "Saluti, YOUR_CLASS.NEW_LINENEW_LINEL'Orda controlla attualmente il Forte di Wintergrasp, ma la prossima battaglia inizierà presto.   Preparatevi a recarvi a Wintergrasp e a supportare le nostre forze!NEW_LINENEW_LINELa battaglia successiva inizia tra $4354k."
GS_Gossip[1273966947] = "Di quali anomalie stai parlando?"
GS_Gossip[1277292753] = "Non male, non male... Ma manca di pepe! Che ne dici di aggiungere il veleno delle scorpidi? Sì! Questo lo risolverà subito!"
GS_Gossip[1278716277] = "Come rappresentante del Consorzio, sono sempre consapevole delle conseguenze che le mie interazioni hanno sui nostri affari.NEW_LINENEW_LINEÈ purtroppo spiacevole che gli elfi del sangue non trattino le loro partnership con tale rispetto."
GS_Gossip[1279481366] = "OK! Lump ti dirà qualunque cosa tu voglia!"
GS_Gossip[1280447096] = "Per favore sbrighiamoci, YOUR_NAME. Sono in grande dolore e il tempo sta scadendo."
GS_Gossip[1281637363] = "Prendi le tue cose, YOUR_NAME! Ho appena ricevuto notizia da Nilith Lokrav nella Fossa Ardente che l'Undermarket ha stabilito operazioni nel cuore del Calderone. Trova Nilith Lokrav nella Fossa Ardente e scopri i dettagli!"
GS_Gossip[1281937326] = "Come voli in questo clima freddo?"
GS_Gossip[1282584720] = "Ricordo quando io e mio fratello ci accampavamo da soli nella selvaggina di Azshara. Guarda come è adesso. "
GS_Gossip[1284412325] = "Il Cavaliere senza Testa, un tempo un cavaliere della Mano d'Argento e un eroe tra i suoi confratelli paladini, è maledetto. Sconvolto nella Monastero Rosso, crede di essere vivo e che noi siamo morti.NEW_LINENEW_LINEOra, il suo fervore non serve più la Luce. Con l'arrivo di Hallow's End, egli diffonde ombre e fuoco tra le villaggi di Azeroth."
GS_Gossip[1285080135] = "Che il Re dei Lich bruci nell'inferno per ciò che ha fatto scendere su questa terra."
GS_Gossip[1285334727] = "Grandi?"
GS_Gossip[1287386590] = "Ciò che seguì fu una serie di eventi tragici, portando alla morte di ogni mago Kirin Tor che entrò in contatto con Atiesh.NEW_LINENEW_LINEVedi, era un'artefatto con coscienza. Una coscienza concessa ad esso da Sargeras..."
GS_Gossip[1287532221] = "Per favore portami alla tana del maestro."
GS_Gossip[1288832941] = "Lasciami in pace. Non ho niente per gente come te."
GS_Gossip[1288893730] = "Io gestisco i combattimenti qui intorno. Vuoi scommettere? Fai lo scommettitore sicuro - chiunque venga beccato a manipolare i combattimenti dovrà camminare sulla tavola.NEW_LINENEW_LINELo farò io stesso!"
GS_Gossip[1289620459] = "Qualcosa di cui hai bisogno, signore?"
GS_Gossip[129402304] = "Con nuovi nemici ai nostri cancelli, non dobbiamo permettere ai nostri antichi nemici di approfittare della nostra situazione!"
GS_Gossip[1294046074] = "Saluti YOUR_RACE, sono Tharnariun Treetender."
GS_Gossip[1294353226] = "Torna tra il tuo popolo e digli di mandarmi uno dei tuoi sciamani."
GS_Gossip[1298340404] = "Heigan sta probabilmente eseguendo manutenzione sul suo studio di danza pieno di slime e merda."
GS_Gossip[1299843208] = "Mostrami dove posso volare."
GS_Gossip[1301712051] = "Ci sono molti posti che potresti visitare a Teldrassil. Dimmi cosa cerchi."
GS_Gossip[1302444667] = "Puoi sentire il male che ci circonda, YOUR_CLASS? Per mano, deve essere purificato!NEW_LINENEW_LINEI demoni hanno distrutto il nostro mondo natale, Argus. Non tollererò la loro presenza qui nel nostro nuovo mondo, Azeroth!"
GS_Gossip[1302517371] = "Salve, giovane shaman. Fatti comodo nel mio reef."
GS_Gossip[1309081728] = "<Mentre posi i tuoi frammenti di apexis nel fel cristalloforge e tiri la leva, l'apparato emette un suono inumano mentre li macina in polvere. Dopo un momento, la tua fiala esce dalla sua 'bocca'.>"
GS_Gossip[1311670306] = "Mio marito è stato sparito da giorni. Siamo andati insieme in questo pellegrinaggio; dovevamo finirlo insieme.NEW_LINENEW_LINETutto questo preoccupazione mi ha portato a utilizzare i cristalli di mana con maggiore frequenza di quanto non dovrebbe."
GS_Gossip[1313221755] = "Signore-Comandante, vorresti ripetere ciò che hai detto prima?"
GS_Gossip[1318485988] = "Attraverso i miei studi, vedo che sconfiggere l'avatar del dio Hakkar l'ha indebolito. Ma la maggior parte della sua forza rimane, celata all'estremità opposta del Nether.NEW_LINENEW_LINEHai sconfitto il suo avatar una volta, YOUR_NAME.  Forse se lo sconfiggi nuovamente potrai indebolire ulteriormente il dio in modo che, un giorno, possiamo affrontare la sua vera forma.NEW_LINENEW_LINEHo preparato un incantesimo che puoi utilizzare per richiamare nuovamente un avatar di Hakkar all'interno del Santuario del Dio Caduto. Vuoi affrontarlo nuovamente?"
GS_Gossip[1318744617] = "Il volo verde è in tuo debito."
GS_Gossip[1319190250] = "Ciao, pelle secca."
GS_Gossip[1319260595] = "Quando la Festa delle Ombre sarà finita, distruggeremo tutti questi zucche. Sarà il giorno più fantastico della mia vita!"
GS_Gossip[1319261791] = "Elder Farwhisper può essere trovato vagando per le strade di Stratholme."
GS_Gossip[1320313033] = "Questo è un portale per la zona di battaglia della Forra dei Cantaguerra."
GS_Gossip[1322568998] = "Molti sono caduti all'interno di Valhalas e i loro corpi sono un testimonianza della forza delle nostre vie.NEW_LINENEW_LINEI tuoi ossi copriranno anche questo luogo d'onore e di battaglia, YOUR_NAME?"
GS_Gossip[1322666483] = "Benvenuto, amico, nel barbiere! Vuoi un taglio? Un colore? Forse qualcos'altro?NEW_LINENEW_LINEPossiamo curare la barba facciale, eseguire piercing, riformare i denti da cavallo e le corna, e persino modificare le caratteristiche degli undead!NEW_LINENEW_LINESiediti e passeremo subito all'azione. Sei a poine monete di distanza da una nuova e più attraente versione di te..."
GS_Gossip[1327541244] = "YOUR_NAME, hai la minima idea di cosa ci aspetta nella Valle d'Alterac? Sei pronto a combattere la Tribù dei Lupo Gelido?"
GS_Gossip[1328257032] = "Vorrei allenarmi."
GS_Gossip[1330851130] = "Sono Hydraxis, Duca dei Signori dell'Acqua. Non sei un elemento e quindi non puoi comprendere la nostra lotta, ma forse possiamo trovare un accordo che beneficerà entrambi..."
GS_Gossip[1333540387] = "Riconosco un asso quando lo vedo. Grazie ancora per avermi salvato la vita!"
GS_Gossip[1334197291] = "Questo è ciò che ho raccolto dall'informazione che hai raccolto dal sondaggio.NEW_LINENEW_LINEEsistono due accampamenti principali di forgia: Accampamento di Forgia: Odio, direttamente a ovest del punto in cui stiamo stando e Accampamento di Forgia: Paura, direttamente a sudovest. Ogni accampamento ha un trasportatore della Legione, una forgia e diverse torri di protezione magica. Inoltre, gli accampamenti sono difesi da guardie infuriate che tengono in mano cannoni felici. Infine, ogni accampamento ha un sovrintendente del Signore delle Fosse.NEW_LINENEW_LINEBene, allora questo non dovrebbe essere affatto un problema...NEW_LINENEW_LINE<Altruis ride.>"
GS_Gossip[1335812950] = "A nome della Crociata d'Argento, ti do il benvenuto nel Torneo d'Argento."
GS_Gossip[1336029314] = "Maestro della battaglia"
GS_Gossip[1337714979] = "..."
GS_Gossip[1339259935] = "Bene, siete sicuri di trovare alcuni addestramenti nelle arti magiche nel Hall of Mysteries, a nord delle porte di Forgiardente. Juli Stormkettle può sempre essere trovata lì con il naso in un libro."
GS_Gossip[134133872] = "Dobbiamo colpire Jotunheim in modo continuo. Mai dare loro la possibilità di riposarsi, mai la possibilità di dormire, e mai accettare la resa!NEW_LINENEW_LINETirion Fordring con tutta la potenza di Ashbringer e la Crociata d'Argento alle sue spalle non può sperare di compiere ciò che stai facendo!NEW_LINENEW_LINEOra, sbrigati con i tuoi affari, YOUR_NAME. C'è troppo che sta accadendo per permettere chiacchiere inutili."
GS_Gossip[1346425449] = "Esistendo solo per il caos, il suo più lieve sussurro significava la distruzione di interi mondi!NEW_LINENEW_LINETuttavia, c'erano ancora coloro che avrebbero cercato di adorare quest'essere privo di mente. C'erano perfino coloro più pazzi che osarono pensare di controllarlo."
GS_Gossip[134888456] = "Potresti dirmi dove hanno imprigionato la Cancelliera Amai?"
GS_Gossip[1349535494] = "Come posso dimostrare il mio valore ai furbolg di Timbermaw?"
GS_Gossip[1351762850] = "Certo. L'ho trovato sul cadavere di un nano vicino."
GS_Gossip[13525091] = "Quando Rocket-Chief Fuselage stava cercando volontari per aiutare a costruire la X-52 Nether-Rocket, ho inviato il mio curriculum per la divisione di sicurezza.NEW_LINENEW_LINEPurtroppo, l'unico incarico rimasto era quello di capo ingegnere. Fortunatamente per me, ho Xyrol qui a controllarmi le spalle."
GS_Gossip[1352542190] = "Elder Pamuya è appena fuori da Warsong Hold."
GS_Gossip[1352849518] = "Non possono continuare così! Le loro ali finiranno per cedere..."
GS_Gossip[1352941171] = "Questo fu il sito di una grande battaglia.  Molte grandi battaglie."
GS_Gossip[135336594] = "Il mio nome è J.D., e non posso davvero dirti molto su come sono arrivato qui, ma ciò che posso dirti è che questo campo è adesso la mia casa!NEW_LINENEW_LINEPasso il mio tempo studiando i cristalli strani che si possono trovare ovunque nel cratere. Devi averne visti alcuni per strada. Ehi, per caso ne hai raccolti alcuni?"
GS_Gossip[135373413] = "Saluti, YOUR_CLASS. Posso aiutarti a recuperare i compagni persi."
GS_Gossip[1353774070] = "Benvenuto al Pig and Whistle! Prendi un drink amico mio e tira fuori una sedia, più siamo meglio è!"
GS_Gossip[1355254070] = "I miei colleghi e io stiamo raccogliendo le sostanze piú pericolose che conosciamo e testando gli effetti su i nostri nemici. Una volta che avrò tutto ciò di cui ho bisogno, preparerò delle peste che questo mondo non ha mai visto."
GS_Gossip[1355767789] = "Ecco altri dispositivi incendiari, YOUR_NAME. Prestare attenzione a questi, possono causare un notevole disordine nel tempo se utilizzati in modo improprio."
GS_Gossip[1355969261] = "Dove si trova Elder Wildmane?"
GS_Gossip[1356744806] = "Dove si trova Elder Highpeak?"
GS_Gossip[1359757909] = "Le forze della signora Proudmoore hanno perso sangue per ritardare Archimonde e la sua Legione Infuocata, e ora questo compito cupo spetta a noi. Sei pronto a stare al mio fianco per fronteggiare l'assalto?"
GS_Gossip[1363808580] = "Dai, sembri familiare. Ci siamo già incontrati?"
GS_Gossip[136740157] = "Desidero affrontare il Defiler."
GS_Gossip[137437416] = "Saluti, YOUR_CLASS.  Benvenuti a Cenarion Hold.  Da qui colpiremo i silithid là dove sono più forti.  Spero che siate venuti a dare una mano."
GS_Gossip[1375377769] = "Ciao! E benvenuto! Purtroppo il mio stand non è aperto... sono necessarie molte riparazioni...NEW_LINENEW_LINEMa sono ancora vincolato da un giuramento di sangue a mettere un sorriso sul tuo volto. Quindi per favore, sorridi, o devo tagliarmi la mano e non consumare carne viva fino a quando non si rigenera..."
GS_Gossip[1375903070] = "Lui è nell'anello interno del Quartiere dei Ladri."
GS_Gossip[1377601293] = "Questo è triste. Come è successo?"
GS_Gossip[1379106067] = "Sto diventando sordo. Quella grande harpia verde non smette di parlare per cinque secondi. So guidare questa roba, va bene? Non sono un idiota!"
GS_Gossip[1379680833] = "L'avidità ti ha riportato da me.NEW_LINENEW_LINE<Mathredis rideva.>NEW_LINENEW_LINEUn saggio Draenei mi disse una volta che - la golosità - è la singola qualità che tutte le razze di questo mondo condividono. Dovrei concordare.NEW_LINENEW_LINEHai raccolto i componenti elencati nel libram?"
GS_Gossip[1381697569] = "Ho perso un pezzo dell'Amuleto del Signore Valthalak!"
GS_Gossip[1383011013] = "Benvenuti nella nostra piccola cappella della Luce. Vi prego, prendete posto. Godetevi un momento di pace lontano dai mali del mondo."
GS_Gossip[1383108296] = "Thrallmar ha bisogno di te, YOUR_CLASS. Il capo guerriero ha bisogno di te. Resta pronto a svolgere il tuo dovere."
GS_Gossip[1383624311] = "I furbolg di Winterfall che vivono qui a Winterspring un tempo erano nostri alleati... Ma un giorno, tutto è cambiato.NEW_LINENEW_LINEMosso dalle strane richieste del loro capo, hanno iniziato ad attaccare tutti gli altri con cui entravano in contatto, incluso il nostro clan. Ora si tengono lontani..."
GS_Gossip[138957221] = "Desidero viaggiare a dorso di un grifone."
GS_Gossip[1392747402] = "Dove si trova Elder Sandrene?"
GS_Gossip[1395641955] = "Lo spirito ucciso di Lunaclaw ti guarda intensamente, come se volesse qualcosa da te."
GS_Gossip[1395715792] = "Hai mai sentito parlare di un posto chiamato Dire Maul?"
GS_Gossip[1395845723] = "Hemet è il cacciatore più grande che io conosca. Ci siamo imbattuti l'uno nell'altro nelle colline di Winterspring su Azeroth molti anni fa. Lui e io stavamo inseguendo la stessa preda: il grande gatto noto come Rak'shiri.NEW_LINENEW_LINEPiuttosto che combatterci per la preda, ne abbiamo fatto una scommessa; chi raccoglieva la pelle del frostsaber avrebbe potuto richiedere qualcosa all'altro. Al mio eterno imbarazzo, è così che ho guadagnato il soprannome, Fitz.NEW_LINENEW_LINESembro un Fitz?"
GS_Gossip[1397170813] = "Isto insegna ai cacciatori i modi e le tradizioni dei nostri antenati."
GS_Gossip[1400763049] = "Gioielli, Reliquie & Oggetti per la Mano Libera"
GS_Gossip[1404307783] = "Non sei un bello spettacolo per occhi stanchi!NEW_LINENEW_LINEC'è lavoro da fare e non molto tempo."
GS_Gossip[1405460701] = "Vi presento il Libro della Resilienza."
GS_Gossip[1405567205] = "Nani!!! Ora mi stai dicendo che i nani originariamente venivano dagli Earthen?!"
GS_Gossip[1405857778] = "Il cristalloforno malefico può essere utilizzato per trasformare i tuoi frammenti di apexis in flaconi instabili della bestia. Questi flaconi rendono l'assaggiatore più agile, più forte e più robusto.NEW_LINENEW_LINESembra tuttavia che non possediate le dieci schegge necessarie per acquistare anche una singola fiala."
GS_Gossip[1406791118] = "Il percorso di coloro che intraprendono una professione è lungo e ricco di ricompense. Quale percorso sceglierai di intraprendere?"
GS_Gossip[1411154658] = "Abbiamo catturato l'armureria, YOUR_NAME.  Non fermiamoci sui nostri successi, tuttavia.  La Legione certamente non lo farà."
GS_Gossip[1413013309] = "Scommetterei che Keryn Sylvius conosce il tipo che stai cercando. La compagnia che Keryn frequenta non è proprio onorevole. Di solito si trova all'Inn del Orgoglio del Leone."
GS_Gossip[1418099727] = "Rabbia. Questo è come posso riassumere i miei sentimenti verso tutto questo casino. Abbiamo lavorato fino all'osso per arrivare attraverso la foresta alla riva, solo per scoprire che eravamo arrivati troppo tardi. L'unico modo per tornare a casa era stato distrutto."
GS_Gossip[1418435766] = "Di che tipo di aiuto hai bisogno?"
GS_Gossip[1421023911] = "Cosa è Ysera e come sei stato benedetto?"
GS_Gossip[1421548642] = "Non avevo scelta, o almeno così pensavo. Sarei sopravvissuto alla distruzione di Thaurissan e mi sarei posto al fianco del mio re e del suo popolo.NEW_LINENEW_LINESotto il controllo di Ragnaros, il Re Dagran Thaurissan strappò il cuore di questa montagna e eresse la Blackrock Spire. Abbiamo lavorato incessantemente per costruire una città elfica più potente di qualsiasi città o fortezza che venne prima... o che sarebbe venuta dopo."
GS_Gossip[1424595962] = "Saluti, YOUR_RACE. Sono Franclorn Forgewright. Sei qui per imparare sulla Torre e sui Dark Iron?"
GS_Gossip[142498696] = "Il carretto di frutta di Applebough si trova solitamente nella parte sud-ovest di Dalaran, vicino alla Silver Enclave."
GS_Gossip[1425652436] = "Bene? Non avete teste da far rotolare e tesori da scavare?"
GS_Gossip[1425828903] = "È bello rivederti, amico."
GS_Gossip[1426853555] = "Lo spirito dell'acqua ci ha abbandonati. La nostra tribù è condannata."
GS_Gossip[1427317416] = "Se stai cercando un volo per tornare a Picco del Tuono, allora dovresti parlare con il mio omologo tauren, Bunthen Plainswind."
GS_Gossip[1428993316] = "Cerchi la scheggia del bastone carica per la protezione del Blue Flight?NEW_LINENEW_LINE<Azuregos sembra sorridere.>"
GS_Gossip[1430460270] = "Insegnammi i modi degli spiriti."
GS_Gossip[1431797890] = "Trova Kaplak sopra la tana nella sezione sud-ovest del paese."
GS_Gossip[1431819704] = "Renataki, della Milizia delle Mille Spade.NEW_LINENEW_LINEIl dolore è il suo sangue. La paura, il suo alleato. Possa un giorno tornare e portare con sé un sangue gioioso.NEW_LINENEW_LINERenataki ora abita vicino all'orlo della follia."
GS_Gossip[1432004560] = "Astaia ha pescato alcune curiose tesori nel corso degli anni passati a pescare. Perché non vai a trovarla sulla terrazza dei commercianti e le chiedi di mostrartene alcuni?"
GS_Gossip[1432718765] = "Il Giustiziere Mariel Trueheart ci ha chiesto di provvedere alle esigenze del torneo. Coloro che hanno guadagnato il diritto di stare in piedi come campioni e che si sono dimostrati degni ai nostri occhi sono pregati di aiutare in questi compiti."
GS_Gossip[1435527355] = "Cerca Austil de Mon nella sala da pranzo principale del Gallows' End Tavern. Il tavern è situato nell'angolo sud-est di Brill."
GS_Gossip[1436271926] = "Prenderemo tutto da loro, cavaliere delle ombre."
GS_Gossip[1438668383] = "Sì, YOUR_CLASS?"
GS_Gossip[1439113605] = "Dentro la grande tenda nell'angolo nord-ovest del villaggio risiede Chaw Stronghide. Egli vi insegnerà ciò che dovete sapere sulla lavorazione delle pelli per ora."
GS_Gossip[1439843621] = "I liquidi e le miscele schiumano e si dimenano mentre ti avvicini. Accanto all'equipaggiamento giace una grande pinza che sembra adatta per immergere campioni di melma.NEW_LINENEW_LINEC'è del materiale di protezione presente, ma sembra polveroso e completamente ignorato.NEW_LINENEW_LINENon pensi che toccare qualcosa sarebbe una buona idea."
GS_Gossip[1445737113] = "Sei qui per l'addestramento? Oppure sei qui per sprecare il tempo di un guerriero?"
GS_Gossip[1446150079] = "Servitori del Traditore"
GS_Gossip[1446332888] = "Stringere amicizia con i Sunstrider ha dato i suoi frutti; posso condurre ricerche con soggetti che trovo solo a Outland e loro ottengono... la mia affascinante personalità e il mio aspetto robusto e attraente."
GS_Gossip[1450115354] = "Cerca The Scribe's Sacellum nell'Esposizione Commerciale dei Magi, nel nord-ovest di Dalaran."
GS_Gossip[1450443467] = "Cosa posso fare in un albergo?"
GS_Gossip[1452220885] = "La mia storia? È molto gentile da parte tua chiederlo. Bene.NEW_LINENEW_LINEDa molto tempo fa sul pianeta Draenor - i resti dei quali sono ora noti come Outland - tutti i draenei vivevano in pace. Ma poi la Legione Infuocata arrivò, e corrottero gli orchi con le loro magie felici.NEW_LINENEW_LINECon nessun'altra opzione abbiamo combattuto per sopravvivere, ma l'esposizione a queste energie fel aveva effetti orribili su alcuni di noi, nel tempo trasformandoci nei Rottami come me, o peggio, nei sembranti privi di mente Persi.NEW_LINENEW_LINEDovrei andare avanti?"
GS_Gossip[14527577] = "Gawurgggl! Blrgl-brgl grgl!"
GS_Gossip[1454839359] = "I funghi sanguinari sono più comuni rispetto alle altre varietà di funghi e si possono trovare principalmente ovunque nei boschi intorno a Bloodmyst. Mantieni la tua ricerca a sud della strada che divide Bloodmyst se ti curi della tua vita."
GS_Gossip[1455505862] = "Questo emettitore mi sta facendo impazzire! Perdo tutti i pezzi necessari per ripararlo."
GS_Gossip[1459675845] = "Grazie per l'aiuto nel preparare la pomata, YOUR_NAME. Una volta che avrà avuto la possibilità di attenuare il dolore, vedrò quanto lontano posso arrivare con questa gamba."
GS_Gossip[1459919655] = "Stai cercando reagenti o forniture per veleni? Se è così, sei nel posto giusto!"
GS_Gossip[1461833686] = "Il maestro del volo di Shattrath è Nutral. Lo troverai a est del centro della città."
GS_Gossip[1462620957] = "Non ci sono emozioni. Non ci sono moralità. Non ci sono zelanti.NEW_LINENEW_LINEC'è solo la Fratellanza.NEW_LINENEW_LINEEcco, nella chiesa dove Uther il Portatore di Luce ha aderito all'Ordine della Mano d'Argento, io, Korfax, Campione della Luce, ispirerò terrore nei coraggiosi.NEW_LINENEW_LINENiente potrà contenere la mia furia - non la Crociata Scarlatta, non l'Alba d'Argento, non i miei fratelli, nemmeno te."
GS_Gossip[1463459841] = "Sono interessato alla formazione del mago oscuro."
GS_Gossip[1463721462] = "Hai ballato già al palo del nastro?"
GS_Gossip[1464805761] = "Vuoi acquistare alcuni oggetti pirateschi?"
GS_Gossip[147466390] = "La Mano Frantumata riporterà l'Orda al suo antico splendore."
GS_Gossip[1477466707] = "Karazhan non era sempre così... minaccioso. L'oscurarsi di Karazhan arrivò solo con la morte di Medivh. O almeno, così crediamo."
GS_Gossip[1477555281] = "Vai, YOUR_NAME, nel Bacino d'Arathi! Uccidi, UCCIDI, come non hai mai ucciso prima!"
GS_Gossip[1477888611] = "Un seguace dell'arcano sei tu? Hmph! Va bene... li puoi trovare intorno alle Piscine della Visione sotto l'Alto Spirito."
GS_Gossip[1478024960] = "Le mie scuse, non mi ero reso conto che potessi comprendere ciò che stavo dicendo. Cosa stai facendo qui fuori?"
GS_Gossip[1483098438] = "Hai visto dove hanno portato l'ingegnere Sanitario Burke?"
GS_Gossip[1486309394] = "Se state cercando l'incantatrice Eredania, non cercate oltre la piccola festa di Saltheril. Lei ha ricevuto il suo invito qualche giorno fa."
GS_Gossip[1491212245] = "Maledetti questi dannati Flagello se pensano di spostarci! Noi coloni abbiamo sacrificato tutto per iniziare una nuova vita nel Nordrend.NEW_LINENEW_LINEDovrai crederci, combatteremo fino all'ultimo respiro."
GS_Gossip[1491461943] = "<Il suono del messaggio di A'dal risuona rassicurante nella tua mente.>NEW_LINENEW_LINENon preoccuparti, figlio. Guarda nella tua bisaccia e lo troverai nuovamente."
GS_Gossip[1493079952] = "È fantastico far parte del club \"Brew of the Month\"."
GS_Gossip[1494760878] = "Questo è affare di troll. Cerca Un'Thuwa nel villaggio di Sen'jin a sud."
GS_Gossip[14996552] = "Le pelli più resistenti provengono dai kodo che si sono riposati in questa terra desolata."
GS_Gossip[1502898294] = "Hai fatto un buon inizio, ma hai ancora molto da imparare, YOUR_NAME."
GS_Gossip[150325166] = "Abbiamo un banchetto davvero speciale per te, amico."
GS_Gossip[1505578189] = "Benvenuto nel Circolo Cenariano, YOUR_CLASS."
GS_Gossip[1507581995] = "Se hai veramente il desiderio di imparare questa professione, ti indirizzerei verso Ainethil, un alchimista esperto alla Terrazza degli Artigiani nel nord di Darnassus."
GS_Gossip[1511151697] = "Come nuovo arrivato in Ogri'la, non hai ancora sufficiente familiarità con i cristalli presenti qui per poterne trarre tutti i benefici. Inoltre, hai solo una testa.NEW_LINENEW_LINENoi, invece, siamo qui da molto, molto tempo. Quindi, come puoi immaginare, siamo abbastanza esperti in molte cose.NEW_LINENEW_LINEDi recente, abbiamo preso un interesse particolare per i demoni dei campi di fabbrica. Più specificamente, abbiamo escogitato un modo per sbarazzarcene per sempre.NEW_LINENEW_LINEAlmeno, questa è la teoria."
GS_Gossip[1512161327] = "Chi è questo Terokk di cui continui a parlare?"
GS_Gossip[1516562028] = "Ehi. Sono in pausa."
GS_Gossip[151746338] = "Dimmi di più sul Pilone di Cristallo Orientale."
GS_Gossip[1517966917] = "Carne, pelle, ossa... un bravo cacciatore non spreca niente. Ogni brandello di pelle può essere recuperato, forse per rinforzare l'armatura di un alleato. Così, ognuno di noi è forte da solo, ma insieme diventiamo invincibili."
GS_Gossip[1519725365] = "Fatemi vedere cosa avete da offrire."
GS_Gossip[1521460923] = "Sylann, una delle migliori cuoche della città, si trova al piano superiore del taverniere Wayfarer's Rest. È possibile acquistare anche attrezzatura da cucina dal suo assistente lì."
GS_Gossip[1522731004] = "Prenderò il volo."
GS_Gossip[1522868900] = "Benvenuto nel Campo Oneqwah."
GS_Gossip[1524664626] = "Riuscire ad uscire da qui senza una lama alle spalle o veleno nel sangue sarebbe un'impresa."
GS_Gossip[1528683312] = "Hai strappato il controllo dell'Oculus alle forze di Malygos. Il volo rosso è in tuo debito."
GS_Gossip[153187449] = "Cosa è quello $T scrub : girlie;?  Vuoi la tua mamma?  Beh, peccato.  Forse dovresti fare una visita al club degli ufficiali di Thrallmar per riprenderla?"
GS_Gossip[1534341987] = "Portami indietro alla vita"
GS_Gossip[1534568228] = "Mi insegnano a muovermi bene. Li trovi nel Quartiere dei Ladri nell'anello esterno della Sepulcra."
GS_Gossip[1535633268] = "Pietra del Portale"
GS_Gossip[1545750003] = "Mantieni gli occhi aperti, YOUR_CLASS.  Non sai mai quando un animale selvaggio ti sta osservando invece che l'inverso."
GS_Gossip[154674175] = "Benvenuto, YOUR_NAME.  Siamo gli Aldor, sacerdoti della Luce e servitori dei Sha'tar.NEW_LINENEW_LINEBenvenuto a rimanere con noi per quanto tempo ne hai bisogno."
GS_Gossip[1547629486] = "In un posto chiamato Feralas a ovest di qui, i hippogryf, antichi compagni degli elfi notturni, sono in pericolo.NEW_LINENEW_LINEHai bisogno di salvare un uovo dalle rovine di Isildien, a sud, là. Il Super Egg-O-Matic può analizzare qualsiasi uovo portato a lui e giudicare se è probabile che schiuda. Poi invio gli uova ai druidi, al sicuro dalle oscure magie degli orchi Gordunni.NEW_LINENEW_LINEPrego di sapere, YOUR_NAME, alcuni degli uova salvate sono uova cattive, e non si schiuderanno mai."
GS_Gossip[1548066713] = "Per anni, la Rocca dell'Onore ha resistito agli orrori della Penisola del Fuoco Infernale. Ora, ora che il portale si è riaperto e l'aiuto giunge da Azeroth, forse questo stallo sanguinoso finirà."
GS_Gossip[1556904258] = "Siamo sicuri. Andiamo!"
GS_Gossip[1560628178] = "Ho perso la mia pistola a luce di Kor'kron, signore. Posso averne un'altra?"
GS_Gossip[1562910816] = "Ho poco tempo per parlare, scusa."
GS_Gossip[1567164697] = "So chi sei, YOUR_NAME.  Destino e forze al di là di esso ti hanno portato da me per una ragione, e ne prendo piacere nel farne parte.  Ci saranno molte decisioni che prenderai nei tempi a venire, e spero che tu sia abbastanza saggio da prendere quelle giuste.NEW_LINENEW_LINECredimi, YOUR_RACE, quando ti dirò questo - ci sono scelte corrette."
GS_Gossip[1568181092] = "Zul'Farrak nel deserto di Tanaris è la casa di Elder Wildmane."
GS_Gossip[1569814250] = "Di che ne sai, Franzahl?"
GS_Gossip[1570770704] = "Ti dirigi verso l'anello interno dell'Apothecarium. Lavinia Crowe è là."
GS_Gossip[1570991052] = "Korfax, dove posso trovare frammenti di ferro nero?"
GS_Gossip[1573489588] = "C'è qualcosa qui. È nelle rocce e nella terra!"
GS_Gossip[15758835] = "Perditi prima che ti sconfigga con il mio boomerang."
GS_Gossip[1586485995] = "<Il soldato dimenticato scuote la testa.>NEW_LINENEW_LINENon possiamo continuare così, amico. Se il Principe Arthas non torna presto, tutti noi periremo."
GS_Gossip[1590010863] = "I cani normali non si avvicinano più a me da quando ho scoperto... ero solito adorare quelle bestie.NEW_LINENEW_LINEI Plaguehounds fanno un ottimo sostituto, tuttavia. Non sono proprio... così facili da guardare. Ma allora, neanche io!"
GS_Gossip[159295919] = "È solo questione di tempo prima che la peste sopraffaccia New Avalon."
GS_Gossip[1598357331] = "Siamo pronti. Questa volta le cose saranno diverse."
GS_Gossip[1601046189] = "Ho perso il mio Tabard dell'Esploratore."
GS_Gossip[1602062216] = "Questi neonati vivranno. Con amore e affetto cresceranno per diventare forti membri dell'Orda, e col tempo i terribili ricordi delle loro vite spezzate svaniranno."
GS_Gossip[1603759294] = "Ishnu-dal-dieb, YOUR_NAME. Hai cercato qui la conoscenza?"
GS_Gossip[1603821088] = "Vai a Riposo delle Stelle nel Dragonblight e troverai l'Anziano Morthie."
GS_Gossip[1604029285] = "Perché celebriamo il Ringraziamento del Pellegrino...? Chi può dirlo. Abitudine, suppongo. Certamente non riesco a gustarne nessuno.NEW_LINENEW_LINETorta di zucca, piaghe virulente... Ha realmente importanza COSA stiamo preparando?"
GS_Gossip[1604845164] = "Ah, vedo che sei un amico del Consorzio. Forse ti interesserebbe fare un acquisto?"
GS_Gossip[1608798858] = "Ecco, se vuoi andare a parlare con quegli ingegneri nell'anello esterno del Quartiere dei Ladri, è la tua pelle."
GS_Gossip[160900068] = "Voglio volare sulle ali della spedizione rossa."
GS_Gossip[1609524293] = "L'ultima cosa di cui avevamo bisogno era che i pazzi troll Drakkari sparassero giù una necropoli del Flagello nel nostro cortile.NEW_LINENEW_LINECome hanno fatto a farlo?!"
GS_Gossip[160976864] = "Esistono altri mazzi?"
GS_Gossip[1610512372] = "Sono esattamente ciò di cui hai bisogno per distruggere in modo da liberare il reggimento! Come avevo detto prima, Kirith aveva un piano.NEW_LINENEW_LINEOgni servitore ha una debolezza. Punire la loro forma fisica in prossimità delle loro pietre finché non si avvicinano allo stato di disgregazione. È in quel momento, e solo in quel momento, che le pietre di legame diventano vulnerabili all'attacco. Dovrai però affrettarti a distruggere le pietre, poiché una volta che gli schiavizzati riprendono la calma, saranno nuovamente invulnerabili al danno."
GS_Gossip[1610724503] = "Salve a te YOUR_NAME.  Vuoi che ti aiuti nel tuo viaggio verso la Forra dei Cantaguerra?"
GS_Gossip[161428129] = "Pugnale"
GS_Gossip[1614901876] = "Li puoi vedere, mortale? No... Non credevo che potessi. Visti ma ciechi - è il tuo dono e la tua maledizione."
GS_Gossip[1617918632] = "Dovrai andare a Orgrimmar per quello. Segui semplicemente la strada che esce da Razor Hill verso nord attraverso la gola e arriverai lì. Quando arriverai, chiedi a uno dei loro soldati per ulteriori indicazioni."
GS_Gossip[162384525] = "Come suggerisce il nome, puoi trovarlo vicino a rovine. Loreth'Aran ha la risposta.NEW_LINENEW_LINEIn effetti, il nome non suggerisce realmente ciò -- stavo solo cercando di essere furbo nel dare un nome ai funghi."
GS_Gossip[1624331127] = "Non chiedere..."
GS_Gossip[1624404942] = "Vorrei visionare i tuoi beni"
GS_Gossip[1625199277] = "Il Capitano Selana mi ha istruito ad aiutarti nei tuoi sforzi qui sulla Sunwell Plateau."
GS_Gossip[1625448574] = "Dove è rimasto?"
GS_Gossip[1627457655] = "Il sole è già sorto? Non ci sono mai abbastanza ore durante la notte! Bene, Saelienne si prenderà cura di te. La puoi trovare che si occupa dei suoi ospiti sulla Terrazza degli Artigiani, a nord-est di Darnassus."
GS_Gossip[1629253884] = "Ci sono coloro che tentano di seguire la via del Ladro, ma solo gli elfi notturni sono veramente accettati dalla notte. Se cerchi di camminare sulla via ombrosa, allora trova Syurna nell'Enclave Cenarion."
GS_Gossip[1630083874] = "Sono pronto per essere teletrasportato a Dalaran."
GS_Gossip[1633136242] = "Grazie, Kodian. Farò quanto posso."
GS_Gossip[1638896224] = "Non parlare la tua lingua volgare con me! Solo Hydraxis può sopportarla."
GS_Gossip[1639173799] = "Tomas potrebbe non essere il miglior cuoco del posto, ma ha un paio di piatti che colpiscono nel segno. Al momento sta lavorando all'Inn della Superbia del Leone se volete imparare la professione."
GS_Gossip[1639369624] = "L'Isola della Conquista è carica di risorse preziose che non possiamo permettere che cadano nelle mani dell'Orda. Vuoi unirti alla battaglia?"
GS_Gossip[1640478740] = "Permesso di visualizzare il tuo menù stagionale."
GS_Gossip[164138595] = "Il maestro dei cavalieri del vento"
GS_Gossip[1642784875] = "Non sono bellissimi i disegni? Ogni uno parla con la sua voce."
GS_Gossip[1643181084] = "Ho bisogno di un po' di alcol, Coot."
GS_Gossip[164433589] = "Ah, una buona domanda.NEW_LINENEW_LINESe preferisci cacciare all'aperto, qui nei Plaguelands, Azshara, Burning Steppes, Felwood, Silithus, Winterspring e anche nel Cratere di Un'Goro ci sono elementali.NEW_LINENEW_LINESe sei il tipo che ride in faccia al pericolo, forse dovresti visitare Dire Maul. Ho sentito che all'interno delle sue mura esistono molte aberrazioni elementali. Farebbe anche molto bene cercare gli elementali impiegati dai nani Dark Iron delle profondità di Blackrock."
GS_Gossip[1649211887] = "Con tutta la lotta che facciamo, ovviamente abbiamo un Allenatore di Prima Aid a Razor Hill. Trova Rawrk all'interno dei caserma sul lato est del paese."
GS_Gossip[1649920383] = "Stai sprecando tempo. Vai a uccidere i sottoposti del Re dei Lich, YOUR_CLASS!"
GS_Gossip[1651213937] = "Permesso di guardare le tue merci, Cookie."
GS_Gossip[1659040285] = "<Il costrutto indica la porzione orientale del Tier.>"
GS_Gossip[1660134783] = "È bello essere il re! Ora, torniamo a ciò di cui stavamo parlando prima..."
GS_Gossip[1661158367] = "Throm'ka, YOUR_CLASS. Lo sapevi che la nostra battaglia con i Guardiani d'Argento nei pressi della Forra dei Cantaguerra continua ancora? La tua presenza sarebbe benvenuta là..."
GS_Gossip[1662355092] = "Sono Kessel, signore degli elekk, discepolo della Mano di Argus. Sei il nuovo recluta?"
GS_Gossip[166329006] = "Guarda alle tue spalle, YOUR_RACE. La covata si agita mentre la terra che ci circonda trema e si scuote.NEW_LINENEW_LINEÈ arrivato il momento che io adempi a una promessa fatta mille anni fa. I sabbia si muovono nuovamente mentre i Qiraji pianificano la guerra."
GS_Gossip[1663944899] = "Jack Trapper può essere trovato a cucinare nel mercato all'aperto della città bassa, nel sud-est."
GS_Gossip[1670069849] = "Hai l'aria smarrita, YOUR_CLASS. Non farmare che ti metto a lavorare sulle pareti insieme agli altri peoni."
GS_Gossip[1670374273] = "Quando la Fiera di Lunacupa si apre, sarà situata a Mulgore.  Pitcheremo le nostre tende proprio a sud-ovest del Picco del Tuono!"
GS_Gossip[167062679] = "Voglio diventare un fabbro."
GS_Gossip[1673869081] = "Lasciami in pace, idiota!"
GS_Gossip[1674133529] = "Fognature"
GS_Gossip[167811758] = "Benvenuto nel mio negozio, YOUR_CLASS. Cosa possono fare per te i fratelli Goodstitch?"
GS_Gossip[1679293868] = "Ma tu dici 'Butcher'? Oh, un addestratore di Prima Aid! La stessa cosa. Quando vedrai la Nurse Neela in piedi appena all'interno del Gallows' End Tavern sul lato sud-est del paese, capirai il motivo."
GS_Gossip[1680175322] = "Sei perso? La maggior parte dei commercianti del paese si trova vicino al centro del paese."
GS_Gossip[1681537573] = "Catturare il Santuario della Portata del Sole è stato il primo passo del nostro piano di battaglia. I nostri ordini sono di prendere il controllo dell'arsenale successivamente.NEW_LINENEW_LINESiamo $3233w percento completato del nostro obiettivo."
GS_Gossip[1681774619] = "Non sono sicuro di dove si trovi il zeppelino in questo momento, in effetti..."
GS_Gossip[1682017906] = "Sono un prigioniero!NEW_LINENEW_LINEMi hanno sparato e il mio magnifico zeppelino fuori dal cielo. E per cosa? Perché stavo trasportando uomini e materiali per l'Orda? Non è niente di nuovo!NEW_LINENEW_LINEOra mi fanno correre in cerchio attorno alla baia in modo che possano bombardare i pirati. Non ho semplicemente le parti necessarie per mantenerla in funzione in questo modo! Sto appena riuscendo a tenerla insieme con della saliva e filo di ferro!NEW_LINENEW_LINENon sarò responsabile di ciò che ti accadrà, ma potresti comunque salire a bordo prima che se ne vada.NEW_LINENEW_LINEÈ un crimine, te lo dico io!"
GS_Gossip[1682418333] = "Per mantenere il nostro collegamento con il continente, abbiamo iippogriofi che volano costantemente tra Rut'theran Village e Darkshore."
GS_Gossip[1683607807] = "Il zeppelino dovrebbe appena aver raggiunto Orgrimmar."
GS_Gossip[1684406684] = "La raccolta e la conoscenza delle erbe è una specialità di Firodren Mooncaller. Cercalo nei Giardini del Tempio nell'area sud-occidentale di Darnassus."
GS_Gossip[1684902866] = "Cosa posso fare per te, YOUR_RACE?"
GS_Gossip[1686873363] = "Lode a Elune! Sono passati molti anni da quando ho avuto visitatori."
GS_Gossip[1687030487] = "Sì, lo faccio!"
GS_Gossip[1687399989] = "C'è un potente infernale chiamato Kroshius a nord-est di questo accampamento. È il motivo per cui Niby è qui. Kroshius è un infernale maggiore - un infernale che ha durato più a lungo del previsto. Vedi, nub, un infernale precipita sulla terra con grande intensità per servire il suo padrone, ma questa intensità svanisce rapidamente. Una volta che le fiamme ardenti si sono spento, l'infernale si disintegra."
GS_Gossip[1687455442] = "Cerchi un tabard?"
GS_Gossip[1689955471] = "Sì, giovane, non devi convincermi di queste cose, il Capo delle Guerre e io abbiamo molto storia. Tuttavia, la tua dedizione è nota.NEW_LINENEW_LINECome dicevo, Rend aveva trovato una nuova casa per il suo popolo, e io ero tra coloro che avrebbero seguito con riluttanza.NEW_LINENEW_LINEDa un conflitto ne sono nati altri... innumerevoli altri. Fu in quelle battaglie per la Blackrock Spire tra la famiglia Blackrock e i nani Dark Iron che i miei figli sono entrambi morti. Fu in quel momento che ho realizzato che il mio tempo tra la famiglia Blackrock era giunto alla fine."
GS_Gossip[1693580910] = "Ciao, piccolo YOUR_RACE."
GS_Gossip[1693725884] = "Ero un giovane tauren, appena entrato nell'adolescenza, ma sapevo che coloro che avrebbero affrontato le battaglie per la nostra libertà erano ben protetti nei mantelli che portano il mio nome."
GS_Gossip[1695374073] = "Come posso aiutare?"
GS_Gossip[1697423757] = "Sono pronto a tornare nel regno dei vivi."
GS_Gossip[1698953274] = "Guarda nelle acque che dividono quest'isola, ma ti avverto: lo stinkhorn striker ha il suo habitat nelle acque del fiume."
GS_Gossip[1701008994] = "Il Nonno Inverno può essere trovato davanti alla banca di Forgiardente. L’albero vicino a lui è dove vengono distribuiti i regali."
GS_Gossip[1701048857] = "Non sentiamo nulla. Le nostre anime restano qui, nell'limbo. Non possiamo lasciare finché i nostri resti non vengono trovati e le nostre anime non vengano riposate."
GS_Gossip[1701058658] = "Successo! Mi sono accordato con il Citadello dell'Inferno e la magia al suo interno. Ah, tale potere!NEW_LINENEW_LINECi sono innumerevoli orchi felici in quel posto... ma non è tutto! Percepisco potere demoniaco all'interno di quelle mura come pure...NEW_LINENEW_LINESe ti apri, allora prenderò brevemente, ti prego, il controllo della tua mente e userò la penna per registrare i miei risultati per te..."
GS_Gossip[1702596091] = "La resistenza di Woo Ping è semplicemente sbalorditiva. Guardandolo allenarsi per ore con le sue tecniche d'arma, mi dispiaceva per il manichino successivamente. Non riesco a immaginare nessuno più adatto per addestrarti nel combattimento armato."
GS_Gossip[170387030] = "Esiste un mercato nero di sorta nella parte nord-orientale delle fogne."
GS_Gossip[1704905872] = "Devi sconfiggere i nostri rivali in uno qualsiasi dei Campi di Battaglia. Con ogni vittoria, c'è una possibilità che ti venga inviato un Medaglione d'oro."
GS_Gossip[1706440851] = "Questo è strano..."
GS_Gossip[1707146134] = "Il Capitano Spaventoso DeMeza ha attraccato alla Baia del Bottino e ha dichiarato che è il Giorno dei Pirati!NEW_LINENEW_LINESta rendendo onorario membro dell'equipaggio chiunque abbia il coraggio di condividere un drink con lei."
GS_Gossip[1707237064] = "Stai cercando di diventare un taxidermista? Non mi piacciono le persone che pensano di potermi imbalsamare e appendermi perché pensano che io sia morto. No? Bene! Cerca Rand Rhobart in un accampamento a sud-est della città. Per raggiungerlo, prendi la strada a sud-est da Brill e gira a sinistra all'incrocio."
GS_Gossip[1710523743] = "Questo non ti riguarda. Vattene."
GS_Gossip[1711147109] = "Il Sogno Verde è diventato un posto pericoloso. Mi preoccupo sempre di più per coloro che hanno sacrificato la loro vita risvegliata in Azeroth nella speranza di salvarla."
GS_Gossip[1713026216] = "Niente da vedere qui, amico. Vai pure, perché non lo fai?"
GS_Gossip[1713119235] = "Riagenti & Merci Magiche"
GS_Gossip[1715221760] = "Solleva la coda del leopardo delle nevi per verificare se è maschio o femmina."
GS_Gossip[1717870296] = "Devo trovare Zepik, hai il suo corno da caccia?"
GS_Gossip[172058536] = "C'è un erborista che vive nelle colline a est di Roccavento insieme al nostro alchimista. Una combinazione molto utile, non ti sembra?"
GS_Gossip[172408129] = "Sì. L'ho."
GS_Gossip[1724584486] = "Elder Yurauk può essere trovato nelle Sale di Pietra."
GS_Gossip[1725769008] = "Dove è detenuto il Senior Scrivener Barriga?"
GS_Gossip[1728329126] = "Il mio fratello ha detto che potremmo guadagnare molto denaro con questa rotta commerciale, ma non mi ha detto che sarei io a vivere da questa parte. Se torni indietro in questo modo sulla Zeppelino, potresti portarmi qualcosa da mangiare? Vendi alcuni dei migliori tagli di carne a Orgrimmar, e sicuramente mi servirebbe qualcosa che non è morto settimane prima che smettesse di muoversi."
GS_Gossip[17286893] = "Sono già stato a Forgiardente. Lì c'è un odore strano."
GS_Gossip[1734383097] = "Vedo acciaio torcito e sento terra squarciata."
GS_Gossip[1735046353] = "È possibile imparare a pescare vicino alla fontana incantata nell'Eventide, un quadrato nel sud di Dalaran."
GS_Gossip[1740419758] = "Come?? Beh, è una lunga storia."
GS_Gossip[1742433926] = "Le mie sorelle e io siamo venute giù dalle Montagne di Pietraaffilata per porre fine a una tragedia del passato. Purtroppo, non siamo abbastanza potenti da raggiungere i nostri obiettivi da soli e ora cerchiamo mortali come te per aiutarci.NEW_LINENEW_LINESe sei abbastanza potente, allora abbiamo molto di cui discutere, YOUR_CLASS. Se non lo sei, per la tua sicurezza, lascerò fuori dalla nostra conversazione i dettagli del mio incarico."
GS_Gossip[1744621498] = "Ho bisogno dell'aiuto di un altro cacciatore di spiriti, Ar'tor."
GS_Gossip[1744639019] = "I nostri antenati ci insegnano che mentre l'individuo deve essere forte, c'è sicurezza in numeri. Desideri difendere l'onore di Picco del Tuono organizzando una guilda?"
GS_Gossip[1744890447] = "L'apertura del Portale Oscuro ha portato notizie sulla sorte del mio popolo. In un certo senso, l'esilio mi ha protetto dal condividere il loro declino, ma vedere i Farstriders schierarsi con Kael'thas...NEW_LINENEW_LINENon ho mai immaginato i miei un tempo fratelli capaci di una cosa del genere.NEW_LINENEW_LINEIl ritorno che un tempo sognavo non avverrà mai. Questa foresta è l'unica casa che mi rimane."
GS_Gossip[1745413576] = "Devi utilizzare le bombe incendiarie sui barili all'interno dei dormitori di internamento di Durnholde Keep. Una volta che cinque bombe sono state accese e la distrazione è stata messa in atto, trova Thrall nella prigione del seminterrato di Durnholde e liberalo. Seguilo e assicurati che non muoia!NEW_LINENEW_LINEBrazen ti porterà a Durnholde quando sarai pronto."
GS_Gossip[1746223418] = "Benvenuto nel mio negozio. Cosa posso fare per te?"
GS_Gossip[1747953024] = "Il cimitero della città si trova proprio a nord della Cittadella Viola nell'occidentale Dalaran."
GS_Gossip[1749269769] = "<Grugniti>  Immagino che quelle montagne siano apparse dal nulla...  Tutte e cinque le volte!"
GS_Gossip[1750211580] = "Crafty, ho perso il mio travestimento di orco Warsong."
GS_Gossip[1750359469] = "Sì, sono sicuro che la sicurezza è la tua priorità. Dammi un pacchetto a reazione a razzo."
GS_Gossip[175062480] = "FINE! E come, oserei chiedere, dovrei acquisire un galleggiante di arcanite?"
GS_Gossip[1751821369] = "Probabilmente puoi sentire Tognus che batte sull'incudine quando sei a Kharanos. Tuttavia, se non hai pulito recentemente il cera dalle tue orecchie, allora perché non vai a dare un'occhiata nel laboratorio dell'armaio."
GS_Gossip[1751916431] = "Oh, stai cercando un po' di illuminazione arcana? Non c'è posto migliore del Santuario del Mago nel Quartiere dei Magi."
GS_Gossip[1754026525] = "Se devo insegnarti i segreti dell'evocazione di un servo infernale, devi distruggere Kroshius e portarmi il nucleo infernale dai suoi resti bruciati. Tuttavia, non è così facile come sembra. Kroshius è quasi completamente bruciato. Devi riaccendere il suo corpo e risollevarlo dai detriti. Per farlo, tuttavia, devi raccogliere alcuni componenti da altre entità demoniache.NEW_LINENEW_LINEIl mio demone, Impsy, ti accompagnerà nel tuo viaggio."
GS_Gossip[1754291190] = "Ciao, supervisore. Sei pronto per l'attacco?"
GS_Gossip[175507249] = "Bene, questo è preoccupante! Come diavolo dovrei raccogliere i campioni di minerale per i magi se le miniere sono state invase da vermi gnoll?"
GS_Gossip[1756552529] = "Non è sempre questione di denaro, clem! Mentre riceviamo generose donazioni - alcune estremamente sostanziose - il nostro gruppo itinerante di artisti è alimentato creativamente dal bisogno di illuminare questo mondo devastato dalla guerra. Non preoccuparti per noi, ma piuttosto lascia che ci preoccupiamo di come intrattenervi meglio."
GS_Gossip[1757009722] = "Desidero dimenticare la Maestria delle Pozioni."
GS_Gossip[17580017] = "Il Re Magni si aspetta che vinciamo il torneo e lo rendiamo orgoglioso. Non falliremo."
GS_Gossip[1760209696] = "Cosa è successo qui, spirito?"
GS_Gossip[1761744352] = "Guardati intorno, sciamano. Puoi vedere l'equilibrio degli elementi nella terra, nell'aria, nell'acqua e nel fuoco che hanno toccato tutti?"
GS_Gossip[1763684932] = "È davvero un piacere rivederti, YOUR_NAME."
GS_Gossip[1764183173] = "Non so cosa è successo. Appena arrivato a Venomspite, all'improvviso mi sono svegliato in questa gabbia!NEW_LINENEW_LINESei qui per salvarmi?"
GS_Gossip[1768588877] = "Wushoolay, la Strega della Tempesta.NEW_LINENEW_LINEIl suo potere è il potere del cielo, della pioggia e della terra spezzata. Possa egli nuovamente regnare come padre dei Gurubashi.NEW_LINENEW_LINEWushoolay ora dimora lontano da qui. Un giorno, potrebbe tornare..."
GS_Gossip[1769093901] = "Oh... Mi sento stordito..."
GS_Gossip[1770507030] = "YOUR_NAME!  Grazie ancora per tutti gli aiuti."
GS_Gossip[1771364927] = "Mmrrglglglg? Glbmr brmmrggl glmrrbmrgl.NEW_LINENEW_LINEGrglgrlbrr mrgl!!!"
GS_Gossip[1777781895] = "Mi divertivo a intrattenermi accettando sfide da chiunque le offrisse, ma da tempo ne ho avuto abbastanza di tali vittorie facili.NEW_LINENEW_LINEPer ora, sto prendendo un po' di tempo per mettere a punto il mio business di reagenti e scrivere un libro sulle mie esperienze con il Martello del Crepuscolo."
GS_Gossip[1780340714] = "Mi stavi raccontando del Coltellaccio Velato e di come hai preso la missione sbagliata."
GS_Gossip[1781267689] = "Mi capisci? Ora dovremmo essere in grado di capirci."
GS_Gossip[1781728627] = "È una maggiore conoscenza dei modi del mago oscuro che desidero."
GS_Gossip[1781735176] = "Benvenuto a Theramore."
GS_Gossip[1783894998] = "Cap'n Stash è IL MIGLIORE!"
GS_Gossip[1786261557] = "Glumrggl?"
GS_Gossip[178858979] = "Barnil, sembra che io abbia perso il Capitolo III."
GS_Gossip[1789308538] = "Un furbolg chiamato Tur Ragepaw. Non uno dei nostri.NEW_LINENEW_LINEQuesto proviene dalle terre meridionali. Era della tribù Timbermaw.NEW_LINENEW_LINEVoleva vedere Ursoc. Sembrava pensare che l'onta di Vordrassil potesse essere purificata e utilizzata per salvare mio padre.NEW_LINENEW_LINEÈ folle nutrire tali speranze. Accetterai quando vedrai l'oscurità che lo ha colpito, come ho visto io."
GS_Gossip[1792285987] = "Attrazioni?"
GS_Gossip[1793940272] = "Se stai cercando un martello, sei nel posto giusto."
GS_Gossip[1795303954] = "Cucito? Hmm. Ah sì, ovvio. Dovrai andare a Picco del Tuono, a nord. Prendi il sentiero fuori dal villaggio per arrivarci. Quando arriverai alla base delle colline, prendi l'ascensore fino in cima e parla con uno dei Guardiamonti."
GS_Gossip[1795627665] = "Se un giorno incontri il Dottore delle Streghe Tor'gash, digli che i suoi rimedi e i suoi amuleti non funzionano! Ho fatto esattamente ciò che mi ha detto eppure Magasha ha gli occhi solo per Zurai.NEW_LINENEW_LINENon credere una parola a quel vecchio stregone!"
GS_Gossip[1795787800] = "L'Apexis Monumento si erge sopra di te."
GS_Gossip[1798937955] = "Gli umani hanno rivendicato gran parte della Palude delle Ceneri, ma la tribù delle Martelli di Pietra, con il nostro aiuto, è riuscita a respingerli."
GS_Gossip[1803718094] = "Forse dovrei dirti perché sono qui.NEW_LINENEW_LINEConosci l'Aspetto, Deathwing? O i suoi progenitori, Nefarian e Onyxia?"
GS_Gossip[1804454305] = "Qualcosa che posso fare per te, Boss?"
GS_Gossip[1804674512] = "I segni su questa tavola mostrano diagrammi antichi e contengono parole potenti e terribili, ma il loro significato è incomprensibile per te."
GS_Gossip[1804950992] = "Non capisco perché vorresti lasciare queste spiagge sole e queste acque cristalline. È come un paradiso qui sotto. Ma non dirlo a mio fratello Zapetta, è già abbastanza amaro per essere bloccato lassù a Tirisfal tutto il giorno. Questa Zeppellina qui fa scalo a Orgrimmar, quindi non dovrai preoccuparti di dover ascoltare i suoi lamenti. Ma se ti trovi a Tirisfal presto, presto attenzione al mio avvertimento e non fargli cominciare."
GS_Gossip[180569270] = "L'acquabramo Hydraxis si nasconde in Azshara, su un'isola nella Baia delle Tempeste. Che tipo di minaccia può radunare l'idiota da lì?"
GS_Gossip[1805983655] = "Desidero acquistare materiali per le arti e mestieri."
GS_Gossip[1806858294] = "Portatemi fuori di qui, YOUR_RACE!"
GS_Gossip[1808178734] = "La mia vista è piena di visioni di eventi che si svolgono in tutto il mondo e di quelli che potrebbero ancora accadere. Molti di essi sono cupi, ma non dobbiamo credere che siano incapaci di cambiare."
GS_Gossip[1808582051] = "Dove si trova l'anziano Chogan'gada?"
GS_Gossip[1808771742] = "Sto cercando un compagno perso."
GS_Gossip[1811292716] = "<Isfar sospira.>NEW_LINENEW_LINEUn paio di casette tra gli alberi non fanno una casa, ma era un miglioramento considerevole rispetto alle Sale di Sethekk.NEW_LINENEW_LINEComoda com'era a Shattrath, non riesco a tornare al mio vero domicilio a Skettis senza mia sorella. È ancora intrappolata nelle Sale di Sethekk, prigioniera del nostro fratello maggiore."
GS_Gossip[181261706] = "La porta è aperta, Kharan. Sei un uomo libero."
GS_Gossip[1816281605] = "Saluti, giovane, e benvenuto nel Picco del Tuono. Troverai qui un rifugio sicuro dalle fatiche del mondo. Tutti i membri dell'Orda sono benvenuti qui.NEW_LINENEW_LINEGli spiriti del presente e del passato prendono vita qui in questo luogo sacro, mio amico. Onorali, e in tal modo onorerai te stesso."
GS_Gossip[1818174794] = "È buono vederla viva e in salute, YOUR_NAME!"
GS_Gossip[1819141660] = "Sarebbe meraviglioso! Grazie, Meridith."
GS_Gossip[181935251] = "Altruis mi ha mandato. Ha detto che potresti aiutarmi."
GS_Gossip[1819883799] = "<L'agente Sunhawk catturato sorride.>NEW_LINENEW_LINENon preoccuparti, nuovo sangue, ci sono molti altri controllori di portale e molti altri luoghi adatti per i portali. Sono certo che Sironas installerà una nuova porta molto presto. Questi cani con pelle blu non sono destinati a rimanere in questo mondo. Sironas e l'abominio puliranno tutto ciò che le forze dei Sunhawk lasceranno indietro."
GS_Gossip[1819977082] = "Druidi? Non ne ho visti nessuno da queste parti. Sebbene esista un quartiere a Roccavento che è diventato proprietà delle notti elfiche."
GS_Gossip[1820117346] = "Mi temo che non sopravviveresti a lungo nella Valle d'Alterac, YOUR_CLASS.  Torna a trovarci quando avrai vissuto un paio di altre stagioni."
GS_Gossip[1820401367] = "Nessuno sa veramente chi abbia creato le Carte della Luna Oscura o qual è il loro vero scopo, ma posso dirti che sono state trovate in tutto l'Azeroth, di solito nelle mani di un villain che tenta di svelarne i misteri."
GS_Gossip[1821821099] = "Non credo davvero che la nostra situazione sia così brutta. Sono certo che tutto verrà risolto presto e il potere del Sole benedetto verrà ripristinato. Non può certo essere così terribile come tutti sembrano fare credere."
GS_Gossip[1828714432] = "Sì, è lei su cui stai camminando. Una bella ragazza, non è vero? Il Barone mi nominò capitano un po' di tempo fa. Non è originariamente mia, quindi non l'ho battezzata io; se vuoi sapere la mia opinione, ragazzo, penso che il marinaio che l'ha battezzata ha passato un po' troppo tempo in mare e non abbastanza tempo in porto, se capisci cosa intendo."
GS_Gossip[1829829021] = "Come si naviga la torre?"
GS_Gossip[1830155928] = "I conflitti in Outland sono più mortali di qualsiasi cosa abbia mai visto. E le loro vittime più tragiche sono i bambini che rimangono indietro.NEW_LINENEW_LINEOra, con la minaccia contro Shattrath proveniente dagli arakkoa di Skettis, ci saranno ancora più orfani da prendersi cura. Questi bambini spesso vivono senza la speranza di un futuro luminoso."
GS_Gossip[1832599228] = "Pagami e parlerò...NEW_LINENEW_LINEOh ciao, sei tu, YOUR_NAME! Non ci pensare..."
GS_Gossip[1833170594] = "Rane e palle di pelle in vendita!"
GS_Gossip[1833353185] = "Riempi il tuo boccale e tira fuori una sedia. Abbiamo storie da raccontare e barili da svuotare."
GS_Gossip[1837483794] = "Non hai sentito parlare di Ysera? La guardiana della natura? L'Aspetto del Sogno? È la matrona di tutti i draghi verdi! Sì, fu Ysera in persona a donare il suo branco al mio regno. Stammo fianco a fianco con quelle nobili creature e ci permisero di cavalcarle in battaglia contro i nostri nemici. Tutto procedeva bene per molti secoli... fino a quando..."
GS_Gossip[1837910860] = "Perché, sembri un comune straccione!"
GS_Gossip[1838560488] = "È buono vedere un YOUR_RACE, come te, che contribuiscono al benessere di Sylvanaar. Abbiamo fatto molto qui in un breve periodo, ma le forze che ci circondano minacciano il nostro modo di vivere.NEW_LINENEW_LINEAscolterei ciò che hai da dire.  Parla liberamente, YOUR_CLASS."
GS_Gossip[183857513] = "Di che dovere si tratta?"
GS_Gossip[1840931184] = "Si dice che questa nottiaglio sia tranquilla in presenza degli elfi notturni e dei loro alleati, il che la rende un'avversaria ancora più degna. Il percorso di caccia di Shadumbra la porta dal Raynewood Retreat a ovest di qui, finendo per raggiungere le terre a ovest di lì. Il suo pelo è del colore del catrame, e la sua velocità non va sottovalutata."
GS_Gossip[1843329732] = "Posso avere un altro agnello da corsa?"
GS_Gossip[1845801659] = "Qui per imparare a utilizzare un nuovo arma, o solo per sprecare il mio tempo?"
GS_Gossip[1849459772] = "Prevedo che parlerai con l'Arcimago Lan'dalock, YOUR_NAME."
GS_Gossip[1849838246] = "La tua schiavitù è giunta al termine, Doom'rel. Ti sfido!"
GS_Gossip[1852559346] = "In tutta la terra le nostre fiamme ardono forti e sincere!"
GS_Gossip[185315178] = "Trova il Maestro dei Cavalieri del Vento in cima alla Torre del Cielo nella Valle della Forza. Doras ti assicurerà che troverai la strada per la battaglia che cerchi."
GS_Gossip[1866611975] = "Il Tavern The World's End può essere trovato nella parte orientale della città bassa."
GS_Gossip[1867300600] = "Sono pronto, storico Archesonus."
GS_Gossip[187035101] = "Un tunnel porta fuori alla base della città nei sotterranei occidentali, poco a nord del Taverna delle Canterelle e dei Corvi.NEW_LINENEW_LINEAlcuni dei più avventurosi lo usano per volare in e fuori da Dalaran."
GS_Gossip[1870879313] = "Non sono interessato a nessuna di quelle cose spaventose che ti piacciono, Brazie. Mostrami solo le \"legali\" merci."
GS_Gossip[1874036929] = "Documenti come i moduli per la creazione di una guild possono essere ottenuti dal Guild Master nella città di Darnassus.  "
GS_Gossip[1875854999] = "È abbastanza semplice, davvero, YOUR_NAME. La mia vecchia compagnia di mercenari, La Lama Velata, ha preso la missione sbagliata nel momento sbagliato.NEW_LINENEW_LINESiamo stati assunti da un goblin contrabbandiere di Baia del Bottino, uno Gremnik Rizzlesprang, che era avido del libro delle incantazioni del Signore Valthalak. Oppure, forse c'era qualche vecchia rivalità là? Immagino che ormai non lo scopriremo mai, perché Gremnik è stato ucciso non molto tempo fa da un gruppo di assassini spettrali di Valthalak. Davvero possono essere molto mortali quando un gran numero di loro si raduna.NEW_LINENEW_LINEDove ero?"
GS_Gossip[1876881137] = "Il dottor Herbert Halsey è chi cerchi. Solo non provare a fare niente di strano. Se continui con quelle sciocchezze sulla peste, ti troverai un'ascia in posti scomodi."
GS_Gossip[1876987742] = "Sono stato abbattuto da quel folle imprudente, Mulverick. Temo che se non riesco a tornare in base, tutto sarà perso! Mulverick e il suo squadrone di War Riders devono essere fermati!"
GS_Gossip[1878923648] = "Deve esserci qualche posto su Azeroth dove possiamo trovare degli oozes non corrotti dal Flagello o da qualsiasi altra cosa. Ma dove?!"
GS_Gossip[1880187451] = "Credo di aver perso quel drappo che hai incantato per me, Falrin."
GS_Gossip[1880272614] = "Questo portale conduce alle Cavernes del Tempo, profondamente sotto la terra in lontano Tanaris.NEW_LINENEW_LINEPossiedo il potere di mandarti là, se ne hai realmente desiderio."
GS_Gossip[188088919] = "Ya man, tu sei che vuoi l'Arboreto di Jandi.  L'ho appena detto?  Glok'tar, devo essere stanco!  Segui le scale di legno dietro al Mercato di Asoran nella Valle della Saggezza fino a The Drag e troverai Jandi lì in alto."
GS_Gossip[1881112929] = "Bella giornata per volare, non è vero?"
GS_Gossip[1885461565] = "Godendo del Festival del Fuoco di Mezz'estate, YOUR_CLASS?"
GS_Gossip[1887125830] = "Esistono alcune ricompense adatte solo a coloro che hanno ottenuto il titolo di Crociato, esaltati agli occhi della Crociata d'Argento così come da tutti i loro popoli alleati.NEW_LINENEW_LINETirion stesso mi ha incaricato di trovare tali eroi e di conferire loro le decorazioni appropriate."
GS_Gossip[1888680478] = "Fai la tua parte per tenere a bada il Flagello, soldato! Segnala tutte le attività sospette e uccidi prima, poni domande dopo!"
GS_Gossip[1890696356] = "Hai provato il nostro pane? Masterson, il fornaio, deve essere il cuoco più talentuoso che abbia mai vissuto!"
GS_Gossip[1891137706] = "Forse esiste un modo?"
GS_Gossip[1892315610] = "Kel'Thuzad è la mia risposta."
GS_Gossip[1898048508] = "Incredibile, non credi? Tutti questi reperti e reliquie.NEW_LINENEW_LINENon sono sicuro di cosa mi impressioni di più, le loro dimensioni, o le storie che le accompagnano. C'è così tanto da studiare e imparare. E le connessioni che possiamo fare...NEW_LINENEW_LINESapevi che si dice che molte razze abbiano la stessa origine degli Elfi Notturni?"
GS_Gossip[1899346917] = "Cerco ulteriore addestramento druidico per comprendere meglio la volontà della Madre Terra."
GS_Gossip[1901155811] = "Saluti, YOUR_RACE.NEW_LINENEW_LINESe sei interessato ad aiutare nella difesa del tempio, parla con Lord Afrasastrasz all'interno."
GS_Gossip[1902582421] = "L'est."
GS_Gossip[1902718469] = "Per i Naaru, non sei un mago! Se stai cercando addestramento, devi cercare un YOUR_CLASS addestratore."
GS_Gossip[1903355965] = "Semplificando, questa è corretta.NEW_LINENEW_LINELe caratteristiche fisiche degli Earthen sono quelle di un umanoide di statura inferiore, sebbene la loro composizione sia costituita dai vari composti di base rocciosi di Azeroth. Il loro design massimizza forza e resistenza senza sacrificare la potenza di elaborazione cognitiva. La loro pelle e muscolatura sono quasi impervie al danno fisico, e con modifiche molto minime gli Earthen mostrano una notevole resistenza a forze magiche indesiderate."
GS_Gossip[1903781499] = "Cerca Tarshaw Jaggedscar nei dormitori del lato est del paese."
GS_Gossip[1904088831] = "Sono così intelligente!  S-M-R-T!"
GS_Gossip[190485996] = "Veramente una spada straordinaria, non ti pare? Non è un'arma di fabbricazione elvetica, no, è molto più antica di quella.NEW_LINENEW_LINEQuesti rappresentanti dei Sunreaver e del Patto d'Argento sembrano intenzionati a risolvere il mistero. Sto già redigendo un rapporto per Brann."
GS_Gossip[1906523650] = "Il trucco nell'usare l'evasione è rendersi conto che i quindici secondi migliori della tua vita sono spesso gli ultimi."
GS_Gossip[1910217656] = "Sono Ulysses Rackmore, capitano della Gallant. E questo è il diario degli ultimi giorni della mia nave condannata.NEW_LINENEW_LINEStavamo navigando verso il Forte di Luna di Piuma con un carico di forniture quando le naga hanno attaccato i lati della Gallant. Li abbiamo respinti, ma sapevamo che sarebbero tornati. Preoccupato per la perdita dei miei beni più preziosi, ho diretto la Gallant verso un'isola lungo la costa di Desolace, una con antiche rovine elfiche notturne. E lì ho lasciato il mio tesoro."
GS_Gossip[191361619] = "Raene, ho perso la Bacchetta di Trasformazione di Dartol."
GS_Gossip[1914822530] = "Fascinante. Per favore, continua."
GS_Gossip[1914921299] = "Abbiamo già perso un paio di buone persone qui sopra. Sto iniziando a dubitare che questo posto valga la nostra attenzione."
GS_Gossip[1915399134] = "Per favore, YOUR_RACE, portami fuori di qui! Sbloccare la gabbia attirerà sicuramente l'attenzione del mio fratello. Uccidi Syth l'Intrecciatore delle Tenebre!"
GS_Gossip[1916318207] = "Vieni a imparare dal maestro eh?"
GS_Gossip[1916648518] = "Ho bisogno di una seconda testa quanto ne ho bisogno di perdere la prima."
GS_Gossip[1920700349] = "Lo puoi sentire?NEW_LINENEW_LINEIl mondo spirituale si avvicina durante il Giorno dei Morti. Questo è il motivo per cui decoriamo le tombe dei nostri cari defunti con fiori, candele e offerte: per accoglierli nuovamente, anche se solo per un breve periodo.NEW_LINENEW_LINEEcco come! Balla con me! Che possiamo onorare e ricordare coloro che abbiamo perso, nella loro presenza fantasma, in modo che possano mangiare e bere e sorridere e sapere che sono amati."
GS_Gossip[1920877507] = "Già so molto dello stile. Ora è solo questione di padroneggiare le tecniche per lavorare con la pelle. Fortunato che Simon sia davvero disponibile ad aiutarmi a impararle."
GS_Gossip[1921492661] = "Troverai il Maestro dei voli della città a Krasus' Landing nell'est di Dalaran."
GS_Gossip[1923089475] = "Raccontami di nuovo la tua storia, Fizzcrank."
GS_Gossip[1924873468] = "Sono disposto a provare ma avrò bisogno di istruzioni."
GS_Gossip[1925186963] = "Non lo so, ma sono contento che l'abbiano fatto. La pausa ha permesso all'Anacoreta Elbadon di salvare molte delle persone sotto il mio comando. Ho mandato in avanscoperta alcuni dei miei esploratori più discreti, e hanno riferito qualcosa di interessante. Quasi tutti i Protettori della Lama Solare sono spenti! Le forze di Kil'jaeden sembrano conservare la loro energia e sembrano soddisfatte di contenere noi con un solo Protettore attivo. Se tu e i tuoi compagni volete forzare l'ingresso, permettetemi di suggerirvi un piano d'attacco."
GS_Gossip[1925364809] = "Benvenuto nel mio Albergo, viaggiatore stanco. Cosa posso fare per te?"
GS_Gossip[1925536150] = "Non è bellissima? Vuoi darle una prova?"
GS_Gossip[1929676035] = "Conosco queste foreste come se fossero parte di me... ma sappi che c'è ancora molto da imparare da loro, e molto pericolo ancora nascosto."
GS_Gossip[1930416054] = "Solo i campioni dell'Esodar possono acquistare ciò che ho da offrire."
GS_Gossip[1932425771] = "Sì, il Re dei Lich cadrà sotto la nostra potenza. Avremo la nostra vendetta finale.NEW_LINENEW_LINEMa prima di tutto, ci assicureremo che la peste nota come Furia Scarlatta venga definitivamente messa fine!"
GS_Gossip[1936591267] = "Questi sembrano essere i resti di Thalorien Dawnseeker, l'ultimo portatore di Quel'Delar."
GS_Gossip[1939423049] = "Ho sentito che c'è un nano a Roccavento che ha guadagnato un po' di fama per le sue abilità di cacciatore. Forse dovresti andare a vedere se potrebbe aiutarti."
GS_Gossip[1939671073] = "Tram di Deeprun"
GS_Gossip[1940267203] = "Il Ringraziamento del Pellegrino è un momento per riflettere sulla propria fortuna e condividere con tutti coloro che vi sono attorno.NEW_LINENEW_LINEIn Mulgore e nell'Orda, abbiamo trovato sia una casa che amici con cui godere dei suoi molti frutti.NEW_LINENEW_LINEÈ nostro augurio che ogni uno dei nostri alleati sarà in grado di unirsi a noi per il banchetto e la celebrazione."
GS_Gossip[1940294986] = "Questo posto... è maledetto.NEW_LINENEW_LINESono appena riuscito a scappare, e non posso sopportare l'idea di tornare giù per i tunnel.NEW_LINENEW_LINEMio fratello, e le mie sorelle... Non hanno avuto la stessa fortuna. Intrappolate dentro, sono febbrili a causa del velo corrotto che scorre dal giardino malvagio che cresce là.NEW_LINENEW_LINEPer favore, devi aiutare."
GS_Gossip[1941408440] = "Barbiere"
GS_Gossip[1941855426] = "Cosa hai da mangiare, Celeste?"
GS_Gossip[1942287559] = "La battaglia per il Bacino d'Arathi è una battaglia per le risorse. Legname, minerale, cibo... tutti questi sono necessari per condurre una buona guerra.NEW_LINENEW_LINENegare alle nostre nemiche le loro risorse è altrettanto efficace che ucciderle sul campo di battaglia."
GS_Gossip[1946539895] = "Ti mostrerò! Dammi quel paracadute di allenamento!"
GS_Gossip[1948143238] = "Gurf è il mio nome, straniero. Gurf l'Audace!"
GS_Gossip[1949074083] = "C'è solo un cacciatore intorno qui con cui parlare, e sarebbe Grif Wildheart. Lo troverai in piedi proprio fuori dallo spazio delle armi a Kharanos."
GS_Gossip[1953427583] = "Non si riposano mai?!NEW_LINENEW_LINESe vogliamo garantire un futuro per le persone della Città Bassa, dobbiamo occuparci del Consiglio delle Ombre prima che causino un cataclismo ancora più grande di quello delle Lande di Osso!NEW_LINENEW_LINEPoiché la leadership di Shattrath non agirà rapidamente, noi, i liberi abitanti della Bassa Città, abbiamo preso le cose in mano noi stessi.NEW_LINENEW_LINEMa i nostri spie sono stati scoperti.  Teniamo fuori gli agenti del Consiglio delle Ombre mentre tu ti infili nel labirinto e vedi cosa puoi scoprire."
GS_Gossip[1954241848] = "Il scribe della città si trova nell'Apothecarium, qualcuno di nome Margaux Parchley."
GS_Gossip[195430550] = "Il Capitano Adams mi ha mandato qui per investigare su ciò che sta accadendo a Halgrind. Questo è quanto sono riuscito a raggiungere; tuttavia, la torre abbandonata dei Vrykul mi offre un certo riparo dagli occhi curiosi.NEW_LINENEW_LINEI Forsaken stanno combinando qualcosa di losco laggiù. Lo posso sentire!"
GS_Gossip[1954929163] = "Gli elementi parlano a noi, YOUR_CLASS.  Condividono conoscenze che dobbiamo imparare e segreti che devono essere custoditi."
GS_Gossip[1955603342] = "Non desidero più guadagnare esperienza."
GS_Gossip[1956218627] = "Ci sono delle cozze da raccogliere e orche da uccidere. Aiuta o stai fuori dal camino!"
GS_Gossip[1957132247] = "L'ampia quantità di tessuti dell'Esodar è diminuita pericolosamente. La tua reputazione tra i draenei aumenterebbe se donassi del tessuto per aiutarci."
GS_Gossip[1957395208] = "Mostrami come addestrare con un bersaglio a distanza."
GS_Gossip[1957482926] = "Di cosa hai bisogno, YOUR_RACE?"
GS_Gossip[1957962919] = "Gli Infiniti stanno tentando qualcosa insolitamente sottile per loro. Stanno cercando di nascondere le prove che porteranno Arthas a decidere di sterminare Stratholme.NEW_LINENEW_LINEI loro agenti hanno utilizzato magia illusoria sui carichi di grano infetti nelle campagne vicine per farli apparire normali.NEW_LINENEW_LINEHai bisogno di trovare il grano nascosto e di usare questo Disruptore Arcano sui carichi. Gli uomini di Arthas stanno cercando grano infetto, e lo troveranno rapidamente con l'illusione svanita."
GS_Gossip[1958315590] = "Aiuto!NEW_LINENEW_LINESe mi porti fuori di qui, posso far esplodere la porta che conduce al capo di Zul'Farrak!"
GS_Gossip[1959737831] = "Hai il coraggio di mettere piede dentro Ravenholdt Manor, verme?"
GS_Gossip[1960460211] = "Accetterò la tua offerta, Eitrigg."
GS_Gossip[1961070704] = "Dove si trova l'anziano Thoim?"
GS_Gossip[1961792278] = "Dimmi di più sulla nostra missione qui, Nazgrel."
GS_Gossip[1962256669] = "Duca dei Fathoms! Ho il tuo sigillo! Ascolta il mio richiamo!"
GS_Gossip[1965911462] = "Dicono che un esercito si muove grazie allo stomaco, e questo è la verità. Per qualsiasi offensiva abbia successo, i tuoi soldati devono essere ben nutriti e ben provvisti."
GS_Gossip[1969255992] = "Desideri un giorno unirti alle nostre file? Sark Ragetotem può aiutarti nel tuo percorso. È presente nella Hall dei Cacciatori."
GS_Gossip[1971722499] = "Merci & Equipaggiamento"
GS_Gossip[1974855308] = "Dimenticare la lavorazione delle pelli elementali non è una decisione da prendere alla leggera. Se scegli di abbandonarla, dimenticherai anche tutte le ricette che richiedono la lavorazione delle pelli elementali!"
GS_Gossip[1979152824] = "C'era un'altra cosa che volevo chiederti, Altruis."
GS_Gossip[1980191119] = "\"Bravo per aver raccolto risorse per la guerra,\" dissero, \"Hai una promozione,\" dissero.  Cio' che realmente intendevano e' \"Sei schierato fuori da un alveare di insetti a Silithus con un gruppo di elfi sudati, Carnes!\"NEW_LINENEW_LINEGrazie per la promozione, Capitano!"
GS_Gossip[1981872846] = "È un onore rappresentare la Crociata d'Argento in questo torneo."
GS_Gossip[1982959447] = "È integrale per l'assimilazione di questi dati che si comprenda che i Creatori volevano sintetizzare una razza che sarebbe rimasta a lungo una parte integrante del ciclo di sviluppo di questo mondo dopo che se ne fossero andati. Questa razza sarebbe stata determinante per il raggiungimento degli obiettivi di sviluppo a lungo termine dei Creatori per Azeroth.NEW_LINENEW_LINECome nota aggiuntiva, il termine \"Earthen\" è stato ritenuto appropriato per la nuova razza dai Creatori, in base alla composizione degli Earthen."
GS_Gossip[1983616642] = "Cosa hai per me?"
GS_Gossip[1984396607] = "Grimnur Stonebrand ti racconterà alcune belle storie su quello che è scappato via, ma è comunque uno dei migliori pescatori della zona. Ha aperto un negozio all'interno della Grotta Abbandonata chiamato Il Pescatore Viaggiatore."
GS_Gossip[1991345465] = "Insegnante di volo in condizioni climatiche fredde"
GS_Gossip[1991799267] = "Noi vogliamo molti animali domestici. Anya Maulray ti aiuterà a prendersene cura. La puoi trovare all'inn, nel anello superiore del Quartiere del commercio."
GS_Gossip[1993764708] = "[Furbolg] Mil'ork kix ilfin o oomtor..."
GS_Gossip[199726774] = "Permesso di consultare i miei colleghi."
GS_Gossip[1997403697] = "Dobbiamo assicurarci di non perdere altre anime a causa dei mari."
GS_Gossip[1997716907] = "Quali sono i componenti?"
GS_Gossip[2000440418] = "Ho sentito che eri morto... beh, non ti ucciderò facilmente dopo questo!"
GS_Gossip[2005628560] = "Cercatelo in alto, sul lato occidentale della Valle della Forza. $"
GS_Gossip[2013405349] = "Quale allenatore di professione stai cercando?"
GS_Gossip[2014962735] = "Non intendo addestrarti finché non sarai esaltato agli occhi dei draenei."
GS_Gossip[2017263852] = "Mago strano?"
GS_Gossip[2018042840] = "A volte mi sorprendo perfino io!"
GS_Gossip[2021233438] = "La corruzione di Felwood ha intrappolato il mio spirito qui... Forse non riposerò mai..."
GS_Gossip[202171578] = "In giorni ormai lontani, vivevamo per la caccia. Cacciavamo per la gloria, per l'onore...NEW_LINENEW_LINEÈ così diverso adesso?"
GS_Gossip[2021841058] = "Ciao. Cosa ti porta al Campo di Vento Gelido oggi?"
GS_Gossip[2022430461] = "Mi dispiace, ma dobbiamo parlare in un altro momento. Arrivederci."
GS_Gossip[2024113683] = "Il continuo sacrificio dell'Accordo delle Ceneri e di eroi come te ci sta portando sempre più vicini alla vittoria finale. Ora sono venuto alla Rocca della Corona di Ghiaccio per prestare aiuto a coloro che combattono contro il Flagello. Insieme porremo fine alla tirannia del Re dei Lich!"
GS_Gossip[2024260289] = "L'abilità preternaturale del demone delle cripte di cacciare e uccidere il suo nemico è una studiata e vantata da uomini della mia professione. Io stesso ho ucciso migliaia di quelle bestie nella mia crociata per liberare questo mondo dal Flagello.NEW_LINENEW_LINESebbene io detesti il demone delle cripte per la sua natura implacabile, le sue abilità devono essere ammirate. Ha un lavoro e lo svolge - molto bene."
GS_Gossip[2024778857] = "C'è un Allenatore di Ingegneria a Razor Hill. Si chiama Mukdrak e di solito si trova vicino alla forgia."
GS_Gossip[2025763053] = "La razza non determina l'onore, YOUR_RACE. Mentre rimani sul mio fondo, ti chiedo di ricordare e rispettare questo credo.NEW_LINENEW_LINEHo conosciuto orchi onorabili quanto i cavalieri più nobili e umani vili quanto i più spietati del Flagello.NEW_LINENEW_LINEMa non vi annoierò con racconti dei miei anni giovanili! C'è molto lavoro da fare - se è questo che desiderate."
GS_Gossip[2027739687] = "Non sembri così forte."
GS_Gossip[202950445] = "Resistere? Contro un attacco frontale della vanguardia della legione? Non credo proprio!NEW_LINENEW_LINENo, la storia non registra ciò che accadde successivamente... poiché non vi furono sopravvissuti. I demoni infuriati lasciarono poco più delle rovine che vedete oggi, e i segreti dell'accademia rimasero sepolti nel suolo di Azshara."
GS_Gossip[2029785234] = "Ah, YOUR_NAME - è bello rivederti.  Confido che le tue faccende vadano bene."
GS_Gossip[2030817834] = "Gli esuli di Gnomeregan si trovano in situazioni ancora più disperate a causa della scarsità di riserve di stoffa! Forse puoi aiutarci, eh?!NEW_LINENEW_LINEPortami pezzi extra di stoffa che potresti avere per aiutarci a rifornire le nostre scorte. Donandoli, guadagnerai il rispetto e la fiducia di tutti i gnomi. Questo è qualcosa che il denaro non può comprare! Be', immagino che la stoffa lo possa, ma questo è un altro discorso..."
GS_Gossip[2032150803] = "Magister Hathorel ha detto che potresti essere in grado di prestarmi un certo tabard."
GS_Gossip[2033351258] = "Benvenuto. Ti riposerai qui, o forse prenderai un pasto?"
GS_Gossip[2035459441] = "Se sei stato mandato a uccidermi, per favore prendi un numero e aspetta il tuo turno."
GS_Gossip[2036919074] = "Farii addestra coloro che sono interessati all'arte della gioielleria. Puoi trovarla nella Sala dei Cristalli vicino alla caverna là."
GS_Gossip[2037371369] = "Abbiamo preso il porto, e questa nave è un bel bonus. Peccato che non sia ancora navigabile.NEW_LINENEW_LINENel frattempo, sono stato istruito ad occuparmi del disboscamento delle naga sulla costa di Greengill.NEW_LINENEW_LINEPensi di potermi aiutare?"
GS_Gossip[2039485202] = "Benvenuto a Zabra'jin, YOUR_CLASS. Sono Shadow Hunter Denjai, responsabile di questo avamposto e comandante delle forze Darkspear a Zangarmarsh."
GS_Gossip[2043438529] = "Lok'tar ogar! Siamo pronti! Avanti, orco fratello!"
GS_Gossip[2044321098] = "Salve, YOUR_NAME.  Abbiamo bisogno del tuo aiuto."
GS_Gossip[2046018596] = "Sono con te, Thorim."
GS_Gossip[2050716924] = "Le tue parole di lode sono apprezzate, Maestro del Colosseo."
GS_Gossip[2051971297] = "Troverai i nostri maestri di battaglia nel Tesoro delle Luci. C'è anche uno \"Miglik Blotstrom\" che sta con Caregiver Breel, che sostiene di rappresentare un circuito di combattimenti arenavi in questo mondo."
GS_Gossip[2054113738] = "Sebbene siamo giunti nel paese promesso, YOUR_NAME, molto lavoro resta da compiere. Il nostro popolo non raggiungerà Kael'thas se ci lanciamo disperatamente attraverso l'Outland.NEW_LINENEW_LINEDeve essere trovato un percorso sicuro, devono essere garantiti i risorse e i nostri nemici devono essere evitati o distrutti."
GS_Gossip[2059448434] = "Ho sentito dire che le donne vrykul non sono in grado di combattere. Se vuoi dimostrarmi il contrario, puoi provare."
GS_Gossip[2063017971] = "Ho bisogno di un altro travestimento."
GS_Gossip[2063517445] = "La nostra ultima attrazione, e senza alcun costo per voi, questi piccoli carri armati, o Tonks come li abbiamo abilmente battezzati, possono essere controllati da qualsiasi console di controllo Tonk sparsa per tutta la fiera.NEW_LINENEW_LINETutto ciò che devi fare è attivare un terminale di controllo disponibile. Ogni tonk verrà equipaggiato con un set standard di dispositivi e un potere speciale casuale da usare contro il tuo nemico!NEW_LINENEW_LINETieni battaglie epiche con i tuoi amici, gira intorno, o semplicemente causa caos selvaggio... la scelta è tua!"
GS_Gossip[2068025692] = "Sì, sì. Ti vedo.NEW_LINENEW_LINEVai pure. Potresti aver guadagnato la fiducia di alcuni, ma ci vorrà di più per convincermi!"
GS_Gossip[2069227893] = "La Signora Sylvanas ha ordinato l'indagine su alcuni fenomeni naturali di Azeroth. Ritiene che ci sia qualcosa di grande da imparare dal suo passato segreto.NEW_LINENEW_LINENon so come abbia imparato queste cose, ma la confido completamente, quindi farò del mio meglio.NEW_LINENEW_LINESto attualmente investigando slime, oozes e simili. Tutti gli esseri sembrano essere simili nella composizione, ma molto influenzati dal loro ambiente.NEW_LINENEW_LINEPotrei usare il tuo aiuto per raccogliere campioni delle creature."
GS_Gossip[2069757086] = "Ciao ancora una volta, YOUR_NAME.  Percepisco che il flusso del tempo rimane minacciato da forze molto potenti.  Il tuo continuo aiuto è sempre benvenuto dalla schiera dei draghi bronzei.NEW_LINENEW_LINEMentre il passato è radicato nei suoi modi, il futuro è sempre in cambiamento. Le decisioni che prendi in questo momento aiutano a guidare quel cambiamento."
GS_Gossip[2070282423] = "Devi essere esaltato con i gnomi degli Esuli di Gnomeregan prima che io ti insegni a pilotare un Mechanostrider, YOUR_CLASS."
GS_Gossip[2070880949] = "Lo so, lo so, sono qui in mezzo a nessuno!NEW_LINENEW_LINELa mia casa è realmente a Ratchet, ma dopo aver schiantato il mio zeppelin qui, ho pensato che tanto valeva iniziare la ricerca per cui sono venuto qui!"
GS_Gossip[2077408315] = "La Sinottica è composta da un gruppo di hacker - disorganizzati, inesperti e pigri... "
GS_Gossip[2077828469] = "Siamo sempre ansiosi di ottenere più dati di volo! Dove vuoi andare?"
GS_Gossip[2078875462] = "Northrend richiede la tua attenzione, Sovrano Hellscream. Affronteremo il Re dei Lich e i suoi seguaci senza il tuo aiuto."
GS_Gossip[2078988434] = "Orci? Terre desolate? Sono invincibile!"
GS_Gossip[2081016711] = "Eh, sto prendendo alcuni prigionieri che abbiamo trovato fuori prima del re per la punizione."
GS_Gossip[2081150904] = "Vendi qualcuna di queste cose?"
GS_Gossip[2082912014] = "Langrom's Leather & Links nel sud di Dalaran dovrebbe avere ciò che cerchi."
GS_Gossip[2083200740] = "Benvenuto a Garadar, estraneo. Cerchi un posto dove riposare?"
GS_Gossip[2086027511] = "C'è qualcosa per cui mi pagheresti di fare?"
GS_Gossip[2086400339] = "Uhh, puoi mandarmi in giro per Zul'Drak?"
GS_Gossip[2089298068] = "Oooh, un'osteria è, eh? Beh, non si può certo battere la Distilleria del Tuono. Se devi riposare, fallo pure, ma assicurati di bere un paio di birre mentre sei lì."
GS_Gossip[2090152482] = "Bixi qui può insegnarti come lanciare armi. Se Darnassus è più nel tuo stile, parla con Ilyenia Moonfire sulla Terrazza dei Guerrieri là."
GS_Gossip[2090971363] = "Fabbro"
GS_Gossip[2092685809] = "Tutte le cose in vendita, mio amico! Grandi e piccole, qualunque cosa tu abbia bisogno, Hazzin ti fornirà.NEW_LINENEW_LINESe ti curi della tua vita, non avvicinarti al Manaforge Ultris senza un rifornimento. Hazzin è l'ultima possibilità che hai."
GS_Gossip[2094412818] = "Solo i più valorosi e onorevoli della tribù possono guadagnare l'onore di essere sepolti alle Red Rocks."
GS_Gossip[2095598590] = "YOUR_CLASS, tornando su Azeroth, i Sentinelli dell'Ali d'Argento ostacolano i nostri progressi nella foresta. Abbiamo bisogno che tu sia lì sul fronte del combattimento per spingerli indietro! Guadagnerai grande onore e reputazione con gli Outrider della Guerra Song per aiutarci - unisciti a noi ora!"
GS_Gossip[209970641] = "<Non puoi comprendere nessun frammento del tecnico balderdash su questo rotolo.>"
GS_Gossip[2099718481] = "NO!"
GS_Gossip[2100398325] = "Un grande male si agita, YOUR_RACE. Lo senti?NEW_LINENEW_LINEBah! Certo che non puoi. Dammi il tuo armamento e le tue armi e io rinnoverò la loro vitalità."
GS_Gossip[210096799] = "<indietro>"
GS_Gossip[2103433627] = "Ciao. Spero che questa giornata ti trovi bene?"
GS_Gossip[210953493] = "Gubber, non so come pescare."
GS_Gossip[2109838370] = "Mantieni il tuo volume basso. Non vorremmo attirare l'attenzione di questi mostri!"
GS_Gossip[2111659704] = "Sono interessato alla formazione del mago."
GS_Gossip[2111682391] = "Nessun altro festival si confronta con i banchetti e le bevande di Brewfest!"
GS_Gossip[2112840015] = "Onori gli spiriti degli animali che devi uccidere non lasciandoli andare a vuoto. Aska Mistrunner ti mostrerà come fare. Ha una cucina nell'edificio alto."
GS_Gossip[2114763263] = "Bende, anti-veleni e simili, queste sono le inevitabili necessità della vita sulle pianure. Vira Younghoof può insegnarti questa conoscenza. La puoi trovare nella lunga casa sul lato ovest del villaggio di Bloodhoof."
GS_Gossip[2117647594] = "Sbrigati! Dovresti parlare con Mekkatorque! Se non iniziamo l'assalto presto, arriveremo in ritardo.NEW_LINENEW_LINEE il mio capo ODIa quando siamo in ritardo!"
GS_Gossip[2121818628] = "Non posso addestrarti. Devi parlare con il tuo allenatore di classe."
GS_Gossip[212390655] = "Ti consiglio vivamente di visitare Sayge per farti predire il futuro. Lo so, lo so... è un gnoll. Ma è un gnoll molto speciale, in grado di divinare il tuo futuro!NEW_LINENEW_LINEE stiamo costantemente espandendo la fiera con ogni sorta di nuove attrazioni!"
GS_Gossip[2125971260] = "Lavinia Crowe è l'incantatrice locale. Ha aperto bottega nel anello interno dell'Apothecarium."
GS_Gossip[2126517058] = "Mostrami cosa hai in vendita, \"Slender.\""
GS_Gossip[2127329133] = "Infatti. Mal'Ganis sta comandando il Flagello dalla Piazza dei Crociati, ma le porte che portano lì dall'ingresso della città sono chiuse.NEW_LINENEW_LINEPoco sa che una piccola forza può comunque raggiungere il Piazzale muovendosi attraverso il Palazzo Comunale. Vuoi unirti a me in questo attacco?"
GS_Gossip[2128194451] = "Spero che fosse vero, YOUR_NAME, ma ci vorrà più di te da solo per superare le forze di Razelikh e i suoi sottoposti.NEW_LINENEW_LINERaccogli un gruppo adatto di avventurieri e aspiranti eroi e libera i miei uomini dal loro tormento eterno! Devi distruggere diciotto pietre.NEW_LINENEW_LINECombatti con forza e muori con onore, YOUR_NAME."
GS_Gossip[2130517684] = "Guidami al Cimitero di Eastspark."
GS_Gossip[2130743296] = "Grazie per l'informazione, Frankal."
GS_Gossip[2130939742] = "Le nostre carovane escono 'bout due volte al giorno, ma dannazione se il Flagello non ha fatto di tutto per fermare Didier e i suoi mule per impedire loro di portare le spedizioni alle linee del fronte. La cosa più pazzesca che abbia mai visto. Se solo avessimo i tipi avventurieri eroici per aiutare a proteggere le spedizioni..."
GS_Gossip[2133157918] = "Utilizza il cristalloforno dei Bash'ir per effettuare un altro acquisto."
GS_Gossip[2133193335] = "Sì, ho gestito questo negozio da un po' di tempo. Negli ultimi tempi gli affari vanno abbastanza bene. Arrivano molte nuove avventuriere..."
GS_Gossip[2135039520] = "Tutta carne e nessun cervello, è questa la caratteristica dei peons! Sono utili quando riesci a motivarli, ma devi dargli un calcio per farli partire, se capisci cosa intendo."
GS_Gossip[2135382138] = "I pellegrini solitamente portano tutte le loro pelli a Forgiardente per farle asciugare. Perché non vai lì e vediamo se riesci a trovare uno che ti addestrerà?"
GS_Gossip[2136198560] = "Li vedo ancora con le armi? Perché hai permesso loro di tenerle?!"
GS_Gossip[2136874271] = "Cerchi qualcosa nel nostro bel paese?"
GS_Gossip[2136932188] = "Mi dispiace, ho poco tempo per parlare con chiunque altro che non siano i fantasmi e il capitano per riferire i miei risultati. Perdonatemi."
GS_Gossip[2137971230] = "Il Rosso presso Glorious Goods nel sud-est di Dalaran può fornire la maggior parte delle forniture generali del commercio.NEW_LINENEW_LINESe hai bisogno di qualcosa di più specializzato, prova il Magus Commerce Exchange. Ogni bottega di commercio lì ha il proprio fornitore di materiali."
GS_Gossip[2141275937] = "<L'Oracolo Rainspeaker ferito gemisce per il dolore.>"
GS_Gossip[2141794537] = "Signora Oscura, credo di sentire Arthas che arriva. Qualunque cosa tu stia per fare, fallo in fretta."
GS_Gossip[2142763344] = "<Il soldato ghiacciato tenta di alzarsi in piedi mentre ti avvicini, ma inciampa e cade a terra, stringendo una ferita chiaramente dolorosa al fianco.>"
GS_Gossip[2146386134] = "Ehi, amico, non so chi sei o perché ti sei stato a seguire, ma sto per imbarcarmi su una nave e voglio essere lasciato in pace, capito?"
GS_Gossip[2146519129] = "Grande battaglia ancora in corso a Sparktouched Haven.NEW_LINENEW_LINEForse trovi un momento per aiutare un po'?"
GS_Gossip[2149287138] = "Ravenholdt Manor non ti riconosce, YOUR_CLASS."
GS_Gossip[2149333100] = "I cuccioli-mostri ci hanno attaccato per giorni ormai. Il Grande Pietra di Fulmine tuttavia è ancora al sicuro.NEW_LINENEW_LINESoo-holu viene a darci una mano come tante altre volte prima... i cani non hanno alcuna possibilità."
GS_Gossip[2150938412] = "Ehilà, come stai?NEW_LINENEW_LINECome ta learn the art o' the Charge, YOUR_CLASS?"
GS_Gossip[215156001] = "Ora che mi hai battuto fino all'ultimo respiro, cosa vuoi?"
GS_Gossip[215571252] = "Yo. Cercando di tornare nel Vecchio Mondo? Volare nella Radure di Tirisfal in stile sulla Cloudkisser."
GS_Gossip[2156875755] = "L'estensione della corruzione in Outland è veramente sorprendente, YOUR_CLASS. Il Circolo Cenariano spera di comprendere come questi esseri siano riusciti a sopravvivere. Studiare questa terra rotta, tormentata e i suoi abitanti potrebbe ancora insegnarci come curare parti malate del nostro stesso mondo."
GS_Gossip[2157144592] = "Hai degli strumenti per la cottura?"
GS_Gossip[2158584147] = "Oh, oh, oh! Calmatevi, YOUR_NAME. Abbassala!NEW_LINENEW_LINE<Blast si guarda intorno.>NEW_LINENEW_LINENon vogliamo che quei vrykul gelidi ci notino, vero?NEW_LINENEW_LINECosa ne pensi del mio jumpbot? L'ho basato sul mechagnome. Piuttosto figo, eh?"
GS_Gossip[2158866933] = "Allora, cosa sceglierai? Rum? Birra?NEW_LINENEW_LINEOppure forse qualcos'altro?"
GS_Gossip[2159084028] = "Hai visto tutte le meravigliose cose qui nel Cratere di Ungoro, YOUR_NAME? È semplicemente incredibile. Non altrettanto incredibile come alcune delle cose che posso creare con la mia abilità nell'ingegneria, ma considerando che è tutto naturale qui... non è male.NEW_LINENEW_LINEIl mio zio Remtravel ama le cose vecchie come questo posto. Sto seguendo i suoi passi in un certo senso--voglio scoprire nuove cose provenienti da culture perse anch'io!"
GS_Gossip[216264845] = "Cosa puoi dirmi su Loken e i nani di ferro?"
GS_Gossip[2166538159] = "Gerk, Burr, Dargath: tutti spariti... Restiamo solo io e MacKellar fuori qui. Spero che tu abbia portato notizie buone."
GS_Gossip[2167112519] = "Se riesci a completare un mazzo di carte benedizioni, riceverai in premio una carta oscura più potente della crociata. Questo aumenterà i danni che infliggi con i tuoi incantesimi e attacchi mentre continui a combattere."
GS_Gossip[2169089104] = "Mi dispiace, ma i miei servizi sono utili solo ai magi neri."
GS_Gossip[2176709618] = "<Salta sul banco di lavoro e lascia che Walt ti metta l'armatura del golem.>"
GS_Gossip[2178379991] = "Troverai numerosi addestratori in giro per Dolanaar, con anni di esperienza per insegnarti. A quale vorresti che ti indirizzassi?"
GS_Gossip[2180631388] = "Throm'ka YOUR_CLASS!  Sei pronto a combattere per l'Orda alla Forra dei Cantaguerra?"
GS_Gossip[2180918464] = "Le persone sono state distrutte per preservare la vita immortale del Principe e i suoi poteri quasi illimitati. Il potere una volta diviso tra migliaia ora si concentra nel Principe e nei seguaci zelanti dei Shen'dralar. I pochi superstiti rimasti stanno alimentando direttamente il potere nei pali per mantenere Immol'thar imprigionato.NEW_LINENEW_LINESe il demone dovesse liberarsi dai suoi legami, distruggerebbe senz'altro ciò che resta di questa volta grande fortezza dell'arcano."
GS_Gossip[218166610] = "Ho addestrato nuovamente come alchimista. Vorrei specializzarmi nelle trasmutazioni."
GS_Gossip[2181916054] = "Lavoriamo per preservare l'equilibrio come insegna Cenarius,YOUR_CLASS.  La Luce è quella di un faro che ci mostra la via, e dobbiamo fare di tutto per preservare quella luce."
GS_Gossip[2185056124] = "Hippogrifo incandescente"
GS_Gossip[2185762395] = "Signore-Comandante, vorrei sentire la tua storia."
GS_Gossip[2191894765] = "Quando non hai un guaritore che si occupi delle tue ferite, la conoscenza della Prima Aid può salvarti la vita. Ti consiglio di consultare Dannelor laggiù sulla Terrazza degli Artigiani per imparare questa abilità."
GS_Gossip[2193472506] = "Archibald da maestro del fucile a retrocarica. Egli è il maestro delle armi della Sepulcra, situato nel Quartiere della Guerra."
GS_Gossip[2195740599] = "Nope, no alchemists out here in Dun Morogh. Ye best take a look in Forgiardente for them... try the gnomes in Tinker Town."
GS_Gossip[2196968738] = "L'Orgrimmar Auction House si trova nella Valle della Forza. Cercalo sul lato est accanto a Boomstick Imports."
GS_Gossip[2197104753] = "Piangi la grande perdita."
GS_Gossip[2197240451] = "Siate vigili rispetto all'Etere che ci circonda da ogni lato."
GS_Gossip[2197816787] = "Ciao, YOUR_NAME. Se vuoi imparare qualcosa sulla cucina, visita il mio negozio in qualsiasi momento."
GS_Gossip[2198016400] = "Preferisci fucili o balestra?"
GS_Gossip[2198225116] = "Chi credi di essere per entrare qui e rivolgermi la parola? Sono il leader del Consiglio delle Ombre in questo villaggio. Vattene da qui!NEW_LINENEW_LINESe ti vedo di nuovo, sarò l'ultima persona che vedrai. Capito?NEW_LINENEW_LINEForse ti piacerebbe essere sepolto nel labirinto di Auchindoun, o sacrificato a Murmur?"
GS_Gossip[2200148439] = "<La bocca del bruto si inumidisce, aspettando il sangue.>"
GS_Gossip[2200963166] = "James Van Brunt in War Quarter, sull'anello interno."
GS_Gossip[2201401313] = "Io rendo disponibili i miei animali da sella solo a coloro che sono considerati esaltati verso Orgrimmar e la razza Orca. Vai a dimostrare il tuo valore a noi, e renderò disponibili i miei potenti lupi per la tua ispezione."
GS_Gossip[2204570918] = "Perché mi guardi così? Non intendi darmi un bacio, vero!?"
GS_Gossip[2204745415] = "Questo è la torre di Karazhan e la residenza del mio maestro, Medivh. Come umile portiere, non posso spiegarti molto altro."
GS_Gossip[2205548304] = "Mineraria"
GS_Gossip[2205623203] = "Krumn è il toro che stai cercando. Puoi trovarlo sulla collina bassa presso l'Informazioni Civiche di Picco del Tuono."
GS_Gossip[2206233204] = "L'interrogatore sta cercando di scoprire cosa stanno facendo questi elfi del sangue qui a Nagrand. Da quanto sento, stanno cercando la polvere cristallina residua di Oshu'gun, la montagna diamantifera a ovest.NEW_LINENEW_LINENessun dubbio che venga utilizzato in qualche sinistro piano o miscela...NEW_LINENEW_LINESe stai cercando di aiutare la nostra causa e di fermare questi elfi del sangue, il conflitto sta avvenendo proprio adesso a nord-ovest, a Halaa. Gli elfi del sangue e quei soldati della Mano di Argus stanno combattendo! Unisciti e mostragli cosa è giusto!"
GS_Gossip[2209134708] = "Rimarrà da vedere se sei pronto, giovane uno. Neppure i druidi più saggi e più vecchi sono mai veramente pronti quando giunge il loro momento finale di prova.NEW_LINENEW_LINEHai udito le mie parole, e ora devi proseguire. Presta attenzione a quanto ti ho insegnato. Arriverà un momento in cui la tua forza sarà messa alla prova. Devi affrontare il tuo nemico come farebbe l'orso - con la forza del corpo e con la forza del cuore. Impara dalla battaglia, giovane uno. Va'... con le mie benedizioni."
GS_Gossip[2211707291] = "Sembra che abbia perso il Prigione Arcano Potenziato. L'ho lasciato qui con te?"
GS_Gossip[2217253309] = "Di che ti stai interessando?"
GS_Gossip[2224698287] = "Puoi crederci? Questo etereo non ha nemmeno un singolo occhio di basilisco!NEW_LINENEW_LINEE il suo leader ha il coraggio di chiamarsi \"il Principe dei Contrabbandieri!\""
GS_Gossip[2229438044] = "Se desideri cibo, il Capo Cuoco Grace può provvedere alle tue esigenze."
GS_Gossip[2231445754] = "Ciao! Sono Kwee Q. Peddlefeet! Sono qui per scoprire chi è il più popolare tra tutti gli eroi in Azeroth!NEW_LINENEW_LINEÈ davvero bello vedere tanti fan adoranti salutare i loro leader, ma... sai cosa mi piacerebbe ancora di più?NEW_LINENEW_LINEUn bacio!"
GS_Gossip[2232805861] = "Sebbene la costa di Darkshore sia più pericolosa rispetto a quella di Teldrassil, molti pescatori trovano profitto qui."
GS_Gossip[2233271814] = "Quando ho scosso la testa prima che diventassi il nuovo re... um... stavo solo scherzando.NEW_LINENEW_LINESì!"
GS_Gossip[2239697002] = "Mumman ha allestito il suo umile negozio vicino all'ingresso principale della città, appena oltre l'albergo. Una cuoca eccellente, quella."
GS_Gossip[2240748375] = "Puoi trovare Arthaid, il nostro maestro dei cavalli, fuori dal Centro per il Benessere. Si trova al piano superiore del hub centrale, vicino all'ingresso principale dell'Exodar."
GS_Gossip[2242119457] = "Il Custode delle Storie è un antico. Ha servito sotto la nostra gloriosa Regina!"
GS_Gossip[2244891485] = "La fortezza Viola"
GS_Gossip[2246526493] = "Sono Zarevhi del Consorzio. Le mie abilità come transmutatore sono note in mille mondi."
GS_Gossip[2251055571] = "Mostrerei l'orecchio della bestia al mio signore e rivendicherei la morte della bestia come mia - dopotutto, l'ho uccisa. Poi offrirei una parte della ricompensa al cavaliere povero per aiutare la sua famiglia."
GS_Gossip[2252157354] = "Sì, cosa vuoi? Non puoi vedere che sono occupato qui? Il Consiglio delle Ombre non mi paga all'ora!"
GS_Gossip[2252328859] = "Siamo onorati della tua presenza, amico. Come possiamo servirti oggi?"
GS_Gossip[2253255413] = "Un sonno ristoratore è sicuramente garantito nei letti che l'oste Keldamyr tiene all'Albergo a Dolanaar.  "
GS_Gossip[2256236811] = "Dove si trova il Cratere di Un'Goro?"
GS_Gossip[2257871026] = "Le marcature della sfera corrispondono al marchio sulla tua mano."
GS_Gossip[2259117702] = "Guidami al Cimitero di Westspark."
GS_Gossip[2259284992] = "John, tesoro, dove sei?"
GS_Gossip[2259650636] = "Il gestore dei pipistrelli"
GS_Gossip[2263257749] = "Raccogli i tuoi sensi velocemente, dobbiamo proseguire."
GS_Gossip[2267196066] = "I troll di Stranglethorn non ci prendono troppo bene, noi Darkspear. Non ho paura di nessun Bloodscalp o Skullsplitter, ma comunque... le alte mura di Grom'gol mi fanno sentire al sicuro."
GS_Gossip[2267489884] = "Dove si trova Elder Darkhorn?"
GS_Gossip[2270869234] = "Cos'è il club \"Birra del Mese\"?"
GS_Gossip[2271660392] = "Ho perso il mio Tabard di Cielo Estivo."
GS_Gossip[2273042382] = "SONO FLUENTE IN PIÙ DI DUE LINGUE: IL DWARVISH, IL GNOMISH E LA COMUNE LINGUA UMANA. MA NON HO LA MINIMA IDEA DI COSA STAI DICCENDO!NEW_LINENEW_LINEPARLA PIÙ FORTE; NON TI SENTO A CAUSA DEL RUMORE DEI MIEI GOMITI!"
GS_Gossip[227532474] = "Erbe... devi parlare con Jandi nel suo arboreto in The Drag.  Ci sono alcune scale in legno dietro al mercato di Asoran nella Valle della Saggezza.  Seguile per raggiungere il livello superiore di The Drag e la troverai."
GS_Gossip[2275670657] = "La Festa del Birraio ha subito alcuni cambiamenti da quando è iniziata. Ora emettiamo token della Festa del Birraio invece di biglietti. Se hai vecchi biglietti, posso scambiarteli per te."
GS_Gossip[2275945145] = "Sono davvero tanti i bug che lasciano la spazzatura qua intorno."
GS_Gossip[2276415934] = "Il solido contenitore è posizionato al centro della segheria, circondato da detriti e da devoti molto zelanti della Crociata Scarlatta."
GS_Gossip[2279272594] = "Penso di averli visti prendere il controllo di lui dal lato nord dell'abbazia, vicino ai bersagli per l'arco."
GS_Gossip[2280314267] = "Sei pronto a combattere i Guardie Stormpike nella Valle d'Alterac, YOUR_NAME?"
GS_Gossip[2284077896] = "Cerco addestramento, Signora Alistra."
GS_Gossip[2287158915] = "Ho di ogni genere di merci in vendita, YOUR_CLASS.  Esplora a tuo piacimento."
GS_Gossip[2287899351] = "Tragico..."
GS_Gossip[2289219694] = "Un drago ambra al massimo potere può eseguire il rift temporale, che crea una bolla di tempo compresso intorno a un nemico. I incantesimi che passano attraverso la bolla infliggono danno doppio e possono generare cariche di shock sul bersaglio."
GS_Gossip[2289665288] = "Sono pronto a lavorare per te oggi! Dammi le cose buone!"
GS_Gossip[2291472963] = "Non abbiamo un posto del genere nel villaggio. Le altezze imponenti del Picco del Tuono invece sì. Dirigiti a nord lungo la strada che esce da Bloodhoof Village fino a raggiungere la base delle scogliere. Là, prendi l'ascensore fino in cima e parla con un Guardiano delle Scogliere. Che i tuoi antenati vegliino su di te."
GS_Gossip[2292164400] = "Noi praticanti delle arti arcane ed elementali seguiamo un percorso senza fine di scoperta. Per questo motivo cerchi il mio consiglio? Desideri ulteriore addestramento?"
GS_Gossip[2293388374] = "Controlla il quadro degli annunci se stai cercando lavoro, YOUR_RACE."
GS_Gossip[2294356442] = "Maestro del Zeppelin"
GS_Gossip[2294561657] = "E tu chi sei?"
GS_Gossip[2294842102] = "Benvenuto al porto di Orebor, amico. Non c'è nulla da temere qui. Siamo rotti, ma non siamo i tuoi nemici.NEW_LINENEW_LINESono Ikuti della Kurenai, un gruppo di Danneggiati che desidera ristabilire i legami con i nostri fratelli draenei e i loro nuovi alleati."
GS_Gossip[2299202348] = "Mercante di Gemme Aldor"
GS_Gossip[2302097040] = "I nani ci hanno protetti nel loro domicilio per un certo periodo ormai, e per questo li ringraziamo. Tuttavia, l'occupazione del nostro domicilio da parte del traditore Thermaplugg deve finalmente terminare.NEW_LINENEW_LINEGnomeregan ha fermentato sotto il peso atomico del nostro piano mal concepito per troppo tempo. L'esplosione delle bombe a radiazione ci ha costretti a lasciare la nostra città, ma ora possediamo la tecnologia per riprenderla!NEW_LINENEW_LINERiconquisteremo ciò che è nostro... e porteremo Thermaplugg alla giustizia!"
GS_Gossip[2303004806] = "Devo dire che Baia del Bottino ha il miglior zuppa di cozze disponibile ovunque nel Sud dei Mari. Oh, non interessato alla cucina eh? Bene, allora lasciami essere il primo a darti il benvenuto al molo della Maiden's Fancy, la nave passeggeri più raffinata che viaggi tra i Regni Orientali e Kalimdor. Sta per tornare per un altro viaggio a Ratchet, quindi rilassati finché non arriva."
GS_Gossip[2305580371] = "Come li vedi ora?"
GS_Gossip[230564658] = "Sono stato ucciso cento volte. Mi sveglio sempre qui, vivo. Alcuni dicono che sono maledetto e altri..."
GS_Gossip[2306390357] = "Cerco qualcuno, YOUR_CLASS. Per favore, lasciami in pace... è importante che li trovi."
GS_Gossip[2307305900] = "Scommetto che voi cretini pensavate di essere piuttosto furbi alla Porta dell'ira, non è vero? Il tempo di gioco è finito. Siamo qui per assicurarci che non proviate a fare niente."
GS_Gossip[2307418179] = "Prendiamo il comando da qui, hai guadagnato un po' di riposo dopo quella battaglia."
GS_Gossip[2308729910] = "Tu vai nel Quartiere Reale. Tutti lì, in cerchio intorno alla stanza."
GS_Gossip[2309619703] = "Posso dire che il tuo guardaroba ha un disperato bisogno di cure."
GS_Gossip[2312197261] = "Non tutto è perduto, Kharan!"
GS_Gossip[2315331658] = "Maestro di battaglia dell'arena"
GS_Gossip[2315993825] = "Dobbiamo evitare un'altra guerra con l'Orda a tutti i costi!"
GS_Gossip[2316986366] = "Puliscimi per il teletrasportatore, sono pronto a partire!"
GS_Gossip[2317993028] = "Eva, ho perso l'Essenza Spectrale. Ne ho bisogno di un'altra."
GS_Gossip[2319742515] = "Provo a tenere Sentinel Hill fornito, e non è facile con tutta l'azione che vediamo."
GS_Gossip[2321877508] = "Non lo farei in un altro giorno, ma... ho sete e odio bere da solo.NEW_LINENEW_LINEAlziamo i calici!"
GS_Gossip[2323523865] = "Krang Stonehoof è in piedi sopra il suo cerchio di addestramento nell'angolo sud-est del villaggio."
GS_Gossip[2324703386] = "Non puoi vedere che sono occupato qui?"
GS_Gossip[2329534772] = "Puoi dormire nei dormitori, se vuoi. Solo non svegliare i miei uomini, altrimenti ti butterò fuori nel neve io stesso."
GS_Gossip[2334103540] = "L'Albergo dell'Aldor si trova in alto sopra la città di Shattrath, sulla collina dell'Aldor. La funivia per arrivarci si trova a nord-ovest del centro della città."
GS_Gossip[2337171927] = "Se Vi piace, Re Jokkum, potrei sapere cosa è successo a Krolmir?"
GS_Gossip[2340268392] = "Bevvi da questa fiala, e la nebbia verrà dissipata per un breve periodo. Vai con gli spiriti, mio amico."
GS_Gossip[2341726802] = "Nefarian aveva ordinato che gli argomenti non adatti venissero distrutti immediatamente, ma questi orribili mostri non lo avrebbero fatto senza prima infliggere un 'ampio' quantitativo di tortura.NEW_LINENEW_LINEQuando eravamo completamente 'distrutti', raccoglievano ciò che restava e ci gettavano a questi malfattori. I nostri corpi usati come strumenti nel loro gioco malato: gettati nella lava o peggio; nelle braccia aperte e pronte della legione assetata di sangue qui sotto."
GS_Gossip[2341867707] = "Testo US mancante"
GS_Gossip[2341880712] = "Non merito tali elogi, Warlord Goretooth."
GS_Gossip[2342897297] = "Desidero acquistare uno di questi creature."
GS_Gossip[2343496584] = "Va bene, signore dei muffin, mostrami i tuoi muffin!"
GS_Gossip[2343690788] = "Congratulazioni, la tua mente è stata espansa."
GS_Gossip[2344650512] = "Va bene. Dove?"
GS_Gossip[2346832933] = "Gli elementali dell'acqua sono in guerra con gli elementali del fuoco, il che significa più o meno che sono in guerra con noi. Uno dei loro leader, Hydraxis, sta radunando agenti per la sua causa..."
GS_Gossip[2347423992] = "Spero che non stiate cercando quelle aberrazioni. I farmacisti non possono essere fidati, e questo significa che nessuno dei loro piccoli costrutti che pattugliano i corridoi può essere considerato attendibile. Siamo qui per mantenere le cose sicure."
GS_Gossip[2348653465] = "Devo aver vissuto una vita incantata, YOUR_NAME.  Per tornare al mondo come membro dei Forsaken e della Società degli Apotecari... non potrei desiderare un destino più adatto."
GS_Gossip[2348676690] = "Posso sentire la polvere da sparo proveniente da tutte le bombe e i razzi! Vuoi uscire e unirti al divertimento?"
GS_Gossip[2350917002] = "Ok!"
GS_Gossip[2351371482] = "Alleanza Inn"
GS_Gossip[2351746504] = "Larion, voglio aiutarti a combattere questi fastidiosi insetti!"
GS_Gossip[2352928856] = "Dove si trovano le Piastre di Uldum?"
GS_Gossip[2353456797] = "Allora, sei disposto ad aiutare a riparare l'imponente Exodar? Ho sentito che ci vorranno anni prima che l'Exodar torni completamente funzionante. Hai due ore. Scherzo. I nostri ingegneri si trovano nei piani inferiori del Trader's Tier. Vai con la Luce."
GS_Gossip[2354261544] = "Grazie ancora per avermi restituito il mio fortunato nastro da misurazione, YOUR_NAME.  Giuro che mi aiuta a pescare pesci più grandi!"
GS_Gossip[2356618453] = "I maestri delle armi nella Valle dell'Onore all'interno di Orgrimmar, Sayoc e Hanashi, possono insegnarti come usare un arco. Ileda, la maestra delle armi di Lunargenta, che si trova nel Quadrato dei Viandanti, è un'esperta."
GS_Gossip[2359626586] = "Hai un extra di banane?"
GS_Gossip[2360966499] = "Kartak viene per la carne di lingua grossa. Frenzyheart si assicura che ne sia pronta tanta."
GS_Gossip[2362694478] = "Ah, devi recarti alle altezze del Picco del Tuono per visitarne uno. Segui il sentiero verso nord uscendo dal villaggio di Bloodhoof. Alla base delle scogliere troverai un ascensore che ti porterà in cima. Una volta arrivato, chiedi ulteriori indicazioni a uno dei Bluffwatchers."
GS_Gossip[2362785929] = "L'acciaio non è forte, esaltato, la carne è più forte. L'acciaio trae la sua forza da chi lo impugna. Ma basta con questo... In che modo possiamo aiutarti, esaltato?"
GS_Gossip[2369091022] = "Un diario con pagine ingiallite giace aperto all'ultima voce:NEW_LINENEW_LINE\"Non so cosa succederà adesso che Harold si è voltato. Mi è costato tutto per trascinarlo nell'unico posto che ho trovato che potesse tenerlo bloccato e tenerlo. Ho nascosto la chiave su di me, e prego che funzioni...\"NEW_LINENEW_LINESpero di poter uscire da qui, ma per farlo ho bisogno di denaro. Le nostre cose sono tutte nell'armadio, credo... e adesso che ci penso, Harold non tiene sempre la chiave con sé?NEW_LINENEW_LINECi riposerò sopra, adesso sono completamente stanco.\""
GS_Gossip[2370211950] = "Signor Combs, l'ingegnere e il quartiermastro della nave, può fornirvi qualsiasi tipo di forniture possiate necessitare. È anche un bravo riparatore, se il vostro equipaggiamento dovesse aver bisogno di riparazioni."
GS_Gossip[2373571209] = "Cosa possono insegnare altri maestri d'arma?"
GS_Gossip[2375006165] = "L'esecutore supremo e Dame Auriferous mi stanno facendo aspettare, ma non ho tempo per questo! I miei amici sono là fuori che muoiono, YOUR_CLASS!"
GS_Gossip[237800639] = "Allora, supponiamo che io ottenga questa pelle, cosa altro ti servirebbe e cosa potresti realmente creare?"
GS_Gossip[2378753692] = "Assolutamente! Mandami all'Avamposto della Guardia del Cielo."
GS_Gossip[2380407062] = "<Disegnato su questo pergameno c'è lo schema di un robot per riparazioni sul campo.>"
GS_Gossip[2382138044] = "Derak Nightfall, a vostra disposizione!"
GS_Gossip[2382253914] = "Tutti i membri dell'Orda sono uguali ai miei occhi, YOUR_NAME. Abbiamo tutti sofferto molti pesi, e se non fosse per la saggezza e l'onore, saremmo no migliori del Flagello o del mio popolo mentre il nostro sangue era contaminato dal demone Mannoroth.NEW_LINENEW_LINEÈ dovere tuo aiutare l'Orda e difendere il nostro modo di vivere. Ma è anche tuo dovere sapere quando concedere quartiere e compassione a amici e nemici allo stesso modo.NEW_LINENEW_LINECapiscilo bene. Questa è la nuova Orda, non un esercito di demoni-spuntati che manca di libero arbitrio."
GS_Gossip[2383574697] = "TESTO MANCANTE"
GS_Gossip[2385007389] = "Benvenuto a Roccavento. Ci è voluto molto tempo per ricostruirla, ma è stato più che giustificato. Allora sei qui per visitarla, o sei qui per affari?"
GS_Gossip[2385774804] = "Un allenatore di classe"
GS_Gossip[2392296535] = "Il mio compito è prendere cura di queste povere anime. Accetto l'aiuto di chiunque voglia prestare una mano, siano essi Aldor o Scryer.NEW_LINENEW_LINESiamo così sottopersonale che non mi dispiacerebbe affatto mandare via un orco se sapesse come applicare un tourniquet. La politica della città non mi interessa molto."
GS_Gossip[2393468406] = "Indietro o ti taglio in due."
GS_Gossip[2395298782] = "Il modo in cui Michelle Belle si comporta accanto al letto è straordinario! Anche se potrebbe non essere in grado di insegnarti questo, sicuramente potrebbe insegnarti alcuni corretti Primi Aiuti. Al momento risiede nell'Albergo del Orgoglio del Leone."
GS_Gossip[2399464954] = "È il mio capo, Grande Madre. Il leader del mio popolo. Dalla mia terra. Lui... Lui è il figlio di Durotan. È il tuo nipote."
GS_Gossip[2400721355] = "Vai a trovare quelle casse di grano infetti nascoste e usa il tuo Disruptore Arcano su di esse!NEW_LINENEW_LINEArthas avrà quindi le prove necessarie per iniziare l'eliminazione di Stratholme."
GS_Gossip[2401888250] = "Quando ho appreso delle mie parenti qui nel nord, sono venuto a conoscere di più. Ciò che ho scoperto erano tribù in guerra che agivano contro la nostra stessa natura.NEW_LINENEW_LINENon ho più speranza, YOUR_RACE.  Anche il potente Ursoc è stato contaminato da questo luogo maledetto.NEW_LINENEW_LINEHo perso ogni speranza."
GS_Gossip[2404328224] = "Eravamo tutti pronti a salpare per Northrend, ma abbiamo notato un numero elevato di insetti a bordo della nostra nave."
GS_Gossip[2406007204] = "È arrivato il momento di distruggere la Spirale Vettoriale!"
GS_Gossip[2406898463] = "Ho installato un nuovo dispositivo nel matrice regulometro della nostra auto. Questo dovrebbe aumentare il suo coefficiente di velocità di un fattore non inferiore a quindici!"
GS_Gossip[2408228786] = "Il Flagello non è benvenuto a Zul'Drak!"
GS_Gossip[2408957012] = "Mrfrrmrfrmrrr!NEW_LINENEW_LINE<Il geist si schiarisce la gola.>NEW_LINENEW_LINESì?"
GS_Gossip[2411114243] = "Con parte della tecnologia recuperata da gnomi audaci che hanno esplorato Gnomeregan, sono riuscito a costruire la mia invenzione più grande: Il Trasportatore di Materia!    Tutto ciò di cui ho bisogno ora è un ingegnere gnomo esperto per costruire un potente faro accordato con il trasportatore."
GS_Gossip[2416044025] = "Il cuoia della città si trova nel cerchio interno del Quartiere dei Ladri."
GS_Gossip[2417568183] = "Confisco il grano rubato, lo avverto che rubare è una via che porta alla distruzione e alla rovina, ma lo lascio andare per tornare a casa sua."
GS_Gossip[2417620424] = "Dovrai crederci! Affronterai due dei più potenti luogotenenti val'kyr di Arthas!"
GS_Gossip[2419641739] = "Cercavi un gryphon per un volo, eh? Dungar tiene i suoi uccelli su sulla merlatura nel Distretto del commercio. Ricordati solo di aggrapparti forte!"
GS_Gossip[2423438369] = "Non chiamerò mai Brackenwall Village la mia casa. Farlo significherebbe abbandonare ogni speranza di riconquistare le nostre terre giustamente nostre."
GS_Gossip[2427188224] = "Mi insegnò la via del sacerdozio, che in un certo senso è solo un altro aspetto della Luce. Unirsi al vento fu l'acqua dell'oasi, il fuoco del mio accampamento e la terra su cui sedetti. Tutti avevano qualcosa da dire.NEW_LINENEW_LINENegli anni successivi mi hanno insegnato cosa significasse invocare e unirsi agli elementi del mondo. Mi hanno detto che i mondi di tutte le stelle nel cielo, perfino questo, sono composti da questi elementi.NEW_LINENEW_LINEMa arrivò il giorno in cui sentii che avevo imparato abbastanza per andarmene."
GS_Gossip[2431408080] = "Stai bene, Awbee. I tuoi aggressori sono stati eliminati."
GS_Gossip[2433984204] = "Puoi trovare Tannysa in piedi fuori da Alchemy Needs nel quartiere dei Magi."
GS_Gossip[2437732310] = "A lungo abbiamo lavorato per vedere il nostro paese tornare al suo antico splendore, YOUR_CLASS. Mai smetteremo di restare vigili contro coloro che hanno invaso e profanato Quel'thalas. Non riposeremo finché non saranno scacciati dalla nostra vista.NEW_LINENEW_LINENon permettere che esista chi si oppone ai sin'dorei!"
GS_Gossip[2439064938] = "Non avevo mai pensato che saremmo riusciti a scappare da quella giungla umida! Ora sono l'ingegnere capo di questa spedizione. "
GS_Gossip[2442153057] = "Le persone a Nighthaven sanno davvero come divertirsi!"
GS_Gossip[2443765244] = "Oh?"
GS_Gossip[244393397] = "È tu che difenderai il mio popolo e porterai avanti un nuovo periodo di prosperità per Stillpine!"
GS_Gossip[2444079589] = "È bello rivederti, YOUR_CLASS YOUR_NAME.  Dornaa ha chiesto di te."
GS_Gossip[2445330858] = "Shelby Stoneflint custodisce un gran numero di animali domestici per i cacciatori locali. Puoi trovarla vicino alla Distilleria del Tuono se hai bisogno che si occupi di un animale domestico."
GS_Gossip[2449826415] = "Lok'tar YOUR_CLASS!  Abbiamo bisogno dei tuoi servizi nella Valle d'Alterac.  Posso aggiungerti alle liste?"
GS_Gossip[2453526761] = "Alexstrasza, puoi mostrarmi cosa è successo qui?"
GS_Gossip[2453857143] = "Bene, bene... a vedere chi ci ha portato il gatto... e come posso aiutarti, YOUR_CLASS?"
GS_Gossip[2454865423] = "Bg'grrml brgl brm!"
GS_Gossip[2455921211] = "Penso di sentirlo arrivare! Guarda a ovest!"
GS_Gossip[2456284302] = "La taverna \"Riposo del Viandante\"."
GS_Gossip[2456361721] = "Spero che questo posto si riveli una base avanzata per le operazioni del Consiglio delle Ombre. So che suona strano, ma in un certo modo mi manca il Labirinto delle Ombre."
GS_Gossip[2457915637] = "I Riformatori Arcani possono modificare gli effetti magici di un oggetto; questo complesso processo magico è noto semplicemente come riformatura.NEW_LINENEW_LINEAttraverso la riforgatura, un attributo secondario di qualsiasi pezzo di armatura, arma o gioiello può essere ridotto al fine di aggiungere un ulteriore attributo secondario. In questo modo è possibile personalizzare l'equipaggiamento per adattarlo al meglio al proprio ruolo e alle proprie abilità.NEW_LINENEW_LINEPer esempio, se un oggetto ti dava un bonus per colpire i nemici ma preferiresti che ti facesse attaccare più velocemente, un Arcano Reforger potrebbe, per un prezzo, riformare l'oggetto per ridurre il Danno ma aumentare la Velocità d'attacco."
GS_Gossip[246069967] = "Krasus' Landing"
GS_Gossip[2461255592] = "I Highborne sono tornati, e con loro l'arte magica perduta al mondo da secoli.NEW_LINENEW_LINEHai qualcosa da farmi esaminare?"
GS_Gossip[246272831] = "Mi dispiace YOUR_CLASS, ma non sei ancora abbastanza esperto per entrare nella Forra dei Cantaguerra."
GS_Gossip[2463728420] = "Sei sicuro di essere pronto a combattermi?"
GS_Gossip[2464339958] = "Capitolo sul Filo Rosso Incantato."
GS_Gossip[2466185810] = "Il vento non parla più alla nostra tribù, YOUR_NAME.  Il mio popolo è perduto senza anziani per condurre gli spiriti verso di loro."
GS_Gossip[2468684918] = "La conoscenza è potere - POTERE vero, mio giovane amico. Sarà saggio da parte tua acquisirene il più possibile e prestare attenzione a coloro che l'hanno già fatto.NEW_LINENEW_LINEPrima dell'abbattimento del Pozzo del Sole, ci illudemmo pensando di essere giunti all'apice della nostra civiltà. Fu il Flagello a gettarci a terra... e in un certo senso, a riportarci alla realtà."
GS_Gossip[2469729048] = "Sono un prigioniero!NEW_LINENEW_LINEMi hanno sparato e il mio magnifico zeppelino fuori dal cielo. E per cosa? Perché stavo trasportando uomini e materiali per l'Orda? Non è niente di nuovo!NEW_LINENEW_LINEOra mi fanno correre in cerchio attorno alla baia in modo che possano bombardare i pirati. Non ho semplicemente le parti necessarie per mantenerla in funzione in questo modo! Sto a malapena tenendola insieme con della saliva e filo di ferro!NEW_LINENEW_LINESe sei determinato ad aiutarli, dovrebbe tornare in porto entro un minuto.NEW_LINENEW_LINEÈ un crimine, te lo dico io!"
GS_Gossip[2469830823] = "Ileda degli elfi del sangue, che si trova all'interno del Farstrider Square di Lunargenta, addestra i suoi studenti nell'uso di spade monomane e doppie. Archibald, maestro delle armi di Sepulcra, può addestrarti anche lui; si trova nel Quartiere della Guerra."
GS_Gossip[2471116853] = "Io confronto il sovrano per il suo comportamento malvagio, difendendo l'onore del mio signore a rischio di ogni futura diplomazia."
GS_Gossip[2472309441] = "Un altro bel giorno cupo qui a Tranquillien, non ti pare, YOUR_CLASS?NEW_LINENEW_LINECosa posso fare per te?"
GS_Gossip[2475712112] = "Sì! Voglio di più di quel fantastico Eliciario Noggenfogger!"
GS_Gossip[2475782954] = "<Mentre saluti l'ambasciatore Frasaboo in lingua furbolg, lui sorride.>NEW_LINENEW_LINEDevi essere tu di cui si parla nella profezia. È un grande onore incontrarti.NEW_LINENEW_LINESono l'Ambasciatore Frasaboo, il rappresentante del Capo Stillpine a Blood Watch."
GS_Gossip[2476321321] = "Dove si trova Morndeep l'Anziano?"
GS_Gossip[2476438287] = "Sono giurato per legge tuskarr di vendicare i miei simili... questi assassini hanno bruciato Pal'ea fino all'ultimo angolo."
GS_Gossip[2476490388] = "La nostra Skyguard Aether-tech e il suo convoglio stanno studiando la forgia cristallina Bash'ir. Ha bisogno di aiuto! Vai a Bash'ir Landing, trova l'aether-tech e proteggila!"
GS_Gossip[2477224460] = "Huh? Cosa? Sono un po' occupato qui, amico!NEW_LINENEW_LINECerto, se sei qui per aiutare, ho tutto il tempo del mondo."
GS_Gossip[247770983] = "C'è qualcosa che posso fare per te, Nonna Grande?"
GS_Gossip[2479128375] = "Cerco di comprendere l'importanza della forza del corpo."
GS_Gossip[2479773245] = "Sei serio? Mi ha gia' ucciso! Cosa potrebbe volere di piu'?"
GS_Gossip[2480284911] = "Tamburi della Guerra"
GS_Gossip[2480697675] = "Starà bene per ora, non preoccuparsi per me. Troverò un modo per uscire da qui una volta che avrò eseguito alcuni rituali di purificazione in questa stanza. Magia malsana inquina questo posto, YOUR_NAME."
GS_Gossip[2488244195] = "La Legione Infuocata. Demoni. Li vedo chiaramente quanto puoi vedere la tua mano davanti al tuo viso. Intendo, un tempo ero in grado di vederli chiaramente.NEW_LINENEW_LINECon il ritorno della Legione arrivano nuove machinationi. In condizioni normali, sono in grado di percepire la presenza di un demone da un miglio di distanza.NEW_LINENEW_LINE<Altruis sbatte le palpebre.>"
GS_Gossip[2488823053] = "Tai'jin è il suo nome e la troverai all'interno dei caserma del lato est di Razor Hill. Ti insegnerà a rispettare gli dei. Assicurati di mostrare il rispetto giusto in cambio!"
GS_Gossip[2491175953] = "Sto per scoprire cosa sta combinando questo misterioso gruppo, qualunque cosa stia facendo!"
GS_Gossip[2492276390] = "Ascia"
GS_Gossip[2492333617] = "Posso vedere le tue merci?"
GS_Gossip[2492962216] = "Sto lavorando, qui."
GS_Gossip[2493054570] = "Mi hanno mandato a cercarti? Bene, non tornerò senza i miei uomini."
GS_Gossip[2493869885] = "L'Hippogriph è un animale nobile, orgoglioso e veloce. Sono un onore addestrarli, e possono portare rapidamente il loro cavaliere a una grande distanza."
GS_Gossip[2499022322] = "Devo obbedire."
GS_Gossip[2499414211] = "E pensi che possa mangiare qualcosa che voglio? Stai chiaramente cercando di mangiare i Danneggiati di Telaar."
GS_Gossip[2501852038] = "Una battaglia?"
GS_Gossip[2502137539] = "Allenami."
GS_Gossip[2502211366] = "Dovrei saperlo? A me sembri un orco."
GS_Gossip[2503754562] = "La battaglia contro Kael'thas e Illidan continua su tutti i fronti. La sconfitta non è un'opzione."
GS_Gossip[2504481501] = "Arco"
GS_Gossip[2505037232] = "Lascia perdere la mantella! Sì, sì, so che ne vorresti una anche tu. Tutti vogliono una delle mie mantelle. Ti credo, persona di bassa moralità e scarsa posizione sociale, un giorno farò fortuna vendendo le mie mantelle. Tutti, da qui a Forgiardente, conosceranno il nome di Bartolo Ginsetti. Il marchio Ginsetti sarà ambito da tutti!"
GS_Gossip[2508878586] = "Xon'cha stabilizzerà i tuoi animali domestici extra. Trovalo nella Valle dell'Onore, alle stalle tra l'arena e la Hall del Cacciatore. Ora andate via!"
GS_Gossip[2511500419] = "Il mio odio per gli interruzioni è superato solo dalla mia avversione per Gruul il Dragonkiller e i suoi sette figli!"
GS_Gossip[2512725457] = "La console sembra antica, anche se non c'è segno di decadimento o deterioramento. Un'unica fessura sembra adattarsi a dischi circolari di grandi dimensioni."
GS_Gossip[2513703373] = "Con la mia libertà viene la vendetta della tempesta!"
GS_Gossip[2514682499] = "Cosa vuoi, YOUR_CLASS? Sto arrivando in ritardo, e il mio datore di lavoro non gradisce la puntualità."
GS_Gossip[2516564791] = "Serviamo Thrall con grande orgoglio. Viaggeremo quanto necessario per sconfiggere l'avversario."
GS_Gossip[2518239846] = "L'orso delle zampe di ghiaccio giace qui tranquillizzato."
GS_Gossip[2518525720] = "A differenza della maggior parte degli orchi, io so benissimo a cosa serve un gabinetto - darti uno schizzo. Ora vattene."
GS_Gossip[2519749254] = "I miei rapitori erano crudeli al di là di ogni misura, YOUR_NAME. Alternavano tra il Tenente Kirith e me, torturando uno mentre l'altro osservava. Durante una pausa nell'attività di un giorno particolarmente crudele, Kirith mi raccontò cosa era successo ai miei uomini e un piano che aveva formulato per liberarli dai loro padroni.NEW_LINENEW_LINEHanno subito un destino molto peggio della morte, o perfino del dolore che Kirith e io abbiamo sopportato."
GS_Gossip[2519800650] = "Se riesci a completare un mazzo di carte dei portali, ti verrà premiato con una carta oscura più potente del Nether Tormentato. Questa carta ti farà occasionalmente richiamare lo spirito nel tuo corpo dopo la morte e ti ripristinerà."
GS_Gossip[2523530829] = "Quello che devi capire è che essere in grado di indicizzare 10,000 anni di esistenza mi hanno dato una prospettiva abbastanza unica sulla vita. Le vostre prove e sofferenze del presente sono senza significato."
GS_Gossip[2525989381] = "Niente al mondo è come sentire qualcosa di morto che si strofina contro di te. Puoi trovare Shelene Rhobart dirigendoti a sud-est lungo la strada che porta fuori dal paese, e poi andando a est all'incrocio. È in un piccolo accampamento lì non troppo lontano lungo la strada."
GS_Gossip[2526464816] = "Sono tornato tra il mio popolo e sono stato accolto con volti sorridenti e braccia aperte, soprattutto da coloro che erano stati Danneggiati. I pregiudizi contro di noi da parte di molti draenei erano continuati durante la mia assenza. Ma era come se sapessero che stavo arrivando, e presto ho scoperto il motivo.NEW_LINENEW_LINEVelen, il profeta e leader di tutti i draenei, aveva visto il mio ritorno in uno dei suoi visioni e era lì per salutarmi. Mi chiese di parlare in privato e, mentre gli raccontavo la mia storia, annuì e sorrise, poiché anche questo l'aveva previsto."
GS_Gossip[2530762643] = "Sarò uno dei primi a rispondere al richiamo alla battaglia di Vol'jin. Ti unirai a noi?"
GS_Gossip[253263363] = "Sarei felice di prenderti sotto la mia ala. Cominciamo."
GS_Gossip[253275967] = "Il nostro maestro Malfurion è tornato dal Regno dei Sogni,YOUR_CLASS.  La Luce è quella di un faro che ci mostra la via, e dobbiamo fare di tutto per preservare quella luce."
GS_Gossip[2532898381] = "Hai bisogno di rendere i tuoi punti più piccoli, YOUR_NAME. Pochi oggetti scapperanno dalle tue faretre e dai sacchi di munizioni. Inoltre, nessuno apprezza una tunica rigonfia."
GS_Gossip[2534537160] = "L'Apexis Reliquia brilli, tradendo una intelligenza nascosta al suo interno."
GS_Gossip[2535079735] = "Sì, per favore continua."
GS_Gossip[2537780696] = "Che differenza fa se queste lupa femmine e i giganti del gelo si uccidono a vicenda ogni giorno?NEW_LINENEW_LINENo, no... Voglio che Thorim si svegli e raduni tutti i suoi alleati per riprendere Ulduar.NEW_LINENEW_LINEIl mondo sarà strappato in due se non riuscirà a compiere questo compito!NEW_LINENEW_LINEE naturalmente, ti ripagherò appropriatamente."
GS_Gossip[2538532497] = "Tale saggezza è impregnata di un mistero che si può trovare solo nel grande Picco del Tuono. Segui il sentiero verso nord uscendo dal villaggio di Bloodhoof fino ad arrivare a un ascensore alla base dei rilievi. Prendilo fino in cima e chiedi a uno dei Bluffwatchers ulteriore assistenza."
GS_Gossip[2539036317] = "Thel'zan deve morire, se solo per fermare il continuo blaterare!"
GS_Gossip[2539142625] = "Dove si trova Elder Bronzebeard?"
GS_Gossip[2540356530] = "Finiamolo!"
GS_Gossip[2541112166] = "Dovresti restare nascosto, per favore? Sto cercando di fingere di essere ancora sotto il controllo del Re dei Lich!"
GS_Gossip[2543628485] = "Darei quasi tutto per avere l'occasione di salire là e parlare con loro..."
GS_Gossip[2549548671] = "È da questo trono che emetto il comando di Hellscream. La sua parola è vita e la sua parola è morte."
GS_Gossip[2550537367] = "Vivo solo per servire, Capo Guerriero! La mia vita è vuota e priva di significato senza la tua guida."
GS_Gossip[25554656] = "L'attivazione dei sistemi difensivi secondari porterà all'estinzione delle forme di vita non autorizzate tramite impianti orbitali.NEW_LINENEW_LINESei un essere vivente non autorizzato. Per favore conferma."
GS_Gossip[2556615428] = "Salve, campione! Hai mai pensato a diventare un gladiatore a tempo pieno? Tu e io potremmo accumulare una montagna d'oro."
GS_Gossip[2562649454] = "Cosa gli è successo inizialmente? Quando io... l'ho incontrato, era abbastanza malvagio."
GS_Gossip[2566653071] = "Qual è la tua funzione?"
GS_Gossip[2568550828] = "I nani Wildhammer potrebbero avere cavalli veloci, ma quei gryfoni del Picco dell'Aerie resisterebbero al calore della Grande Fucina? Non credo proprio!"
GS_Gossip[2569266463] = "Ciao! Il mio nome è Jenna! E tu? "
GS_Gossip[2573023989] = "Puoi trovare il maestro del gryphon sulla rampart nord-est che sovrasta la Valle degli Eroi."
GS_Gossip[2574024092] = "Finalmente, sono libero dalla corruzione che un tempo mi legava a questo posto..."
GS_Gossip[2574593780] = "I troll si comportano in modo strano, YOUR_NAME.  Non mi piace.  Non mi piace per niente."
GS_Gossip[2575888957] = "Ehi, non puoi vedere che sono occupato qui?!NEW_LINENEW_LINEVuoi vedere lo spettacolo? La band suona ogni notte alle otto."
GS_Gossip[2576114227] = "Ho preso una decisione. Fammelo dimenticare, la mia maestria nell'alchimia!"
GS_Gossip[2578153150] = "Alloggio"
GS_Gossip[257867719] = "Posso indicarti altri maestri d'arma se preferisci. Di cosa hai interesse?"
GS_Gossip[2579564697] = "La tua propaganda non funzionerà su di me. Sputa il tuo sporco traditore altrove, traditore!"
GS_Gossip[2579850675] = "Formatore di professioni"
GS_Gossip[2580237515] = "Josetta è stata una benedizione per questa città grazie all'aiuto che ha dato ai guardie locali.  Se cerchi lei per addestramento nei modi di un prete, puoi trovarla nell'Albergo del Orgoglio del Leone."
GS_Gossip[2581190319] = "Desidero acquistare un acceleratore arcano da te."
GS_Gossip[2582083656] = "I miei ordini sono di creare una distrazione alla Dead Scar in modo che le nostre forze possano prendere l'Armadio di Sun's Reach. Potrebbe non essere altrettanto glamour come uccidere i demoni faccia a faccia, ma se vince questa battaglia, ne sono tutto a favore.NEW_LINENEW_LINESiamo $3233w percento completato del nostro obiettivo."
GS_Gossip[2582115925] = "Noi abbiamo l'attrezzo per pelle. Lo otteniamo da Killian Hagey, che ci insegna come pelleare le prede. Hai una bella pelle. Lo trovi sulla ringhiera interna del Quartiere dei Ladri."
GS_Gossip[25843375] = "Ciao. Sono Vixton Pinchwhistle, venditore ufficiale per l'Arena del Circuito di Combattimento di Steamwheedle. Se hai la reputazione necessaria, ho gli articoli che ti faranno venire l'acquolina in bocca."
GS_Gossip[2592635124] = "L'oscuro anziano vagherà vicino al Sepolcro nella Foresta di Silverpine."
GS_Gossip[2594159003] = "L'anziano Thoim ha trascorso molti anni a Moa'ki Harbor nel Dragonblight."
GS_Gossip[2594839286] = "Mettiti da parte, YOUR_RACE. Non puoi vedere che siamo in mezzo a una battaglia!"
GS_Gossip[259507003] = "Se trattengo il respiro, di che colore diventerei?"
GS_Gossip[2595565532] = "<Brann ti guarda in attesa.>"
GS_Gossip[2596202380] = "Chu'a'lor ha detto delle cose buone su di te, YOUR_NAME.  Se vuoi, abbiamo un paio di birre speciali degli ogre in vendita.NEW_LINENEW_LINESono davvero deliziosi!"
GS_Gossip[2596542889] = "Stiamo celebrando la primavera durante Noblegarden. Affermazione della vita e tutto il resto."
GS_Gossip[2599988817] = "Frenzyheart può essere violento, ma noi siamo persone buone. Vedi, se rimani a lungo, diventiamo amici con quelli intelligenti e forti, e va tutto bene.NEW_LINENEW_LINENon ci piace semplicemente l'ignoranza."
GS_Gossip[2601597917] = "Faccio quanto posso per addestrarti nei modi sacerdotali, se questo è il motivo per cui sei qui."
GS_Gossip[2601918452] = "Salve! Se siete qui per accedere agli schemi di ingegneria goblin, sappiate che interagiamo solo con ingegneri goblin certificati."
GS_Gossip[2602849184] = "Benvenuto a Tanaris, YOUR_NAME. Come posso esserti di aiuto oggi? Non sembri un fabbro, ma so che spesso l'apparenza può ingannare."
GS_Gossip[2603206346] = "Fucile"
GS_Gossip[2605765672] = "Le conoscenze di Cyndra in alchimia sono un po' limitate, ma ne sono sicuro sarebbero sufficienti per fartene un'idea. Pratica la sua arte proprio a est dell'Albergo, a Dolanaar."
GS_Gossip[260679840] = "Eldrin è l'unico a Elwynn Forest che chiamerei sarto. Lo puoi trovare al Eastvale Lumber Camp se sei interessato a imparare la professione."
GS_Gossip[2610200152] = "Ecco qua! La Fiera di Lunacupa è ora aperta per gli affari! Assicuratevi di vedere lo spettacolo più emozionante di tutta l'Azeroth!"
GS_Gossip[2612253292] = "I maestri di battaglia dell'Arena si trovano nella città bassa sud-est, lungo il muro."
GS_Gossip[261289149] = "Be'... sì."
GS_Gossip[2613630520] = "Cerca la Torre di Atterraggio del Zeppelin orientale fuori dalla città a sud-est."
GS_Gossip[2614778500] = "Sono un prigioniero!NEW_LINENEW_LINEMi hanno sparato e il mio magnifico zeppelino fuori dal cielo. E per cosa? Perché stavo trasportando uomini e materiali per l'Orda? Non è niente di nuovo!NEW_LINENEW_LINEOra mi fanno correre in cerchio attorno alla baia in modo che possano bombardare i pirati. Non ho semplicemente le parti necessarie per mantenerla in funzione in questo modo! Sto a malapena tenendola insieme con della saliva e filo di ferro!NEW_LINENEW_LINESe sei determinato ad aiutarli, dovrebbe tornare in porto in meno di $3078w minuti.NEW_LINENEW_LINEÈ un crimine, te lo dico io!"
GS_Gossip[2616589671] = "Stavamo per prepararci a riprendere le Isole dell'Echo. Zalazane ha lavorato per un po' il suo voodoo magic, convincendo la gente che lui sia morto e praticando antichi rituali oscuri.NEW_LINENEW_LINESaprebbe che stiamo arrivando, quindi dobbiamo assicurarci di essere preparati."
GS_Gossip[2616637913] = "Non sto combattendo, quindi mandami dentro adesso!"
GS_Gossip[2617601117] = "Oh bene, rinforzi!"
GS_Gossip[2617805815] = "Il nostro cibo dovrebbe soddisfare anche la fame più intensa."
GS_Gossip[2621779927] = "Che aspetto ha? Il terreno è congelato come una roccia!NEW_LINENEW_LINELe ruote su questi carri da carne sono state costruite per superare la fanghiglia al massimo. Abbiamo bisogno di un abominio e di alcune catene per recuperarli."
GS_Gossip[2627589488] = "Benvenuto, amico del popolo libero della Città Bassa, ma non trattenerti a lungo.NEW_LINENEW_LINESi sentono rumori di battaglia provenienti dall'interno. I miei compagni potrebbero aver bisogno del tuo aiuto!"
GS_Gossip[2632944426] = "Ah, credo che Gimble Thistlefuzz sia chi vi servirà se state cercando di imparare la professione dell'Incantatore. Lo troverete nel suo negozio, Thistlefuzz Arcanery, proprio accanto al Maestro Grifone presso La Grande Fucina."
GS_Gossip[2634016853] = "Il nostro progresso costante nella nostra lotta contro i Qiraji può essere attribuito all'aiuto diversificato che abbiamo ricevuto da quasi ogni angolo di Kalimdor.NEW_LINENEW_LINEHai bisogno di più di semplici soldati per combattere una guerra, YOUR_NAME.  Tanti dei silenziosi eroi della guerra sono i commercianti e gli artigiani che mantengono fornite le nostre forze con le risorse di cui hanno bisogno."
GS_Gossip[2634868798] = "Il maestro della guild è Christopher Drakul. È sulla piattaforma orientale nel quartiere commerciale."
GS_Gossip[2636131254] = "Alza gli occhi al cielo, YOUR_CLASS. I voli draghi non sono stati visti in questa area da mille anni! Quei Qiraji stanno combinando qualcosa, ne sono sicuro!"
GS_Gossip[2636789569] = "Nana sempre disse che non c'era niente di migliore al mondo di una fetta calda e profumata di torta di ciliegie fresche fatta in casa."
GS_Gossip[2637266069] = "Ileda dei blood elf, nel Farstrider Square di Lunargenta, addestra i suoi studenti nell'uso di spade monomane e doppie. Archibald, maestro delle armi di Sepulcra, ti addestra anche tu, mon. Lui si trova nel War Quarter."
GS_Gossip[2642005505] = "Non sei molto sveglio, eh? Hmm, se fossi un maestro di stalla forse potrei essere nei paraggi, diciamo, della stalla? Cerca Morganus laggiù."
GS_Gossip[2644174628] = "Rinchiuso in questa piccola casa, sogno di unirmi alle battaglie che infuriando fuori dalle mura della città. Tuttavia, il dovere mi costringe a condividere le mie conoscenze con altri che combattono al mio posto... per ora."
GS_Gossip[2644617838] = "Le Plaguelands sono un eccellente posto per colpire il Flagello!"
GS_Gossip[26447066] = "Gorzeeki, desidero effettuare un acquisto."
GS_Gossip[2645589329] = "<L'Arcano Guardiano resta immobile, aspettando che tu chiarisca a quali Battlemaster ti riferisci.>"
GS_Gossip[2647301759] = "La mia ascia ha visto molti battaglie, e mi piace tenerla a portata di mano. Le forze nemiche hanno combattuto il loro modo dentro la nostra capitale diverse volte ormai, ma non temere: le abbiamo sempre respinte indietro."
GS_Gossip[2652743280] = "Se vuoi imparare come impugnare le armi, vai da Archibald nell'anello interno del Quartiere della Guerra."
GS_Gossip[2653724775] = "Dobbiamo preparare questo avamposto per l'attacco verso il Bacino di Sholazar.NEW_LINENEW_LINENon stare lì immobile, YOUR_CLASS. Esci e rappresenta l'Orda con onore e sangue versato!"
GS_Gossip[2655431283] = "Per favore continua, Eroe..."
GS_Gossip[2655646822] = "Vivere qui nel deserto è dura! Mi sento così assetato stando fuori al calore."
GS_Gossip[2656064399] = "Entra fuori dal freddo e riposa un po' le tue ossa stanche. La nostra ospitalità è tua."
GS_Gossip[2656988242] = "Elder Chogan'gada può essere trovato nel Pinnacolo di Utgarde."
GS_Gossip[2660475938] = "Ah, la bellezza di Shadowglen non smette mai di deliziare i miei sensi!"
GS_Gossip[2667950860] = "Saluti. In che modo possiamo aiutarvi oggi, dal Banco della Borsa Reale?"
GS_Gossip[267083782] = "Cosa ti aspetti, mon?NEW_LINENEW_LINEMaywiki solo occuparsi dei druidi e degli shaman."
GS_Gossip[2670971849] = "Un'altra nuova faccia? È così bello conoscerti. Sono Dellylah."
GS_Gossip[2673469347] = "Per favore rispetta le leggi di Dalaran mentre sei qui, straniero.NEW_LINENEW_LINESei perso? C'è qualcosa che posso aiutarti a trovare?"
GS_Gossip[2673867422] = "Solo un piccolo libretto di canzoni che pensavo potresti apprezzare. Contiene i testi di una canzone nota come Il Lamento degli Altissimi; quella che la Signora Sylvanas ha estratto dall'aria con il suo incanto."
GS_Gossip[2673962691] = "<Budd rimane immobile, fingendo di non sentirti. Guardandolo attentamente, noti che da sotto la sua maschera gocciola un po' di bava.>"
GS_Gossip[2675177946] = "Per l'amore di tutto ciò che è santo e caro, per favore ditemi che siete venuti a liberarci da questa terra abbandonata. Anche se sono con i Marshal Expeditions, vi darei i denti d'oro della mia bocca per poter entrare nella vostra borsa e lasciare questo posto."
GS_Gossip[2677121288] = "Allora, cosa ne dici se consegni un messaggio per me?"
GS_Gossip[267743443] = "Svuinciare? L'unica cosa che sembri in grado di svuinciare è il tuo ginocchio! Ah! Ora perché non vai a parlare con Balthus Stoneflayer, così può insegnarti come svuinciare correttamente degli animali. Lo troverai in Finespindle's Leather Goods, dal lato nord della Grande Fucina."
GS_Gossip[2677688269] = "Ti addestrerei, ma non sei un guerriero."
GS_Gossip[2679171628] = "Stare così vicino alla lama che ha messo fine alla mia vita... Il dolore... È rinato."
GS_Gossip[2679832926] = "Il bersaglio da combattimento ravvicinato addestra gli Aspiranti in attacco e difesa montati.NEW_LINENEW_LINEAvvicinati al bersaglio da vicino e colpiscilo con un attacco di spinta. La forza del colpo spesso fa ruotare il bersaglio abbastanza da farti male o al tuo montato. Questo è il momento in cui la difesa entra in gioco.NEW_LINENEW_LINEAssicurati di avere almeno uno strato di Difendere prima di attaccare il bersaglio e continua a sovrapporre e rinfrescare Difendere durante l'esercitazione. Altrimenti potresti ritrovarti smontato.NEW_LINENEW_LINELo stesso vale nel combattimento effettivo a cavallo: bilanciare attacco e difesa, spostandoti ogni volta che ne hai l'occasione e mantenendo i livelli di Difesa al meglio possibile."
GS_Gossip[2680673357] = "Vekjik non vuole essere disturbato."
GS_Gossip[268293515] = "La nostra punizione è anche la nostra benedizione."
GS_Gossip[2687453203] = "A nome della Società Reale degli Alchimisti, sono lieto di offrirti i migliori animali da sella disponibili per i Forsaken. Questi animali hanno sopportato prove e tribolazioni come noi tutti, e ora sono emersi più forti e resilienti di quanto la carne mortale avrebbe mai potuto farli diventare! Per favore, ispezionali da te stesso e vedrai."
GS_Gossip[2688510850] = "Ci vuole un po' di pratica per stare così vicino ai silithid senza farsi notare. Non ti consiglio di provarci se puoi evitarlo."
GS_Gossip[2691574710] = "Posso creare cose incredibili con i materiali che trovo qui fuori. Per la barba di Muradin, ci sono creature fantastiche in queste colline! Vai a provarle, YOUR_NAMEe portatemi indietro qualche storia avvincente."
GS_Gossip[2693042389] = "L'osteria - se si può dire così - si trova sulla parte alta del quartiere commerciale. Non hanno nemmeno i letti."
GS_Gossip[2693361740] = "Guarda questi esempi! Cosa significa? Cosa significa? Mi servirà tempo, tempo per esaminare tutta questa informazione. E mi servirà più informazioni. Informazioni che non posso ottenere... dannazione! Pensa, Laris, pensa!NEW_LINENEW_LINECosa intendi fare? Cosa?!NEW_LINENEW_LINEDeve esserci una soluzione!"
GS_Gossip[2693742647] = "Devo aver commesso un errore da qualche parte per essere stato assegnato qui."
GS_Gossip[2697324812] = "L'antico Altare di Hakkar giace in silenzio vicino all'ingresso della stanza.NEW_LINENEW_LINEGuardando alle balconate sopra, noti che su ciascuna riposa una statua molto simile a una serpe. Le statue sembrano molto simili a quelle sull'altare davanti a te. Devono essere in qualche modo correlate..."
GS_Gossip[2701829176] = "La raccolta delle bende procede secondo il piano. Per quanto riguarda le bende di lino, ne abbiamo raccolte $2076w di $2077w. I bendaggi di seta sono stati conteggiati a $2082w fuori da $2083w, e abbiamo $2088w fuori da $2090w fasciature di tela magica necessarie."
GS_Gossip[2704554673] = "<La Grande Madre Geyah ride debolmente.>NEW_LINENEW_LINECerto che no, cara. Ma non è a me che tocca credere...NEW_LINENEW_LINEGarrosh può guidare i Mag'har. È forte e saggio. Tutti gli spiriti lo approvano. Deve solo credere in se stesso. Ha così tanto timore... Ha tanto timore che se si lascia andare, la sua rabbia lo consumerà e tutto ciò che lo circonda."
GS_Gossip[2710631440] = "Celebrare la nascita di un altro nemico mortale è una cosa strana, almeno a dirsi. Tuttavia, uniremo i nostri alleati nelle loro celebrazioni."
GS_Gossip[2715155448] = "Sono pronto ad imparare la Ricetta del Mantello di Gelidi Mortai."
GS_Gossip[2715410278] = "Sono pronto, vostra grazia. <bacia il anello>"
GS_Gossip[2715763452] = "Impaziente di raggiungere Northrend, eh? Il Kraken a vapore parte da qui per Valiance Keep nella Tundra Boreale."
GS_Gossip[2717763043] = "Arnok produce buoni bendaggi. Trovalo alla capanna di Survival of the Fittest sulla riva del lago accanto alla Spirit Lodge nella Valle degli Spiriti. Si trova sopra e a ovest della Valle della Forza."
GS_Gossip[2722824171] = "Promesso, ti ringraziamo per l'avvertimento. La tribù Stillpine sarà preparata."
GS_Gossip[2723747730] = "Cerco addestramento nei modi del Cacciatore."
GS_Gossip[2728102831] = "Perché adesso, YOUR_RACE? Non lo capisco. Tanto lavoro da fare..."
GS_Gossip[2728991749] = "Salve a te, YOUR_CLASS."
GS_Gossip[2736123704] = "Troverai le caselle postali all'interno o appena fuori dagli uffici postali e dagli alberghi degli Aldor e dei Scryers."
GS_Gossip[2736575069] = "Plucky? Ho sentito dire che il maestro delle razze Kronkrider su nella torre sa dove si trova."
GS_Gossip[2736979525] = "Ma sei dei draghi! Come potrebbero gli orchi farti questo?"
GS_Gossip[2738746010] = "Stendardo del Campione dei Caduti"
GS_Gossip[2739345356] = "Hai degli scorpioni o dei coleotteri, YOUR_CLASS?  Scurrono veloci, ma se sei più veloce, li troverai molto appetitosi!"
GS_Gossip[2739930018] = "Le razze più giovani fanno un gran chiasso riguardo al Winter Veil. La banca di Forgiardente è al centro delle celebrazioni."
GS_Gossip[2740253711] = "Saluti, YOUR_NAME.  Siamo venuti da Moonglade per diffondere lo spirito del Festival Lunare in ogni angolo del mondo.NEW_LINENEW_LINENon ti unirai a noi per celebrare?"
GS_Gossip[2740713726] = "Grazie, YOUR_RACE. Ora preparatevi. Archimonde è in marcia, e dobbiamo resistere all'inevitabile per quanto più a lungo possibile."
GS_Gossip[2741008] = "Come stai, amico?"
GS_Gossip[2747954169] = "Sei sicuro di volere il mio aiuto nella battaglia contro Yogg-Saron?"
GS_Gossip[2749573774] = "Guardiano Leesa'oh, perché sei qui fuori?"
GS_Gossip[2751225792] = "Sì, certo, vai pure a dire al vecchio Babbo Natale cosa vorresti per questa Veglia Invernale.NEW_LINENEW_LINEHo ho sbrigati."
GS_Gossip[2752598522] = "Fai attenzione ai tuoi passi, straniero. Non permettiamo misfatti nel nostro paese."
GS_Gossip[275318536] = "Cacciatore"
GS_Gossip[2753623112] = "Benvenuto a Blood Watch, YOUR_CLASS. Nel mio viaggio, ho raccolto una vasta varietà di strumenti, oggetti e conoscenze provenienti dalle varie popolazioni che abbiamo incontrato.NEW_LINENEW_LINESe dovessi trovare il bisogno di questa conoscenza, hai soltanto da chiedere."
GS_Gossip[2753755017] = "Dove si trova Elder Brightspear?"
GS_Gossip[2754243162] = "C'è del denaro da guadagnare! Proprio come diceva sempre papà - non c'è momento migliore per incassare i soldi che durante un periodo di guerra."
GS_Gossip[2756104758] = "Desidero fare della Rocca dell'Onore la mia casa, Sid."
GS_Gossip[2756393606] = "Dovremo semplicemente migliorare la nostra collaborazione per stare al loro livello."
GS_Gossip[2758810485] = "A tutti piace bere. Cosa possiamo offrirti?"
GS_Gossip[2761282447] = "Non ne vedo troppi intorno a questi parti, vero? Sto cominciando a pensare che sia perché i magi ci danno tutti i lavori pericolosi che preferirebbero non fare da soli."
GS_Gossip[2762759407] = "Un potere incredibile può essere trovato nello spirito o \"muisek\" delle creature contro cui combattiamo.NEW_LINENEW_LINEGuarda dentro di te; impara a sfruttare il potere del tuo spirito, e sarai più potente di quanto mai immaginato."
GS_Gossip[2765216943] = "Ancora facciamo le cose come prima, ma il banchetto di Winter Veil ora sembra vuoto. A Orgrimmar hanno la vera celebrazione."
GS_Gossip[2765652721] = "Prima Aid"
GS_Gossip[2767180859] = "Salve, viaggiatore! Ti va di approfondire i misteri dell'arcano? Hm?"
GS_Gossip[2768133137] = "Giuro... se Quint prova a piazzarmi un altro verme da pesca, andrò a tagliare suo albero con la mia spada non troppo arrugginita."
GS_Gossip[2773179744] = "Ho troppo da fare e non abbastanza tempo per farlo, YOUR_RACE! Per favore, scostati.NEW_LINENEW_LINESe sei infettato dalla melma delle larve o dalla putrefazione dei necromanti, forse posso aiutarti."
GS_Gossip[2773707509] = "Tra gli etheriali, alcuni membri si occupano specificamente di carne e esseri di carne. Quegli individui sono noti come manipolatori di carne."
GS_Gossip[2774937059] = "A volte quei dannati elfi del sangue fanno visita e richiedono alcuni reagenti o veleni inutili. Devo mantenere sempre a magazzino una scorta di tali oggetti, altrimenti Lord Illidan potrebbe venire a sapere che i Dragonmaw non stanno collaborando...NEW_LINENEW_LINE<Rumpus inghiotte con difficoltà.>NEW_LINENEW_LINENon vogliamo che accada..."
GS_Gossip[2775654010] = "Cerchi qualcuno che si distingue? Beh, non hai sentito dire questo da me, ma... forse se chiedi a Kronkrider là in alto sulla torre, lui te lo dirà..."
GS_Gossip[2775694711] = "Quello che vedete qui su questa costa non è il risultato del Flagello. In effetti, crediamo che anche il Flagello abbia paura del nebbioso - il che potrebbe spiegare il motivo per cui non vengono qui.NEW_LINENEW_LINEVedi, l'alone è vivo, amico. Dentro quelle sottili tentacoli si nasconde la morte...NEW_LINENEW_LINESe dovessi entrare nel suo dominio, scomparirai. La nebbia ti porterà via!NEW_LINENEW_LINENon abbiamo mai visto nessuno tornare indietro vivo dalla nebbia."
GS_Gossip[277671185] = "La creazione di gioielli e gemme è ciò per cui vivo. Posso condividere la mia passione con te?"
GS_Gossip[27782323] = "Il pozzone rosso sangue all'interno dell'occhio si agita, rivelando immagini di un esercito in massa del Flagello. L'occhio sembra tirare verso di te, cercando di entrare nella tua mente e spingendoti istintivamente a ritrarti. Ti senti molto a disagio in presenza di questo oggetto."
GS_Gossip[277902490] = "Dove si trova Wanikaya l'Anziano?"
GS_Gossip[2784310702] = "Sono un artigiano di qualche riconoscimento, YOUR_CLASS. Con i materiali giusti, sono in grado di creare un'armatura nota come Dreamwalker. I Druidi - e persino alcuni shaman - sono attratti da questa armatura a causa delle sue proprietà magiche. Sei interessato?"
GS_Gossip[2785099046] = "Laurna Morninglight offre guarigione a coloro che vivono intorno a Dolanaar. Forse lei sarebbe in grado di insegnarti nei modi di un sacerdote."
GS_Gossip[2785458541] = "Dimmi del tuo passato, Guardiano della Vista."
GS_Gossip[2787691991] = "Di che ti stai occupando?"
GS_Gossip[278784034] = "Non fu tanto tempo fa che dovevamo strappare il controllo del Forte dei Tuoni al vicino orco.NEW_LINENEW_LINESei qui per aiutarci a mantenere le nostre difese? So che Gor'drek sta cercando assistenza."
GS_Gossip[2791068928] = "Via da qui, YOUR_CLASS!NEW_LINENEW_LINESolo i campioni di Sepulcra possono acquistare ciò che ho da offrire."
GS_Gossip[2800899961] = "Con l'aiuto dell'ingegnere Lapforge da Gadgetzan ho costruito un potente trasportatore gnomico qui alla Stazione di Toshley! Sarei felice di aiutare ogni ingegnere gnomico abbastanza abile da costruire il proprio proprio segnale di trasporto personale."
GS_Gossip[2803577979] = "Mostrami cosa ho accesso, Lokhtos."
GS_Gossip[2803896011] = "Hemet Nesingwary, cosa stai facendo qui nell'Outland?"
GS_Gossip[2804770198] = "Cosa è un giovane YOUR_CLASS come se stessi visitando un vecchio contadino come me?"
GS_Gossip[2805797521] = "Grazie per aver scelto la Banca di Lunargenta. Cosa posso fare per te oggi?"
GS_Gossip[2806566776] = "Vi presento il Libro della Rumination."
GS_Gossip[2808379878] = "Fai di questa locanda la tua casa."
GS_Gossip[2810124997] = "Stai zitto su ciò che senti e vedi qui intorno, YOUR_RACE."
GS_Gossip[2810260022] = "Siamo venuti per competere per l'onore, il riconoscimento e il diritto di combattere il Flagello al fianco dei fratelli della Crociata d'Argento."
GS_Gossip[2810437480] = "Posso insegnarti l'erboristeria.  Interessato?"
GS_Gossip[2810763106] = "Benvenuto, YOUR_RACE. Sono qui come risorsa di consigli per l'Altissimo Esecutore, da utilizzare come ritiene opportuno. Sono convinto che insieme possiamo plasmare l'Orda in qualcosa che sarà ancora più forte del passato e sconfiggere una volta e per sempre la minaccia del Flagello!"
GS_Gossip[281279669] = "In che modo possiamo aiutarti?"
GS_Gossip[2816242863] = "Beh, ciao! Sei qui per imparare la tecnica corretta di un nuovo arma?"
GS_Gossip[281763318] = "I Kvaldir non hanno pietà, YOUR_NAME.  Ma non posso abbandonare sacro Kaskala.  Se non abbandoniamo gli spiriti, gli spiriti non ci abbandoneranno nemmeno."
GS_Gossip[2819913848] = "Ciao, YOUR_CLASS.  Sono ciò che viene definito uno dei Rottisi.  Come i Perduti, anche se non altrettanto gravemente, siamo stati colpiti dalle energie feliche che ci hanno trasformati dalle nostre forme originali di draenei."
GS_Gossip[2820203813] = "Sono lusingato, ma davvero non sono interessato... Che? Vuoi sapere dove imparare l'incantazione? Oh, quanto imbarazzante! Be', dovresti... Sono sicuro che potresti... andare a vedere, uh... Taladan! Sì, vai a vedere Taladan laggiù sulla Terrazza degli Artigiani!"
GS_Gossip[2820704590] = "Dobbiamo entrare in battaglia. Sei pronto?"
GS_Gossip[2821140596] = "Preparati a incontrare il tuo creatore."
GS_Gossip[2824458100] = "La Signora Mehley"
GS_Gossip[2826922690] = "Dovrei poter uscire da qui ora. Grazie!"
GS_Gossip[2828667992] = "Un alchimista?  Nessun problema YOUR_CLASS.  Ainethil, in tutto il suo lavoro e fatica, è diventata l'alchimista più brava della Terrazza degli Artigiani.  Andrei lì senza perdere tempo se fossi tu. Senza perdere tempo!  Ora via da qui!"
GS_Gossip[2828946020] = "Mi prenderò l'ultima risata... la vedranno! Oh, ciao YOUR_CLASS, non ti ho visto lì."
GS_Gossip[2833095467] = "Dhugru Gorelust si nasconde dietro i casermati del lato est del paese. Non permettere che io scopra che sei in alleanza con la Legione Infuocata!"
GS_Gossip[2834351284] = "La battaglia aerea infuriata è vicina, YOUR_NAME.  Entrambi noi e l'Orda mandiamo bombardieri nel Bombardamento e nella Valle della Speranza Perduta.  Vorrai entrare in battaglia?"
GS_Gossip[2836131369] = "Cerca Shandrina a Silverwind Refuge. Può venderti il \"Expert Cookbook\"."
GS_Gossip[2836819287] = "Premi il pulsante rosso contrassegnato 'E.C.A.C.'"
GS_Gossip[2842534664] = "I druidi stanno tenendo una grande celebrazione del Festival Lunare a Moonglade. Se è troppo lontano per camminare, stanno trasportando le persone dalle grandi città."
GS_Gossip[284382075] = "Questi nani sono gli stessi di oggi, sì? I nani mantengono altri legami con gli Earthen?"
GS_Gossip[2847315905] = "Saluti, amico."
GS_Gossip[2847442824] = "Come combattono i cavalieri della Crociata d'Argento?"
GS_Gossip[2852605448] = "Ehi, non puoi vedere che sto cercando di bere qui?"
GS_Gossip[285524890] = "La celebrazione del Festival Lunare è in pieno svolgimento a Moonglade. Puoi fare il viaggio in persona, oppure i druidi nell'Enclave Cenarion offrono il trasporto."
GS_Gossip[2857621199] = "Questo gruppo è inutile. Quei nobili sciocchi non vedranno mai Medivh. Non possono vedere questo? Dovrei essere rimasto a Darkshire con la mia famiglia invece di sprecare il mio tempo qui."
GS_Gossip[2858172845] = "Sebbene non ci sia un Istruttore di Ingegneria a Brill, ce n'è uno a Sepulcra. Per raggiungerlo, dirigiti nella parte posteriore delle Rovine di Lordaeron, a sud della città, e prendi l'ascensore. Una volta arrivato, chiedi a un Guardiano di Sepulcra indicazioni più precise."
GS_Gossip[286130691] = "Cucito"
GS_Gossip[2868584139] = "Allora è Bowen Brisboise che cerchi. Lo troverai all'interno della sua casa a sud-ovest di Brill, proprio dall'altra parte del ponte a Cold Hearth Manor."
GS_Gossip[2868865741] = "Desidero dimenticare la Maestria degli Elixir."
GS_Gossip[2874228066] = "Chi sei?NEW_LINENEW_LINEVattene... Sono esausto per via del duro lavoro sulla Strada del Porto. È ora di bere un po' di birra elvetica, piangere un bel po' e prendere un sonnellino."
GS_Gossip[2876827171] = "Spero che questi abitanti di Shattrath smettano presto di combattere. Stanno cominciando a darmi fastidio.NEW_LINENEW_LINECome posso aiutarti?"
GS_Gossip[2877038089] = "I cavalieri della Crociata d'Argento credono nel bilanciamento e nella precisione, mescolando abilmente attacco e difesa.NEW_LINENEW_LINETuttavia, spesso si espongono ai Colpi cercando di guadagnare distanza da te.NEW_LINENEW_LINEAvvicinati con una Carica prima che possano farlo loro, e poi rompi il loro Scudo mentre ti giri per altre Spinte."
GS_Gossip[2880731781] = "Sa'at, ho perso il cronobeacon e ne ho bisogno di un altro!"
GS_Gossip[2880795315] = "Cucciolo di tigre spettrale"
GS_Gossip[2881648946] = "Oh, ciao! Sono Hol'anyee, scienziato capo e biologo delle Esplorazioni del Generale. Io e mio fratello, insieme ai nostri compagni, viaggiamo per Azeroth esplorando la selvaggia e incontaminata magnificenza. È eccitante... ma, ehm... credo che stavolta ci siamo andati un po' troppo oltre!"
GS_Gossip[2881692328] = "Posseduto da cosa?"
GS_Gossip[2883995582] = "I simboli sulla tavola sono stati trascritti con cura..."
GS_Gossip[2885857763] = "Se non fosse per quella maledetta, fortuna gnomica, non vincerebbero mai una gara!"
GS_Gossip[2888271663] = "Il seme che hanno piantato ha dato un frutto. All'inizio sembrava funzionare. Ursoc è tornato e per un momento breve mi sono riempito di gioia.NEW_LINENEW_LINEMentre si riprendeva, era chiaro che non era più lo stesso. Nemmeno i furbolg lo erano.NEW_LINENEW_LINEQualsiasi male che ha causato agli antichi druidi di abbattere Vordrassil si è manifestato nell'albero nuovo e li ha trasformati tutti in mostri pieni di sete di sangue.NEW_LINENEW_LINELa cosa che ora cammina nei Colli Bradi non è mio padre e deve essere messa a riposo."
GS_Gossip[2889079806] = "Le maree della guerra sono tornate. Dal freddo nord, le necropoli del Re dei Lich hanno messo assedio alle nostre terre. Invia necropoli volanti per invadere in tutto il mondo."
GS_Gossip[2890001837] = "Sapevi che gli alchimisti possono trasformare certi gemme? Mar'nah e io abbiamo parlato di questo.NEW_LINENEW_LINESono convinto che, data la sua abilità, una volta che il suo laboratorio sarà completato, lei e io saremo in grado di creare gemme che si credeva fossero perse nel tempo."
GS_Gossip[2891288616] = "Cosa ti porta fin qui in alto, piccolo YOUR_RACE?"
GS_Gossip[2894945304] = "Dopo la caduta della setta della Lama Ardente, noi maestri della spada abbiamo giurato di liberare noi stessi e il nostro popolo dal controllo demoniaco.NEW_LINENEW_LINEQuesto può essere fatto, ma il mio onore rimane insoddisfatto.NEW_LINENEW_LINECombatterò per l'Orda - e addestrerò altri guerrieri a farlo - finché non morirò gloriosamente in battaglia. Questa è l'unica via che posso percorrere."
GS_Gossip[2896770996] = "Vuoi imparare la pelle, eh? Simon Tanner sarebbe in grado di insegnartelo. Puoi trovarlo in Old Town presso la Protective Hide."
GS_Gossip[2902800444] = "Il Circolo dell'Emeraldia si adopera per guarire la terra ferita di Felwood. Pur essendo il nome della terra legato proprio a ciò che l'ha corrotta, speriamo un giorno di poter eliminare la corruzione da questa terra."
GS_Gossip[2902808129] = "<Inizio spegnimento di emergenza.>"
GS_Gossip[2905391999] = "<Floon emette una serie di strani suoni di cliccamento e clacclac.>"
GS_Gossip[2906197036] = "Dimmi di te, Xarantaur. Perché ti chiamano il testimone?"
GS_Gossip[290738445] = "La grande tartaruga marina Walker of Waves viaggia da questo molo a Moa'ki Harbor nel Dragonblight."
GS_Gossip[290887882] = "Non conosco un esperto migliore di Buliwyf per quanto riguarda gli asce! Con una mano, con due mani... è un maestro in tutto questo!"
GS_Gossip[2910686649] = "YOUR_RACE! Sì, tu! Perché sprechi tempo a rimandare in questa città in rovina quando il tuo posto giusto è nel Bacino d'Arathi? La Lega di Arathor è implacabile nell'assalto; il tuo contributo è necessario, e sarai ricompensato!"
GS_Gossip[2911238262] = "Lanciato"
GS_Gossip[2913000947] = "L'Arsenal di Dalaran, situato nella parte sud-est, offre una vasta gamma di armi da mischia."
GS_Gossip[2916474603] = "Il maestro giocoliere draenei Hamanar può essere trovato tra il suo popolo sulla Collina degli Aldor."
GS_Gossip[2917318510] = "Ehi, amico.NEW_LINENEW_LINEHai voglia di stabilire i tuoi animali domestici, o stavi cercando un compagno perso?"
GS_Gossip[2917327919] = "Dio mio, per la barba di Muradin, YOUR_CLASS. Questa terra è ai margini dell'annientamento. Non riesco a immaginare che qualcuno abbia sopravvissuto qui da quando è finita la seconda guerra."
GS_Gossip[2917545814] = "Sei un $T civile : civile;?"
GS_Gossip[2917738821] = "L'ovest."
GS_Gossip[291907429] = "Le pianure selvagge di Nagrand offrono alcune delle migliori esperienze di caccia che abbia mai vissuto."
GS_Gossip[291919415] = "Mai lasciare casa senza un'ampia quantità di polvere luminosa, soprattutto quando si lavora con altri. Garantisco che ogni volta qualcuno si esaurirà.NEW_LINENEW_LINEQuando la scelta si riduce a distribuire materiali o lasciare che povero diavolo muoia, io aiuto... la maggior parte delle volte."
GS_Gossip[2920938367] = "Troverai Carolai Anise che cerca di far esplodere la sua casa all'estremità nord-occidentale del paese. Perché non vai a vedere se puoi aiutarla?"
GS_Gossip[2922343153] = "Congratulazioni, prego prendere il portale per Dalaran quando siete pronti!"
GS_Gossip[2922503165] = "C'è un'ottima pellegrina che vive nella casa vicino al Lago dei Cristalli. È sicuramente in grado di mostrarti come iniziare nell'arte della pellegrina."
GS_Gossip[292250407] = "L'Alto Bluewolf è intrappolato nella battaglia per Wintergrasp."
GS_Gossip[2926429358] = "I nostri amici nell'Alleanza si radunano per combattere al fianco dei Guardiani d'Argento nei Forra dei Cantaguerra. Viaggerai là per aiutarli?"
GS_Gossip[2927438229] = "La forma corporea di Ragnaros deve essere distrutta. Dalle sue ceneri emergerà la sua essenza. In questo stato indebolito, l'abbraccio di Ragnaros sulla prigione di Thunderaan si allenta. L'essenza stessa agisce come una chiave..."
GS_Gossip[2929265501] = "Ehi là!  Bene che tu sia qui - non ho molti visitatori e i tecnici non sono molto bravi a conversare.NEW_LINENEW_LINEScommetto che sei in procinto di recarti nell'Area 52. Hai ragione?"
GS_Gossip[2930487255] = "*GRRRR* *RUFF* *RUFF*"
GS_Gossip[2931374210] = "<L'Arcano Guardiano aspetta in silenzio che tu approfondisca ulteriormente.>"
GS_Gossip[2934973426] = "Il Quadrato dei Runeweaver è un parco al cuore stesso di Dalaran."
GS_Gossip[2937397839] = "Hai una storia per me?"
GS_Gossip[2937553693] = "Eroi della schiera? C'Thun deve essere espulso! Possiamo aiutarti, mortale!"
GS_Gossip[2939696531] = "No... non puoi sederti sulle mie gambe."
GS_Gossip[2940279270] = "L'inn dei Cartomanti si trova sopra la città di Shattrath, sul livello dei Cartomanti. La funivia per arrivarci si trova a sud-ovest del centro della città."
GS_Gossip[2942314381] = "Abbiamo le ceneri purificate del germoglio di Vordrassil. Se riusciamo a sottomettere Ursoc, potremmo essere in grado di guarire la sua anima."
GS_Gossip[2943400684] = "Se hai bisogno di ulteriore addestramento, sarò felice di dirti chi può aiutarti. Qual è l'arma che ti ha attirato?"
GS_Gossip[2943825690] = "Sono sempre pronto per un bello sconto a tre dita. Rubare è tutto nella mano... e quando quella fallisce, allora infili qualcosa di affilato tra le costole, e anche questo è tutto nella mano.NEW_LINENEW_LINELe mani esperte valgono più di un assegno fisso, l'hai sentito?"
GS_Gossip[2944345305] = "Se ti senti male, parla con Pestle. Potrebbe avere qualcosa per il mal di mare."
GS_Gossip[2945563424] = "Il villaggio di Astranaar in Ashenvale è la casa attuale di Elder Riversong."
GS_Gossip[2948467835] = "Magi? Sono nel Quartiere della Magia, nell'edificio centrale. Pensavo che fossi abbastanza sveglio da capirlo."
GS_Gossip[2951130718] = "A est."
GS_Gossip[2952834585] = "Se fossi tu, comprerei un buono per la razza goblin. Sostenere la squadra avversaria è un spreco di tempo."
GS_Gossip[2953623217] = "Finché rimani qui con noi, sei il re. Se te ne vai, un altro orco prenderà il tuo posto. Questo è il modo dei Gordok!"
GS_Gossip[2958384356] = "Chi è questo tipo di Budd?"
GS_Gossip[2958536566] = "Dove si trova Elder Graymane?"
GS_Gossip[2960902889] = "Dove potrebbe essere? Un po' di tempo fa ho mandato mia allieva, Shatharia, alle miniere di Underlight a ovest. Abbiamo bisogno di quegli campioni di minerale indietro, e presto, altrimenti il nostro esperimento fallirà!"
GS_Gossip[2961401818] = "Quali incantamenti ti interessano oggi, YOUR_CLASS?"
GS_Gossip[2964201399] = "<più>"
GS_Gossip[2964233482] = "Mostrami il mio banco"
GS_Gossip[2964582638] = "Questo pelle non è ancora pronta per essere lavorata. Spero che non ci volesse così tanto tempo per fare la pelle. Deve esserci un modo per ridurre tutta questa attesa. Non può essere buono per la mia salute, sai?"
GS_Gossip[2965508940] = "Vivo solo per servire il nostro Re."
GS_Gossip[2967478748] = "Non abbiamo alcun percorso facile davanti a noi. Se hai un braccio forte, rimani qui finché una delle mie squadre non è pronta ad ascendere a Ymirheim. Potranno usare tutto l'aiuto possibile."
GS_Gossip[2969008456] = "Tutta la vostra squadra di avventurieri è pronta a proseguire? Farò partire una scarica da questo cristallo di attivazione per coprire la ritirata dei miei guardiani."
GS_Gossip[2969712671] = "Sebbene i miei connazionali vorrebbero che tu assumessi un ruolo attivo in quanto sta accadendo a Zul'Drak, noi Zandalari siamo qui principalmente per assistere a quanto sta accadendo e per registrare la fine di un impero."
GS_Gossip[2971946303] = "Per quel rivelatore di fantasmi.  Per caso l'ho lasciato qui?  Sembrerebbe che non l'abbia più con me."
GS_Gossip[2972570081] = "Due volte al giorno, alle sei e quindici del mattino e alle sei e quindici della sera, High Tinker Mekkatorque in persona esce sui terreni della Festa delle Birre per la cerimonia dell'Apertura delle Botti. Non perdetela!"
GS_Gossip[2974246528] = "Se riesco a costruire una nuova macchina da guerra, so che posso guadagnare un bel po' di denaro al Wrath Gate.NEW_LINENEW_LINEAlcune delle nostre iterazioni precedenti non sono state del tutto... stabili, ma la mia macchina volante dovrebbe funzionare se riesco solo a sviluppare un sistema di bombe efficace per essa."
GS_Gossip[2974496050] = "Cosa è un \"Ologista?\" Una domanda migliore potrebbe essere cosa non è un \"Ologista.\" Significa che studio tutto! In effetti, sono così preparato su \"tutto\" che sono garantito per essere l'ethereale più intelligente che tu incontrerai - o ti restituiamo il denaro.NEW_LINENEW_LINEScusa. È il commerciante in me che parla..."
GS_Gossip[2975629387] = "Il zeppelino dovrebbe appena essere arrivato a Sepulcra."
GS_Gossip[2976935818] = "Non sono mai troppo occupato per parlare con uno sconosciuto! Quasi mai, comunque..."
GS_Gossip[2977876262] = "Cerco ulteriore addestramento nei modi sacerdotali."
GS_Gossip[2979240747] = "Cosa è allora? Non puoi vedere che sono un nano occupato?"
GS_Gossip[2979345893] = "In servizio. VIA. ANDATENE."
GS_Gossip[2979719957] = "<Warden Treelos ti guarda in modo strano e poi fa una pausa, chiaramente combattendo con se stesso.>NEW_LINENEW_LINEZangarmarsh... troppo vicino alla verità.NEW_LINENEW_LINE<Il suo volto va di nuovo fuori di testa.>NEW_LINENEW_LINESta ancora osservando!?"
GS_Gossip[2984826256] = "Telredor era un tempo un ritiro isolato per i sacerdoti e i pellegrini draenei. I sacerdoti residenti ricevevano raramente visitatori.NEW_LINENEW_LINEQuando gli orchi hanno iniziato ad attaccare le colonie draenei, i rifugiati hanno iniziato ad arrivare in numero sempre maggiore. L'anchorita Ahuurn e gli altri hanno trasformato Telredor da un santuario in un rifugio sicuro. Molti draenei, incluso me stesso, devono la propria sopravvivenza ai suoi sforzi."
GS_Gossip[2988864384] = "Dovresti provare gli antipasti di zampe di primavera, sono da morire per la fame!"
GS_Gossip[2988880216] = "Token & Souvenirs"
GS_Gossip[2988918653] = "<Lo sguardo di Thayreen è vuoto. La purificazione della corruzione di Vordrassil ha avuto un impatto sul druido.>"
GS_Gossip[2990048262] = "La mia fede guida le mie azioni, YOUR_RACE. So so that Ivus will come."
GS_Gossip[2992424128] = "Ho catturato tre polli per il pranzo. Scommetto che non ne potresti catturare nemmeno uno."
GS_Gossip[2995619728] = "Il tuo aiuto è stato inestimabile, amico mio.NEW_LINENEW_LINEPosso assicurarti che l'Esplorazione Cenarion farà di tutto per contrastare qualsiasi futuro cristallo contaminato che cadrà dal cielo per opera di Illidan."
GS_Gossip[2995952120] = "Le nostre unità sono state aggiornate a Esperte, ma non ho abbastanza forniture per aggiornarle a Veterane."
GS_Gossip[2999294496] = "Molti anni fa, io e i miei uomini seguimmo il mago Khadgar e il paladino Turalyon in questo mondo. Il nostro unico scopo era annientare gli orchi e i loro odiosi parenti. Tuttavia, qualcosa andò terribilmente storto nelle ultime ore della nostra guerra.NEW_LINENEW_LINEAlla fine, questo oscuro mondo fu strappato in due - e i miei cari amici furono persi nel vuoto."
GS_Gossip[3017482212] = "Sì? Maledizione, ora dovrò ricominciare da capo!"
GS_Gossip[3019043868] = "Benvenuto YOUR_CLASS, al mio umile ritiro. Trovo questo posto molto rilassante e ho sempre amato essere a casa a Dalaran. A volte però può essere un posto molto solitario... un posto così solitario."
GS_Gossip[3020541501] = "Cosa si può fare? Ho provato molte cose diverse. Ho fatto del mio meglio per aiutare la gente di Nagrand. Ogni volta che mi sono avvicinato a Garrosh, mi ha respinto."
GS_Gossip[3021615787] = "La natura fornisce tutto ciò di cui abbiamo bisogno. Parla con Komin Winterhoof a Holistic Herbalism sulla collina centrale."
GS_Gossip[3026129133] = "Il diario di Jandice Barov è pieno di rabbiose lamentazioni riguardo i morti viventi. Verso la fine del libro c'è ciò che sembra essere un modello per la creazione di una borsa in tessuto felico. Questa borsa è utilizzata dagli stregoni per conservare frammenti di anime. Desideri copiare il modello nel tuo diario?"
GS_Gossip[303138387] = "Posso percepire il tuo desiderio di potere, YOUR_CLASS."
GS_Gossip[3031403976] = "Sì, per favore richiamalo!"
GS_Gossip[3032846201] = "Un ritrovamento raro, davvero.NEW_LINENEW_LINE<Mathredis annuisce.>NEW_LINENEW_LINE Se desideri continuare, avrò bisogno degli componenti."
GS_Gossip[3034244877] = "Perché l'Outland non si chiama più Draenor?"
GS_Gossip[3034717923] = "Non sono in grado di elaborare il tuo riferimento cronologico rispetto all'archiviazione di questi dati, mi scuso.NEW_LINENEW_LINESebbene il nano mantenga la maggior parte dell'attunimento mentale degli Earthen alla composizione delle pietre di Azeroth, il ritorno alla biomassa vivente rappresenta la principale degradazione della matrice. I nani mangiano e si riproducono attraverso metodi tipici di altre biomasse standard.NEW_LINENEW_LINEI Creatori considerano il nano una variante accettabile, degna di origine in proprio diritto."
GS_Gossip[3035451598] = "YOUR_NAME, è bello vederti.  La nostra guerra con gli altri signori elementali continua, ma i tuoi sforzi aiutano a garantire la nostra vittoria."
GS_Gossip[3039569719] = "Per un periodo limitato, il rana croccante è disponibile esclusivamente qui alla Fiera di Lunacupa."
GS_Gossip[3042774778] = "Questo raggio lunare ti porterà a Orgrimmar. Usa l'invito quando vorrai andare."
GS_Gossip[3043893203] = "Saluti, YOUR_CLASS. Sono Leoren, maestro del maneggio di Cenarion Hold."
GS_Gossip[3044448094] = "<L'Arcano Guardiano fa un gesto verso la Tier, verso l'osteria e il maestro dell'attrezzeria fuori da essa.>"
GS_Gossip[3045045423] = "Hai il coraggio di affrontare i drakes d'élite di Malygos nel loro regno, YOUR_RACE?"
GS_Gossip[304672964] = "Scambio Biglietti"
GS_Gossip[3049267946] = "Qui per la canna? Oppure, forse stai semplicemente accumulando runici?NEW_LINENEW_LINEAspetta un momento! Stai cercando solo di scaricare un sacco di roba su di me?! Maledetto il mio incessante impulso di comprare, comprare, comprare!"
GS_Gossip[3050206552] = "Appena fuori dal principale ingresso della città c'è un cartello. Indicherà la strada per la torre zeppelin occidentale."
GS_Gossip[3052362377] = "La convocazione di demoni è una pratica pericolosa, ma il potere che ne può derivare può essere immenso. Il nostro esperto residente è Alamma, che supervisiona i maghi neri all'interno di Murder Row."
GS_Gossip[3052363047] = "Al momento ho le mani piene qui, YOUR_CLASS.NEW_LINENEW_LINECosa posso fare per te?"
GS_Gossip[3053024685] = "Benvenuto a Dalaran, YOUR_CLASS."
GS_Gossip[3054544727] = "Ascoltami, umano. Non mi importa nulla della tua sofferenza, ma hai qualcosa che mi serve. Dimmi dove trovare gli ingotti forgia-sangue."
GS_Gossip[305576018] = "Cosa sta succedendo?NEW_LINENEW_LINESei qui per mangiare, mon? Oppure forse per imparare a cucinare dal migliore, eh?"
GS_Gossip[3056213334] = "Grazie! La battaglia per Darrowshire mi ha condannato, ma tu mi hai liberato!"
GS_Gossip[3056432709] = "Conosci chi siamo, straniero? Siamo i Mag'har - orchi bruni, come ho sentito che la tua gente ci chiama. I Mag'har sono sopravvissuti: sopravvissuti a una dinastia caduta; sopravvissuti alla Peste Rossa; sopravvissuti a un mondo distrutto...NEW_LINENEW_LINESono Jorin, figlio di Kilrogg; l'ultimo della stirpe di Deadeye: Capo Guerriero della Tribù della Cavità Sanguinante."
GS_Gossip[3063207207] = "Ebbi il piacere di vedere Kyra Windblade in combattimento una volta. Considerando ciò che ho visto, sono convinto che ti addestrerà bene. Cerca la sua figura all'Albergo a Dolanaar."
GS_Gossip[3064295648] = "Dimmi di più sul Pilo cristallino occidentale."
GS_Gossip[3064762237] = "Finalmente abbiamo capito da dove provenivano gli strilli. Il Macellaio ci ha sottoposti a un dolore che non sapevamo esistesse. Ci ha usato in numerosi esperimenti, cercando di creare una peste.NEW_LINENEW_LINEI giorni si sono trasformati in settimane. Saremmo morti il primo giorno, se non fosse stato per quel crudele mostro che ci ha tenuti in vita attraverso mezzi magici."
GS_Gossip[3069636300] = "Ricevo rapporti sui tuoi exploit contro il Consiglio Abissale ogni volta, YOUR_NAME.  Stai facendo cose fantastiche là fuori!NEW_LINENEW_LINEContinua così, e ne farà valere la pena!"
GS_Gossip[3074961504] = "Ciao! Siamo bloccati da quei maledetti pirati là fuori in baia! Pensi che possa aiutarci lanciando un paio di bombe su di loro?!NEW_LINENEW_LINEIl nostro zeppelino rubato è meno di $3078w minuti di distanza. Assicurati di essere a bordo quando parte!"
GS_Gossip[3075547648] = "Mentre abbiamo molto da insegnare alle altre razze dell'Alleanza, abbiamo altrettanto da imparare da loro. Tieni gli occhi, le orecchie e la mente aperti, YOUR_CLASS."
GS_Gossip[3075833462] = "Dobbiamo scoprire cosa c'è dietro il mistero del gigantesco cristallo che è caduto dal cielo sulla cresta di Fallen Sky."
GS_Gossip[3078418201] = "La storia del tuo viaggio verrà raccontata per anni a venire!"
GS_Gossip[3079748340] = "Credo di aver notato una nuova consegna di posta non molto tempo fa. Troverai la casella postale appena fuori dalla Banca del Picco del Tuono, sulla collina bassa."
GS_Gossip[308206004] = "Con il benestare della Signora Sylvanas, i numeri dei Deathstalkers crescono. Più lame per colpire i nostri nemici quando meno se lo aspettano."
GS_Gossip[3082770147] = "L'occupazione del Pinnacolo dei Crociati è solo il primo passo in un lungo e pericoloso viaggio. C'è molto altro da fare prima che possiamo assediare la Rocca della Corona di Ghiaccio.NEW_LINENEW_LINEÈ possibile solo con il tuo aiuto e di persone come te, eroe."
GS_Gossip[3082785715] = "Di che tipo di armi si tratta?"
GS_Gossip[3087907658] = "Non del tutto capisco..."
GS_Gossip[3089989833] = "C'era un tempo in cui ti avrei strappato il cuore solo per vedere l'espressione sul tuo volto...."
GS_Gossip[3091030126] = "I Cavalieri del Sangue nel Quadrato dei Viandanti lontani permettono cortesemente spazio all'interno dei loro palazzi a Ileda, maestra d'arma di Lunargenta. Sebbene il suo addestramento non sia economico, apprezzerai la sua competenza."
GS_Gossip[3091768004] = "Ho bisogno di risposte, orco!"
GS_Gossip[3092699081] = "Elder Highpeak veglia sui Hinterlands da una collina vicino al suo centro."
GS_Gossip[3093836457] = "Perché... è molto carino da parte tua.  Immagino che tu stia volontariando del tempo per la Settimana dei Bambini, sì YOUR_CLASS?  Bene, va comunque riconosciuto.  È imperativo che ricordiamo coloro che sono meno fortunati - specialmente i bambini.NEW_LINENEW_LINESarei felice di firmare un'autografo. Ecco qui."
GS_Gossip[3094788044] = "Cosa devo fare?"
GS_Gossip[3095675492] = "Realizzato dai migliori artigiani di tutto Teldrassil, portato a mano da Kalimdor ad Azeroth come segno dell'Alleanza crescente tra il popolo dell'Albero Grande e gli umani di questa terra. Se c'è qualcosa di cui hai bisogno, non hai che da chiedere."
GS_Gossip[3096544183] = "È il consiglio di Gennia Runetotem che cerchi. La troverai nella grande tenda sul lato est del villaggio."
GS_Gossip[3096958025] = "Mi fa venire l'acquolina in bocca solo a pensarci. Pyall Silentstride è il miglior cuoco di Bloodhoof Village. Lo troverai nella grande tenda nell'angolo nord-occidentale del villaggio."
GS_Gossip[3097276086] = "Tutti i pellegrini e i conciatori possono essere trovati a Legendary Leathers nell'Exchange Commerciale del Magus, nordovest di Dalaran."
GS_Gossip[3102371563] = "Questo raggio di luce lunare conduce alla Sepulcra. Ritirati quando sei pronto."
GS_Gossip[3104948658] = "Non so cosa sta cercando di catturare là, ma Armand Cromwell è sul molo nel Quartiere della Magia."
GS_Gossip[3105371821] = "Sathein trova le pelli di lince a Eversong perfette per le sue creazioni. Dovresti parlare con lui - si trova accanto a Mathreyn proprio a sud-ovest della Porta del Magistero."
GS_Gossip[3107412630] = "Se solo i miei cari fratelli potessero essere qui con me in questo momento. Non crederebbero a quanto sarà importante questa scoperta!NEW_LINENEW_LINEIl Tribunale sono i bibliotecari dei dischi dei Titan, che sono conservati in questa stessa stanza.NEW_LINENEW_LINEGuarda! Puoi vedere i dischi sotto al pavimento! Dobbiamo sbrigarci, la più grande scoperta della razza degli Elfi Nani è proprio davanti a noi."
GS_Gossip[3110005831] = "Non ho tempo per pettegolezzi inutili, sono un professionista!"
GS_Gossip[3111003318] = "Non dimenticherò mai ciò che hai fatto per Thassarian. Sarò sempre debitore nei tuoi confronti."
GS_Gossip[3112007248] = "Sono estremamente occupato, YOUR_RACE.NEW_LINENEW_LINEAbbiamo un problema terribile tra le nostre mani che deve essere risolto immediatamente!"
GS_Gossip[3117745300] = "Sono interessato."
GS_Gossip[3117825833] = "Vieni qua, Budd. È tempo di giocare con gli troll ghiacciati!"
GS_Gossip[3118182930] = "Per coloro che preferiscono affidarsi a metodi ordinari per riparare la carne, Kanaria tiene una stazione ordinata all'interno dell'inn di Falconwing Square."
GS_Gossip[3119274455] = "Bah, i ladri non hanno fatto altro che rendere più difficile il nostro lavoro qui a Roccavento. Vorrei poter trascinare entrambi Osborne e Mathias fuori dal Vecchio Quartiere e direttamente in Carcere."
GS_Gossip[3121913210] = "Prova questi lanciatori di fuochi d'artificio. Sono un vero divertimento!"
GS_Gossip[3124944914] = "Crociati...NEW_LINENEW_LINE<Rivendare scuote la testa.>NEW_LINENEW_LINESono convinto che siano un lotto unico tra gli umani. La mia teoria è che manchino di funzioni cerebrali superiori, non essendo in grado di valutare logicamente una situazione e calcolare un esito. Basta solo menzionare la Luce per farli diventare furiosi e pronti alla battaglia - in quel momento si lanceranno senza esitazione in qualsiasi combattimento con totale disprezzo per la propria sicurezza."
GS_Gossip[3128815118] = "Questi scarti sono segnati da una terribile magia. Dobbiamo fare tutto il possibile per rimediare a questa grande ferita."
GS_Gossip[3129052827] = "Ehi! Manchi i Regni Orientali, eh? Beh, lo Squalo torna a Roccavento se sei veramente impaziente di tornare. So che mi piacerebbe molto il clima più caldo!"
GS_Gossip[3129180125] = "Questo è un portale per il campo di battaglia dell'occhio della tempesta."
GS_Gossip[3136084331] = "Riscatta i segni del campo di battaglia per onore."
GS_Gossip[3136985856] = "Sono certo che lo farai. Forse un giorno potresti consegnare un messaggio a un vecchio amico mio. Ho sentito che ancora gira per quei boschi.NEW_LINENEW_LINE<Eitrigg china la testa per un momento, come se in preghiera.>NEW_LINENEW_LINECosì Rend, sì... Rend e suo fratello Maim governavano la Torre, in costante conflitto con i nani Dark Iron. Riuscirono a spostare i nani dalla parte superiore della città, ma solo dopo che i draghi arrivarono e solo dopo la morte di Maim."
GS_Gossip[3137329770] = "Il Tavern The World's End non ha nulla da offrire a coloro del mio tipo. Tuttavia, ho notato che attira il tipo di clientela interessata a ciò che ho in vendita.NEW_LINENEW_LINEMi specializzo in prodotti ingegneristici esotici acquistati da ogni parte del mondo. Di tanto in tanto potrei anche avere un paio di cose rare in vendita.NEW_LINENEW_LINEDi cosa potrei interessarti?"
GS_Gossip[3142525994] = "I segreti nascosti all'interno dei Piloni del Cratere di Un'Goro sono ora tuoi. Visita i Piloni in qualsiasi momento per accedere al loro potere e ottenere risorse utili."
GS_Gossip[314540321] = "Ho sentito Regnus Thundergranite nel Salone delle Armi vantarsi di un nuovo trofeo per la sua tana l'altro giorno. Se stai cercando addestramento da un bravo cacciatore, Regnus è la persona giusta da cercare."
GS_Gossip[3146146336] = "Sacerdote"
GS_Gossip[3148220899] = "Resterò in silenzio riguardo all'uccisione e permetterò al cavaliere di rivendicare la ricompensa per aiutare la sua famiglia."
GS_Gossip[3150202773] = "La Mano Spezzata è riuscita a piazzare spie in tutto il castello superiore di Blackrock. Pur essendo stato lento il processo di raccolta delle informazioni, abbiamo fatto scoperte che non possono essere ignorate."
GS_Gossip[3150316970] = "Per favore, raccontami di più su Zaetar."
GS_Gossip[3153477883] = "Amico - Roccavento ha bisogno del tuo aiuto e della tua generosità!NEW_LINENEW_LINEIl nostro una volta ampio stock di tessuti è sceso criticamente basso. Roccavento è ora impegnata in un'effort multi-faceted per ricostruire quelle scorte per la produzione di tessuti e bende! La tua donazione di stoffa aiuterebbe Roccavento enormemente, nonché guadagnare il rispetto della popolazione!"
GS_Gossip[3153619241] = "Ho sempre saputo che saresti venuto a cercarmi, YOUR_NAME.NEW_LINENEW_LINEOgni essere senziente in questo mondo è mosso dalle scelte che fa. Le scelte generano altre scelte, e queste a loro volta definiscono chi si è. Questo è il punto da cui trai la tua fortuna - chi sei, e le scelte che fai.NEW_LINENEW_LINESei pronto a scoprire dove si trova la tua fortuna?"
GS_Gossip[315566326] = "I Scryer mi hanno mandato a contattarti? Non sembri affatto un Scryer."
GS_Gossip[3158187535] = "Questo è preoccupante. Per favore continua."
GS_Gossip[3158512550] = "Skwak!"
GS_Gossip[3158546867] = "<Il Maggiore annuisce brevemente.>"
GS_Gossip[3159328697] = "Dai, non perdi tempo a cercare un altro set di redini..."
GS_Gossip[3159528689] = "Ci siamo lasciati dopo, è successo così. Troppa cattiva volontà, suppongo... era accumulata da un po'. E la cosa con l'amuleto è stata l'ultima goccia che ha fatto traboccare il vaso.NEW_LINENEW_LINEDa allora i servitori di Valthalak ci hanno eliminato uno per volta. La maggior parte dei portatori dei frammenti dell'amuleto è morta, le loro anime corrotte dalla porzione dello spirito di Valthalak contenuta al loro interno.NEW_LINENEW_LINEPer questo sono contento che tu sia qui, YOUR_NAME. Con il tuo aiuto saremo in grado di ricombinare l'amuleto e restituirlo a Lord Valthalak!"
GS_Gossip[3166738227] = "Qualche posto dove volare? Per quello dovrai andare alla Sepulcra! Procedi a sud lungo la strada che esce dal paese, quindi a sud-ovest fino alle Ruine di Lordaeron. Puoi prendere l'ascensore giù fino alla Sepulcra dal retro delle ruine e una volta lì chiedi a un Guardiano della Sepulcra per ulteriori indicazioni più specifiche."
GS_Gossip[3167255116] = "Afferra l'occhio del Re dei Lich e concentra la tua volontà su di esso per indagare su informazioni importanti."
GS_Gossip[3171223766] = "Come si utilizza il cannone?"
GS_Gossip[317554415] = "Ehi, ti riconosco! Immagino che debba ringraziarti per il fatto che io sia qui. Quell'incidente con il teletrasporto è stato la cosa migliore che mi sia mai capitata.NEW_LINENEW_LINESe ti ritrovi di nuovo nella Tundra Boreale, fai sapere al mio doppio, quel nerd che non perde mai occasione per lamentarsi, che ho fatto parecchi progressi nel mondo!"
GS_Gossip[318145361] = "Sei pronto a fare qualunque cosa debba essere fatta per proteggere Lordaeron?"
GS_Gossip[3182773572] = "Non riusciremo mai a preparare queste navi in tempo. L'inverno arriva, e con esso la nostra condanna. Temo che il giovane principe abbia dannato tutti noi."
GS_Gossip[3182881789] = "Benvenuto in Forest Song, YOUR_CLASS. Se c'è qualcosa che posso fare per te, per favore dìmi."
GS_Gossip[3183681082] = "Krasus' Landing è nell'estremo oriente di Dalaran.NEW_LINENEW_LINEIl maestro del volo della città è presente, così come l'istruttore per il volo in condizioni di freddo."
GS_Gossip[3185205798] = "Il contenuto sulle pagine di questo tomo sembra essere in costante mutamento. Ti senti come se i tuoi pensieri venissero sottratti dalla tua mente e assorbiti dal libro."
GS_Gossip[3188081142] = "I reliqui sono davvero un grande mistero. Forse studiandoli regolarmente, guadagnerai una maggiore comprensione delle loro capacità."
GS_Gossip[3188811518] = "Bemarrin insegna l'arte del falegnameria nel Quadrato dei Viandanti Lontani. Sebbene un'occupazione... un po' sporca, immagino abbia i suoi vantaggi."
GS_Gossip[3190042691] = "Nessun insetto cresciuto troppo mi farà scappare via da Zangarmarsh! Mostrerò loro di cosa è fatta la Lega degli Esploratori..."
GS_Gossip[3193507234] = "Stiamo preparandoci per la guerra, YOUR_CLASS. Abbiamo preso tutto ciò che intendevamo prendere dai Silithid e dai loro padroni ad Ahn'Qiraj. Per prepararci, stiamo raccogliendo ogni sorta di materiale. Io mi occupo di raccogliere le Lacrime di Arthas. Non sono sicuro di cosa ne servirà, però. Se mi chiedi io non vorrei avere nulla a che fare con quel pazzo, anche se è solo un fiore che prende il suo nome.NEW_LINENEW_LINETuttavia, sono figlia del mio padre e una soldata, quindi faccio ciò che mi viene detto. Al momento abbiamo $2057w e devi raccogliere un totale complessivo di $2058w."
GS_Gossip[3196107033] = "I miei compagni e io ci chiamavamo i Figli di Lothar - in onore dell'uomo più grande e più altruista che mai avessimo conosciuto. Abbiamo dato tutto per sconfiggere Ner'zhul e porre fine alla sua follia.NEW_LINENEW_LINEMentre questo mondo condannato crollava intorno a noi, abbiamo distrutto il Portale Oscuro per prevenire ulteriori danni al nostro amato Azeroth."
GS_Gossip[3199207513] = "Come rappresentante della Città Bassa, sono qui per presentare la nostra richiesta che Auchindoun venga liberato dall'infestazione del Consiglio delle Ombre. Questo è, se vogliamo avere speranza per un futuro e scongiurare la possibilità di un cataclismo maggiore della creazione delle Lande di Ossa!NEW_LINENEW_LINETutti i nostri popoli hanno già sofferto troppo. Sono qui per assicurare che il dolore si fermi!"
GS_Gossip[3200064945] = "I eroi della stirpe di Trollbane sono leggendari. Idolatro quell'uomo.NEW_LINENEW_LINEE trovare lui, vivo, nell'Outland...NEW_LINENEW_LINE<Romus ti guarda oltre.>NEW_LINENEW_LINEQuando l'ho visto per la prima volta, quasi mi sono svenata. Lo choc era insopportabile. Mentre mi inginocchiavo davanti a lui, ho dovuto lottare per non piangere.NEW_LINENEW_LINEPuoi scommettere il tuo posteriore dolce che farò di tutto per assicurare che i Figli di Lothar rimangano al sicuro."
GS_Gossip[3204226344] = "Mantieni il tuo tono basso, straniero. Non vuoi disturbare le meditazioni del Maestro."
GS_Gossip[3205576412] = "Infatti. La madre della schiera dei draghi neri aveva usato illusioni e trucchi per travestirsi da membro della corte reale. Peggio ancora, aveva preso il controllo dell'attuale Alto Signore di Roccavento, Bolvar Fordragon.NEW_LINENEW_LINENon c'è da stupirsi che decisioni militari così sciocche siano state prese. Il movimento delle forze dell'Alleanza negli ultimi tempi ci aveva lasciati perplessi. Ora comprendiamo che la Black Flight stava cercando di dividere l'impero - distruggerlo da dentro."
GS_Gossip[3207436985] = "Non portarlo più vicino, mortale. Posso percepire il male che scorre attraverso il sigillo da dove sto.NEW_LINENEW_LINEDammi un momento per ispezionare l'oggetto - tienilo saldamente."
GS_Gossip[3208410751] = "Ti serve un po' di addestramento? Beh, Azar Stronghammer è sempre disponibile per insegnare un paio di cose ai paladini più giovani. Perché non vai a trovarlo alla Distilleria del Tuono?"
GS_Gossip[3209528559] = "Chiamami \"Boss\". Cosa hai per me!"
GS_Gossip[3211059600] = "Ciao, YOUR_RACE.  Benvenuti a condividere questa gola con noi come rifugio dai draghi.  Fate attenzione al goblin nano... il suo popolo non può essere fidato."
GS_Gossip[3212949181] = "Ho bisogno di un cronobeacon, Sa'at."
GS_Gossip[3213537165] = "Ora, se fossi l'oste Renee dove potrei essere? Hmmm? Oh, forse all'interno del Taverna Gallows' End. Sì, è così, ne sono sicura. Prova l'estremo sud-est di Brill... pensi di riuscire a trovarla?"
GS_Gossip[3213625195] = "Questo orso percorre un sentiero vicino a dove si trova la Talondeep Path, a ovest di Mystral Lake e dell'outpost dell'Alleanza Silverwind Refuge.  Sebbene sia il più facile dei tre creature che incontrerai durante la caccia di Ashenvale, non deve essere sottovalutato.  La sua presenza rappresenta una costante minaccia per i viaggiatori che si recano tra Ashenvale e le Montagne di Stonetalon."
GS_Gossip[3214469247] = "Se non sapessi meglio, penserei che ti stessi prendendo in giro, mortale; ma sì, è per lo più corretto. Puoi rimanere completamente vestito."
GS_Gossip[3216059951] = "Steward, per favore permettetemi di montare uno dei drachi per raggiungere la stanza della regina in cima al tempio."
GS_Gossip[3216545108] = "Cosa sono gli Ethereum?"
GS_Gossip[3220033363] = "Vorrei costruire un'ingegneria da assedio."
GS_Gossip[3222332793] = "I Vrykuls sono più grandi e forti di noi.  Ma noi siamo più belli!"
GS_Gossip[32244659] = "Dimmi di più sulla creazione di armature."
GS_Gossip[3226667198] = "Orda Inn"
GS_Gossip[3227343552] = "Siamo pronti ad aiutare!"
GS_Gossip[3229351039] = "Ho mandato la Ranger Salissa a sud verso l'enclave e la Ranger Lethvalin a ovest verso Tranquillien più di un giorno fa! Li hai visti? Sei l'aiuto che è stato mandato indietro?"
GS_Gossip[3235585888] = "Giganti fungini sporchi! Cosa abbiamo mai fatto loro?"
GS_Gossip[3237274631] = "Veleno... i miei interni stanno sobbollendo..."
GS_Gossip[3239728321] = "Tutta questa attrezzatura solo per esaminare il ghiaccio?"
GS_Gossip[3240828819] = "Ho perso il mio Tabard dell'Accomplimento."
GS_Gossip[3245173327] = "Gri'lek, dell'Acciaio SanguinarioNEW_LINENEW_LINEL'errante.  Che la sua forza e la sua sete di battaglia trapassino gli anni.  NEW_LINENEW_LINEGri'lek ora abita lontano da qui. Un giorno, potrebbe tornare..."
GS_Gossip[3247604514] = "Io, come mio fratello, onoro coloro che onorano i loro antenati. Mi riempie di grande gioia condividere i miei segreti artigianali con i discepoli della Festa Lunare!"
GS_Gossip[3248522189] = "YOUR_NAME, come posso ulteriormente migliorare il tuo addestramento agli occhi della Madre Terra?"
GS_Gossip[3252408664] = "Vuoi imparare l'antica arte? Vuoi fondere il ferro oscuro?NEW_LINENEW_LINEAccontentami, YOUR_RACE.  Mostrami un sacrificio e lo considererò!"
GS_Gossip[325292077] = "La forza del cuore è ciò che ti dà la determinazione per agire... azioni radicate in intenzioni pure e sincere. Mantenere l'equilibrio non significa essere indifferenti o banali.NEW_LINENEW_LINEDevi dimostrare risolutezza per ciò in cui credi, e devi essere disposto a lottare per esso. La madre orsa mostra convinzione infinita nel proteggere i propri cuccioli, così come un orso anziano protegge la sua tana. È questa risolutezza, questa forza d'animo, che devi imparare a conoscere se intendi padroneggiare la via della Clava."
GS_Gossip[3255856311] = "Sono qui per il training culinario."
GS_Gossip[325845816] = "Skaldrenox!  Ho il tuo bastone e ti incarico di entrare in questo mondo!"
GS_Gossip[3262071799] = "La Luce sia con te, YOUR_CLASS. Come posso aiutarti?"
GS_Gossip[3262452187] = "Ho fatto tutto ciò che potevo, Grande Nonna. Ti ringrazio per le tue gentili parole."
GS_Gossip[3263245867] = "Potente uno! Come possiamo servirti?"
GS_Gossip[3267070027] = "Sì, sono rimasto qui da tanto tempo quanto riesco a ricordare.NEW_LINENEW_LINENella mia vita precedente, ero un armatore. Forse posso ripararti qualcosa?"
GS_Gossip[3268834902] = "Perché soffri?"
GS_Gossip[3272257745] = "Ti sfido, paladino della morte!"
GS_Gossip[3277586876] = "Sono al 100% sicuro che desidero imparare nei modi dell'ingegneria goblin."
GS_Gossip[3284605197] = "Solo un idiota oserebbe disturbarmi nel mio nascondiglio."
GS_Gossip[3285545163] = "Zorus, ho bisogno di una nuova coppia di occhiali."
GS_Gossip[3292090339] = "Oh, nonna, che fantastici oggetti hai."
GS_Gossip[3294408257] = "Sembra che tu abbia già trovato l'amore. Puoi darmi un token d'amore, ma non ti sto dando niente di bello. Sto aspettando qualcuno speciale."
GS_Gossip[3296768083] = "Brusco. Il Maestro Ravenholdt non apprezza il brusco."
GS_Gossip[3299890945] = "La banca di Picco del Tuono può essere trovata nella parte inferiore della collina."
GS_Gossip[3304318485] = "Mi dispiace, amico. Purtroppo abbiamo utilizzato tutte le parti che potevamo spareggiare in questo momento."
GS_Gossip[3304607264] = "Vai nel anello centrale; troverai gli auctioneer lì."
GS_Gossip[3306687255] = "L'ultima volta che ho sentito Hauthaa, ha indicato che siamo $3228w percento del tragitto completato.NEW_LINENEW_LINENon posso esprimere quanto sia vitale per i nostri sforzi ottenere che vengano creati. Uomini e donne avranno bisogno di armature e armi migliori, e l'incudine e la forgia sono la chiave per questo.NEW_LINENEW_LINETroverai l'armaiolo dietro l'Armatura di Sun's Reach, YOUR_NAME."
GS_Gossip[3306760216] = "Il Re dei Lich ha inviato solo piccole forze contro ciascuna delle capitali di Azeroth, mentre le loro forze principali attaccano periodicamente le seguenti terre:NEW_LINENEW_LINEAzshara, le Terre Flagellate, le Steppe Bruciate, il Deserto di Tanaris, le Plagued Lands Orientali e Winterspring."
GS_Gossip[330773686] = "La Regina Alexstrasza mi ha posto a capo della difesa del Tempio della Lega dei Draghi.NEW_LINENEW_LINECome sai, Malygos aveva ordinato alle sue forze di distruggere un ancoraggio vicino alla linea di potere. Le forze della dragonflight hanno poi deviato quel potere verso il Santuario del Drago Azzurro.NEW_LINENEW_LINEI draghi blu stanno utilizzando quel potere per rafforzarsi; tanto da osare attaccare il tempio stesso! Stanno iniziando a vincere.NEW_LINENEW_LINESei qui per aiutarci, YOUR_RACE?"
GS_Gossip[3308433167] = "Il cristalliforgiato dei Bash'ir può essere utilizzato per trasformare i tuoi frammenti di apexis in flaconi instabili del mago. Questi flaconi rendono l'assumente più intelligente, più robusto e aumentano l'efficacia delle loro magie danneggianti e curative.NEW_LINENEW_LINESembra tuttavia che non disponga del numero necessario di dieci frammenti per acquistare anche una singola fiala."
GS_Gossip[3308503187] = "Uh, hai ucciso il re, eh? Questo significa che prendi il suo posto. Questo ti rende il nuovo capo! Salve al re!"
GS_Gossip[3315062369] = "Elder Dawnstrider può essere trovato a Flame Crest sulle Burning Steppes."
GS_Gossip[3315321349] = "Non dovrebbe finire così."
GS_Gossip[3317073574] = "Alcuni sono stati risparmiati dall'angoscia che le memorie portano."
GS_Gossip[3317175784] = "L'abilità con cui Telonis forgia l'armatura è ineguagliabile. Dovresti essere grato che non chieda di più per la conoscenza che trasmette ad altri. Vai ora e cerca lui nella Terrazza degli Artigiani, nella sezione nord-est di Darnassus."
GS_Gossip[3319304829] = "Saluti, YOUR_CLASS.  Cosa può fare per voi oggi questo umile servitore del Forte della Luna Piumata?"
GS_Gossip[3321280992] = "Mi puoi indicare la strada?"
GS_Gossip[3321614702] = "La Madre della Terra chiama e tu rispondi. Troverai il Salone degli Spiriti sul Sentiero degli Spiriti."
GS_Gossip[3323138355] = "La vendetta sarà mia."
GS_Gossip[3323496559] = "YOUR_NAME, i Figli di Lothar hanno combattuto qui, sulla Penisola del Fuoco Infernale, per due decadi. Siamo circondati da orchi indigeni e demoni infernali della Crociata Bruciante, e sebbene i nostri cuori battano ancora con forza, gli anni di guerra hanno ridotto i nostri numeri.NEW_LINENEW_LINETu, e l'arrivo della nuova generazione di eroi di Azeroth, è un benvenuto davvero gradito!"
GS_Gossip[332380506] = "Nuovo quest'anno: il PX-238 Winter Wondervolt. Vieni a vedere e non essere timido!NEW_LINENEW_LINEE firma questi moduli prima di provarlo, stiamo ancora risolvendo alcuni bug in questa cosa..."
GS_Gossip[3326162927] = "Nella città ci sono due banche: La Contabilità di Roccavento nel Distretto Commerciale, e la Banca Reale di Roccavento nel Distretto Elvico."
GS_Gossip[3327561724] = "Percorso di Illidan"
GS_Gossip[3328390852] = "Dove posso trovare il Ripristino Cristallino?"
GS_Gossip[3330616137] = "Tutto questo caramello gratuito è solo una brutta strategia commerciale, ti dico. Oppure... forse è solo un prodotto di lancio... ti fanno entrare nell'osteria, e poi ti fanno pagare caro la carne. È brillante!"
GS_Gossip[3331636517] = "<Utilizzare il dispositivo di trascrizione per raccogliere un frammento.>"
GS_Gossip[3332472834] = "Qualunque cosa tu stia per chiedere, fallo velocemente."
GS_Gossip[333464710] = "Viviamo e moriamo, e la terra rimane, eterna, immutata dal nostro passaggio. Così, la terra non può appartenere a noi, YOUR_NAME. Invece, ci appartieniamo ad essa. Pertanto proteggiamo la terra, poiché senza di essa non possiamo sperare di sopravvivere."
GS_Gossip[3334812747] = "Sei l'aspetto che mi fa pensare di dover stare attento al mio portamonete. C'è qualcosa in cui posso aiutarti?"
GS_Gossip[3335057116] = "Ogni due anni gli Spiriti della Competizione diventano particolarmente ferventi... e adesso è il momento! Indossiamo questo tabard nei Campi di Battaglia per onorarli, cercando di sconfiggere i nostri nemici e guadagnarci il loro favore."
GS_Gossip[333703373] = "Sono Al'tabim, l'Onnividente - un inviato del Re Rastakhan.NEW_LINENEW_LINEI miei affari sono con i sacerdoti, gli stregoni e i maghi."
GS_Gossip[3337471609] = "YOUR_NAME, è bello rivederti.NEW_LINENEW_LINERicorda di rimanere concentrato sul tuo apprendimento. Rappresenti il nostro futuro, e se dovessi vacillare, il nostro futuro sarà davvero oscuro."
GS_Gossip[3341023432] = "Gri'lek, dell'Acciaio SanguinarioNEW_LINENEW_LINEL'errante. Possa la sua forza e la sua sete di battaglia trapassare gli anni.NEW_LINENEW_LINEGri'lek ora si aggira vicino all'orlo della follia..."
GS_Gossip[3341038833] = "Posso aiutarti a gustarlo?"
GS_Gossip[3347472522] = "Spero che tu sappia, cara. Non ascolterà te, né ascolterà me. In verità, è per questo che sono ancora qui. È per questo che non sono andata via con la madre Kashur. Deve trovare il suo cuore. Il nostro popolo non sopravviverà all'inverno senza leadership."
GS_Gossip[334833049] = "Il Anello delle Prove un tempo era un luogo di grande gloria e onore. Ma poi, il Cartello del Vapore arrivò, con i loro carri d'oro e penne da scrivere più affilate di qualsiasi ascia ork..."
GS_Gossip[3349385076] = "Hai bisogno di alcuni materiali per l'alchimia, eh? Oppure hai altre faccende da sbrigare con me?"
GS_Gossip[3351771963] = "Elder Igasho è stato visto l'ultima volta mentre esplorava all'interno di The Nexus."
GS_Gossip[3352171967] = "Con la maggior parte delle forze della Sepulcra schierata a Vengeance Landing in Northrend, il Warchief ci ha mandati per rinforzare le difese della città."
GS_Gossip[335573583] = "<Lo spettro arakkoa si protende verso di te come se volesse identificarti. Hai l'impressione che non ti veda chiaramente.>NEW_LINENEW_LINERokkaram, sei tu?"
GS_Gossip[3356856450] = "Conosci qualcuno... o forse qualcosa, con il nome di Eranikus?"
GS_Gossip[3357224099] = "Ora che i capi sono stati eliminati, siamo pronti a iniziare il nostro assalto! Presto, YOUR_NAME...."
GS_Gossip[3361418248] = "Salve, Loramus. Porto notizie dalle Terre Maledette."
GS_Gossip[3362432570] = "Pensi di avere ciò che serve?"
GS_Gossip[3364297487] = "Dammi un rapporto sulla situazione, capitano."
GS_Gossip[336469953] = "Consegno l'uomo al mio signore per la punizione, poiché ha violato la legge del paese e è il mio dovere giurato di farvi rispettare."
GS_Gossip[3365665472] = "Un mago... cerchi di imparare la magia dei portali, sì?"
GS_Gossip[3365740060] = "Dove si trova Elder Dawnstrider?"
GS_Gossip[3370478749] = "Perché vorrei cavalcare un shredder?"
GS_Gossip[3370919593] = "Bevici qualcosa, YOUR_CLASS.  Potrebbe essere l'ultima!"
GS_Gossip[3373467437] = "Di cosa stai nascondendo sotto quella piega di carne?"
GS_Gossip[3377081968] = "Ascolta, YOUR_RACE. Ascolta bene...NEW_LINENEW_LINEI cavalieri dei draghi sono arrivati di notte, montati sui draghi neri. Hanno attaccato velocemente e con precisione letale, prendendo i piccoli draghetti - come me - e fuggendo sotto il velo dell'oscurità.NEW_LINENEW_LINELi ho visti con orrore mentre usavano miei fratelli e sorelle nei loro esperimenti. Dalla nostra essenza sarebbe stato creato il volo cromatico."
GS_Gossip[3382727279] = "Non so molto sulla magia, ma c'è un mago di nome Zaldimar che sta alzando al Lion's Pride Inn e potrebbe probabilmente aiutarti."
GS_Gossip[3384270811] = "Solo i cacciatori più esperti dei seguaci di Illidan possono accedere ai miei beni.NEW_LINENEW_LINESarai considerato degno quando lo status con i Sha'tar, l'Esplorazione Cenarion e gli Aldor sarà esaltato."
GS_Gossip[3387746107] = "La Luce ti protegge, YOUR_CLASS."
GS_Gossip[3389536054] = "La moda della Vergine"
GS_Gossip[3390522373] = "Ho una bella idea di cosa farà il vecchio Babbo Natale quando finirà questo turno. Ho una bottiglia di festa del Velo d'Inverno proprio qui nella mia borsa, e intendo scoprire fino in fondo."
GS_Gossip[339078978] = "Se hai una destinazione, posso portarti lì."
GS_Gossip[3391547526] = "I Guardia Stormpike devono essere distrutti!  Pronto per la Valle d'Alterac YOUR_CLASS?"
GS_Gossip[3393643786] = "La levatrice Neela saluta tutti i suoi futuri clienti mentre entrano al Gallows' End Tavern nell'estremo sud-est del paese."
GS_Gossip[3394350579] = "Per favore, siediti e fatti comodo."
GS_Gossip[3398113693] = "Godendo del Festival del Fuoco?"
GS_Gossip[3398357665] = "Mercante di Gemme"
GS_Gossip[3404410843] = "Poi incontrami all'ingresso dell'abbazia. Arriverò presto."
GS_Gossip[3404533966] = "<Eitrigg ride.>NEW_LINENEW_LINEGiovane, il mondo non è sempre stato in tale disordine. Fu un tempo prima che il Flagello avesse saccheggiato la terra. Prima che quelle parti di Lordaeron fossero note come le Terre della Peste.NEW_LINENEW_LINEEra là che Thrall mi ha salvato dalla morte e fu allora che ho aderito alla nuova Orda... ma mi sto allontanando. Questa è una storia per un altro momento. Sì, un altro momento... Forse..."
GS_Gossip[3404604259] = "Hai nuovi tesori che vorresti tenere al sicuro? Dovrai conservarli al Tesoro con i Stonemantles. Troverai il Tesoro a pochi colpi di martello a nord-est dall'ingresso di Forgiardente."
GS_Gossip[3405962675] = "Che? Non puoi vedere che sono occupato qui?NEW_LINENEW_LINEPensi che questo trasmatore si riparerà da solo?!"
GS_Gossip[3406160616] = "Punti di interesse"
GS_Gossip[3410057091] = "Noi di Darnassus ci aspettiamo di partecipare al torneo."
GS_Gossip[341545201] = "Ci sono due mercanti di gemme in residenza: uno lavora in stretta collaborazione con gli Scryers, e l'altro è fedele agli Aldor. Chi cerchi?"
GS_Gossip[3415878177] = "Gordo come raccogliere fiori. Raccogliere fiori un po' come uccidere."
GS_Gossip[3417718978] = "Intendi l'iceberg?"
GS_Gossip[3418463934] = "Uccido l'uomo sul momento come il mio signore si aspetterebbe che faccia, poiché non è altro che un ladro e un bugiardo."
GS_Gossip[3420618553] = "Armare le guardie presso il santuario ci aiuterà a occuparlo più velocemente. Non vogliamo che nessun Wretched si metta di traverso quando scateniamo un attacco su larga scala contro la Legione e Kael.NEW_LINENEW_LINESiamo $3244w percento completato del nostro obiettivo."
GS_Gossip[3428921815] = "Ho un'altra domanda da farti."
GS_Gossip[3430668492] = "Hai bisogno di qualcosa, YOUR_CLASS?  Forse posso aiutarti."
GS_Gossip[3434251401] = "Benvenuto! Hai già onorato questa terra con il suo fuoco?"
GS_Gossip[3437854957] = "Certo, YOUR_NAME. Ti sembri una persona su cui si può contare... Onesto! Lo si nota da un miglio...NEW_LINENEW_LINEComunque, torniamo a ciò di cui stavo parlando. Ci vuole una pianta di Evoroot per preparare l'Elixir di Videre. Il resto degli ingredienti è veramente banale, ma l'Evoroot, beh, può essere un po' difficile da ottenere."
GS_Gossip[3438008801] = "Dicono che questi fuochi d'artificio utilizzino il potere della luna!"
GS_Gossip[3438528618] = "Dove è l'assistente di Tirth?"
GS_Gossip[3439872763] = "Quali ambienti ad alta tensione causerebbero la destabilizzazione degli Earthen?"
GS_Gossip[3441861145] = "Salva te stesso, YOUR_RACE. Fuggi da questo posto! Il Sigillo Rosso ti eseguirà appena ti scoprirà."
GS_Gossip[3441917924] = "Mi scuso, YOUR_CLASS. Mi ero sbagliato, pensavo fossi una persona con un po' di coraggio. Vattene; i nostri segreti non sono per orecchie inesperte."
GS_Gossip[3444356464] = "Vai a trovare Margaux Parchley. Lei è una bella signora nell'Alambicco."
GS_Gossip[3445015802] = "Troverai i maestri di battaglia all'interno del Salone dei Valorosi nella Valle dell'Onore."
GS_Gossip[3445542793] = "Dai a un toro un pesce e lo nutrirai per un giorno. Insegna a un toro a pescare e lo nutrirai per tutta la vita. Uthan Stillwater può insegnarti a pescare. Cercane la saggezza a ovest del villaggio di Bloodhoof lungo le rive del lago Stonebull."
GS_Gossip[3462245557] = "Raccoglierò gli altri schiavi e li preparerò per combattere. Ci raggiungeremo prima che tu entri in battaglia con Tyrannus del Flagello."
GS_Gossip[3463758601] = "Fammi vedere quali uccellini hai in vendita."
GS_Gossip[3464963865] = "Il Santuario di Remulos è un luogo sacro per noi nel Circolo Cenariano qui in Moonglade... quindi per favore comportatevi in modo degno di un visitatore.NEW_LINENEW_LINEUn visitatore che non vuole la mia scimitarra piantata in lui, cioè."
GS_Gossip[3466471725] = "Cosa hai fatto poi?"
GS_Gossip[3469120948] = "Ho visto un troll chiamato Lau'Tiki pescare a sud, sulla spiaggia Darkspear. È proprio ai margini del villaggio Sen'jin."
GS_Gossip[3474510681] = "Questo piano di teletrasporto etereo è coperto di pulsanti e interruttori colorati, ma sembra essersi rivelato inutilizzabile."
GS_Gossip[3475592482] = "Ecco dove ci troviamo adesso, YOUR_NAME.NEW_LINENEW_LINENon possiamo certo occuparci di tutto questo da soli, e onestamente, mi sento un po' fuori dalla mia profondità. Jinky sa cosa deve essere fatto. Dovresti andare da lei adesso.NEW_LINENEW_LINESpero solo che tu sarai in grado di portarci fuori da questo pasticcio con i nostri corpi intatti."
GS_Gossip[3475636554] = "La mia dolce fanciulla Kali ti ha mandato giù da me? Lei è la mia pupilla."
GS_Gossip[347601818] = "Non fare lo schivo, compra una birra per tutti!"
GS_Gossip[3476403648] = "Arthur Moore nel quartiere dei Ladri, anello interno, è uno di quelli che insegnano la concia delle pelli."
GS_Gossip[3480408332] = "Quel pigro Leland... tutto ciò che fa è sedersi fuori dal molo vicino al Distretto del commercio e pescare tutto il giorno. Spero davvero che sia bravo in quel lavoro per tutto il tempo che passa a pescare. Se vuoi imparare, perché non vai a parlare con lui?"
GS_Gossip[3482513403] = "Posiziona 35 frammenti Apexis vicino all'uovo del drago per aprirlo."
GS_Gossip[3483920871] = "Come stai, amico!"
GS_Gossip[3484400833] = "Devo scusarmi per non essere stato del tutto onesto con te riguardo alla mia identità. Dovevo essere certo che potessi essere fidato - pochi persone avrebbero prestato volontariamente aiuto a un vecchio e dimenticato eremita.NEW_LINENEW_LINEHai dimostrato di essere una di quelle persone: Una persona di integrità e onore."
GS_Gossip[3487124477] = "È arrivato il momento del Noblegarden! È tempo di ringraziare la Luce per la rinascita del mondo."
GS_Gossip[3487648578] = "Ho bisogno di addestramento da guerriero."
GS_Gossip[3487885015] = "Ne sai qualcosa riguardo all'occhio viola? Forse avrò tempo per te più tardi.NEW_LINENEW_LINEDevo tornare al mio lavoro."
GS_Gossip[349024390] = "Sii grato che io sia rinchiuso dentro questa gabbia, YOUR_RACE."
GS_Gossip[3492259761] = "Cosa c'è che non va con te, amico? Non hai mai visto un troll prima d'ora?"
GS_Gossip[3494473122] = "Di che tipo di addestratore stavi cercando di trovare?"
GS_Gossip[3496446286] = "Pubblicazioni ufficiali dei cittadini e degli ufficiali di Wintergarde."
GS_Gossip[3496586168] = "Attenzione, mortale, oltre questa sala si nascondono pericoli mai sentiti nel tuo mondo. Cammina con cautela..."
GS_Gossip[3500736070] = "Sono un cacciatore in cerca di addestramento, Acteon."
GS_Gossip[3501145178] = "Questo piccolo cagnolino verde non era di alcuna utilità nelle miniere. Non importa, farà comunque da buon riscaldamento per la battaglia."
GS_Gossip[3506039211] = "Vuoi che partecipi all'Hyldsmeet per porre fine alla guerra?"
GS_Gossip[3515658087] = "Dobbiamo recuperare quei contenitori di approvvigionamento!"
GS_Gossip[3515807353] = "Il nostro modesto albergo si trova a nord di Azure Watch; Chellan si prenderà cura di te."
GS_Gossip[351778442] = "Mentre cerchiamo di ottenere l'aiuto dei popoli di questo mondo contro la Legione Infuocata, dobbiamo imparare anche a vivere in pace tra di loro.NEW_LINENEW_LINETieni presente questo mentre il tuo viaggio ti porterà per tutta Azeroth. Che la Luce ti guidi."
GS_Gossip[3518985579] = "<Prendi il controllo di un Lithe Stalker attraverso l'occhio.>"
GS_Gossip[3521107460] = "La Magistrix Carinda mi ha mandato a chiederti del segreto di Arelion. Con chi aveva rapporti?"
GS_Gossip[3522853570] = "Sono pronto, Brann. Andiamo a creare la pietra focaiola."
GS_Gossip[3524292670] = "Questo è ciò che mi piace sentire."
GS_Gossip[352676709] = "Intrappolati in questo deserto distrutto, abbiamo fatto del nostro meglio per sopravvivere. Con il passare del tempo, abbiamo percepito che una nuova malvagità si stava avvicinando a noi dal Twisting Nether. Peggio ancora degli orchi oscuri - era la Legione Infuocata stessa che cercava di prendere il controllo di questo... Outland."
GS_Gossip[3528522968] = "Tratta il cavaliere del vento con gentilezza, poiché ti porterà alla tua destinazione. Che i tuoi antenati vegliino su di teYOUR_NAME."
GS_Gossip[3528653292] = "Oh, l'eterna ossessione per la ricchezza materiale. Bene, la fortuna sorride a te, poiché puoi trovare la casa d'asta nella Terrazza dei Mercanti."
GS_Gossip[3532897266] = "Un vento violento sta arrivando - lo posso capire dal dolore alla mia ginocchia scoperta. Spero solo che non ci venga a prendere."
GS_Gossip[3535592850] = "Speriamo di poter creare più di una darkrune al giorno, ma sarebbe uno spreco di tempo. È semplicemente fisicamente impossibile. Inoltre, non riusciamo nemmeno a crearle a quel ritmo in modo affidabile.NEW_LINENEW_LINEE fidati, se ci fosse qualcun'altro qui abbastanza intelligente da aiutare, sarebbe arruolato e avremmo tanti darkrunes quanti ne servono."
GS_Gossip[3535617884] = "È bello rivederti, Dottore YOUR_NAME. Sto seguendo i tuoi progressi e oserei dire che è arrivato il momento in cui tu impari alcune tecniche più avanzate di bendaggio.NEW_LINENEW_LINETorna da me di tanto in tanto, man mano che il tuo livello di abilità cresce, e ti insegnerò tutto ciò che so."
GS_Gossip[3536544760] = "Impressionante, non credi? Questi giganti sarebbero il perfetto cibo... eh, alleati. Questo è il loro leader, ma continua a rifiutare di parlare con me."
GS_Gossip[3537305330] = "Gli Ethereum si sono oscurati... contorti. La vendetta è diventata la loro sola via di uscita e chiunque si opponga al loro cammino o non aderisca alla loro causa è considerato un nemico. Molti hanno visto che gli Ethereum stavano precipitando nella follia e se ne sono andati. Diversi dei Principi del Nexus del consiglio degli Ethereum hanno abbandonato gli Ethereum per formare altre gruppi e fazioni con obiettivi diversi. Il Consorzio è un esempio di tale gruppo derivato. La Protettorato ne è un altro... "
GS_Gossip[3537453257] = "Fshhhhhhsssfhhhhh?"
GS_Gossip[3540814255] = "Rilevo una carica nella tua regione paranarbulatrica! Devi aver usato recentemente il Capacitorium di Zephyrium -- non puoi usarlo di nuovo finché la carica non si esaurisce..."
GS_Gossip[3541162323] = "Abbiamo vinto $2219W battaglie contro il Flagello.  Preparati, YOUR_NAME, perché questa guerra è molto lontana dall'essere finita."
GS_Gossip[3541682434] = "Il sarto Keelen è sempre alla ricerca di più curiosi studenti per insegnare la sua delicata arte. Il suo negozio è un po' difficile da scoprire all'inizio, ma si trova proprio a nord dell'asta nel Bazaar. Lo troverai al piano inferiore dell'edificio."
GS_Gossip[3542204072] = "Cosa è la Fratellanza della Luce? Beh... Siamo tutti membri della Crociata d'Argento al nucleo - membri della Crociata d'Argento che non sono frenati da morale, rimorso e inutili emozioni umane."
GS_Gossip[3542626925] = "I partecipanti devono parlare con il Guardiano Bullrok prima di pubblicare qualsiasi compito.NEW_LINENEW_LINEColoro che vengono trovati a pubblicare messaggi non approvati saranno perseguiti.NEW_LINENEW_LINEPosta senza bollette."
GS_Gossip[3543180039] = "Come puoi vedere, sono solo un uomo con un paggio goffo e lento. La potenza dei nani Dark Iron e le creature tenute in schiavitù da Ragnaros mi sopraffarebbero facilmente da solo, ma ho la massima fiducia nel fatto che un avventuriero coraggioso e ambizioso come te non avrebbe alcun problema a gestire gli abitanti della pentola. Se dovessi scegliere di aiutarmi, ti ripagherò con ricchezze e fortune al di là dei tuoi sogni più folli."
GS_Gossip[3543857260] = "Per favore, raccontami di più suiippogrifi."
GS_Gossip[3544482528] = "Se devi chiedere, non mi conosci abbastanza bene da poter usare quel soprannome."
GS_Gossip[3545296343] = "Rocket-Chief Fuselage, comandante del B.O.O.M - il Braintrust delle Operazioni e Meccanica Orbitali - a vostra disposizione.NEW_LINENEW_LINETutti i sistemi sono pronti?! A giudicare dall'aspetto, il razzo X-52 Nether-Rocket ha ancora bisogno di molto lavoro!NEW_LINENEW_LINEAndiamo gente... siamo a T-minus MAI qui!"
GS_Gossip[3546735661] = "Per favore, sblocca la porta del cortile."
GS_Gossip[3550768472] = "L'arcano corrompe solo chi è debole. Tieni allenati i tuoi poteri, altrimenti potresti trovare una sorte simile."
GS_Gossip[3551182486] = "Questo teletrasportatore ti porterà a Grom'gol nel Nord del Stranglethorn.NEW_LINENEW_LINEDi solito.NEW_LINENEW_LINEIntendo dire, a volte ti disintegrerà semplicemente, o ridurrà tutti i tuoi tessuti molli in una nebbia verde, maleodorante, ma per la maggior parte del tempo è sicuro!NEW_LINENEW_LINE...per lo più."
GS_Gossip[355142141] = "Creare accampamenti?"
GS_Gossip[3554921156] = "Capo Ashtotem, ho perso il token che mi hai dato."
GS_Gossip[3556908149] = "Troverai Elder Northal all'interno del Transitus Shield a Coldarra."
GS_Gossip[3558604975] = "Beh, ora che lo dici, sì, ho visto qualcosa che mi è sembrato un po' strano ieri pomeriggio!NEW_LINENEW_LINEStavo correndo vicino a delle vecchie rovine troll a sud-est da qui; be', non stavo realmente correndo, più che altro saltellavo... La sabbia è così calda!NEW_LINENEW_LINEComunque, stavo saltando sopra le rovine, quando ho notato un accampamento allestito là. A me sembra un posto strano per allestire un accampamento... Avrei perlustrato un po' di più, ma uno di quei grandi avvoltoi pazzeschi mi ha cacciato via."
GS_Gossip[3560792593] = "Stalla Aldor"
GS_Gossip[3561957564] = "Nelle regioni orientali dei Campi dell'Alieno Netherwing si trova la Fortezza della Bocca del Drago. È lì che la crudele tribù orca della Bocca del Drago tortura i drakes che catturano, cercando di piegarli alla loro volontà. Molti hanno perso ogni speranza, scegliendo invece di obbedire alla Bocca del Drago. Gli altri... Rifiutano di atterrare per paura che le truppe di guerra della Bocca del Drago li catturino e li portino indietro alla fortezza."
GS_Gossip[3562461962] = "Benissimo. Le parole che cerchi hanno un nome, YOUR_NAME. Sono noti come il Codice dell'Inferno: le parole pronunciate da Gul'dan stesso per distruggere questa terra. L'incantesimo che ha reciso l'ultimo legame che gli orchi avevano con gli elementi di Draenor.NEW_LINENEW_LINE<Oronok annuisce.>NEW_LINENEW_LINEAye, è il cifrario che devi ricostruire e alla fine le parole del cifrario che devi richiamare."
GS_Gossip[3568203723] = "Dobbiamo prendere ciò che è nostro. La nostra sopravvivenza dipende da questo."
GS_Gossip[3568836062] = "Vorrei volare a Picco del Tuono."
GS_Gossip[3569211492] = "Potremmo stare lavorando insieme, ma questo aumenta solo la necessità di discrezione. Ancora una volta, siate attenti alle vostre parole e ai vostri comportamenti.NEW_LINENEW_LINEPosso garantire che siamo molto lontani dall'essere gli unici qui fuori."
GS_Gossip[3569848243] = "Sei arrivato proprio quando stavano per gettarmi ai mostri là sotto - per questo, ti ringrazio. Forse, io - piuttosto - noi, della spedizione azzurra, possiamo aiutarti ulteriormente?NEW_LINENEW_LINESei arrivato fin qui, YOUR_RACE, hai rischiato molto. Vorrai andare ancora più lontano per combattere Nefarian e la sua legione di Blackrock? "
GS_Gossip[357109086] = "Tonks?"
GS_Gossip[3572194989] = "Nella città ci sono tre banche: La Banca di Dalaran a nord, la Banca dei Mercanti di Dalaran a sud e un'altra sotto la città, nei sotterranei."
GS_Gossip[3575362745] = "Dai un'occhiata alle mie carni, amico. Non vorrai uscire nei Barrens senza un buon stock di provviste."
GS_Gossip[3577817866] = "Cerco addestramento, Signore Thorval."
GS_Gossip[3579185992] = "Dove si trova l'Eldest Obsidian?"
GS_Gossip[35794533] = "Dammi un paio di minuti, YOUR_NAME. C'era un po' di eccitazione qui un momento fa, e voglio solo accertarmi che le cose si siano calmate. Ti parlerò presto abbastanza."
GS_Gossip[3579684274] = "Interessante equipaggio che hai qui...."
GS_Gossip[3583796781] = "Dove si trova Elder Thunderhorn?"
GS_Gossip[3585014589] = "Che Jormund Stonebrow abbia un occhio per l'ago, è vero. Se dovessi aver bisogno di qualche addestramento, lo troverai da Stonebrow's Clothier nel lato settentrionale di The Great Forge."
GS_Gossip[3587457307] = "Se me lo chiedi, e l'hai fatto, penso che dovremmo uccidere tutti gli apotecari prima che sia troppo tardi!"
GS_Gossip[3590678630] = "Elder Morndeep trascorre del tempo al Ring of Law nelle Blackrock Depths."
GS_Gossip[3593627262] = "Eh, ciao! Se sei qui per questioni relative alle tasse e/o un invito, allora devi avermi scambiato per qualcun altro. Molto dispiaciuto!"
GS_Gossip[3593675176] = "Purtroppo, solo gli stimati campioni di Lunargenta possono acquistare ciò che ho da offrire."
GS_Gossip[3593958979] = "Le istruzioni per l'uso della daga possono essere ottenute da tre maestri d'arma: Archibald nel Quartiere della Guerra della Sepulcra, Sayoc all'interno della Valle dell'Onore a Orgrimmar, e Ileda a Lunargenta, nel Mercato dei Viaggiatori lontani."
GS_Gossip[3600050227] = "Wind Trader Marid, sono tornato con ulteriori informazioni sui drakes dell'aldilà. Sono pronto a diventare tuo socio e, per un extra, mi occuperò di quel fastidioso elfo e del suo amico umano."
GS_Gossip[3600537413] = "Sentiamo che gli Ethereum rappresentano una minaccia altrettanto grande per la nostra esistenza quanto Dimensius. Entrambi devono essere fermati..."
GS_Gossip[360303325] = "Se vuoi imparare l'incantazione, vai a cercare Lavinia Crowe nel cerchio interno dell'Apothecarium."
GS_Gossip[3605327271] = "Hai allevato tutti questi orchi qui, Grande Nonna?"
GS_Gossip[3606871167] = "Elder Sandrene ha viaggiato fino a Lakeside Landing nel Bacino di Sholazar."
GS_Gossip[3609404209] = "Sono assolutamente certo che voglio imparare la lavorazione delle pelle di squama di drago."
GS_Gossip[3609656509] = "Il corpo è quello di una guerriera orca femmina.NEW_LINENEW_LINEÈ chiaro che lei è morta in battaglia, probabilmente contro i quilboar nell'area."
GS_Gossip[3610135095] = "Hai visto qualcosa di strano nel deserto di recente?"
GS_Gossip[3610456331] = "I vrykul riposano pacificamente nel loro sonno magico."
GS_Gossip[3611335350] = "Salve, mortale."
GS_Gossip[361942351] = "Dove si trova Goldwell l'anziano?"
GS_Gossip[3620817087] = "Guardi nell'Alambicco. Là è dove il Dottor Herbert Halsey e il Dottor Marsh praticano."
GS_Gossip[3621664694] = "Il cammino del Druida è fratello a quello del Cielo. Gennia Runetotem è impregnata di tale conoscenza. Cercala nel grande tenda a lato est del villaggio di Bloodhoof."
GS_Gossip[3621696487] = "L'Orda ha rischiato molto per avventurarsi in Outland - risorse, personale - perfino la difesa tattica delle nostre terre è in gioco. Nonostante tutto, Thrall crede nel potenziale di questa terra devastata. C'è una strana luce nei suoi occhi ultimamente - come se percepisse un'illuminazione straordinaria che il resto di noi non riesce a comprendere.NEW_LINENEW_LINETuttavia, è il mio capo guerriero e mio fratello di sangue. Lo seguirei attraverso le porte dell'abisso stesso."
GS_Gossip[3624610157] = "Dove è finito il mio spinner? L'ho appena lasciato qui da qualche parte..."
GS_Gossip[3625375595] = "Non ho tempo da perdere, straniero. Dì il tuo scopo o vattene!"
GS_Gossip[3627989259] = "L'Alba d'Argento ti saluta, YOUR_CLASS.  Sono Hasana - una delle poche autorizzate a gestire l'equipaggiamento e il materiale per l'alba.NEW_LINENEW_LINEMentre combatti il male per nostro incarico - guadagnando nel frattempo il nostro rispetto e la nostra fiducia - guadagnerai token di valore da Officer Garush. I token servono a due scopi: utilizzali per ottenere un maggiore prestigio all'interno delle nostre file, oppure utilizzali come mezzo di scambio per acquistare oggetti speciali.NEW_LINENEW_LINEMentre migliorerai la tua posizione nei confronti dell'Alba, scoprirai che sempre più oggetti saranno disponibili per te."
GS_Gossip[3629203718] = "Il Consorzio ha pianificato questa operazione da mesi! Eravamo destinati a scavare Oshu'gun, il diamante più grande conosciuto nell'universo.NEW_LINENEW_LINEMinuti prima che iniziassimo, il Principe Nexus Haramaad ci ha fatto sapere che dobbiamo attendere finché non si risolve una questione politica nel Netherstorm. Nel frattempo, ho trasformato la nostra operazione in un centro di smistamento per gemme contraffatte, ma questo sta lentamente riducendo i nostri profitti."
GS_Gossip[3629757186] = "Cosa succede quando gli Earthen si destabilizzano?"
GS_Gossip[3630975223] = "Questa terra è stata devastata dall'impatto. Mentre potresti non seguire le nostre filosofie, YOUR_CLASS, vi prego di fare tutto il possibile per aiutare nel processo di guarigione."
GS_Gossip[363269953] = "Cosa è l'armatura di Cryptstalker?"
GS_Gossip[3633018777] = "Ah, l'Altissimo è arrivato. Benvenuto a Stillpine Hold."
GS_Gossip[3633780855] = "Mostrami come addestrare con un bersaglio di Carica."
GS_Gossip[3634134021] = "Benvenuto, amico. Spero che stia godendo Noblegarden? Perché non unirsi al divertimento?"
GS_Gossip[3634725521] = "Un mortale in possesso di conoscenze arcane e oscure che nessuno potrebbe superare, ideò un metodo per migliorare il proprio incantamento attraverso la cattura e l'utilizzo di anime innumerevoli.NEW_LINENEW_LINEInteri popoli furono portati all'estinzione attraverso i suoi dispositivi animati per alimentare il rituale attraverso il quale lui e i suoi complici avrebbero portato Murmur nel loro mondo."
GS_Gossip[3636935730] = "Finalmente è giunto il momento perché i gnomi esiliati ritornino.NEW_LINENEW_LINEAncora una volta, Gnomeregan sarà la nostra casa!"
GS_Gossip[3637108369] = "Inizia la tua ricerca a nord, YOUR_NAME. I nostri esploratori hanno avvistato il Pistone di Distorsione vicino alla riva."
GS_Gossip[3638042645] = "Questo è il luogo da cui provengono gli ordini dei cultisti. Il loro leader è destinato a comparire presto.NEW_LINENEW_LINENon lasciamo sfuggire questa opportunità."
GS_Gossip[363855952] = "Buliwyf qui sarà felice di insegnarti tutto ciò che c'è da sapere sui fucili!"
GS_Gossip[3640841739] = "Siamo troppo misericordiosi con i Miserabili. Dovremmo infilzare ciascuno di loro con una spada.NEW_LINENEW_LINELa loro audacia a Sunsail Anchorage è inaccettabile."
GS_Gossip[3643149873] = "Sentendo che hanno un Allenatore di Minatura nella Sepulcra. Tutto ciò che devi fare per arrivare là è andare a sud fuori dal paese e recarti alla parte posteriore delle Ruine di Lordaeron. Poi prendi l'ascensore giù nella Sepulcra stessa e chiedi a un Guardiano della Sepulcra ulteriori indicazioni."
GS_Gossip[364390910] = "Se diventi un amico della Città Bassa, forse possiamo fare affari?"
GS_Gossip[3649538829] = "Salve, viaggiatori. Sono stato istruito a trattare qualsiasi portatore di una chiave per Karazhan come un ospite onorato del Maestro. Non esitate a farmi qualsiasi domanda desideriate. In che modo posso aiutarvi?"
GS_Gossip[3650805444] = "Hai catturato tutti: Bach'lor, Banthar, Gutripper e perfino il potente Tusker! Sei veramente il miglior cacciatore di grandi prede che io conosca!"
GS_Gossip[3650896342] = "Tabard del Vuoto"
GS_Gossip[3654778804] = "C'è una differenza tra muco e melma?"
GS_Gossip[365972467] = "Il Macellaio parlerebbe del 'sangue degli innocenti,' e del suo oscuro padrone, 'Kirtonos.' Di come deve placare il suo padrone.NEW_LINENEW_LINEFinalmente, la bestia aveva finito con i suoi esperimenti. Eravamo stati svuotati di ogni vita. I nostri spiriti distrutti. L'abbraccio dolce della morte era sopra di noi e l'abbiamo accolto con braccia aperte. Ma nella sua infinita crudeltà, il Macellaio ci ha risvegliati dalla porta della morte.NEW_LINENEW_LINESaremmo stati tenuti in vita e gettati ai suoi ghouls assetati di sangue. Rise mentre guardava i mostri divorare la nostra carne."
GS_Gossip[3659869894] = "Come funzionano le Tavole Abbondanti?"
GS_Gossip[3663119878] = "È affascinante... Ho sentito orchi dichiarare che l'odore degli umani è disgustoso e ho sentito umani dichiarare che l'odore degli orchi è orribile; tuttavia, a me, tutte le razze di queste terre emanano lo stesso odore: L'odore disgustoso e vertiginoso della golosità.NEW_LINENEW_LINEDubitavi della validità della mia affermazione? Non vedi queste cose che governano la tua vita come semplice residuo della cupidigia che determina ogni tua decisione?NEW_LINENEW_LINECosì sia. Poiché fu la golosità a spogliarmi della mia casa, sarà la golosità a riportarmi indietro."
GS_Gossip[3664871245] = "Chi è Malygos?"
GS_Gossip[3666342530] = "Whew! Cosa è quel odore?"
GS_Gossip[3670678539] = "Lasciami pensarci, Zamael."
GS_Gossip[3670793286] = "Attraverso un rigoroso ricondizionamento, ho dovuto rompere molti studenti da tutto ciò che avevano imparato precedentemente, affinché potessi insegnargli nuovamente. Il servizio che offro diventa sempre più difficile da eseguire ogni volta che viene fatto. Per questo motivo, diventa sempre più costoso con ogni ricondizionamento. Desideri che io ti rompa delle abilità che hai imparato?"
GS_Gossip[3672354396] = "Fui uno dei primi tauren druidi, dell'ultima generazione insegnata da Shan'do Cenarius, prima della Legione, prima dello Scisma, quando il mondo era ancora giovane. Prima che tutto cambiasse.NEW_LINENEW_LINEMentre i miei fratelli cacciavano grandi bestie, io cacciavo storie. Ero stato attratto dagli arti druidici da questa fame, questa sete di conoscenza. Per un po', quella fame fu saziata mentre imparavo a parlare agli alberi, alle rocce e alle bestie, e ascoltavo le loro storie.NEW_LINENEW_LINEMa poi arrivò il momento in cui Cenarius non camminò più tra di noi e i miei fratelli iniziarono a dimenticare ciò che ci aveva insegnato. Io non potei dimenticare, tuttavia, e avevo ancora bisogno di imparare di più sul nostro mondo.NEW_LINENEW_LINECosì ho detto addio e mi sono recato al di là delle terre del mio popolo."
GS_Gossip[3672807305] = "Sono un inviato di Balthas. Egli mi ha mandato a raccogliere un'essenza arcanica perfetta."
GS_Gossip[3673267185] = "Io testimonio un miracolo che si pone davanti a me! In mille anni di prigionia, non ho visto nemmeno un singolo ESIMIO esemplare - tranne quei disgustosi Qiraji e silithid - entrare in queste stanze."
GS_Gossip[367445219] = "Sì, per favore fallo."
GS_Gossip[3675608210] = "Salve, eroe. Creo e vendo armature Ahn'kahar Blood Hunter per cacciatori."
GS_Gossip[367661349] = "Grazie alla Luce per te!"
GS_Gossip[3676820633] = "Dovrai trovare un modo per dimostrare che entrambi state combattendo per la stessa parte. Anche se i Timbermaw potranno attaccarti ora, se sarai diligente, troverai un modo.NEW_LINENEW_LINEDevi ricordare che qualsiasi attacco diretto contro i furbolg Timbermaw ostacolerà notevolmente le tue possibilità di guadagnarli come alleati.NEW_LINENEW_LINEUn buon posto da cui iniziare sarebbe il furbolg di Deadwood che si trova in molti punti di Felwood. Questi furbolg sono nemici della tribù Timbermaw, e ucciderli migliorerebbe notevolmente la tua posizione nei loro confronti."
GS_Gossip[3680092408] = "Forte di corpo e spirito. Non può esserci combinazione più forte! Trova il tuo destino con Sark Ragetotem nella Hall dei Cacciatori."
GS_Gossip[3683088406] = "Il vascello della rinascita deve essere rafforzato con l'elementium. Conosco un solo luogo dove si trova questa materia: i piani elementali, al centro del nostro mondo.NEW_LINENEW_LINENe esiste uno, un Modellatore terrestre, che potrebbe sapere più di me riguardo all'acquisizione di tali oggetti. Devi trovare questo Modellatore terrestre!"
GS_Gossip[3684463278] = "Il mio padre è partito per destinazioni più esotiche in cerca di prede più grandi. Non preoccuparti però, siamo comunque qui alla ricerca!"
GS_Gossip[3685662861] = "La Cattedrale della Luce nel Piazzale della Cattedrale è la dimora dei sacerdoti di Roccavento. Là troverai la Sacerdotessa Alta Laurena."
GS_Gossip[3686816163] = "Le pozioni e gli oli, queste sono cose che Yelmak ti insegnerà se sei degno. Cerca il suo negozio al centro di The Drag."
GS_Gossip[3688278136] = "Come hai fatto a sapere? Intendo dire, sì... Sì, sto cercando quel frammento. Ce l'hai?"
GS_Gossip[3696022893] = "Vuoi sapere qualcosa sulle raccolte di razioni? Bene. L'ultima volta che ne ho sentito parlare, l'Orda aveva preparato $2095w su $2096w bistecche di lupo magro. Abbiamo anche messo da parte $2102w su $2103w sardine maculate e $2105w su $2106w salmoni arrostiti necessari."
GS_Gossip[369724912] = "Voglio viaggiare veloce"
GS_Gossip[3697294463] = "La Magica Menageria si trova nel nordest di Dalaran. Lì sono disponibili forniture per animali domestici, monture esotiche e stalle."
GS_Gossip[3697822154] = "Elder Beldak può essere trovato all'accampamento della Brigata Westfall nei Colli Bradi."
GS_Gossip[3701979230] = "Vorrà visitare Simply Enchanting, appena fuori dall'Exchange Commerciale dei Magi nel nord-ovest di Dalaran."
GS_Gossip[3703824839] = "Se hai bisogno di viaggiare verso l'Exodar, ho proprio il cavallo hippogryph per te!"
GS_Gossip[3708408060] = "Come desideri, Eitrigg."
GS_Gossip[3710842833] = "Hai bisogno di qualcosa?"
GS_Gossip[3712508384] = "Benvenuto alla fiera, giovane uno!   Abbiamo raccolto meraviglie da ogni angolo del mondo per la tua visione.   Oh, e per favore, fammi sapere se riesci a raccogliere un set di carte oscure minori di Darkmoon, poiché il maestro... intendo io sarei molto interessato a loro."
GS_Gossip[3715841473] = "Sono pronto, Gymer. Andiamo!"
GS_Gossip[371697948] = "Aberrazioni del Flagello... Presto riceveranno ciò che meritano."
GS_Gossip[3718756544] = "È triste vedere cosa è successo a questa terra. L'Esplorazione Cenarion farà del suo meglio per comprendere e riparare i danni causati."
GS_Gossip[372036985] = "Molto furbo come hai fatto a entrare qui in quel modo, YOUR_NAME.NEW_LINENEW_LINEChe? Sorpreso che io conosca il tuo nome? Sono un demone, è questo che facciamo. Conosco anche il tuo vero nome, quindi sarebbe meglio che comprassi qualcosa di costoso."
GS_Gossip[3722290547] = "Avevo avuto fortuna nel trovare un'oasi e avevo deciso di rimanere lì finché non avessi ricevuto una risposta. Così mi sedetti lì, muovendomi solo quando assolutamente necessario, vivendo di quelle creature che si avvicinavano alla pozza. Tale era il mio orgoglio.NEW_LINENEW_LINECome ho detto, decenni sono passati senza una risposta. Ma posso ricordare un particolare tramonto bellissimo una sera. Un tiepido zephyro soffiò sulla terra e ero sicuro di aver sentito una voce, ma non c'era nessuno intorno.NEW_LINENEW_LINECome puoi immaginare, ho pensato di essere finalmente perso la testa."
GS_Gossip[3722597054] = "Dirge Quikcleave di Gadgetzan è un maestro dell'arte culinaria. Per migliorarti, dovrai cercarlo."
GS_Gossip[3724094073] = "Non ho né il tempo, né l'inclinazione, di spiegarti le cose, scemo! Ora, hai qualcosa di importante da dire, o sei qui solo per invitarmi a bere un drink, principessa?"
GS_Gossip[3725494990] = "Esamino ulteriormente il corpo."
GS_Gossip[3725622238] = "Elder Bronzebeard può essere trovato nella casa ancestrale dei Bronzebeard, Forgiardente."
GS_Gossip[3727569784] = "L'infestazione del Flagello cresce in Azshara. Ogni guerriero in grado di combattere è necessario per contenere l'onda dell'invasione del Flagello.NEW_LINENEW_LINENumero di Necropoli rimanenti: $2279W"
GS_Gossip[3728718415] = "I martelli degli earthen stanno uniti alle spalle di Bouldercrag. Opporremo resistenza ai seguaci di Loken fino all'ultimo momento."
GS_Gossip[3728755007] = "Il maestro della corporazione di Dalaran si trova nel centro visitatori, proprio a sud del centro della città."
GS_Gossip[372909912] = "Gahk nuovo a Ogri'la come un piccolo YOUR_RACE.  È come il paradiso da altri orchi sotto sempre parlano.  Ma, il cervello di Gahk fa male per via dei cristalli che rendono Gahk più intelligente.NEW_LINENEW_LINE<Entrambi i capi di Gahk annuiscono l'uno all'altro.>NEW_LINENEW_LINEUs learning ta make da crystalforged darkrune.  When us learn dat, we smash da demon's warp-gate!"
GS_Gossip[3730459348] = "Abbiamo due case d'asta all'interno di Lunargenta. Quale preferisci?"
GS_Gossip[373234655] = "Dimmi qualcosa sulla ricetta del mantello di gelo mortale."
GS_Gossip[37351352] = "Poi, lasciamo che Archimonde faccia il peggio."
GS_Gossip[3735594053] = "Tutte le ricompense dovranno essere pagate dall'Esecutore Supremo Wroth dopo la verifica.NEW_LINENEW_LINELe persone serie si informino all'interno.NEW_LINENEW_LINENESSUNO SOLLECITATORI!"
GS_Gossip[3738441686] = "Perché sono stato mandato indietro a questo particolare posto e tempo?"
GS_Gossip[3738447355] = "<Il lord-comandante ti fissa prima di proseguire.>NEW_LINENEW_LINEStavo arrivando a questo. Infatti, quando l'Alto Generale Abbendis ha schierato le sue forze su Northrend, ha cambiato il loro nome in Furia Scarlatta.NEW_LINENEW_LINENon fu molto tempo prima che l'ammiraglio Barean Westwind si presentasse a lei a New Hearthglen nella Dragonblight. Secondo tutti i resoconti, non si aspettava che lui si facesse vivo. Nemmeno si aspettava che lui mettesse in discussione la sua autorità e le togliesse il comando.NEW_LINENEW_LINEProbabilmente hai avuto a che fare con la sua morte, ma non importa. Una volta che fu morta, l'ammiraglio fece un'uscita misteriosa e abbiamo perso le sue tracce."
GS_Gossip[3740870738] = "L'eko è la potenza che ogni creatura possiede. Il charm che ho creato per te ti permette di catturarla in una manifestazione fisica.NEW_LINENEW_LINEConosco un incantamento che puoi usare per trasformare l'e'ko che trovi e convertirlo in juju.NEW_LINENEW_LINEPuoi den prendere la Cache di Mau'ari, an' usarla ta riflettere da potenza di da juju su te stesso.NEW_LINENEW_LINEC'mon, give it a try. Bring da e'ko ta Mau'ari an' we have some fun."
GS_Gossip[3746388494] = "Ho sentito che un nobile tra gli elementali dell'acqua, Hydraxis, guerreggia contro i servitori del fuoco. Speriamo che perda!"
GS_Gossip[3748034310] = "Per un momento ho pensato che fossi la mia amata Sif... quel filo di capelli... ma no! Non può essere... Sif è morta....NEW_LINENEW_LINEMio... mio fratello.... l'ha uccisa!"
GS_Gossip[3749341504] = "Mantieni il tuo volume basso, YOUR_CLASS. Non vorremmo che li sentissero."
GS_Gossip[3752466530] = "Quello che chiamano Hellscream potrebbe essere l'unica nostra speranza."
GS_Gossip[3756690175] = "Di che cosa hai sentito parlare dell'Albergo Ombra Profonda?"
GS_Gossip[3757205124] = "Rayne, dove dovrei cercare le fronde selvagge?"
GS_Gossip[3757808362] = "Tutti sapranno di quanto è accaduto qui in questo maledetto tempio, eroe. Sarà scritto nei libri di storia - le storie raccontate come leggenda da Azeroth alle lontane regioni del Nether stesso!"
GS_Gossip[375796579] = "Avvicinati, piccolo; i miei orecchi non sono come un tempo, e non ho intenzione di alzare la voce."
GS_Gossip[3759763367] = "Benvenuto, io sono Azimi! Spesso faccio questa camminata per vendere ai soldati frutta e acqua fresca. Sei affamato, o forse hai sete?"
GS_Gossip[3760163791] = "Ciao, Nonna. Garrosh mi ha detto che volevi parlare con me."
GS_Gossip[3762318282] = "Una buona birra è una birra forte."
GS_Gossip[3765666358] = "Devi essere a cavallo di un montato da torneo prima che io possa istruirti.NEW_LINENEW_LINEEquipaggia una lancia e trova un cavallo da torneo fuori dal padiglione della tua fazione."
GS_Gossip[3772772160] = "Di che cosa hai bisogno di indicazioni?"
GS_Gossip[3773081300] = "Radiazione?!NEW_LINENEW_LINENo, non devi preoccuparti per quello!  Sheesh, le cose che la gente crede questi giorni.NEW_LINENEW_LINEAllora, che ne pensi delle nostre operazioni qui sotto? All'ultima tecnologia, baby! Non dubitarne."
GS_Gossip[3773341441] = "Eh, no... no, non voglio proprio quello."
GS_Gossip[377360683] = "Le cose possono diventare un po' soffocanti qui a Nethergarde. A volte un nano ha bisogno di una bevanda per dimenticare per un momento i suoi doveri."
GS_Gossip[3775628895] = "Saluti, YOUR_CLASS. Sono Kuros, il secondo del Triumvirato della Mano."
GS_Gossip[3775817539] = "Prossimamente pianterò le radici e dormirò.   Prima di riposare ci sono cose che devono ancora essere fatte."
GS_Gossip[3778439389] = "Ho paura che il mio popolo sia in parte responsabile di questa distruzione. Siamo rifugiati, spostati dalle nostre case dalla Legione Infuocata. Questa tragedia è il risultato della nostra ultima evacuazione. La nostra nave è andata distrutta - questo detriti fanno parte di quella nave."
GS_Gossip[3782580305] = "L'ultima volta che ne ho saputo qualcosa, l'Anziano Nurgen si trovava ad Azjol-Nerub."
GS_Gossip[3783681114] = "I druidi sono molto sensibili al destino di tutti gli animali del mondo. Quando è stato scoperto che questi uccelli erano in pericolo, abbiamo creato un sistema per salvaguardarli dalla corruzione di Feralas.NEW_LINENEW_LINEUn gnomo di nome Curgle Cranklehop conduce l'affare; raccoglie le uova e le invia qui, dove le curio.NEW_LINENEW_LINEPotremmo sempre usare più aiuto per la nostra causa, YOUR_NAME. Forse dovresti andare a Gadgetzan e cercare Curgle."
GS_Gossip[3786068968] = "Puoi darmi un'arancia?"
GS_Gossip[3786666518] = "L'Esecutore Anselm richiede il tuo rapporto."
GS_Gossip[3787852373] = "L'avevo tutto, una volta. Fama, fortuna, un completo di equipaggiamento da gladiatore di primissima qualità... e poi l'ho gettato tutto via.NEW_LINENEW_LINEUna volta che il Cartello mi ha beccato a truccare le battaglie... a scambiare le vittorie... era finita.NEW_LINENEW_LINEOra non ho niente se non questi stracci e un fegato cattivo."
GS_Gossip[3791158289] = "Per favore, mi dica di più."
GS_Gossip[3793035091] = "Se non l'hai già fatto, assicurati di offrire il tuo aiuto a Rina Moonspring."
GS_Gossip[3796624673] = "Ciao. Squire Walter e io siamo responsabili del prendersi cura di Old Blanchy qui, insieme al resto dei cavalli."
GS_Gossip[3797561556] = "Ho un indizio sulla chiave di Norgannon, che protegge l'accesso agli archivi di Ulduar, ma i Titani l'hanno divisa in due pezzi e li hanno nascosti.NEW_LINENEW_LINEUno dei pezzi, la conchiglia della chiave, si trova all'interno della Biblioteca dell'Inventore sulla costa settentrionale, a sud di Ulduar stesso. La prima cosa che dovrete fare è recuperare i frammenti di un disco d'accesso dai guardiani della biblioteca."
GS_Gossip[3798307254] = "Vorrei inserire il codice segreto per ricevere il mio animale domestico Murloc."
GS_Gossip[3798652301] = "Nessun riposo per i malvagi, ma credo che tu stia bene. Troverai l'oste Norman nel anello superiore del Quartiere del commercio."
GS_Gossip[3799022502] = "Sono Kodian, figlia di Ursoc. Sorveglio questo antico santuario sacro.NEW_LINENEW_LINENon ho visto un estraneo venire qui da molto tempo."
GS_Gossip[3801164918] = "<Grugniti> Vorrei poter dire che abbiamo evitato di atterrare in acqua. Vorrei poter dire che abbiamo atterrato in acqua solo una volta... ma abbiamo finito per atterrare in quattro laghi diversi, incluso il Lago Lordamere!"
GS_Gossip[3801423706] = "Non farò una cosa del genere. Semplicemente non posso lasciare Taretha in pericolo mentre io corro via in montagna. Non sono un codardo. Ora, dove è lei?"
GS_Gossip[3805566291] = "Ascolta le storie di un anziano. YOUR_NAME. Ne ho molti da dire..."
GS_Gossip[3805754933] = "Vai pure."
GS_Gossip[3805808575] = "Salve! Ecco uno dei migliori strumenti musicali di tutta Lordaeron. È un onore esibirsi per il Maestro e tutti i suoi ospiti. Siediti tra il pubblico, sento che lo spettacolo sta per cominciare presto."
GS_Gossip[3808790601] = "Gubber, non ho una canna da pesca."
GS_Gossip[380922821] = "La tua voce è rauca a causa di tutti quei gridi? Trova la Casa d'Asta di Orgrimmar nella Valle della Forza."
GS_Gossip[3809965411] = "Saluti, YOUR_CLASS.  Anche se il tempo e il bere hanno annebbiato i miei sensi esterni, i miei occhi interni restano forti."
GS_Gossip[3810114566] = "Shh! Sii molto silenzioso; sto osservando i murloc.NEW_LINENEW_LINEVivere all'interno di una conchiglia di tartaruga di dimensioni eccessive è un sacrificio che sono disposto a fare per la scienza. Dopotutto, se i murloc mi vedono qui, reagiranno alla mia presenza e contamineranno i miei dati!NEW_LINENEW_LINECome primo membro gnomo della Lega degli Esploratori, sto osando andare in posti in cui nessun nano è mai andato prima!"
GS_Gossip[3810464165] = "<Deathguard Simmer ti guarda aspettando.>"
GS_Gossip[3810881824] = "Sei... qui per salvami?"
GS_Gossip[3817411011] = "Ecco dove ho sacrificato tutto per liberare mio padre. Ora vengo a distruggerlo..."
GS_Gossip[3818471347] = "I Creatori sono... i Creatori.NEW_LINENEW_LINESono gli esseri che hanno seminato e plasmato questo mondo secondo il loro disegno. Sono la ragione dell'esistenza di questo mondo, nonché di molti altri. Sono la fonte da cui Azeroth scorre."
GS_Gossip[3819241946] = "Vi sveleremo il nostro segreto dietetico: cocktails e sogni. Possiamo aiutarvi con uno."
GS_Gossip[3821912543] = "Cerchi Grol'dar e l'Enclave del Fuoco Oscuro? Trovali nella caverna sotterranea chiamata Cleft of Shadow. Ci sono due tunnel che portano in quella caverna, uno poco a sud della Valle della Saggezza e l'altro da The Drag."
GS_Gossip[3822133337] = "Se ti serve un albergo, l'Albergo di Pietrafiamma è il posto in cui dovresti andare. Lo troverai proprio a sinistra dell'ingresso a Forgiardente se stai arrivando, o a destra se stai andando.NEW_LINENEW_LINEOh, e se vai in quella direzione, digli loro di avere un boccale pronto per me."
GS_Gossip[3822492521] = "Troverai Elder Starglade fuori dalle porte di Zul'Gurub nella Valle di Stranglethorn."
GS_Gossip[3823637317] = "I Sentinelli dell'Ali d'Argento combattono ancora contro l'Orda nella Forra dei Cantaguerra, YOUR_CLASS. Ciò che rimane da vedere è se tornerai là per aiutarli."
GS_Gossip[3827921143] = "Sono ciò che si chiama un capitalista, YOUR_RACE."
GS_Gossip[382947652] = "Non mi importa chi sei o cosa fai fuori dalla Guardia del Cielo, ma fintanto che sei qui farai ciò che ti viene detto."
GS_Gossip[3834002848] = "Non ho niente di nuovo per te, ragazzo. Hai superato il lavoro manuale..."
GS_Gossip[3834157050] = "Aye, tu là! Se vuoi guadagnare il rispetto dei Darkspear, puoi iniziare donando risorse preziose a chi ne ha bisogno! I tessuti e i bendaggi non crescono sugli alberi, sai.NEW_LINENEW_LINEInvece di rivendere i vari pezzi di stoffa che trovi durante le avventure, donali! In questo modo guadagnerai il riconoscimento dei Darkspear!"
GS_Gossip[3834658208] = "Sono libero! Ma il segreto... ora è in pericolo. Akama deve essere avvertito!"
GS_Gossip[3834688429] = "Devo arrivare velocemente al Castello di Wintergarde!"
GS_Gossip[3835427257] = "La mia scommessa è sui goblin! E se hai un po' di cervello, la tua lo è anch'essa!"
GS_Gossip[3835447480] = "È un piacere conoscerti a tua volta, Arcidruido. Sono qui per un compito di Tirion e il tempo è breve, potrei disturbarti per un portale verso Moonglade?"
GS_Gossip[3835938148] = "Analisi del Guardiano: Thorim"
GS_Gossip[3837263245] = "Sei un nuovo recluta? Questo non è armatura standard."
GS_Gossip[3838928679] = "Suppongo che qualcuno debba bendarci noi guerrieri dopo la battaglia. Cerca Arnok alla capanna di 'Sopravvivenza del Più Forte' accanto alla Capanna Spirituale nel Valico degli Spiriti. Guarda sopra e a ovest della Valle della Forza per trovare un lago. Là è dove si trova lui."
GS_Gossip[3840743838] = "Per favore, raccontami di più sui gordunni."
GS_Gossip[3841743210] = "Diamo un taglio a questa... cosa... e finiamola qui."
GS_Gossip[384477669] = "Elder Rumblerock passa gli anni in una caverna sopra la Dreadmaul Rock nelle Burning Steppes."
GS_Gossip[3846261268] = "Inerme... impotente... ripristinare... devo ripristinare... Zevrim controlla... fine a questo tormento..."
GS_Gossip[3846671556] = "Il Warchief porta cambiamenti che porteranno la vittoria all'Orda! Cerca Swart all'interno dei caserma sul lato est del paese."
GS_Gossip[3851216941] = "Tanti bei posti per la minatura in Durotar, o almeno questo è ciò che sento dire. Così tanto buono, infatti, che abbiamo un Allenatore di Minatura proprio qui a Razor Hill. Troverai Krunn accanto alla forgia riscaldata nell'angolo nord-occidentale del paese."
GS_Gossip[3852988114] = "Dovrai cercare Benik Boltshear, quindi. Si trova nel cuore del Distretto Elvico vicino ai fabbri."
GS_Gossip[3854317321] = "E così invocarono Murmur.NEW_LINENEW_LINEPotenti magie di contenimento e silenziamento sono state impiegate, tenute unite dal costante afflusso di anime alimentate loro. Tuttavia, nonostante questo, non riuscivano a controllare la bestia, non riuscivano a piegarla alla loro volontà.NEW_LINENEW_LINEQuesti mortali hanno iniziato a elaborare diverse strategie, e uno dopo l'altro tutti hanno fallito. E così facendo, hanno indebolito i rituali, accidentalmente concedendo a Murmur la minima libertà.NEW_LINENEW_LINEEra tutto ciò che era necessario."
GS_Gossip[3855171343] = "Benvenuto, YOUR_CLASS. Sono Rokaro."
GS_Gossip[3856291261] = "Lasciare Kael'thas è stata la cosa migliore che qualcuno di noi abbia mai fatto. I suoi seguaci sono troppo ciechi o troppo spaventati per rendersi conto dove li sta portando.NEW_LINENEW_LINENoi però non lo siamo."
GS_Gossip[3858774473] = "Hapana borbotta semplicemente e ti fa cenno di andare via verso il Capitano Terribile DeMeza.NEW_LINENEW_LINESotto la pelliccia di un braccio massiccio si può vedere un tatuaggio con la parola \"MAGATHA\" in un cuore perforato da una freccia."
GS_Gossip[3859129262] = "Dealer Dunar, vorrei dare un'occhiata alle tue merci."
GS_Gossip[3861845717] = "Inviami a Garrosh's Landing, Yanni."
GS_Gossip[3861991949] = "Se hai ciò che serve, sarò felice di mostrarti la via."
GS_Gossip[3862914540] = "Per scendere in sicurezza, fornisco ali a chi ne ha bisogno. "
GS_Gossip[3863423368] = "<L'Arcano Guardiano fa cenno verso la porzione orientale della città bassa.>"
GS_Gossip[3863895970] = "Sì, per favore!"
GS_Gossip[387000520] = "Ahoy, mon!  Cosa sta succedendo, tu 'at steppa salato!NEW_LINENEW_LINEDis place be all chacka-chacka, ye scallywag!"
GS_Gossip[3872693354] = "Possiamo operare nell'ombra della società civile, ma qui, sul fronte del combattimento, finalmente le nostre potenze sono riconosciute correttamente."
GS_Gossip[3874121671] = "Di che cosa desideri sapere riguardo all'Incantazione di Gemme?"
GS_Gossip[3874668172] = "Sei un idiota che dovrebbe prestare attenzione ai miei avvertimenti. Nessuno è invulnerabile. Sarebbe saggio ricordare quel consiglio."
GS_Gossip[3876180287] = "<Ahlurglgr sembra sorpreso dal fatto di essere in grado di comprenderti.>"
GS_Gossip[38770364] = "La natura favorisce coloro che sono disposti a imparare i suoi segreti, YOUR_NAME."
GS_Gossip[3880731643] = "Nella guerra precedente, i tauren hanno combattuto. I shaman sono stati mandati in difesa di questo mondo contro l'invasione del Flagello. La maggior parte ha perso la vita. Tanti altri sono stati strappati in pezzi, i loro organi utilizzati per orribili esperimenti in quella maledetta fortezza. Piango la loro scomparsa, ma il mio cuore è pieno di orgoglio per il loro coraggio."
GS_Gossip[3882297282] = "Yonn Deepcut può essere trovato all'interno della grande tenda, nell'angolo nord-ovest di Bloodhoof Village."
GS_Gossip[3885421455] = "È buono vedere altri che combattono il Flagello a Stratholme, poiché è qui che sono più forti.NEW_LINENEW_LINESalve.  Sono Aurius.  Un tempo ero un paladino della Mano d'Argento, ma come altri i cui credi vacillarono... sono caduto in disgrazia.  Il Flagello mi ha sedotto e quasi mi ha trasformato in un cavaliere della morte!NEW_LINENEW_LINEFinalmente avvertendo il mio pericolo, mi sono rifugiato in questa cappella. È un luogo sacro, dove il primo paladino, Uther il Portatore di Luce, fu ordinato nell'ordine della Mano d'Argento."
GS_Gossip[3886086378] = "Permetto all'uomo di prendere abbastanza mais per sfamare la sua famiglia per un paio di giorni, incoraggiandolo a lasciare la terra."
GS_Gossip[3886466643] = "Niente libera lo spirito come volare attraverso il cielo. Esiste un posto simile nel nostro grande centro tribale, Picco del Tuono. La strada a nord fuori da Villaggio della Mandibola Rossa ti guiderà lì. Una volta che salirai in cima con l'ascensore, parla con uno dei Bluffwatchers che possono darti ulteriori indicazioni."
GS_Gossip[3886575712] = "Devi essere alla ricerca di Smith Argus. Di solito si occupa del fucino a Goldshire se hai bisogno di alcuni addestramenti."
GS_Gossip[3886791589] = "Stivali, cosa hai lì dietro che scende liscio?"
GS_Gossip[389043334] = "Cosa stai facendo qui?! Vattene immediatamente ad Alterac Valley, dove sei necessario!"
GS_Gossip[3893614789] = "Me ne sono andato. Non sarei rimasto con i Blackrock. No, le morti dei miei figli non sarebbero state inutili. Non servirei sotto un inetto, un maniaco avido di potere come Rend.NEW_LINENEW_LINEMi sono rifugiato nelle foreste di Lordaeron, vivendo come un eremita vicino a Hearthglen."
GS_Gossip[389438312] = "Sono occupato? Cosa vorresti dire? Pensi che io stia qui tutto il giorno a passare il tempo con le dita? Se sei qui per comprare qualcosa, parla con Handor."
GS_Gossip[3895706344] = "La battaglia per la Forra dei Cantaguerra è una battaglia che non possiamo perdere. Combattiamo per l'onore e combattiamo per la nostra terra, e nessun orco o alleato disorientato li prenderà da noi!"
GS_Gossip[3900628314] = "Telredor ha visto più cambiamenti negli ultimi 20 anni di quanto non ne abbia visti in secoli precedenti. Non posso lamentarmi, YOUR_NAME, perché il mondo è cambiato molto di più in tutto questo tempo.NEW_LINENEW_LINELa Luce mi ha portato amici e compagni che non avrei potuto conoscere come un prete rinchiuso. Impara tutto ciò che puoi del passato nel tuo tempo qui. Ti aiuterà a comprendere dove sta portando la tua via."
GS_Gossip[39042458] = "Ah, stai cercando Lucan Cordell. Gestisce un negozio all'esterno del Quartiere della Magia lungo il tuo cammino verso la Carcerazione."
GS_Gossip[3908254207] = "Qual è l'abilità ultima del drago ambra?"
GS_Gossip[3909389580] = "Anello interno del quartiere della guerra dove James Van Brunt lavora. Lui ci ha creato una buona catena."
GS_Gossip[3912024819] = "Ehi Vi'el, mostrami le tue merci!"
GS_Gossip[3912477358] = "Sei pronto a combattere per l'Orda, YOUR_CLASS?"
GS_Gossip[3914754970] = "Quali abilità hanno i drakes ambra?"
GS_Gossip[3915160420] = "Assicurati di cogliere tutti gli straordinari spettacoli e meraviglie della Fiera di Lunacupa quando arriva in città!"
GS_Gossip[3916712330] = "Chiama l'Uomo senza Testa."
GS_Gossip[3918429723] = "Fatto, fatto e fatto."
GS_Gossip[3919429819] = "Lasciami dare un consiglio: mai fidarti di un gnomo."
GS_Gossip[3920455875] = "Ci sono due caselle postali nella Sedia del Naaru: una vicino alla banca e un'altra fuori dall'asta."
GS_Gossip[3920811368] = "Sei uno degli shaman? Hm. Immagino che tu possa scegliere liberamente la tua strada... qualunque essa sia. Tuluun ha un piccolo accampamento isolato a nord-ovest di Azure Watch."
GS_Gossip[392234083] = "Benvenuto all'Albergo di Piazza Falconale. Posso prepararti un pasto o sistemarti una stanza?"
GS_Gossip[3923406270] = "Cosa intendi con \"puro?\""
GS_Gossip[3923913826] = "Il zeppelino dovrebbe appena essere partito da Sepulcra."
GS_Gossip[3924169296] = "Torno appena sistemo questo disordine."
GS_Gossip[3924589762] = "Il cristalliforgiato dei Bash'ir può essere utilizzato per trasformare i tuoi frammenti di apexis in flaconi instabili del mago. Questi flaconi rendono l'assumente più intelligente, più robusto e aumentano l'efficacia delle loro magie danneggianti e curative.NEW_LINENEW_LINEFai la tua scelta, di seguito."
GS_Gossip[3928639036] = "Ciao amico mio, e benvenuto nel maggior spettacolo su Azeroth!NEW_LINENEW_LINEPer favore, avvicinatevi e godetevi tutto ciò che abbiamo da offrire. Sbizzarritevi a contemplare le meraviglie che la Fiera di Lunacupa ha scoperto in questo vasto e misterioso mondo! Non abbiamo risparmiato alcun impegno per portarvi un'esperienza che divertirà i bambini di ogni età!"
GS_Gossip[3932416462] = "Sono io che eseguo i comandi del Warchief senza domande. Sono l'Orda."
GS_Gossip[3936028388] = "Saluti, giovane YOUR_CLASS."
GS_Gossip[3936838370] = "Il tuo aiuto nel combattere la Legione Infuocata sarebbe molto apprezzato. La Signora Jaina Proudmoore potrebbe aver bisogno del tuo aiuto sulle linee di fronte."
GS_Gossip[3937805383] = "Saluti, YOUR_CLASS.NEW_LINENEW_LINEL'Alleanza controlla attualmente il Forte di Wintergrasp. Quando la battaglia è sul punto di iniziare, parla con me per entrare in battaglia.NEW_LINENEW_LINELa battaglia successiva inizia tra $4354k."
GS_Gossip[3938395848] = "Ah, Zaetar... <Celebras distoglie lo sguardo.>NEW_LINENEW_LINEMio padre, Remulos, ha cercato di fermarlo...NEW_LINENEW_LINEZaetar era testardo, e quando si innamorò di una principessa elementale terrestre, mio padre sapeva che il loro matrimonio era maledetto, ma Zaetar rifiutò di ascoltare.NEW_LINENEW_LINEI centauri sono il risultato del suo errore. Sono nati deformi e pieni di odio; mio zio Zaetar fu ucciso dai propri parenti...NEW_LINENEW_LINELa principessa malvagia, Theradras, tuttora custodisce i suoi resti qui nelle grotte cristalline."
GS_Gossip[3941581625] = "<La nonna Geyah sorride a te.>NEW_LINENEW_LINEMi ricordi mio figlio, YOUR_NAME.NEW_LINENEW_LINEEra una montagna immobile: Un pilastro di forza e onore.NEW_LINENEW_LINE<Gli occhi di Geyah si riempiono di lacrime.>NEW_LINENEW_LINEHa sacrificato se stesso affinché potessimo sopravvivere. Affinché generazioni di orchi dopo di lui potessero nascere in un mondo senza la maledizione del sangue... Senza Gul'dan e la sua oscura Orda...NEW_LINENEW_LINE<Geyah fissa lontano, persa nei propri pensieri.>NEW_LINENEW_LINEOh Durotan, quanto vorrei che tu potessi essere qui. Il tuo popolo ha così disperatamente bisogno di te..."
GS_Gossip[394208365] = "I maestri di cucina si trovano nelle cucine delle locande dell'Alleanza e dell'Orda nei loro rispettivi quartieri."
GS_Gossip[3943417420] = "Durante Hallow's End celebriamo il giorno in cui la Regina delle Banshee ci ha liberati dalle grinfie del Re dei Lich e del Flagello. Assicurati di partecipare al Festival del Wickerman che si tiene ogni sera all'esterno della Sepulcra."
GS_Gossip[3944118696] = "Erboristeria"
GS_Gossip[3944780501] = "Il tuo tentativo di imparare il Draconico è vano, mortale. E perché mai vorresti mai imparare a parlare nella lingua antica? Stranamente confuso..."
GS_Gossip[3945327032] = "Eccezionale! Il grido di morte di Kaz'rogal dovrebbe ispirare terrore nel cuore della Legione Infuocata. Ora sanno del potere delle tue forze, quindi aspettati il peggio che la Legione possa offrire."
GS_Gossip[3945662126] = "Gli uomini e le donne della Rocca dell'Onore hanno versato tanto sangue e hanno perso la loro giovinezza in questo terribile territorio... eppure mantengono ancora alto lo spirito!NEW_LINENEW_LINEOra, tu e i tuoi complici da Azeroth potete aiutarci a cambiare le sorti. Ci date speranza che un giorno possiamo tornare nei nostri paesi natali."
GS_Gossip[3946111971] = "Dicono che io sia benedetto: un annunciatore per udire un nuovo'epoca."
GS_Gossip[394725168] = "Vattene subito, straniero! Non ho affari con te."
GS_Gossip[3947591484] = "Chi è il Re delle ali Ikiss?"
GS_Gossip[3948714084] = "Perché il Flagello ti permette di camminare qua intorno, mon?"
GS_Gossip[3951608125] = "Oh, un sacerdote è così? Beh, se hai bisogno di un po' di addestramento, Maxan è sicuramente da trovare a bere qualcosa nella Distilleria del Tuono."
GS_Gossip[3953072380] = "Un orrore inimmaginabile abita qui, mortale. C'Thun e i suoi adoratori non sono solo un affronto alla natura, la loro esistenza presagisce distruzione per Azeroth come lo conosciamo.NEW_LINENEW_LINEMerithra si è sacrificata mille anni fa insieme a Caelestrasz e Arygos perché sapevano questo. Siamo qui per il nostro giuramento di tornare per loro, ma siamo anche qui perché C'Thun deve essere fermato!"
GS_Gossip[395366583] = "C'è un pescatore all'interno della nostra grande città... se passare del tempo con creature puzzolenti, bagnate e che si agitano è la tua idea di una giornata piacevole."
GS_Gossip[3956177166] = "Ti dirò ciò di cui hai bisogno, ma non devo necessariamente approvarlo. Vi stiamo osservando tu e il tuo tipo."
GS_Gossip[3961457613] = "I funghi crescono sempre in luoghi umidi e per questo assomigliano a ombrelli."
GS_Gossip[3962412934] = "Per favore lasciami alla mia tristezza."
GS_Gossip[3963463214] = "Feyden Darkin si trova al secondo piano al centro della Terrazza degli Artigiani."
GS_Gossip[3963738212] = "Se riesci a completare un mazzo di carte bestie, riceverai in premio una carta oscura più potente del drago blu. Questo è molto utile per il ripristino delle energie magiche."
GS_Gossip[3966287130] = "A ovest."
GS_Gossip[3966879461] = "Cosa c'è da chiedere? È un scimmione, idiota folle. Comunque, sì, la scimmia è andata in estasi dopo aver visto il vecchio Brann schiantarsi sulla sabbia con la faccia in avanti. Niente di ciò che la nottura potesse fare poteva fermare Glibb qui dal pestarle la testa."
GS_Gossip[3968540788] = "Come mago, sei uno di un gruppo selezionato che può evocare un portale per trasportarti indietro in questo stesso posto. Posso insegnarti se sei pronto.NEW_LINENEW_LINEE ricorda che puoi sempre usare il cristallo alle mie spalle per teletrasportarti giù fino alle rovine sotto Dalaran nella Foresta di Cristallo."
GS_Gossip[3973729493] = "Acquista 5 Flaconi Instabili della Bestia al costo di 50 Frammenti Apexis"
GS_Gossip[397599242] = "Teletrasportati a Martello della Luce."
GS_Gossip[3978417043] = "Saluti, YOUR_CLASS.  Cerchi di spingerti ai limiti della tua abilità nel caccia? Non cercare più lontano.NEW_LINENEW_LINEHemet Nesingwary ha radunato l'esplosione più eccellente che il rimanente di questo mondo abbia mai conosciuto. Unisciti a noi per una spedizione se hai il coraggio."
GS_Gossip[3978458972] = "Sono pronto ad essere portato giù nell'Exodar."
GS_Gossip[3979137164] = "Tunnel delle fogne"
GS_Gossip[3979790661] = "Saluti, YOUR_NAME. Sono Myolor Sunderfury, custode della Grande Fucina."
GS_Gossip[3980121271] = "Non possiamo ringraziarti abbastanza per tutto ciò che hai fatto per proteggere la nostra famiglia, YOUR_NAME.NEW_LINENEW_LINEE, tu ti rendi conto che stavamo scherzando prima quando abbiamo offerto di venderti uno dei nostri figli? No, davvero... anche se sentiamo arrivare un paio di altre emicranie.NEW_LINENEW_LINEJunior, stai fermo, per favore?!"
GS_Gossip[3980121585] = "Sono Krathok, supervisore di questi artigiani."
GS_Gossip[3980261226] = "Come osi mettere in dubbio un supervisore del Dragalocca!"
GS_Gossip[3988502630] = "Non riesco a trovare il mio ranocchio, Jubjub. Adora la birra Dark Iron Ale, è l'unica cosa che beve, ma è così difficile da trovare! Ora sono senza... e Jubjub deve aver preso la fuga per cercarne di più!NEW_LINENEW_LINESpero che torni..."
GS_Gossip[3989942210] = "Hai qualcosa di interessante da vendere, Zorbin?"
GS_Gossip[3990135830] = "La celebrazione più grande del Festival Lunare si tiene nel Moonglade. I druidi ti porteranno lì dal Picco del Tuono di Thunder Bluff."
GS_Gossip[3990271844] = "Benvenuti nel villaggio di Fairbreeze. Lunargenta ha quasi rinunciato a noi, ma noi rifiutiamo di andarcene. Questo è la nostra casa."
GS_Gossip[3993216277] = "Non siamo molti rimasti, YOUR_NAME.  Il ritorno del nostro vecchio nemico è motivo di grande preoccupazione."
GS_Gossip[399719836] = "Stai zitto! Non vedi che il maestro sta parlando?"
GS_Gossip[3997362553] = "Ah, desideri allenarti all'estero? Ti indirizzerò. Dimmi qual è l'arma che ti ha interessato."
GS_Gossip[4000688993] = "I commensali dovrebbero mostrare più rispetto!"
GS_Gossip[400236941] = "Poi recati da Bena's Alchemy sulla collina centrale e parla direttamente con Bena. Lei sarà in grado di aiutarti a padroneggiare l'arte dell'allestimento delle pozioni."
GS_Gossip[4002488637] = "I titani non crearono la vita in un solo giorno. Il processo fu graduale e richiese molto esperimenti e iterazioni.NEW_LINENEW_LINEÈ per questo motivo che esistono posti altamente protetti come il Bacino di Sholazar.NEW_LINENEW_LINEPer garantire la sicurezza dei loro siti sperimentali, i titani hanno creato un meccanismo di difesa. La sua forza distruttiva è senza pari tuttavia, e non rivelerei altro a meno che non giuri la tua fedeltà alla mia causa."
GS_Gossip[4003866451] = "Impara i modi del cacciatore. Orgoglio, onore e tradizione."
GS_Gossip[4007367405] = "Grazie, mortale. C'è un solo servizio che posso offrirti prima di tornare nel Sogno.NEW_LINENEW_LINELa porta al maestro di Zevrim, Alzzin, blocca il tuo cammino. Agirò come tuo strumento di distruzione. La porta verrà aperta, aspetto solo il tuo comando."
GS_Gossip[4007819566] = "Permesso di visualizzare i tuoi reagenti e le tue scorte di veleni."
GS_Gossip[4008661347] = "Mille maledizioni su di te, YOUR_RACE!  Questa prigione non mi terrà a lungo!"
GS_Gossip[4009144405] = "Ho perso il mio Tabard del Cavaliere del Sangue."
GS_Gossip[4009639381] = "Noi non siamo d'accordo con i paladini. La signora elfa è venuta in città, sta nel quartiere reale. Lei è un paladino. Tu parli, impari le cose dei paladini."
GS_Gossip[4011262363] = "Macchina del tempo gobbo - Prototipo 01-B"
GS_Gossip[4013540194] = "Sempre vigili nel loro impegno per la protezione del mondo naturale, i druidi sono guidati dall'Arcidruido Fandral Staghelm, che risiede nell'Enclave Cenarion. Lo troverai insieme ad altri addestratori druidi nella sezione settentrionale di Darnassus."
GS_Gossip[4014432282] = "Ascolta attentamente ciò che ti viene detto e non fidarti, o non fidarti troppo velocemente. Perché anche gli amici perseguono i propri fini, YOUR_CLASS.NEW_LINENEW_LINEIl nostro grande Warchief lo sa, e per dimostrare che ci sono stregoni all'interno dell'Orda che non desiderano distruggerla da dentro o prendere il controllo su di essa, ho volontariato per aiutare il nostro giovane leader in ogni modo possibile."
GS_Gossip[4018599171] = "Ciao! Sono appena tornato indietro da un'escursione nelle Rocce di Kel'Theril, a sudovest. Ora intendo investigare i Wildkin che si trovano proprio sopra questa collina, nel folto di Ala d'Uccello.NEW_LINENEW_LINEHai parlato con Erelas Ambersky a Rut'theran Village? Ha richiesto che io venga qui, e forse ha un compito anche per te."
GS_Gossip[4021557] = "Perché non scappi?"
GS_Gossip[402351103] = "Sei il capo adesso, eh? Lunga vita al nuovo re!NEW_LINENEW_LINEKreeg ti fa vedere la bevanda Gordok. La bevanda degli orchi è la migliore tra tutte le bevande, e la bevanda Gordok è la migliore tra tutte le bevande degli orchi! Forse potresti comprarne un po' da me, capo?!"
GS_Gossip[4023637963] = "È bello rivederti, YOUR_NAME."
GS_Gossip[4023857035] = "<Mentre posi i tuoi frammenti di apexis nel fel cristalloforge e tiri la leva, l'apparato emette un suono inumano mentre li macina in polvere. Dopo un momento, le fiale escono dalla sua 'bocca'>"
GS_Gossip[4026472290] = "La cherry pie è il mio cibo preferitissimo in tutto Azeroth."
GS_Gossip[402782039] = "Una donna che sembra una mucca e che sostiene di essere un druido ha allestito un campo all'interno di Lunargenta. Sta sicuramente pascolando sui nostri vasi da coltivazione in questo momento."
GS_Gossip[4029218782] = "Dopo la caduta di Dalaran, mi sono allontanato dal Kirin Tor. Ho trascorso anni a vegliare su Atiesh, solo per vedere il mio scopo all'interno del Kirin Tor strappato via da me in un solo colpo. Troverò la bacchetta, anche se potrebbe volerci una vita intera. È così che sono arrivato a unirmi all'Alba d'Argento e qui sono ora."
GS_Gossip[4033703443] = "Campi d'onore"
GS_Gossip[4035187954] = "Portami indietro nel mio tempo."
GS_Gossip[4036087826] = "L'orso ti guarda calmo e pazientemente, ma non dice nulla."
GS_Gossip[4037942178] = "Dimmi qualcosa sui terreni di addestramento del cacciatore di demoni nei Rovinati di Karabor."
GS_Gossip[4041196499] = "I preti della nostra splendida città possono essere trovati all'interno della Torre del Furore Solare. Cercate la signora Belestra."
GS_Gossip[4041367317] = "Un disordine, ecco cos'è! Tutti questi creature sono apparse dal nulla e stanno correndo fuori controllo! E dove sono finiti il Magister e i suoi allievi? Lasciandomi qui tutto solo senza neanche un \"Ciao Wyllithen, vorresti venire con me?\"NEW_LINENEW_LINEIl coraggio!"
GS_Gossip[4044392361] = "I miei teromoths violenti mi vendicheranno!"
GS_Gossip[4044483112] = "Ameer potrebbe preoccuparsi di ciò che stanno facendo gli Ethereum, ma io sono concentrato sul reale pericolo qui: Dimensius."
GS_Gossip[404484881] = "Il deposito di Forgiardente è il più vicino che troverai in questi paraggi."
GS_Gossip[4048019035] = "Ovviamente. In che altro modo potrebbe infiltrarsi tra di loro e passare per una draenei? Aveva vissuto tra di loro da molto tempo."
GS_Gossip[4049811015] = "Ciao, YOUR_CLASS. Perdonatemi, sto avendo una conversazione con Rimblat. Egli crede che nemmeno questa terra sia irrecuperabile."
GS_Gossip[4056195440] = "Tutte le ricompense per i servizi resi devono essere distribuite da Warcaller Beersnout.NEW_LINENEW_LINEPosta senza bollette."
GS_Gossip[4056315257] = "Dopo alcuni giorni di silenzio, ho inviato una spedizione di esplorazione sulla piattaforma. Non sono mai tornati.NEW_LINENEW_LINEHo inviato un altro gruppo il giorno successivo con gli stessi risultati, e ho perso un paio di macchine volanti durante la ricognizione aerea.NEW_LINENEW_LINEIn quel momento ho mandato qualcuno a sud per cercare aiuto, e ci siamo rintanati per prepararci al peggio. Abbiamo concentrato tutta la nostra attenzione nella produzione di armature, armi e robot in modo da poterci lanciare là fuori con tutta la forza possibile.NEW_LINENEW_LINEQuando l'abbiamo fatto un paio di giorni fa, non credevamo ai nostri occhi!"
GS_Gossip[4068749716] = "Sentite una presenza strana mentre state davanti a questo antico idolo."
GS_Gossip[406949579] = "Archibald per chi stai cercando.  Lui è fuori dal negozio dell'armaio nel anello interno del Quartiere della Guerra."
GS_Gossip[4073257969] = "Settimane private, ho bisogno di un altro travestimento."
GS_Gossip[4073886968] = "Un amico dei Zandalari! Hai osato entrare in profondità nella caverna del Dio del Sangue, YOUR_CLASS. Ascolterai bene ciò che ho da dirti.NEW_LINENEW_LINEMolti millenni fa, mentre i troll indigeni dell'impero di Zul'Aman combattevano gli invasori elfi alti pagani, una grande magia fu rubata da Zanza. Questa magia fu utilizzata dagli elfi alti per incantare le loro armi e armature, per aiutare nella conquista dei troll della regione."
GS_Gossip[4076538001] = "Nope, nobody who can teach ye herbalism out here.  I think ye'll have better luck in Forgiardente though."
GS_Gossip[4084157718] = "Ilyenia Moonfire, la maestra delle armi elfo notturno che risiede sulla Terrazza dei Guerrieri a Darnassus, può insegnarti a usare un arco."
GS_Gossip[4086872794] = "Ci uniamo alla guild? No? Ok, trovi il Maestro della Guild sulla piattaforma a est nel quartiere commerciale."
GS_Gossip[4086955627] = "Posso insegnarti a cucire.  Interessato?"
GS_Gossip[4089050830] = "Chi sono i Creatori?"
GS_Gossip[4090086648] = "Belli animali, non credi? I wyverns che alleviamo qui sono addestrati per gestire le condizioni meteorologiche più selvagge e strane che Draenor ha da offrire. Li troverai affidabili e robusti."
GS_Gossip[409033303] = "Le montagne sono ricche di storia... non dimenticare di fermarti e godertela tutta, YOUR_CLASS."
GS_Gossip[409667450] = "Eseguo lui come perseguito dalle istruzioni del mio signore, e lo faccio in modo tale che soffra dolorosamente prima di morire come rappresaglia per i suoi crimini contro il mio popolo."
GS_Gossip[4097375361] = "Dove si trova la chiave per questa serratura?"
GS_Gossip[4098007240] = "Quali misteri del commercio posso aiutarti a scoprire oggi?"
GS_Gossip[4099230686] = "L'ultima volta che ho sentito, l'Anziano Runetotem stava viaggiando verso Razor Hill, a Durotar."
GS_Gossip[4099332665] = "Siamo pronti a portarti fuori di qui, Thrall. Andiamo!"
GS_Gossip[4100134027] = "Prendi quel teschio e sicuramente farà prendere un bello spavento a Daryl. Non che non lo meriti, quel maledetto arrogante. Ma ah! Non vedo l'ora di vedere l'espressione sul suo viso quando te lo mostri."
GS_Gossip[4103764202] = "Benvenuta, Sorella in Battaglia. Posso aiutarti a recuperare compagni persi."
GS_Gossip[4103854732] = "Le Placche di Uldum sono dischi sintetizzati dai Creatori che permettono l'accesso al complesso di Uldum. Questi dischi contengono e archiviano dati specifici relativi alle attività dei Creatori qui.NEW_LINENEW_LINEFisicamente, sono quasi identici per circonferenza al set di dischi che possiedi attualmente. I loro segni, tuttavia, sono direttamente legati all'informazione su Uldum invece che al complesso di Uldaman."
GS_Gossip[4107341336] = "Costume Orco"
GS_Gossip[4111208622] = "Puoi trovare una casella postale proprio qui accanto al Taverna di Fuoco di Pietra.  Si trova proprio a nord delle porte di Forgiardente."
GS_Gossip[4112840831] = "Banca dei Cartomanti"
GS_Gossip[4114102666] = "Non importa quanto si impara, c'è sempre di più da scoprire."
GS_Gossip[4115360892] = "Benvenuto nell'Evergrove, YOUR_CLASS. Tempo e io abbiamo studiato gli arakkoa di Blade's Edge da un po' di tempo, e abbiamo scoperto alcune differenze allarmanti tra loro e i loro cugini in Terokkar."
GS_Gossip[4116446744] = "Qualsiasi cosa ti serve, Brazie Getz! Te la procuro?NEW_LINENEW_LINEE non sto parlando solo della roba \"legale\". WHATEVER YOU NEED, PAL! Qualsiasi cosa..."
GS_Gossip[4116723787] = "Mentre ispezioni la gabbia e la nottelfa all'interno, provi un curioso senso di déjà vu. Per qualche motivo, lei non ti guarda negli occhi; è quasi come se non fossi presente per lei."
GS_Gossip[4118808919] = "Le tue competenze nell'alchimia non sono ancora sufficienti per trarre vantaggio dalle mie insegnanze. Forse se parlasse con me in un secondo momento..."
GS_Gossip[4119529859] = "Noi Thunderbrew ci prendiamo orgoglio nel sapere che siamo la migliore birrificio in tutti i regni."
GS_Gossip[4123406214] = "Maestro cuoco, puoi addestrarmi nell'arte culinaria?"
GS_Gossip[4125899147] = "Desidero acquistare attrezzatura da pesca."
GS_Gossip[4128588656] = "Bah, è lavoro da goblin! Tuttavia, abbiamo un orco qui a Razor Hill che ti insegnerà queste cose. Cerca Mukdrak vicino alla forgia."
GS_Gossip[4129244916] = "Esiste una casella postale fuori dalla Banca che troverai al centro di Darnassus."
GS_Gossip[4130600220] = "Gahk come piccolo, YOUR_RACE YOUR_NAME.  Yous kill da big demon; make all da little demons scared!NEW_LINENEW_LINE<Le teste di Gahk sorridono entrambe a te.>"
GS_Gossip[4136844108] = "Ah, ospiti del Maestro. Spero che abbiate fatto attenzione a dove mettete i piedi qui dentro."
GS_Gossip[4137920044] = "Ecco qui per un viaggio, YOUR_RACE?NEW_LINENEW_LINEOppure, è qualcos'altro che ti preoccupa?"
GS_Gossip[4138907668] = "Non cercare di teletrasportarti in una delle città dei tuoi nemici. Non funzionerà - potremmo tutti essere amici qui, ma a casa rimangono vecchie rancori..."
GS_Gossip[4140670354] = "Hai veramente sviluppato maggiore astuzia, YOUR_NAME."
GS_Gossip[4141227601] = "Posso insegnarti i punti più raffinati del cavalcare i lupi, purché tu abbia abbastanza oro per coprire la lezione!"
GS_Gossip[4143728252] = "Posso ottenere un passaggio per tornare al livello del suolo, mio signore Afrasastrasz?"
GS_Gossip[4143749375] = "Ahhh, il Centro per Visitatori di Roccavento è allora ciò che stai cercando. È il primo edificio a sinistra mentre cammini attraverso le porte principali provenendo dalla Valle degli Eroi."
GS_Gossip[4144393876] = "Per favore continua, Bodley."
GS_Gossip[4145076593] = "<Metti la mano sull'orbite.>"
GS_Gossip[4147249624] = "Girando il corpo, vedi le cicatrici lasciate da lame e incantesimi sull'orco defunto: l'armatura è quasi distrutta, i capelli incollati al viso.NEW_LINENEW_LINEIn base alla descrizione di Mankrik su di lei, non c'è alcun dubbio nel tuo mente che questa fosse sua moglie.NEW_LINENEW_LINESarà contrariato dalle notizie, ma sei sicuro che debba conoscere la verità."
GS_Gossip[4148951031] = "Questa foresta può essere confondente! Fate attenzione laggiù."
GS_Gossip[4154208400] = "Sacerdote"
GS_Gossip[4155766070] = "Svincola e controlla Flamebringer."
GS_Gossip[4155784076] = "Sei venuto ad allenarti con i guardiani di Theramore?"
GS_Gossip[4158603845] = "Se hai bisogno di addestramento in alchimia, c'è solo un posto a Roccavento in cui devi andare... Alchemy Needs. Lo puoi trovare nel Quartiere dei Magi lungo il bordo esterno dei negozi."
GS_Gossip[4160840252] = "Dove si trova Elder Darkcore?"
GS_Gossip[416154468] = "Siamo felici di fornirti le forniture."
GS_Gossip[416314092] = "Hai la comprensione necessaria per continuare, sciamano? Conosci il motivo per cui sei qui?"
GS_Gossip[4163180834] = "Il Posto di Spinebreaker è un posto perfetto per essere schierati! Le aberrazioni di Bleeding Hollow sono così vicine che si può annusare il loro sangue disgustoso! Che posto migliore per raccogliere vendetta da una razza che ha abbandonato i propri fratelli e ha stretto un patto con i demoni?"
GS_Gossip[4163654936] = "L'Evento"
GS_Gossip[4166120493] = "Questo è il passaggio che le armate di Kael hanno utilizzato per ritirarsi verso la Sunwell. Alcuni dei suoi lacchè rimangono qui; la Legione li ha premiati in un modo... piuttosto insolito."
GS_Gossip[4166224497] = "Non ci pagano abbastanza per questo.  Ma questo villaggio distrutto è sicuramente meglio che nascondersi all'interno di Auchindoun."
GS_Gossip[4166537148] = "Benvenuto tra noi, YOUR_CLASS.  Almeno per il momento."
GS_Gossip[416751637] = "Ma qualcosa è andato storto, non è vero?"
GS_Gossip[4167540761] = "Ho sentito parlare delle tue imprese, YOUR_NAME.  So so che mentre sei qui in terre abbandonate ti comporterai con dignità e come un vero eroe dei sin'dorei!"
GS_Gossip[4167849587] = "Vieni a imparare come si cavalca?"
GS_Gossip[4168928402] = "Saluti, YOUR_CLASS.NEW_LINENEW_LINEL'Alleanza controlla attualmente il Forte di Wintergrasp, ma la prossima battaglia inizierà presto.   Preparatevi a recarvi a Wintergrasp e a supportare le nostre forze!NEW_LINENEW_LINELa battaglia successiva inizia tra $4354k."
GS_Gossip[4169145020] = "Capisco."
GS_Gossip[4170354929] = "Vieni vicino al fuoco e riposati, YOUR_RACE. Spero che non ti dispiaccia l'odore del pesce."
GS_Gossip[4170677372] = "In tempi grigi un druido può essere un caro amico per coloro che lo circondano. Chiedi a qualsiasi druido nell'Enclave Cenarion e ti diranno lo stesso."
GS_Gossip[4171792184] = "Porta dell'ira"
GS_Gossip[4171842860] = "Tu, Flagello, qua non ce la farai, mon."
GS_Gossip[4172836494] = "Saluti, YOUR_CLASS. Hai parlato con Fahrad ancora?"
GS_Gossip[4176341292] = "Benvenuto nel deposito di Steelgrill!"
GS_Gossip[4177117040] = "Il nome del trainer dei Ladri è Marion Call. Puoi trovarla al piano superiore nella stanza da lettura del Gallows' End Tavern, nell'angolo sud-est del paese."
GS_Gossip[4177860227] = "In un tempo e un luogo diversi, sarei stato considerato solo un giovane. Qui invece sono un combattente esperto pronto a vivere e morire per la gloria dei naaru.NEW_LINENEW_LINEDieci di noi siamo entrati nel Manaforge Ara. Tutti gli altri sono caduti alla Legione."
GS_Gossip[417912935] = "Se stai cercando di viaggiare verso il Nordrend, l'icebreaker Northspear parte da qui per raggiungere Valgarde nel Fiordo Echeggiante."
GS_Gossip[4180268853] = "Piacere di rivederti, YOUR_NAME."
GS_Gossip[4181029759] = "Bene, allora sembra che entrambi stiamo cercando Hogral Bakkan. È senz'altro un nano, quindi prima o poi si dirigerà verso la Distilleria del Tuono per una birra -- potrebbe addirittura essere lì adesso."
GS_Gossip[4181592477] = "Maledetti quei blood elf e la loro magia imprudente!"
GS_Gossip[4182743958] = "Romus mi ha informato delle tragedie che colpiscono la mia bella città. Non ci sono parole adatte per esprimere il dolore che ho provato apprendendo la sorte di Lordaeron - e la sorte della mia cara Stromgarde.NEW_LINENEW_LINEVent'anni fa, nessuno aveva sentito parlare della 'Legione Infuocata'... Dannati quei maledetti demoni!NEW_LINESiate rassicurati, YOUR_NAME; se un giorno dovessi tornare ad Azeroth, Stromgarde risorgerà nuovamente come forza di giudizio. Questo giuro..."
GS_Gossip[4184620729] = "Perché non vai tu e Rocknot a cercare un posto privato..."
GS_Gossip[4186084224] = "La casa dei Barov mi tiene davvero occupato. Sempre qualche tipo di rifiuti che escono da lì."
GS_Gossip[4187964261] = "Bene, adesso avrai bisogno di documenti per formare una guild, e Jondor Steelbrow può aiutarti a iniziare con il processo. Lo puoi trovare al Centro per Visitatori di Forgiardente quando sarai pronto a cominciare."
GS_Gossip[4188275747] = "Buongiorno, Hulfdan, sto cercando un addestramento."
GS_Gossip[4189072354] = "Ciao, viaggiatore. Non molti mi trovano qui fuori.NEW_LINENEW_LINEIl mio nome è Rivern, e addestrò i Frostsabers di Winterspring per diventare montature.NEW_LINENEW_LINEQuesti gatti sono i più selvaggi e difficili da domare tra tutti i sabers. Solo i più fidati e esaltati possono tentare di cavalcarne uno.NEW_LINENEW_LINENon venderò mai un simile mezzo a chiunque; no, devi guadartelo e meritare l'accettazione non solo da me, ma anche dai propri compagni di spada."
GS_Gossip[4189396117] = "Throm'ka, YOUR_NAME.  Forra dei Cantaguerra ha bisogno di eroi come te."
GS_Gossip[4189501308] = "Il porto di Roccavento è il modo più rapido per raggiungere Auberdine o il Castello della Valore. Puoi trovarlo tra il Distretto della Cattedrale e il Parco."
GS_Gossip[4194424354] = "Posso insegnarti i punti più raffinati del pilotaggio dei Mechanostrider, purché tu abbia abbastanza oro per coprire la lezione!"
GS_Gossip[4194580654] = "Dobbiamo uccidere più troll! Uccidi abbastanza e ti farò esplodere la porta per raggiungere il capotrollo!"
GS_Gossip[4198896038] = "Pochi duelli si vincono per pura forza. È l'ingegno, i riflessi e la conoscenza della tua arma a decidere la battaglia alla fine."
GS_Gossip[4199202613] = "È una storia piuttosto interessante, signore comandante."
GS_Gossip[4199880988] = "Saluti. Cerchi istruzioni nell'arte della guerra?"
GS_Gossip[420080979] = "Allora ti consiglio di sederti, questa sarà lunga.NEW_LINENEW_LINEQuando siamo arrivati inizialmente a Silithus, la Signora Mar'alith è stata la prima delle nelfe notturne del Cenarion Hold a unirsi all'esploarazione. La nostra routine non era niente di straordinario: formare un gruppo per avventurarsi all'interno delle varie api e cercare oggetti perduti."
GS_Gossip[4201552478] = "Gli ingegneri spesso si addestrano a Like Clockwork nell'Esposizione Commerciale dei Magi, nel nord-ovest di Dalaran."
GS_Gossip[4202144087] = "Sei qui per imparare a pescare, mon? Oppure forse per comprare qualcosa per farlo?"
GS_Gossip[420729502] = "Sarebbe poco saggio assumere che combattere un valoroso sia un compito semplice. Sei sicuro di essere pronto?"
GS_Gossip[4207428824] = "La Grande Madre ci ha tutti allevati. Qualsiasi Mag'hari che vedrai ha avuto la sua vita toccata in qualche modo speciale dalla Grande Madre. La perseguiremo molto quando passerà."
GS_Gossip[4210797034] = "La verità è che non ho mai gradito quel gnomo..."
GS_Gossip[4211150435] = "Vedi la caduta del Re dei Lich."
GS_Gossip[4212023190] = "Devi trovare uno tra i miseri nella parte inferiore di questa fortezza che ha ottenuto un Sigillo Immacolato dell'Ascensione. È un grande onore per un essere inferiore ottenere questo oggetto, poiché rappresenta il primo passo per accedere alla parte superiore della fortezza e diventare uno dei guardie di élite di Nefarian - la legione Blackhand. Trova un tale oggetto e restituirlo a me affinché possa esaminare le sue proprietà. Conoscerò come procedere una volta completata l'ispezione del sigillo."
GS_Gossip[4221113120] = "Sì, l'ho controllato, mi manca il pezzo a sinistra!"
GS_Gossip[4221710589] = "I... Io sono gravemente ferito... "
GS_Gossip[4223083056] = "Per vincere questa guerra, non possiamo rimanere inerti e permettere alle maree di travolgerci. Dobbiamo colpire, con forza e rapidità, altrimenti Arathi non sarà mai più nostra."
GS_Gossip[4228355902] = "Troverai ciò che cerchi a One More Glass nel nord di Dalaran."
GS_Gossip[4229884998] = "Cercherò per tutto il mondo questo plasmatore terrestre. E l'essenza?"
GS_Gossip[4234387029] = "Posso insegnarti i punti più raffinati del cavalcare i Kodo, purché tu abbia abbastanza oro per coprire la lezione!"
GS_Gossip[4235464727] = "Che?! Come hai fatto a passare indisturbato davanti alla mia prigione...intendo, mio servo là fuori? Be', suppongo che sia per il meglio. Le vendite sono state un po' lente di recente.NEW_LINENEW_LINECome posso soddisfare i tuoi bisogni infernali, YOUR_CLASS?"
GS_Gossip[4236100346] = "Arakkoa invisibili... sono dappertutto... ci stanno osservando... aspettando!"
GS_Gossip[4238716201] = "Non ho molto tempo per parlare a meno che non sia urgente, cittadino. Le porte di Theramore sono la mia maggiore responsabilità."
GS_Gossip[4239299254] = "Dove si trova Elder Starsong?"
GS_Gossip[4241790776] = "I guerrieri si trovano nel Quartiere della Guerra, ad allenarsi sulla ringhiera esterna."
GS_Gossip[4242603873] = "Ahh, dovrai recarti quindi alla Hall del Cacciatore. Su Hunter Rise puoi trovare diversi grandi cacciatori, come Holt Thunderhorn."
GS_Gossip[4243200890] = "Qualsiasi amico degli animali è un amico mio. La Hall dei Cacciatori è ciò che cerchi. Si trova in cima alla Collina dei Cacciatori."
GS_Gossip[4248835639] = "Stai zitto! Non posso permettermi di perdere nemmeno un momento di questa lezione!"
GS_Gossip[424914422] = "Sono pronto a lavorare per te oggi! Dammi quel ramo!"
GS_Gossip[4254797320] = "Magia antica si agita nelle profondità dell'occhio. Ti dà un senso di vertigine, come se potessi accidentalmente cadere nell'iride e precipitare per sempre."
GS_Gossip[4255828385] = "Non cercare di imporre la tua volontà al cuoio. Piuttosto, lascia che le sue tendenze naturali determinino la forma e la funzione che assumerà. Questo non è una battaglia da vincere. Lavora con il cuoio, non contro di esso."
GS_Gossip[4256421042] = "Cibo & Bevande"
GS_Gossip[4258968362] = "Allora, qual è il tuo scopo?"
GS_Gossip[4262960533] = "Rastrello per spade in schiuma"
GS_Gossip[4263077688] = "Monumento a Antonidas"
GS_Gossip[4263113121] = "Vuoi dire che non puoi odorare il fumo dei forni Elvini da qui? Bene, cercherai Therum Deepforge se vuoi imparare l'arte della forgiatura. È nel Distretto Elvino, che si trova a nord della Piazza della Cattedrale."
GS_Gossip[4263796727] = "Ho la chiave per terre libere! Se mi inseguite, vedrete!"
GS_Gossip[4266872476] = "Se sei venuto alla ricerca dell'artigianato più raffinato su questo o qualsiasi altro continente del mondo, allora sei nel posto giusto!NEW_LINENEW_LINEGrimand Elmore, a vostra disposizione!"
GS_Gossip[4266897522] = "Fevere della giungla"
GS_Gossip[4269201515] = "Maestro della Corporazione & Venditore"
GS_Gossip[4269622915] = "<Mudlump sta lucidando i suoi stivali.>"
GS_Gossip[4270118047] = "Lo farò, Tirion."
GS_Gossip[4272077476] = "Ho perso i Colori del Maestro delle Leggende."
GS_Gossip[4272702178] = "Ogni frammento utilizzato ci rende meno spreconi e ci avvicina alla Madre Terra. Mooranta può mostrarti la via. Cercala appena fuori dagli Armigeri del Picco del Tuono, sulla collina centrale."
GS_Gossip[4272713659] = "È un attestato della tenacia del nostro popolo che il villaggio di Fairbreeze resista ancora. Non cederemo mai più la vittoria al Flagello."
GS_Gossip[4272876449] = "Non sembri in forma, sorvegliante."
GS_Gossip[4276263434] = "Sono Tinkmaster Overspark, e sono l'architetto capo dei principi moderni dell'ingegneria gnomica nel mondo di oggi. È il mio compito assicurare che il potere dell'invenzione continui a brillare più intensamente dai nostri arclight spanners che da qualsiasi altro posto!NEW_LINENEW_LINEInoltre, se per caso conosci uno schema efficace per eliminare la radiazione, proprio in questo momento siamo alla ricerca di uno simile..."
GS_Gossip[4279699965] = "È tempo di riposo, tesoro, o forse qualcosa da mangiare e un po' di relax?NEW_LINENEW_LINEBeh, se qualcuno lo merita, sei tu!"
GS_Gossip[4281086850] = "Sono un ufficiale della città, che lavora nel ruolo del censimento della Sepulcra.  Da quando siamo stati liberati dal Flagello, abbiamo cercato di tenere un registro accurato della popolazione della nostra città.  Attraverso metodi arcani e una disciplina mentale affilata, sono in grado di accedere a questi registri.  Se hai affari da trattare con me, procedi pure.  Dovresti sapere se è così, comunque."
GS_Gossip[4283419882] = "Gul'dan è la mia risposta."
GS_Gossip[428418720] = "Sayoc e Hanashi, maestri d'arma di Orgrimmar, sono veri artigiani delle armi da lancio. Li si trova ad addestrare studenti disposti nella Valle dell'Onore. Per quanto riguarda la pura maestria nell'arte, però, Ileda del quartiere Farstrider di Lunargenta non ha rivali."
GS_Gossip[4285546344] = "Devo trovare Moodle, hai il suo pallino da stress?"
GS_Gossip[4286937386] = "Tante sono le vie della Luce, YOUR_CLASS.  Devi decidere quale seguire in questo mondo, o in qualsiasi altro."
GS_Gossip[4287347393] = "Come ho detto, il cifrario è stato trovato da Illidan quando ha preso il controllo del Tempio Nero. L'ha diviso in tre parti e ha affidato la loro custodia ai suoi sottoposti.NEW_LINENEW_LINEI miei ragazzi... I miei ragazzi sono cresciuti ora. Quando ho saputo di ciò che Illidan aveva fatto con il cifrario, ho mandato i miei ragazzi a recuperare i pezzi.NEW_LINENEW_LINEDevi trovare i miei ragazzi, YOUR_NAME. Devi trovarli e recuperare il Codice dell'Inferno."
GS_Gossip[4290490098] = "La bellezza naturale di queste colline nasconde un grande oscuro. Cammina con cautela, amico."
GS_Gossip[4291614340] = "Sei un cacciatore? Be', comunque, troverai Thotar nascosto dal sole all'interno della tana nell'angolo sud-occidentale del paese."
GS_Gossip[4293047216] = "Il suolo di questo posto è ancora caldo dal sangue appena versato. Ah, avrei dato volentieri il mio stesso occhio per essere qui quando i demoni hanno stracciato quel portale e si sono scontrati con gli eroi di Azeroth! Che battaglia fu!NEW_LINENEW_LINEMa ora, combattimenti ancora più feroce infuriando dall'altra parte!"
GS_Gossip[4294609290] = "Ummm... la rana dice che sei un traditore, \"compagno.\""
GS_Gossip[4294940624] = "Saluti, YOUR_NAME. Sono Durkot Wolfbrother, protettore del branco."
GS_Gossip[4358560] = "Il mio nome ti suona familiare? Forse ci siamo conosciuti molto tempo fa...NEW_LINENEW_LINEPenso che mi abbiano dato il nome di qualcuno importante..."
GS_Gossip[437097954] = "<La nonna Geyah annuisce.>NEW_LINENEW_LINELo sai che mio figlio?"
GS_Gossip[439019387] = "Il santuario finale dei fanatici pazzi. 'Tis dove creano i loro uniformi scarlatti, magicamente infusi con il filo scarlatto incantato!NEW_LINENEW_LINEA Stratholme, avventuriero!"
GS_Gossip[439182878] = "<Prendi il controllo di un Guardiano Eidolon attraverso l'occhio.>"
GS_Gossip[441812235] = "Hai già sconfitto uno dei nostri cavalieri oggi, quindi non posso accettare la tua sfida."
GS_Gossip[442554759] = "Ho perso la chiave per il Castello Viola."
GS_Gossip[443215866] = "Hai raggiunto un fuoco sacro dell'Orda! Profanalo e spegnilo!"
GS_Gossip[444954945] = "Se vuoi accedere al mercato qui, vai al anello centrale della città."
GS_Gossip[446329353] = "Ora è il nostro momento! Lasciami fuori da questa gabbia!"
GS_Gossip[447228374] = "La Orda mi concederà la possibilità di combattere il Flagello?"
GS_Gossip[447677312] = "Il zeppelino dovrebbe appena essere partito da Sepulcra."
GS_Gossip[448254959] = "Ho perso il mio trasmettitore e ne ho bisogno di un altro, Scooty."
GS_Gossip[449486532] = "Dai un'occhiata intorno e fammi sapere se c'è qualcosa che ti interessa."
GS_Gossip[450051446] = "L'oste Kauth può soddisfare i tuoi bisogni. Può essere trovato sul lato ovest del villaggio in una delle lunghe case."
GS_Gossip[455713818] = "Kil'jaeden è la mia risposta."
GS_Gossip[457309707] = "Perché tutti continuano a dire che l'ULTIMA cosa di cui abbiamo bisogno i gnomi è più zucchero?!"
GS_Gossip[457596151] = "Quello è stato un impressionante spettacolo.  Ma sei pronto per la tua prossima sfida?"
GS_Gossip[458367307] = "Chi sei? Cosa vuoi qui?"
GS_Gossip[461504361] = "Cerchi un passaggio da qualche parte, YOUR_NAME?  I miei pipistrelli ti porteranno lì in un batter d'occhio."
GS_Gossip[466963489] = "Tarren Mill."
GS_Gossip[469664264] = "Non vedo lo spirito del guerriero dentro di te, figlio. Non ho insegnamenti che potrebbero beneficiare un YOUR_CLASS come te."
GS_Gossip[471504000] = "Plucky non vuole che Tirth sappia che è ancora nei Pianori Luccicanti, quindi si è trasformato in un pollo!NEW_LINENEW_LINESe trovi Plucky, richiamalo. Forse uscirà dal nascondiglio."
GS_Gossip[472147089] = "Oh... uno di quei tipi. Bene, Maximillian è l'unico intorno qui che sa qualcosa delle arti oscure. Probabilmente puoi trovarlo nell'oscurità del seminterrato dell'Inn del Orgoglio del Leone."
GS_Gossip[473206734] = "Acquista 5 Pozioni Instabili dell'Incantatore al costo di 50 Schegge di Apexis."
GS_Gossip[476342295] = "Voglio volare in una vecchia località!"
GS_Gossip[477987446] = "Ho paura che ormai non sia più gentile o umile. L'età e le battaglie infinite hanno indurito la mia pelle e l'anima. Forse per questo Cairne mi ha assegnato al Sun Rock Retreat... il dolce vento e il caldo sole alleviano un poco il dolore."
GS_Gossip[481200511] = "Throm'ka, YOUR_CLASS. Questo terreno distrutto è ciò che ti aspettavi di vedere? Non assomiglia per niente alle storie che mi hanno raccontato. È difficile credere che il mio popolo abbia mai prosperato in questo luogo desolato."
GS_Gossip[481953492] = "Salve, amico! Ti interessano alcuni condensatori ectoplasmatici? Oppure forse un bel assimilatore spettrale omni-direzionale? "
GS_Gossip[484174567] = "Cerchi i cacciatori? Li troverai al secondo piano del Trader's Tier, nel Santuario dei Cacciatori."
GS_Gossip[488462919] = "I druidi Cenarion siamo i guardiani del bilancio della natura.  Il punto principale è il bilancio.  Quando siamo chiamati in causa, non dovremmo aspettare troppo a lungo prima di prendere un'azione decisiva.  Non lasciare che nessuno ti dica il contrario, soprattutto coloro tra noi che vorrebbero solo osservare!"
GS_Gossip[494350304] = "Vorrà imparare da Zamja.  Dirigiti verso il Fuoco di Borstan sul piano superiore di The Drag prendendo le scale a sinistra mentre entravi dalla Valle della Forza."
GS_Gossip[494585270] = "Alanna passa gran parte della sua giornata nel Glade dell'Oracolo, dove pratica la sua professione. Se desideri imparare la professione dell'Incantatore, dovrai andarci per trovarla."
GS_Gossip[495141458] = "Aye, aveva fatto ciò che si riteneva impossibile. Dalla fessura emerse un agente di Therazane!NEW_LINENEW_LINEDalla mia posizione, ho visto il goblin che aveva una conversazione con l'agente dell'Old God. Cosa è successa dopo è stata terribile..."
GS_Gossip[49805021] = "Siamo gli ultimi della razza furbolg... La tribù Timbermaw rimane incontaminata, tuttavia dobbiamo affrontare la stessa ostilità degli stranieri; la maggior parte crede che non sia possibile... che potrebbero realmente esistere furbolg che hanno evitato la corruzione...NEW_LINENEW_LINEArrabbiato con coloro che si sforzano di creare nemici troppo in fretta, i miei fratelli ora attaccano chiunque si avvicini; non fidano in nessuno.NEW_LINENEW_LINEMa forse, se ti sforzi di rendere la tua presenza pacifica con loro, potrebbero vederti come un alleato."
GS_Gossip[503091489] = "I pesci delle acque costiere di Teldrassil sono molto grandi e robusti. Si dice che la causa sia la rapida crescita del nostro nuovo albero del mondo."
GS_Gossip[506105987] = "Grazie a te, ora possiamo scoprire i segreti dei cristalli e dei misteriosi pali di sostegno, YOUR_NAME. Se hai bisogno di ulteriori informazioni in qualsiasi momento, torna a visitarmi nuovamente!"
GS_Gossip[506692069] = "Ehi amico. Se hai bisogno di qualcosa, fai sapere."
GS_Gossip[507454213] = "Se desideri formare una compagnia, devi rivolgerti al maestro della corporazione, Lysheana. La troverai sulla Terrazza degli Artigiani, nella sezione nord-est di Darnassus."
GS_Gossip[511612793] = "Gelman Stonehand sarebbe la persona a cui parlare. Penso che abbia una casa là nel Distretto Elvico, ma non riesco a ricordare esattamente. Ti consiglio di andare a controllare da quelle parti."
GS_Gossip[512237985] = "Hai bisogno di essere esaltato con gli umani di Roccavento prima che io ti insegni una skill di cavalcatura, YOUR_CLASS."
GS_Gossip[5166498] = "Montatura X-51, Razzo Nether."
GS_Gossip[517497251] = "Hai impressionato tutti qui oggi con le tue abilità nell'arena. È ora il momento di essere riconosciuto davanti a tutti come campione del torneo."
GS_Gossip[518740654] = "Mi dispiace YOUR_CLASS, ma devi essere più esperto prima di poter sopravvivere nella Valle d'Alterac."
GS_Gossip[518865380] = "Quando ho strisciato fuori dalla tomba, pensavo che la mia famiglia mi avrebbe accolto con braccia aperte. Invece, mi hanno cacciato dal villaggio, urlando in una lingua che non riuscivo più a comprendere."
GS_Gossip[523446614] = "Sei pronto a combattere per l'Alleanza, YOUR_CLASS?"
GS_Gossip[525811885] = "Per la maestria nell'arcano, non devi cercare oltre Semid. Egli insegna nel lato orientale di Azure Watch insieme a Ruada."
GS_Gossip[526857173] = "Lasciami uscire da qui, YOUR_RACE!"
GS_Gossip[529311870] = "Val'kyr? Siamo pronti per loro."
GS_Gossip[531435352] = "L'ammiraglio Keller mi ha mandato, Emilune. Per favore, mandami al Castello di Westguard!"
GS_Gossip[531783378] = "Ho bisogno di alcuni reagenti e veleni, signora."
GS_Gossip[532410112] = "Potrebbero essere i sabotatori nottugli a essere dietro a questo? Dubito. Con il carico che abbiamo messo sul West Sanctum era solo una questione di tempo prima che qualcosa andasse storto."
GS_Gossip[534932874] = "Vorrei andare al campo di battaglia."
GS_Gossip[535890710] = "C'è una persona saggia nel villaggio che si chiama Narm Skychaser. Può proseguire il tuo apprendimento sulla via del Cielo."
GS_Gossip[537237394] = "Benvenuto a Caer Darrow, straniero."
GS_Gossip[537360826] = "C'è un solo Capo Guerra, Eitrigg!"
GS_Gossip[539658095] = "Ora che la guerra è in pieno svolgimento, non abbiamo avuto carenza di combattenti in grado di combattere provenienti dall'Orda e dall'Alleanza.NEW_LINENEW_LINESe solo potessimo tenerli lontani l'uno dall'altro..."
GS_Gossip[5397259] = "Capitolo sul Fluido di Immersione di Frostwhisper."
GS_Gossip[546225860] = "Siamo tutti qui per motivi diversi, YOUR_CLASS.NEW_LINENEW_LINE<Rayne sorride.>NEW_LINENEW_LINESono qui per incontrare Rimblat del Circolo della Terra. Ha alcune interessanti teorie sulla purificazione di queste terre."
GS_Gossip[546278648] = "Il Twisting Nether è formato come una ciambella? E cos'è esattamente un Nether? La matrona degli orfani mi ha detto che non dovevo chiedere alle persone riguardo ai loro nethers."
GS_Gossip[546863630] = "Di che cosa sei lo spirito, spirito?"
GS_Gossip[547617395] = "Fleshling, io sono il Capitano Saeed della Protettoria e questi soldati che stanno accanto a me sono i miei vendicatori. Attendiamo gli ordini dal fleshling che ha distrutto il condotto del vuoto. Su quelle parole del fleshling, ci recheremo nella tana di Dimensius e aspetteremo il momento per lanciare l'attacco finale!NEW_LINENEW_LINETroppo a lungo è stato... Il signore del vuoto presto affronterà la nostra potenza combinata!"
GS_Gossip[548886626] = "Purtroppo non abbiamo qui a Bloodhoof Village nessuno che insegna la Sartoria, ma puoi trovare un allenatore a Picco del Tuono. Segui il sentiero verso nord uscendo dal villaggio finché non arrivi a un insieme di ascensori. Prendine uno fino in cima all'altura e chiedi a uno dei Bluffwatchers presenti le indicazioni."
GS_Gossip[549745933] = "Vieni fuori dalla cenere e dalla fanghiglia. Asciugati per un momento."
GS_Gossip[550025793] = "Per grazia di Elune, sono lieto di offrirti il miglior cavallo che si possa trovare in tutto Teldrassil, e forse nel mondo intero - il nightsaber. Per anni, l'Esercito dei Guardiani ha contato sul valore di questi compagni.NEW_LINENEW_LINEPrendi tutto il tempo che ti serve, amico, e esamina ciascuno a tuo piacimento. Sono sicuro che non sarai deluso."
GS_Gossip[551255690] = "Ahoy! Stai cercando di prenotare un passaggio a bordo della Sister Mercy, matey? Hai trovato il posto giusto..."
GS_Gossip[551767014] = "Bah! Mi sembro una persona che ha tempo per chiacchiere inutili?NEW_LINENEW_LINELo faccio?NEW_LINENEW_LINESbrigati con i tuoi affari. Ci sono orchi da uccidere!"
GS_Gossip[552683874] = "Ti prendi gioco di me mentre non sono in grado di difendermi, legato a questa palla di ferro?"
GS_Gossip[553060268] = "Anni di tecniche di allevamento di qualità e molto amore mi permettono il privilegio di mostrarvi questi cavalli! Per favore, prendetevi tutto il tempo necessario mentre li considerate come vostra montatura. Un cavallo è un compagno per tutta la vita, amico. Non svalutatevi - ottenete il vostro destriero qui oggi!"
GS_Gossip[554865222] = "Per favore continua..."
GS_Gossip[555306544] = "I... morto.NEW_LINENEW_LINEPerché sono ancora qui? Non c'è alcun grande campo di caccia a cui ascendere?NEW_LINENEW_LINENo... Devo prima completare il mio compito. Prima che io possa lasciare questo mondo, deve essere recuperata la seconda parte del Codice dell'Inferno."
GS_Gossip[555470942] = "Elder Nightwind trascorre i giorni al santuario di Jaedenar in Felwood."
GS_Gossip[555999385] = "No, no, per favore continua... è solo che l'aria qui sopra è così, uh, fumosa."
GS_Gossip[557669241] = "Me want Gug fix armor. Maybe me buy someting."
GS_Gossip[558895517] = "Sono Achelus, ufficiale capo delle spedizioni di Blood Watch."
GS_Gossip[566051632] = "Se riesci a completare un mazzo di carte delle Furie, riceverai in premio una carta oscura di vendetta più potente.   Mentre brandisci questa carta, chiunque ti colpisce ha la possibilità di subire una vendetta sacra."
GS_Gossip[569003245] = "Nessuno è altrettanto abile nell'uso delle armi quanto Ansekhwa. Si dice che sia guidato dagli spiriti dei migliori guerrieri dei nostri antenati onorati. Cercalo sulla collina bassa e ti insegnerà ciò che desideri sapere."
GS_Gossip[57057560] = "Non così veloce, YOUR_RACE!NEW_LINENEW_LINESolo i campioni di Forgiardente possono acquistare ciò che ho da offrire."
GS_Gossip[570898645] = "Parlami dei Figli di Lothar."
GS_Gossip[57100828] = "No, no... Non avevo intenzione di tradire il vostro popolo. Stavo solo difendendomi. È stato tutto un malinteso."
GS_Gossip[572544705] = "La Crociata Scarlatta servirà un nuovo padrone - nella morte..."
GS_Gossip[573615110] = "Buongiorno, YOUR_CLASS. Se desideri imparare l'arte dell'armaiolo, sei nel posto giusto."
GS_Gossip[575007210] = "Malygos è la mia risposta."
GS_Gossip[58156897] = "Il tessuto di cui è intessuto il nostro mondo è estremamente delicato. Basta un po' di conoscenza e l'applicazione di tale conoscenza per strappare il tessuto. È così che nascono le lacerazioni."
GS_Gossip[581576534] = "Ricorda solo che, YOUR_NAME, è nell'interesse nostro che tu faccia il possibile per questi... queste persone."
GS_Gossip[584374444] = "Va bene allora...NEW_LINENEW_LINESei stato incaricato dal tuo signore di proteggere i suoi campi di mais dai bracconieri e dai ladri. Una notte, durante la tua pattuglia, ti imbatti in un uomo afflitto, vestito con abiti lisi, che sta rubando mais dal campo. Ti avvicini rapidamente a lui, e lui subito implora per la sua vita. Afferma di rubare il mais per nutrire la sua famiglia, poiché il signore del territorio - il tuo signore - pretende troppi tributi. Il tuo signore è infatti noto per le sue pesanti tasse in tutto il regno.NEW_LINENEW_LINEFai la tua scelta."
GS_Gossip[589264568] = "Bene... Allora devi costruire un galleggiante di arcanite e posarlo nell'oceano. Il mio pesce gatto sarà attratto dalle emanazioni magiche. Quando si avvicinerà al galleggiante - BLAMO! Si esploderà in un glorioso impulso di energia arcanica, rivelando la vera forma del pesce gatto. Inoltre, potresti o non potresti incorrere nell'ira di Neptulon. A 50/50 probabilità direi."
GS_Gossip[595071040] = "Possiamo avere un tuorlo invecchiato?"
GS_Gossip[596331563] = "Sto bene, grazie. Mi hai cercato?"
GS_Gossip[599175105] = "Non pensare nemmeno per un secondo che i tuoi precedenti successi ti diano diritto a qualcosa, YOUR_NAME.  Non lo fanno.NEW_LINENEW_LINESe vuoi il mio rispetto, dovrai guadagnartelo. Questo significa seguire i miei ordini senza fare domande e adempiere a loro... senza eccezioni."
GS_Gossip[603091587] = "Dis be horrible, mon. I cannot bear to be watchin'."
GS_Gossip[604425891] = "Non ho tempo da perdere con uno come teYOUR_CLASS."
GS_Gossip[605142139] = "Gli avventurieri possono ricevere premi per i loro atti giusti nel Silver Enclave o nel Sunreaver's Sanctuary."
GS_Gossip[605811152] = "Se i nostri nemici vedessero che desideriamo solo vivere in armonia con loro, forse non dovremmo attaccarli per la nostra stessa sopravvivenza?"
GS_Gossip[611043709] = "Bena lavora come una posseduta. Giorno e notte l'ho vista chinata su queste pozioni, spesso priva di sonno o cibo. So che i nostri alleati non morti hanno bisogno di aiuto, ma comincio a temere che possa farsi del male."
GS_Gossip[616479694] = "Cosa è necessario per la pentola a Gahrron's Withering?"
GS_Gossip[617391071] = "Non credo che possiamo permetterci di perdere l'occasione di guadagnarci la simpatia della flotta rossa. Con le battaglie che ci aspettano, avere loro come alleati sarebbe di inestimabile valore."
GS_Gossip[618816346] = "Stregoni... non ho alcun rispetto per loro.  Come quel Grimrizz che ha aperto bottega fuori dalla Distilleria del Tuono. La birra probabilmente si ammacherà a causa sua!  Stregoni... bah!"
GS_Gossip[619305837] = "Questo pilota di ricognizione non ha sopravvissuto all'incidente del suo squadrone."
GS_Gossip[619338704] = "I ladri si trovano nel Quartiere dei Ladri. Semplice come questo. Cercali sulla ringhiera esterna."
GS_Gossip[623796746] = "Mhrrumph rummrhum phurr!"
GS_Gossip[627116932] = "Dovrai cercare nel Sepulcra. Nei vecchi Rovini di Lordaeron, a sud di qui, troverai un ascensore che porta giù. Una volta lì, chiedi a un Guardiano del Sepulcra per ulteriori indicazioni."
GS_Gossip[632115084] = "Benvenuto nel Stormspire, YOUR_CLASS.NEW_LINENEW_LINEPer favore, non farmi caso per il fatto che io sia presente attraverso questo dispositivo di imaging. Ho molti nemici che vorrebbero vedermi morto, quindi è solo una precauzione.NEW_LINENEW_LINEVi assicuro che qui siete perfettamente al sicuro."
GS_Gossip[636183168] = "Queste catene che mi legano mi impediscono di portare lo spirito del fuoco al mio popolo, YOUR_NAME.  Anime senza fuoco sono anime che non possono ribellarsi ai loro padroni."
GS_Gossip[636452915] = "Un ladro? Hmmm... be', ho sentito dire che Keryn Sylvius frequenta quei tipi sospetti. Potresti voler parlare con lei e vedere cosa puoi imparare."
GS_Gossip[646903861] = "Non dimenticheremo mai il tuo coraggio, YOUR_NAME. Sei sempre benvenuto a Wintergarde.NEW_LINENEW_LINEVuoi rendere questa locanda la tua casa?"
GS_Gossip[648335845] = "Saluti, YOUR_RACE. I tuoi nobili gesti vengono riconosciuti. Che Elune ti protegga."
GS_Gossip[649511883] = "Porti notizie di battaglia, YOUR_RACE?"
GS_Gossip[649702269] = "I tempi in cui viviamo sono altrettanto incostanti del vento che cambia, YOUR_CLASS. Il terreno stesso trema e grida d'agonia. Dobbiamo rimanere risoluti, altrimenti anche noi saremo inghiottiti dal caos."
GS_Gossip[659408361] = "La Città Violetta"
GS_Gossip[660708242] = "Hmm... Penso che quest'anno il Suntouched Special non sia poi così speciale. Non sarei d'accordo, YOUR_NAME?"
GS_Gossip[665133290] = "Dobbiamo sbrigarci, YOUR_NAME. I piani distruttivi di Malygos presto saranno irrimediabili."
GS_Gossip[667290736] = "Puoi imparare a cucire a Orgrimmar. È a nord. Forse uno dei soldati di Orgrimmar può aiutarti."
GS_Gossip[667491453] = "Se Hydraxis recluta di più nella sua guerra, potrebbe spostare il rapporto di potere..."
GS_Gossip[668217558] = "Insegnante di armi"
GS_Gossip[668830322] = "Mio signore, ho bisogno di arrivare in cima al tempio."
GS_Gossip[673293185] = "Ciao! Sei abbastanza forte e carino e roba del genere. Mi piaci. Restiamo amici, va bene?"
GS_Gossip[673489978] = "È a noi che spetta fare la prima mossa. Non possiamo permettere che si ripetano gli errori del passato..."
GS_Gossip[674599163] = "Non si può mai essere troppo preparati."
GS_Gossip[678011283] = "Con il tuo aiuto, potremmo essere in grado di vincere questa cosa!"
GS_Gossip[680408653] = "L'esperto di armi dei Forsaken Archibald conosce bene l'uso delle armi a lunga asta. Si addestra altre persone nel quartiere della guerra della Sepulcra. Ileda, l'esperta di armi elfo del sangue all'interno del Farstrider Square a Lunargenta, può insegnarti anche le tecniche corrette."
GS_Gossip[680654330] = "Lasciami andare... Ti prego..."
GS_Gossip[680735226] = "È arrivato il momento che Orda e Alleanza si volgano verso Nordrend e l'invasione del Re dei Lich. Nei giorni recenti, territori in tutto Kalimdor e i Regni dell'Est sono stati attaccati. Prenderai le armi per salvare la tua terra dalla distruzione nelle loro mani?"
GS_Gossip[680754246] = "Mai guardare questi Dannati direttamente negli occhi. Penso che possano succhiare l'anima direttamente da te se ne hanno voglia!"
GS_Gossip[680877423] = "Vieni e ti mostrerò come cavalcare gli animali più belli che tu abbia mai visto. Tu... credo che tu abbia abbastanza oro per coprire i costi, no?"
GS_Gossip[68164314] = "Sì, sono uno dei \"Rotti\". Spero che questo non vi disturbi? Che siate Rotti o Draenei, dobbiamo sopportare le derisioni che alcuni nella nostra società potrebbero rivolgerci. Una migliore comprensione e comunicazione con gli elementi di questo mondo è tutto ciò che conta."
GS_Gossip[681693357] = "La Dea mi ha concesso la saggezza, straniero. Se è la sua volontà, la passerò a te."
GS_Gossip[683503107] = "Vuoi imparare a usare un nuovo arma? Trova Sayoc e Hanashi all'interno di Arms of Legend nella Valle dell'Onore."
GS_Gossip[689665611] = "Se sei interessato a conoscere maggiori informazioni sulla tradizionale festa del Ringraziamento del Pellegrino, parla con una delle ospiti."
GS_Gossip[689829630] = "Sono nato qui, YOUR_RACE. Questo è il mio mondo - tutto ciò che conosco... Da ragazzo, mia madre e mio padre mi raccontavano storie del vostro mondo e della sua magnificenza. Quanto desideravo lasciare questo posto.NEW_LINENEW_LINEAhimè, la sorte è una crudele padrona. I miei genitori sono da tempo morti, sepolti in questo stesso cimitero. Rimango per onorare il loro nome e l'onore della mia famiglia - i Figli di Lothar."
GS_Gossip[691719549] = "Benvenuto a Thelsamar, la tua casa lontano da casa a Loch Modan!NEW_LINENEW_LINEThelsamar è un posto bello, ma non è tutto birra e carne salata per coloro che rispondono al richiamo del dovere! Se sei disposto a fronteggiare il pericolo nel nome dell'Alleanza, allora leggi il manifesto fuori dalla sede di Thelsamar dell'Esploratori's League."
GS_Gossip[692078208] = "Dove si trova il Lupoazzurro anziano?"
GS_Gossip[693380423] = "Il volo da Grom'gol a Sepulcra è bellissimo, anche se privo di eventi.  Tuttavia, questo non è una scusa per addormentarsi nel lavoro."
GS_Gossip[69467436] = "Gli strumenti a due mani sono insegnati sia da Woo Ping, il maestro che si trova a Weller's Arsenal a Roccavento, sia da Ilyenia Moonfire, che addestra gli elfi della notte sulla Warrior's Terrace a Darnassus."
GS_Gossip[694711290] = "Questi sono tempi pericolosi, YOUR_RACE.  Un antico male sta risorgendo, e non ha alcuna cura se sei dell'Orda o dell'Alleanza."
GS_Gossip[69888089] = "Noblegarden è il momento in cui i druidi di Azeroth celebrano il ritorno alla vita. Le uova sono un simbolo di fertilità e un ottimo modo per coinvolgere tutti nello spirito, non ti pare?"
GS_Gossip[699018297] = "L'Arcimago Vargoth mi ha affidato il suo bastone quando mi ha detto di fuggire dall'attacco dei blood elf alla Torre Viola. Ho fatto come mi aveva detto, sperando di trovare rifugio nell'antico insediamento draenei di Arklon.NEW_LINENEW_LINENon c'era da aspettarsi un momento di tregua. Mi ero addentrato proprio nel fronte avanzante di una forza della Legione Infuocata. I demoni mi strapparono il bastone, ma riuscii a salvarmi la vita.NEW_LINENEW_LINEAnche se il mio maestro non sa nulla del mio fallimento, mi vergogna comunque."
GS_Gossip[703614314] = "Scherzo o dolcetto!"
GS_Gossip[704210654] = "Tutta questa sparatoria contro Skorn e in altri posti laggiù all'orizzonte, e cosa credi che mi abbia portato?NEW_LINENEW_LINEDovere di recupero delle palle da cannone!NEW_LINENEW_LINENon esattamente ciò per cui mi sono iscritto, sai?"
GS_Gossip[705534324] = "C'è un vecchio detto, \"Dai a un uomo un pesce; hai nutrito lui per un giorno. Insegna a un uomo a pescare; e hai nutrito lui per tutta la vita.\" Naturalmente, potresti voler cucinare quel pesce e questo è dove io entro in gioco."
GS_Gossip[705751641] = "Certamente potremmo usare un altro cuoco a Dolanaar, non che la cucina di Zarrin sia carente, ma perché non vai a vedere cosa può insegnarti?"
GS_Gossip[70979772] = "La Dama Oscura ha detto che la conoscenza sarà la nostra arma più potente in questa guerra."
GS_Gossip[710616269] = "Camminando per la strada! Guardando i miei piedi! Osservando le foglie, cadere dagli alberi!"
GS_Gossip[710705289] = "L'Esportazione commerciale del Magus si trova nel nord-ovest di Dalaran, e ospita la maggior parte dei maestri delle professioni della città."
GS_Gossip[715369651] = "Andando giù a Tranquillien oggi, YOUR_CLASS, oppure c'è qualcos'altro che posso fare per te?"
GS_Gossip[715977075] = "Questo spirito si librava sopra il suo corpo caduto. I suoi occhi spettrali ti penetrano mentre guarda oltre..."
GS_Gossip[717054509] = "La Fiera di Lunacupa sta arrivando! Ci sono divertimento per bambini di TUTTE le età! Venite tutti, non mancate!"
GS_Gossip[719200855] = "Sei sicuro?NEW_LINENEW_LINENon c'è modo di tornare indietro una volta che avrò cancellato dalla tua mente le conoscenze delle abilità che hai imparato."
GS_Gossip[723893479] = "Bene. A vedere chi ha portato il vento dell'aldilà. Entra, siediti e riposati un momento. La tariffa è modesta; sicuramente te la puoi permettere."
GS_Gossip[725139189] = "La professione dell'Incantazione mostra il ciclo di distruzione e creazione che è al centro della natura. Teg presso gli Incantatori dei Dawnstrider sulla collina centrale ti mostrerà come."
GS_Gossip[725265700] = "Ho perso il mio Jubling."
GS_Gossip[729564887] = "Interessante."
GS_Gossip[730798209] = "Per il momento abbiamo solo un piccolo piede d'appoggio su questo continente, ma gli umani non possono respingerci per sempre. Poi pagheranno per averci schiavizzato. Strapperemo loro la lingua per la loro tradizione."
GS_Gossip[734915063] = "Prendi un pinta!"
GS_Gossip[735398180] = "<Il demone evocato trema, lottando contro le regole di gioco di Medivh. Vuole la tua anima!>"
GS_Gossip[737394472] = "I druidi di Azeroth tengono un grande festino nel Moonglade. Se trovi i partecipanti alla festa lunare nella città, possono trasportarti là."
GS_Gossip[738050957] = "Nessun'altra razza su Azeroth ha sofferto tanto quanto il nostro popolo, YOUR_CLASS. Ridere in faccia alla morte è diventato un riflesso naturale per tutti noi."
GS_Gossip[738491168] = "C'è un addestratore di fabbricazione nel nostro grande domicilio Picco del Tuono a nord. Se cerchi tale conoscenza, vai là e chiedi a uno dei Bluffwatchers le indicazioni."
GS_Gossip[74088692] = "Oh mio Dio! Abbassa la voce, YOUR_NAME! Che? Stai cercando di farci morire?!NEW_LINENEW_LINECerto che so chi sei! Chi nell'Alleanza non conosce il nome, YOUR_NAME?!NEW_LINENEW_LINESay, cosa ne pensi del mio jumpbot? È basata sul design del mechagnome. Sottile e aerodinamica!"
GS_Gossip[743603313] = "Ho un dovere tra un'ora, ma fino ad allora... fondo in alto!"
GS_Gossip[747154265] = "I resti sono coperti di mosche e larve."
GS_Gossip[749817834] = "Cosa sembra che stia facendo? Sto sistemando il posto - tutto da solo, se posso aggiungere - così possiamo traslocare!NEW_LINENEW_LINECon una base di operazioni qui in mezzo alla foresta, sarà più facile tenere d'occhio ciò che Shattrath, Allerian, Stonebreaker e i druidi Cenarion stanno combinando. La nostra base ad Auchindoun è semplicemente troppo scomoda per questo.NEW_LINENEW_LINEAspetta un momento, ti conosco?"
GS_Gossip[750511710] = "Piccolo goblin sopra un edificio a nord delle rovine di Lordaeron. Lascia la Sepulcra e vai là."
GS_Gossip[750861245] = "Troverai Funaam, il maestro della guild, vicino all'ingresso del Trader's Tier."
GS_Gossip[754327361] = "Nel caso non fosse chiaro, non sono qui per le relazioni con i clienti."
GS_Gossip[754989452] = "<Il caricatore si erge orgoglioso, pronto alla battaglia.>"
GS_Gossip[755017993] = "Anche i morti viventi devono ripararsi. Mary Edras si occupa di questo qui. Si trova nel Quartiere dei Ladri, sulla ringhiera interna."
GS_Gossip[756214779] = "Non abbiamo molti visitatori da queste parti. Posso interessarti qualcosa?"
GS_Gossip[757362763] = "Troverò i tuoi ragazzi e il cifrario, Oronok."
GS_Gossip[757725936] = "Quando il torneo inizierà, tutti vedranno i Forsaken emergere trionfanti."
GS_Gossip[758374617] = "Non sono cieco, sai. Posso vedere cosa sta succedendo qui intorno!"
GS_Gossip[758925652] = "La Società Reale degli Apicoltori vi dà il benvenuto a Northrend, YOUR_CLASS.  Ora, cosa farai per aiutarci nel servizio di Sylvanas?"
GS_Gossip[76232334] = "Fhwoor come piccoli sporellini. Li salvano Fhwoor. Non li mangiare.NEW_LINENEW_LINEFhwoor odia le naga.  Fhwoor distrugge!"
GS_Gossip[766361720] = "Vorrei un nuovo invito al Festival Lunare."
GS_Gossip[768305666] = "Devi assaggiare questa birra."
GS_Gossip[768738728] = "Voglio volare sulle ali della spedizione bronzo."
GS_Gossip[769666868] = "Non giudico gli altri per la loro statura, YOUR_RACE, ma per il loro coraggio e fedeltà."
GS_Gossip[771486321] = "Legione dappertutto... devono essere affrontati!"
GS_Gossip[776898297] = "Il nostro modo è sacro. Moriremo prima di abbandonare Thorim e unirci al tipo di Re dei Lich."
GS_Gossip[777241458] = "Dis drink good!"
GS_Gossip[777620334] = "Perché intendi dire a Lump? Lump ha fame, è tutto."
GS_Gossip[779097450] = "Prova un po' di questa torta di ciliegie, metterà un sorriso sulla tua faccia, largo dieci miglia."
GS_Gossip[779225493] = "Soo-YOUR_NAME, magari ci dai un fischietto per quando dobbiamo chiamarti. Oki?"
GS_Gossip[77992279] = "Spiacenti, YOUR_CLASS. NEW_LINENEW_LINELa tua comprensione dell'arcano non è sufficiente per comprendere la magia dei portali."
GS_Gossip[780001262] = "La pelle tesa tra le ossa è un richiamo alla battaglia contro il principale difensore dell'Alleanza di Sylvanaar e la Foresta Vivente a ovest."
GS_Gossip[78042623] = "Ho sentito che i troll nel villaggio di Sen'jin hanno un alchimista di nome Miao'zan. Cercate lì."
GS_Gossip[783309849] = "L'Esplorazione Cenarion mi ha salvato dalla morte certa all'interno delle miniere. Gli devo la vita! Offro i miei servizi di riparazione e vendita di reagenti a chi è alleato con l'Esplorazione Cenarion."
GS_Gossip[785143551] = "Bonelashers, odio tutti!NEW_LINENEW_LINESe non fosse per la perdita dell'occhio e per gli svenimenti che a volte mi prendono, sarei là fuori a sparargli addosso tutto il tempo!"
GS_Gossip[788383664] = "Grazie ancora, YOUR_NAME.  Rocknot e io stiamo andando molto d'accordo!"
GS_Gossip[78871922] = "Be', se non è YOUR_NAME!  È bello rivederti; non posso esprimere abbastanza la mia gratitudine per l'aiuto che mi hai dato e per il lavoro di inventore finora.NEW_LINENEW_LINECosa posso fare per te oggi?"
GS_Gossip[794661562] = "Non c'è alcun brivido come il brivido di una caccia al drago."
GS_Gossip[794979709] = "Quando sono arrivato per la prima volta, speravo di incontrare l'omonimo del paese.NEW_LINENEW_LINE<Ros'eleth guarda intorno.>NEW_LINENEW_LINELa maggior parte dei giovani elfi alti cresce fuori dalla fase 'Voglio diventare un Farstrider' quando vengono presi come apprendisti. Poi, si passa alla fase 'Voglio diventare un magister'.NEW_LINENEW_LINEOnestamente, non credo di aver mai del tutto superato la fase del Farstrider. Nessuno sogna di diventare una sarta, ma non possiamo permettere che i Farstrider corressero in giro nudi, come usava dire mia madre."
GS_Gossip[796840493] = "Quando ero un giovane elfo notturno a Darkshore, ho incrociato la strada di un gruppo di individui poco raccomandabili noti come il Martello del Crepuscolo. Un gruppo di loro si amicò con me e, vergognosamente, finii per abbandonare la mia fede in Elune e abbracciare l'odio del Martello del Crepuscolo.NEW_LINENEW_LINENon fu fino a quando una visione mi arrivò da Elune, che mi svegliai dal malessere in cui ero caduto come seguace degli antichi dei.NEW_LINENEW_LINEIn pentimento, ho iniziato a lavorare alla mia preghiera a Elune. "
GS_Gossip[798344127] = "Uno dei cultisti sembra essersi imbattuto nella mia lama e è morto... posso avere un nuovo travestimento? Prometto che questa volta sarò più attento."
GS_Gossip[802709660] = "Dove si trova il zeppelino per la Sepulcra in questo momento?"
GS_Gossip[806490155] = "Può Zamja aiutarti, YOUR_RACE?"
GS_Gossip[806510676] = "Mi unirò all'assalto sulla Rocca della Corona di Ghiaccio quando sarà il momento di colpire."
GS_Gossip[807884805] = "Ho sentito parlare del vostro popolo, ma non avevo mai immaginato di vedere il giorno in cui mi sarei incontrato con un mezzo-razza."
GS_Gossip[807987566] = "Qui giacevano i resti di Weeder Greenthumb, uno dei compagni druidi di Watcher Jhang. A tutti gli effetti sembrava che fosse stato ucciso velocemente e pulitamente mentre cercava di fuggire dalle Carceri dei Schiavi."
GS_Gossip[808517473] = "Se vuoi imparare a pellegrinare, vai nel Quartiere dei Ladri. Il pellegrino ha il suo posto sulla ringhiera interna."
GS_Gossip[810227644] = "Elder Graymane è stato visto l'ultima volta mentre visitava K3 nelle Cime Tempestose."
GS_Gossip[812591443] = "Ma..."
GS_Gossip[812654332] = "{\"Nato dalla luce\" sarebbe una traduzione vicina per Sha'tar.  È il nome che abbiamo dato ai naaru che hanno riconquistato Shattrath dalla città dagli agenti di Illidan."
GS_Gossip[818692356] = "La signora ti insegna a creare oggetti magici.  Lei è nell'anello interno dell'Apothecarium."
GS_Gossip[819068533] = "I spiriti mi hanno detto che saresti venuto, che cercheresti me per qualche motivo, ma che nemmeno tu potresti sapere quel motivo. Allora, sai perché sei qui?"
GS_Gossip[820705539] = "Anya Maulray all'inn sulla ringhiera superiore del quartiere commerciale."
GS_Gossip[820798541] = "Benvenuto sulle linee del fronte, YOUR_CLASS.  Mentre i politici possono complottare e tramarare tra loro, qui non troveranno alcuna tale comodità.  Questo è il Bulwark, e qui combattiamo per la nostra sopravvivenza quotidiana.NEW_LINENEW_LINESe sei venuto qui cercando un'occasione per dimostrare il tuo valore come eroe, troverai molte opportunità per farlo... soprattutto mentre avanziamo verso Andorhal e qualunque maligna forza controlli il Flagello lì."
GS_Gossip[820899680] = "Ah, Noblegarden. È così divertente osservare gli altri gettare via la loro dignità in favore della caccia a uova colorate. Tuttavia, hanno comunque un curioso alone magico..."
GS_Gossip[821550203] = "Un nome sfortunato per un marinaio, no?"
GS_Gossip[825741322] = "Oltre ai Grunts fuori, io e i miei fratelli abbiamo combattuto nella battaglia di Hyjal. Chiunque cerchi di rubare dalla banca deve affrontarci prima."
GS_Gossip[825970592] = "Capisco che questa festa è un'invenzione non dei nostri alleati, ma dell'Orda. Perché la stiamo seguendo, non so."
GS_Gossip[826823839] = "Troverai l'Addestratore dei Magi, Cain Firesong, al primo piano, all'ingresso del Gallows' End Tavern, che si trova all'estremità sud-est di Brill. Immagino che sia arrivato troppo tardi per prenotare una stanza."
GS_Gossip[827792078] = "Portali della capitale"
GS_Gossip[829549716] = "Tutto ciò che è successo da quando è avvenuto l'impatto non è altro che un vago ricordo. Sembra che sia passato un'eternità da quando ero a bordo dell'Esodar.NEW_LINENEW_LINEOra, la mia realtà è limitata a quest'isola con le sue creature mutanti e l'infinito mare di agenti elfi del sangue. Presto, sarà come se non avessi mai conosciuto niente di diverso..."
GS_Gossip[830528007] = "Sono Atuik, capo dei Kalu'ak di Kamagua."
GS_Gossip[833483297] = "I libri stanno scomparendo da un po'. Il Custode delle Storie e i suoi assistenti sono in preda al panico. Sospettano attività illecite all'interno di Eldre'Thalas."
GS_Gossip[838273456] = "Sono onorato di fare la tua conoscenza."
GS_Gossip[839387977] = "Utilizzare i frutti della Madre Terra per creare pozioni che ci aiutino nella nostra eterna lotta è un impegno onorevole. Per imparare di più devi viaggiare a nord verso la nostra grande casa di Picco del Tuono. Quando arriverai in cima, cerca l'aiuto di uno dei Bluffwatchers per ottenere istruzioni più specifiche."
GS_Gossip[84294565] = "Mi vergogno ad ammetterlo, Nork, ma il mio disertore è scomparso."
GS_Gossip[847425326] = "Manaforge Duro è l'installazione più vicina a Tempest Keep, quindi gestisce la maggior parte del carico.NEW_LINENEW_LINECome dovresti sapere, sovraccaricare queste maniforghe causa perdite nelle tubazioni. L'energia emanata attira creature mana indesiderate. Abbiamo avuto infestazioni di creature mana in molti punti di perdita; al momento, la Maniforga Duro è quella che subisce i danni maggiori."
GS_Gossip[847769559] = "Benvenuto nel sottosuolo. C'è qualcosa che posso aiutarti a trovare?"
GS_Gossip[848868327] = "Bene, stavo solo riferendo al nostro leader qui come le cose procedono secondo il piano. Dovrebbe essere solo un paio di settimane in più e avremo questo posto di nuovo in forma.NEW_LINENEW_LINEPotremmo voler far in modo che il Consiglio delle Ombre impieghi solo orchi per il villaggio, tuttavia. In questo modo potremmo avanzare una pretesa ancestrale e lavorare sotto copertura.NEW_LINENEW_LINEAspetta un momento. Ti conosco? Qual'è il tuo nome?"
GS_Gossip[849493896] = "Prossimamente elimineremo la disgustosa presenza dei silithids da Azeroth. Il loro potenziale distruttivo è molto maggiore di quanto hai visto di persona, YOUR_NAME.  Poteri maggiori e più oscuri stanno dietro alle loro attività."
GS_Gossip[849617945] = "Bene, puoi trovare Theridan o Maldryn vicino alla pozza lunare nel Parco. Basta recarsi nell'area occidentale di Roccavento, a nord del Distretto dei Magi, ma a ovest della Piazza della Cattedrale."
GS_Gossip[852456690] = "Dovrai trovare Nat Pagle in Pianura delle Fango per ottenere qualcosa di meglio di quanto sei attualmente."
GS_Gossip[853969189] = "I nostri alleati dell'Alleanza stanno assistendo la Lega di Arathor nella loro difesa del Bacino d'Arathi. Potrebbero aver bisogno del tuo aiuto contro i Defiler non morti, YOUR_CLASS."
GS_Gossip[854033441] = "Siamo stati fortunati a trovare abbastanza pezzi per far funzionare di nuovo questi bei ragazzi!NEW_LINECome posso aiutarti?"
GS_Gossip[856755418] = "Cammina sempre nella Luce, YOUR_NAME."
GS_Gossip[859132551] = "Vieni in cerca di addestramento, cacciatore?"
GS_Gossip[862456251] = "Dovresti sentirti al sicuro qui; abbiamo aumentato la sicurezza in questa struttura dopo gli attacchi al Manaforge Duro."
GS_Gossip[871125299] = "Saluti, YOUR_CLASS. Non ho troppo tempo per parlare--sto usando solo Chillwind come accampamento per riposare prima di andare a Hearthglen. Ho sentito dire che prima di impazzire, la Crociata Scarlatta aveva un mago che lavorava per loro, che stava cercando di creare potenti archi e pistole per i loro soldati. Non sono sicuro se lui abbia avuto successo o no... la Crociata lo uccise prima che alcun prodotto finito uscisse. Forse lo uccisero per tenere segreto il loro lavoro... o forse temono tanto l'arcano."
GS_Gossip[879252820] = "Questo è un buon materiale!  Ma è un po' debole.  Penso che aggiungerò un po' più di alito al蒜..."
GS_Gossip[879469706] = "Vuoi migliorare le tue abilità con le armi? Il nostro maestro delle armi si trova al piano più alto del Trader's Tier, sulla Terrazza dei Guerrieri."
GS_Gossip[880947528] = "I cristalli di focalizzazione? Certo, ve lo spiegheremo, visto che avete solo la metà della capacità mentale per capirlo.NEW_LINENEW_LINEUn cristallo di concentrazione esausto può essere combinato con dieci frammenti di apexis in un processo semplice, che crea un cristallo di concentrazione carico. Questi cristalli carichi hanno alcune proprietà curative, ma ciò che è più importante è il loro utilizzo con un demone posseduto.NEW_LINENEW_LINEVedi, la concentrazione carica può essere utilizzata per abilitare un demone posseduto a manifestare poteri speciali. Dopo un po', Gahk avrà una missione per te da svolgere proprio così."
GS_Gossip[881397381] = "Benvenuto, YOUR_NAME. Dobbiamo essere brevi perché c'è molto da fare."
GS_Gossip[883319287] = "Se un banco è ciò che desideri, allora i tuoi viaggi ti porteranno al cuore di Darnassus. Là troverai lo spazio di archiviazione per i tuoi tesori."
GS_Gossip[88334974] = "L'unica anomalia dell'Earthen nella sintesi è la tendenza alla destabilizzazione della matrice durante l'utilizzo in ambienti ad alta tensione.NEW_LINENEW_LINEAddendum: la scultura della terra profonda era naturalmente adatta al nuovo design della matrice e quindi non ha mai soddisfatto i requisiti per duplicare un ambiente ad alta tensione.NEW_LINENEW_LINELa destabilizzazione non fu scoperta fino a molto avanti nel ciclo principale di servizio degli Earthen per i Creatori. I Creatori iniziarono a lavorare su modifiche post-sintesi, piuttosto che su richiamo e re-sintesi."
GS_Gossip[883771717] = "Taverna della Fine del Mondo"
GS_Gossip[88528315] = "Dove si trova Elder Ironband?"
GS_Gossip[890485730] = "Hai bisogno di essere esaltato con i Forsaken della Sepulcra prima che io ti insegni una skill di cavalcatura, YOUR_CLASS."
GS_Gossip[890743114] = "Ho un'altra domanda."
GS_Gossip[894952631] = "Quello che non darei per essere fuori sulle pianure aperte in un giorno come questo... ma il mio dovere mi lega."
GS_Gossip[89919528] = "E cosa esattamente pensi che io possa fare per te? Non puoi vedere che sono molto occupato qui a discutere questioni importanti con il nostro illustre leader?NEW_LINENEW_LINESbrigati con le tue faccende o ti batterò, cane!"
GS_Gossip[899511439] = "C'era un'altra cosa che volevo chiederti."
GS_Gossip[902188905] = "Gli splendidi commercianti a sud di Dalaran dovrebbero avere tutti i generi di consumo di cui hai bisogno."
GS_Gossip[90343842] = "Ho avuto un brutto incontro con alcuni dei Defias qui intorno di recente, ma Michelle Belle mi ha sistemato abbastanza bene. Controlla con lei all'Inn del Orgoglio del Leone e vedrai se ti insegnerà."
GS_Gossip[9034536] = "Cosa c'entra con le diverse velocità?"
GS_Gossip[904012563] = "Parlerai quando ti parleranno."
GS_Gossip[9053086] = "Desidero rimuovere le abilità del mio animale domestico."
GS_Gossip[909263141] = "Kalaran, ho perso la mia torcia. Ne ho bisogno di un'altra."
GS_Gossip[909313156] = "Non abbiamo sartori qui ad Azure Watch. Potresti provare il campo sulle spiagge, tuttavia - sembra che abbiano un certo numero di artigiani provenienti da tutta la costa."
GS_Gossip[91097512] = "Non è il nostro modo, né sarebbe possibile. Nefarian è protetto da antichi incantesimi, vecchi quanto gli stessi Aspett. Questo mi impedisce di entrare nel santuario interno di questa cittadella. La magia oscura impedisce a qualsiasi altro drago di entrare senza essere consacrato... a meno che."
GS_Gossip[912745720] = "Lee Brown passa l'intera giornata a pescare vicino al Lago dei Cristalli. Probabilmente ha alcune storie da raccontare e alcuni consigli che potrebbe insegnarti."
GS_Gossip[918699858] = "Sei fatto così da sembrare che tu sappia già un po' come si fa con un animale che corre per terra, ma se vuoi volare, ci vorrà addestramento e dedizione. E oro. Hai dell'oro, vero?"
GS_Gossip[921993504] = "Benvenuto, YOUR_CLASS. Puoi parlarmi a meno che non tu abbia affari diretti con mia signora Magatha.NEW_LINENEW_LINEMi occupo della maggior parte dei suoi compiti in modo che possa concentrarsi su questioni più importanti. Forse ci sono alcune cose che potremmo discutere prima che tu vada da lei?"
GS_Gossip[923568448] = "Se stai cercando schemi o conoscenze riguardo all'alta sartoria di ombreintrecciato, sarò felice di aiutarti."
GS_Gossip[924192482] = "Non tutti i Forsaken sono guidati dalla volontà di Sylvanas, YOUR_NAME. Alcuni di noi sono spinti da un potere reale--potere che guadagniamo per noi stessi."
GS_Gossip[928227711] = "Vendete davvero qualcosa?"
GS_Gossip[931376786] = "Archibald è maestro del balestra. È il maestro d'arma della Sepulcra, situata nel Quartiere della Guerra."
GS_Gossip[932132759] = "Un tempo vagavo nei Colli Bradi, figlio di Ursoc, il grande che regnava su questa terra.NEW_LINENEW_LINEMa ora... ora sono condannato a trascorrere il resto della mia vita in questa caverna."
GS_Gossip[932479205] = "Teletrasportati a Salita del Flagellatore della Morte."
GS_Gossip[934758582] = "Inviami a Thrallmar!"
GS_Gossip[934836281] = "Sono pronto a scoprire dove si trova la mia fortuna!"
GS_Gossip[936338955] = "Arthas ha dato l'ordine di sterminare Stratholme, uccidendo ogni singolo umano all'interno delle sue mura.NEW_LINENEW_LINEHa scoperto prove che il Flagello aveva infettato la città con la loro terribile peste, e la malattia non uccide solo le persone.NEW_LINENEW_LINEQuelli che muoiono per questa peste si alzano come zombi senza mente, alimentando ulteriormente la macchina da guerra del Flagello."
GS_Gossip[937481942] = "Posso aiutarti a stabilire una guild."
GS_Gossip[938852864] = "L'ultima volta che ho sentito, l'Orda aveva accumulato $2021w di $2020w peacebloom, $2050w di $2051w firebloom e $2054w su $2055w porpora lotus."
GS_Gossip[941976859] = "Quello che non ho in altezza lo compenso con la magia. Mi occupo bene della Pietra della Grande Nebbia... la maggior parte del tempo comunque.NEW_LINENEW_LINECani stupidi."
GS_Gossip[943192331] = "Giorno dopo giorno, tutto ciò che Mad Jonah Sterling vuole che io faccia è pulire le coperte.NEW_LINENEW_LINESciacquare le coperte?!NEW_LINENEW_LINESono un mago, non faccio il lavapiatti! Almeno non in modo banale."
GS_Gossip[943193099] = "Grok cerca aiuto.  Piccolo YOUR_RACE vai alle montagne e aiuta i Bloodmaul!"
GS_Gossip[946821423] = "Lo pagherò! Lo pagherò! Eeeek! Per favore, non farmi del male!"
GS_Gossip[948144599] = "Il Codice dell'Inferno era custodito nelle stanze private di Gul'dan all'interno di Karabor per vent'anni. Ah, è vero, non hai idea di cos'è Karabor, vero?NEW_LINENEW_LINEIl Tempio Nero...NEW_LINENEW_LINEAye, ora casa di Illidan Stormrage.NEW_LINENEW_LINEQuando Illidan prese il controllo del Tempio Nero, scoprì il cifrario. Riconobbe che i danni a questo mondo erano già stati fatti, ma pensò saggio tenere il cifrario al sicuro per un uso futuro."
GS_Gossip[949306867] = "Come posso aiutarti, YOUR_CLASS?"
GS_Gossip[949689834] = "Come Kel'Thuzad, un tempo anch'io ero un mago del Kirin Tor. E come Kel'Thuzad, io cerco l'Atiesh leggendario, grande bastone del Guardiano. I nostri destini sono intrecciati in questo modo, YOUR_CLASS."
GS_Gossip[952027205] = "Un giorno, Rejek sarà un potente guerriero."
GS_Gossip[952577391] = "Cerco addestramento come druido."
GS_Gossip[955469560] = "Il cristalloforno malefico può essere utilizzato per trasformare i tuoi frammenti di apexis in flaconi instabili della bestia. Questi flaconi rendono l'assaggiatore più agile, più forte e più robusto.NEW_LINENEW_LINEFai la tua scelta, di seguito."
GS_Gossip[956150462] = "Lysheana può fornirti i documenti necessari, abita nella Terrazza degli Artigiani nel nord-est di Darnassus. Che la tua compagnia porti gloria agli Elfi Notturni!"
GS_Gossip[956361837] = "Come responsabile delegato di questo complesso, è mio dovere assicurare che vi sia un certo livello di noia in tutti i tipi di attività, lavoro, riposo e relax che possono aver luogo qui.NEW_LINENEW_LINESe trovi qualcosa che ti viene chiesto di fare troppo facile e senza problemi, segnalamelo immediatamente."
GS_Gossip[959769382] = "I capi drakkari sono stati catturati! Cosa altro vorresti che facessi?"
GS_Gossip[96030629] = "No, seriamente, non capisco ancora..."
GS_Gossip[960782876] = "Mi sottometto per ulteriore addestramento, mio maestro."
GS_Gossip[963110950] = "Ah, sì, quello... il nome. Beh... come si dice, un buon nome, come una buona volontà, si guadagna con molte azioni e si perde con una. Non c'è bisogno di entrare nei come o perché; basta dire che è così che alcuni mi chiamano."
GS_Gossip[964367546] = "<Ulfang ulula e annusa te, e puoi capire ciò che dice.>NEW_LINENEW_LINEIl strano lupo bianco del nord, Garwal, mi ha rubato il mio branco. Dobbiamo strappargli la gola in modo che io possa essere nuovamente il lupo alfa."
GS_Gossip[965233899] = "Non abbiamo un banco qui a Brill, dovrai andare alla Sepulcra per quello. Alla fine delle Ruine di Lordaeron a sud ci sono ascensori che ti porteranno giù nella Sepulcra. Una volta lì, chiedi a uno dei Guardiani della Sepulcra per ottenere indicazioni più precise."
GS_Gossip[966925620] = "Brother Wilhelm spesso si addestra con Lyria Du Lac dietro la bottega da fabbro a Goldshire. Potresti imparare un paio di cose su come essere un paladino da lui."
GS_Gossip[971254409] = "Sto aspettando pazientemente gli ordini, YOUR_CLASS."
GS_Gossip[971422044] = "Posso insegnarti a minare.  Interessato?"
GS_Gossip[973079988] = "Arcanista Vandril, cosa stanno facendo i Forsaken qui?"
GS_Gossip[973335007] = "Ecco dunque come i potenti caddero tremanti ai suoi piedi, temendo che potesse rivolgere le sue parole loro.NEW_LINENEW_LINEMa pur sempre questi ciarlatani, questi adoratori pretensori di una religione inesistente, si sono lamentati contro l'inevitabile in un vano tentativo di controllare il loro 'dio.' Indifferente, e probabilmente nemmeno accorgendosene, Murmur sbadigliò e loro sapevano l'oblio.NEW_LINENEW_LINETuttavia, uno riuscì in qualche modo a sopravvivere, e nella sua follia trovò un modo per portare Murmur nel mondo."
GS_Gossip[986114134] = "Cerca Sayoc e Hanashi nella Valle dell'Onore all'interno di Arms of Legend. Fai attenzione a quel che dici in loro presenza, altrimenti Sayoc potrebbe decidere di darti un pezzo come spuntino al Cane Sorridente."
GS_Gossip[987829513] = "Lo so, lo so... \"pescare in un fiume di scarichi?\" Ma ti sorprenderebbe ciò che puoi catturare qui sotto. Ho anche sentito parlare di squali, se puoi crederci."
GS_Gossip[99203215] = "Alcuni mi chiamano 'Tim', ma per i miei amici, io sono 'lo specialista'."
GS_Gossip[994160712] = "Ho perso la mia chiave per L'Arcatraz."
GS_Gossip[994292751] = "Sono sicuro che Arthas tornerà presto, soldato. Tieni alto il morale!"
GS_Gossip[998927035] = "I Terreni dei Fantasma non saranno riconquistati solo attraverso la forza militare, YOUR_NAME.  Ecco dove entrano in gioco noi magi.NEW_LINENEW_LINELa nostra astuzia e la conoscenza dell'arcano sono ineguagliabili."
GS_Gossip[999607220] = "I orsi sono creature bellissime. Selvaggi, forti e feroci in battaglia... proprio come noi, sorella."
